const n={"abhinandannath-chalisa":{id:"abhinandannath-chalisa",category:"chalisa",title:"श्री अभिनंदननाथ चालीसा",subtitle:"चतुर्थ तीर्थंकर भगवान श्री अभिनंदननाथ स्वामी की भक्ति-स्तुति",type:"structured",verses:[{number:"१",tag:"दोहा",lines:["ऋषभ अजित सम्भव अभिनंदन, दया करे सब पर दुखभंजन।","जनम-मरन के टूटें बंधन, मनमंदिर तिष्ठें अभिनंदन॥"],meaning:"श्री ऋषभदेव, अजितनाथ, सम्भवनाथ और चतुर्थ तीर्थंकर अभिनंदननाथ प्रभु समस्त जीवों के दुःखों का नाश करने वाले परम दयालु हैं। प्रभु हमारे हृदय मन्दिर में विराजमान हों, जिससे जन्म-मरण के सांसारिक बंधन कट जाएँ।"},{number:"२",tag:"चौपाई",lines:["अयोध्या नगरी अति सुंदर, करते राज्य भूपति संवर।","सिद्धार्था उनकी महारानी, सुंदरता में थी लासानी॥"],meaning:"परम पावन और अनुपम अयोध्या नगरी में न्यायप्रिय राजा संवर राज्य करते थे। उनकी पटरानी महारानी सिद्धार्था थीं, जो शील, सदाचार और सौन्दर्य में अद्वितीय थीं।"},{number:"३",tag:"चौपाई",lines:["रानी ने देखे शुभ सपने, बरसे रतन महल के अंगने।","मुख में देखा हस्ति समाता, कहलाई तीर्थंकर माता॥"],meaning:"महारानी सिद्धार्था ने सोलह मंगलकारी स्वप्न देखे। कुबेर ने राजमहल के प्रांगण में साढ़े बारह करोड़ रत्नों की वर्षा की। ऐरावत हाथी को मुख में प्रवेश करते देख वे तीर्थंकर प्रभु की जननी कहलाईं।"},{number:"४",tag:"चौपाई",lines:["जननी उदर प्रभु अवतारे, स्वर्गों से आए सुर सारे।","मात-पिता की पूजा करते, गर्भ कल्याणक उत्सव करते॥"],meaning:"प्रभु वैशाख शुक्ल षष्ठी को माता के गर्भ में अवतरित हुए। स्वर्गों से इन्द्र एवं देवगण अयोध्या पधारे, माता-पिता की वन्दना की और महाआनन्द के साथ गर्भ कल्याणक महोत्सव मनाया।"},{number:"५",tag:"चौपाई",lines:["द्वादशी माघ शुक्ल की आई, जनमें अभिनंदन जिनराई।","देवों के भी आसन कांपे, शिशु को ले गए मेरु पे॥"],meaning:"माघ शुक्ल द्वादशी के शुभ दिन भगवान अभिनंदननाथ का जन्म हुआ। देवों के आसन कम्पायमान हुए और सौधर्म इन्द्र बाल तीर्थंकर को लेकर सुमेरु पर्वत पर पधारे।"},{number:"६",tag:"चौपाई",lines:["नहवन किया शत आठ कलशों से, अभिनंदन कहा प्रेम भाव से।","सूर्य समान प्रभु तेजस्वी, हुए जगत में महा यशस्वी॥"],meaning:"देवराज इन्द्र ने एक सौ आठ कलशों के क्षीरसागर जल से प्रभु का महा जन्माभिषेक किया और प्रेमभाव से वन्दना कर प्रभु का नाम 'अभिनंदननाथ' रखा। प्रभु का तेज कोटि सूर्यों के समान और यश जगद्व्यापी था।"},{number:"७",tag:"चौपाई",lines:["बोले हित-मित वचन सुबोध, वाणी में कहीं नहीं विरोध।","यौवन से जब हुए विभूषित, राज्यश्री को किया सुशोभित॥"],meaning:"बाल्यावस्था से ही प्रभु परम हितकारी, अल्प और ज्ञानवर्धक वचन बोलते थे। युवावस्था प्राप्त होने पर उन्होंने पिता की आज्ञा से राजसिंहासन को सुशोभित किया।"},{number:"८",tag:"चौपाई",lines:["साढ़े तीन सौ धनुष प्रमाण, उन्नत प्रभु तन शोभवान।","परणाई कन्याएं अनेक, लेकिन छोड़ा नहीं विवेक॥"],meaning:"प्रभु के स्वर्ण-वर्ण शरीर की ऊँचाई साढ़े तीन सौ धनुष थी। अनेक राजकन्याओं के साथ परिणय होने पर भी प्रभु ने आत्मा के विवेक और सम्यक्त्व को कभी नहीं बिसराया।"},{number:"९",tag:"चौपाई",lines:["नित प्रति नूतन भोग भोगते, जल में भिन्न कमल सम रहते।","एक दिन देखे मेघ अंबर में, मेघ महल बनते पल में॥"],meaning:"राजभोगों में रहते हुए भी प्रभु जल से भिन्न कमल की तरह सर्वथा अनासक्त थे। एक दिन आकाश में क्षण भर में बनने और मिटने वाले मेघ-महलों को देखकर उन्हें संसार की अनित्यता का गहरा बोध हुआ।"},{number:"१०",tag:"चौपाई",lines:["हुए विलीन पवन के चलने से, उदासीन हो गए जगत से।","राज पाठ निज सुत को सौपा, मन में समता वृक्ष को रोपा॥"],meaning:"हवा के झोंके से बादलों को पल भर में बिखरते देख प्रभु का मन सांसारिक भोगों से विरक्त हो गया। अपने सुपुत्र को राज्य सौंपकर उन्होंने आत्म-कल्याण के लिए परम समता भाव अंगीकार किया।"},{number:"११",tag:"चौपाई",lines:["गए उग्र नामक उद्यान, दीक्षित हुए वहां गुणखान।","शुक्ला द्वादशी थी माघ मास, दो दिन धारा उपवास॥"],meaning:"प्रभु उग्रसेन (सहेतुक) उद्यान में पधारे और माघ शुक्ल द्वादशी को एक हजार राजाओं के साथ दिगम्बर दीक्षा धारण की और दो दिन का निर्जल उपवास किया।"},{number:"१२",tag:"चौपाई",lines:["तीसरे दिन फिर किया विहार, इंद्रदत्त नृप ने दिया आहार।","वर्ष अठारह किया घोर तप, सहे शीत वर्षा और आतप॥"],meaning:"तीसरे दिन अयोध्या में राजा इन्द्रदत्त ने प्रभु को प्रथम शुद्ध आहार कराकर पंचाश्चर्य प्राप्त किए। प्रभु ने अठारह वर्षों तक मौन धारण कर शीत, वर्षा और ग्रीष्म के घोर परीषह सहन करते हुए तप किया।"},{number:"१३",tag:"चौपाई",lines:["एक दिन आसन वृक्ष के नीचे, ध्यान वृष्टि से आत्म सींचे।","उदय हुआ केवल दिनकर का, लोकालोक ज्ञान में झलका॥"],meaning:"सरल (आसन) वृक्ष के नीचे शुक्लध्यान में लीन प्रभु ने चारों घातिया कर्मों का समूल नाश कर दिया। पौष शुक्ल चतुर्दशी को केवलज्ञान रूपी सूर्य उदित हुआ और समस्त त्रैलोक्य ज्ञान में प्रत्यक्ष झलक उठा।"},{number:"१४",tag:"चौपाई",lines:["हुई तब समोशरण की रचना, खीरी प्रभु की दिव्य देशना।","जीवाजीव और धर्माधर्म, आकाश काल षटद्रव्य मर्म॥"],meaning:"कुबेर ने दिव्य समवशरण की रचना की जहाँ प्रभु की अमृतमयी दिव्यध्वनि खिरी। प्रभु ने जीव, अजीव, धर्म, अधर्म, आकाश और काल—इन छह द्रव्यों के रहस्यमयी स्वरूप का प्रतिपादन किया।"},{number:"१५",tag:"चौपाई",lines:["जीव द्रव्य ही सार भूत है, स्वयं सिद्धि ही परम पूत है।","रूप तीन लोक समझाया, ऊर्ध्व मध्य अधोलोक बताया॥"],meaning:"प्रभु ने देशना दी कि चैतन्यमयी जीव द्रव्य ही सारभूत है और अपनी शुद्धात्मा की अनुभूति ही परम पवित्र मुक्ति का मार्ग है। प्रभु ने ऊर्ध्वलोक, मध्यलोक और अधोलोक रूप तीनों लोकों का स्वरूप समझाया।"},{number:"१६",tag:"चौपाई",lines:["नीचे नरक बताए सात, भुगते पापी अपने पाप।","ऊपर सोलह स्वर्ग सुजान, चतुर निकाय देव विमान॥"],meaning:"अधोलोक में सात नरक बताए जहाँ पापी जीव घोर दुःख भोगते हैं, और ऊर्ध्वलोक में सोलह स्वर्ग एवं चार निकाय के देवों के विमान बताए जहाँ शुभोपयोग का फल मिलता है।"},{number:"१७",tag:"चौपाई",lines:["मध्य लोक में द्वीप असंख्य, ढाई द्वीप में जाए भव्य।","भटकों को सन्मार्ग दिखाया, भव्यों को भव पार लगाया॥"],meaning:"मध्यलोक में असंख्यात द्वीप-समुद्र हैं जिनमें मनुष्य क्षेत्र ढाई द्वीप में ही मोक्ष की साधना सम्भव है। प्रभु ने मार्ग से भटके प्राणियों को वीतराग सन्मार्ग दिखाकर संसार सागर से पार उतारा।"},{number:"१८",tag:"चौपाई",lines:["पहुंचे गण सम्मेद अंत में, प्रतिमा योग धरा एकांत में।","शुक्ल ध्यान में लीन हुए तब, कर्म प्रकृति क्षीण हुई सब॥"],meaning:"आयु के अंत में प्रभु श्री सम्मेद शिखर जी पधारे और एकांत में प्रतिमा योग धारण किया। परम शुक्लध्यान के प्रभाव से शेष चार अघातिया कर्मों का भी पूर्ण क्षय कर दिया।"},{number:"१९",tag:"चौपाई",lines:["बैसाख शुक्ल षष्ठी पुण्यवान, प्रात: प्रभु का हुआ निर्वाण।","मोक्ष कल्याणक करे सुर आकर, आनंदकूट पूजे हर्षकर॥"],meaning:"वैशाख शुक्ल षष्ठी की पावन प्रभात में प्रभु ने आनंद कूट से निर्वाण पद प्राप्त किया। देवगणों ने उपस्थित होकर कपूर और अगरु से प्रभु की मोक्षकल्याणक पूजा की।"},{number:"२०",tag:"चौपाई",lines:["चालीसा श्री जिन अभिनंदन, दूर करें सबके भवक्रंदन।","स्वामी तुम हो पापनिकंदन, अरुणा करती शत शत वंदन॥"],meaning:"भगवान अभिनंदननाथ का यह पावन चालीसा पाठ सांसारिक जन्म-मरण के संताप को हरने वाला है। हे पापनाशक प्रभु! हम आपके चरणों में कोटि-कोटि वन्दन करते हैं।"},{number:"२१",tag:"जाप मंत्र",lines:["॥ मूल मंत्र एवं ध्यान ॥","ॐ ह्रीं श्रीं क्लीं अर्हं श्री अभिनंदननाथाय नमः।"],meaning:"चतुर्थ तीर्थंकर देवाधिदेव श्री अभिनंदननाथ स्वामी के पावन चरणों में मेरा अनंत बार नमन हो। प्रभु के चरण-चिह्न 'वानर' (कपि) का ध्यान कर आत्मिक विशुद्धि प्राप्त हो।"}]},"adinath-chalisa":{id:"adinath-chalisa",category:"chalisa",title:"श्री आदिनाथ चालीसा (दोहा, चौपाई एवं भावार्थ सहित)",subtitle:"प्रथम तीर्थंकर भगवान ऋषभदेव / आदिनाथ चालीसा",type:"structured",verses:[{number:"दोहा",lines:["दोहा","शीश नवा अरिहंत को, सिद्धन करूं प्रणाम।","उपाध्याय आचार्य का, ले सुखकारी नाम॥","सर्व साधु और सरस्वती, जिन मन्दिर सुखकार।","आदिनाथ भगवान को, मन मन्दिर में धार॥"],meaning:"सर्वप्रथम अरिहंत परमेष्ठी को शीश नवाकर और सिद्ध प्रभु को प्रणाम करता हूँ। परम सुखकारी उपाध्याय व आचार्य परमेष्ठी का पावन नाम स्मरण कर, सर्व साधु, जिनवाणी माता एवं सुखदायी जिनमंदिर को वंदन करके प्रथम तीर्थंकर भगवान आदिनाथ (ऋषभदेव) को अपने मन-मंदिर में धारण करता हूँ।"},{number:"१",lines:["चौपाई","जै जै आदिनाथ जिन स्वामी। तीनकाल तिहूं जग में नामी॥","वेष दिगम्बर धार रहे हो। कर्मों को तुम मार रहे हो॥"],meaning:"हे प्रथम जिनेन्द्र भगवान आदिनाथ! आपकी जय-जयकार हो। आप तीनों कालों (भूत, वर्तमान, भविष्य) और तीनों लोकों में परम विख्यात हैं। आपने परिग्रह-रहित पावन दिगंबर भेष धारण किया और अपनी अंतर्मुखी आत्मसाधना से समस्त कर्मों का समूल नाश किया।"},{number:"२",lines:["हो सर्वज्ञ बात सब जानो। सारी दुनियां को पहचानो॥","नगर अयोध्या जो कहलाये। राजा नाभिराज बतलाये॥"],meaning:"आप केवलज्ञान से शोभित सर्वज्ञ हैं, जो समस्त लोकालोक और चराचर जगत के सभी भावों को जानते हैं। अयोध्या नगरी में इक्ष्वाकु वंश के कुलभूषण महाराजा नाभिराज आपके पूज्य पिता हुए।"},{number:"३",lines:["मरुदेवी माता के उदर से। चैत वदी नवमी को जन्मे॥","तुमने जग को ज्ञान सिखाया। कर्मभूमी का बीज उपाया॥"],meaning:"परम विदुषी माता मरुदेवी के पावन उदर से चैत्र कृष्ण नवमी के मंगल दिन आपका जन्म हुआ। भोगभूमि की समाप्ति पर आपने प्रजा को असि, मसि, कृषि, विद्या, शिल्प और वाणिज्य का उपदेश देकर कर्मभूमि की नींव रखी।"},{number:"४",lines:["कल्पवृक्ष जब लगे बिछरने। जनता आई दुखड़ा कहने॥","सब का संशय तभी भगाया। सूर्य चन्द्र का ज्ञान कराया॥"],meaning:"जब भोगभूमि के कल्पवृक्ष लुप्त होने लगे और प्रजा जीवन-यापन के संकट से व्याकुल होकर आपके पास आई, तब आपने उनका सारा भय दूर किया और उन्हें सूर्य, चंद्र, ऋतुओं तथा काल-परिवर्तन का यथार्थ बोध कराया।"},{number:"५",lines:["खेती करना भी सिखलाया। न्याय दण्ड आदिक समझाया॥","तुमने राज किया नीति का। सबक आपसे जग ने सीखा॥"],meaning:"आपने प्रजा को आजीविका के लिए कृषि (खेती) का कौशल सिखाया तथा समाज में शांति-व्यवस्था के लिए न्याय, मर्यादा और नीतिपूर्ण शासन की शिक्षा दी। आपके न्यायपूर्ण राज्य से संसार ने धर्म और नीति का पाठ सीखा।"},{number:"६",lines:["पुत्र आपका भरत बताया। चक्रवर्ती जग में कहलाया॥","बाहुबली जो पुत्र तुम्हारे। भरत से पहले मोक्ष सिधारे॥"],meaning:"आपके ज्येष्ठ पुत्र चक्रवर्ती भरत हुए, जिनके नाम से यह पावन देश 'भारत' कहलाया। आपके द्वितीय पराक्रमी पुत्र भगवान बाहुबली हुए, जिन्होंने घोर तपस्या कर भरत चक्रवर्ती से भी पूर्व इस अवसर्पिणी काल में प्रथम मोक्ष प्राप्त किया।"},{number:"७",lines:["सुता आपकी दो बतलाई। ब्राह्मी और सुन्दरी कहलाई॥","उनको भी विद्या सिखलाई। अक्षर और गिनती बतलाई॥"],meaning:"आपकी दो सुयोग्य पुत्रियाँ ब्राह्मी और सुंदरी थीं। आपने ब्राह्मी को अक्षर-विद्या व लिपि (ब्राह्मी लिपि) तथा सुंदरी को गणित व अंक-विद्या की शिक्षा देकर नारी-शिक्षा का अमर आदर्श स्थापित किया।"},{number:"८",lines:["एक दिन राजसभा के अंदर। एक अप्सरा नाच रही थी॥","आयु उसकी बहुत अल्प थी। इसलिए आगे नहीं नाच सकी थी॥"],meaning:"एक दिन आपकी राजसभा में इन्द्र द्वारा भेजी गई नीलांजना नामक देवांगना (अप्सरा) भक्तिपूर्वक नृत्य कर रही थी। उसकी अल्पायु पूर्ण होने पर वह नृत्य करते-करते क्षणभर में विलीन (मृत) हो गई।"},{number:"९",lines:["विलय हो गया उसका सत्वर। झट आया वैराग्य उमड़कर॥","बेटो को झट पास बुलाया। राजपाट सब में बंटवाया॥"],meaning:"नीलांजना के क्षणभंगुर देह-विनाश को देखकर आपके हृदय में संसार की अनित्यता का तीव्र वैराग्य उमड़ पड़ा। आपने तुरंत पुत्रों को बुलाकर न्यायपूर्वक राज्य का विभाजन कर दिया।"},{number:"१०",lines:["छोड़ सभी झंझट संसारी। वन जाने की करी तैयारी॥","राजा हजारों साथ सिधाए। राजपाट तज वन को धाये॥"],meaning:"संसार के समस्त परिग्रह और बंधनों को त्यागकर आपने वन जाकर जिनदीक्षा ग्रहण करने की तैयारी की। आपके साथ चार हजार अन्य राजाओं ने भी राजपाट छोड़कर वैराग्यपूर्वक वन का मार्ग लिया।"},{number:"११",lines:["लेकिन जब तुमने तप कीना। सबने अपना रस्ता लीना॥","वेष दिगम्बर तजकर सबने। छाल आदि के कपड़े पहने॥"],meaning:"किन्तु जब आपने कठोर मौन और घोर निर्ग्रन्थ दिगंबर तप साधना प्रारंभ की, तब वे राजा भूख-प्यास और तप की कठिनता सहन न कर सके। उन्होंने दिगंबर भेष त्याग दिया और वृक्षों की छाल व वल्कल वस्त्र धारण कर लिए।"},{number:"१२",lines:["भूख प्यास से जब घबराये। फल आदिक खा भूख मिटाये॥","तीन सौ त्रेसठ धर्म फैलाये। जो अब दुनियां में दिखलाये॥"],meaning:"कठिन भूख-प्यास से घबराकर वे वन के फल-कंदमूल खाकर क्षुधा शांत करने लगे और भ्रष्ट होकर उन्होंने तीन सौ त्रेसठ (३६३) मत-मतांतरों और पाखंडों की रचना कर संसार में मिथ्या मार्ग फैलाए।"},{number:"१३",lines:["छै: महीने तक ध्यान लगाये। फिर भोजन करने को धाये॥","भोजन विधि जाने नहि कोय। कैसे प्रभु का भोजन होय॥"],meaning:"भगवान ऋषभदेव ने छह माह तक निराहार रहकर आत्म-ध्यान लगाया। छह माह बाद जब वे चर्या (आहार) के लिए निकले, तो उस समय के लोग निर्ग्रन्थ दिगंबर मुनि के आहार की नवधा-भक्ति और विधि नहीं जानते थे।"},{number:"१४",lines:["इसी तरह बस चलते चलते। छः महीने भोजन बिन बीते॥","नगर हस्तिनापुर में आये। राजा सोम श्रेयांस बताए॥"],meaning:"विधि न मिलने से प्रभु मौन भाव से आगे बढ़ते रहे और बिना आहार के और छह माह व्यतीत हो गए (कुल एक वर्ष का उपवास हुआ)। तब विहार करते हुए प्रभु हस्तिनापुर नगरी में पधारे, जहाँ राजा सोमप्रभ और राजकुमार श्रेयांस राज्य करते थे।"},{number:"१५",lines:["याद तभी पिछला भव आया। तुमको फौरन ही पड़धाया॥","रस गन्ने का तुमने पाया। दुनिया को उपदेश सुनाया॥"],meaning:"राजकुमार श्रेयांस को पूर्वभव (श्रीमती-वज्रजंघ) का जातिस्मरण ज्ञान हुआ जिससे उन्हें मुनि-आहार की विधि ज्ञात हो गई। उन्होंने प्रभु का पड़गाहन कर शुद्ध इक्षुरस (गन्ने का रस) का प्रथम आहार (अक्षय तृतीया) दान दिया।"},{number:"१६",lines:["तप कर केवल ज्ञान पाया। मोक्ष गए सब जग हर्षाया॥","अतिशय युक्त तुम्हारा मन्दिर। चाँदखेड़ी भंवरे के अंदर॥"],meaning:"घोर तपस्या के पश्चात वटवृक्ष के नीचे आपको अनंत चतुष्टयरूप केवलज्ञान प्राप्त हुआ, फिर आपने धर्मोपदेश दिया और कैलाश पर्वत से निर्वाण (मोक्ष) पधारे। राजस्थान के प्रसिद्ध अतिशय क्षेत्र चाँदखेड़ी के भूगर्भ (भौंरे) में आपका चमत्कारी जिनमंदिर विराजमान है।"},{number:"१७",lines:["उसका यह अतिशय बतलाया। कष्ट क्लेश का होय सफाया॥","मानतुंग पर दया दिखाई। जंजीरें सब काट गिराई॥"],meaning:"चाँदखेड़ी आदिनाथ का यह लोकोत्तर अतिशय है कि वहाँ दर्शन करने से भक्तों के सभी कायिक व मानसिक कष्ट दूर हो जाते हैं। आपने आचार्य मानतुंग स्वामी की भक्ति पर प्रसन्न होकर भक्तामर स्तोत्र के प्रभाव से उनकी अड़तालीस जंजीरें स्वतः तोड़ गिराई थीं।"},{number:"१८",lines:["राजसभा में मान बढ़ाया। जैन धर्म जग में फैलाया॥","मुझ पर भी महिमा दिखलाओ। कष्ट भक्त का दूर भगाओ॥"],meaning:"आपने राजा भोज की भरी राजसभा में आचार्य मानतुंग का मान बढ़ाया और सत्य अहिंसामय जैन धर्म की कीर्ति पूरे विश्व में फैलाई। हे आदिप्रभु! मुझ दीन भक्त पर भी अपनी दया दृष्टि कीजिए और मेरे सभी कष्ट व बाधाएँ दूर कीजिए।"},{number:"१९",lines:["पाठ करै चालीस दिन जोई। निश्चय संकट रहे न कोई॥","पुत्र पौत्र धन संपति पावै। धरम ध्यान में चित्त लगावै॥"],meaning:"जो भव्य जीव नियमपूर्वक चालीस दिनों तक इस चालीसा का पाठ करता है, उसके जीवन के सभी संकट और विघ्न निश्चित ही दूर हो जाते हैं। उसे सुयोग्य संतान, वैभव व सुख प्राप्त होता है और चित्त सदा धर्म-ध्यान में लगा रहता है।"},{number:"२०",lines:["चालीसे को जो नर गावे। सुख-सम्पत्ति सब घर में पावे॥","'चन्द्र' प्रभु के चरण मनावै। आवागमन मिटा सुख पावै॥"],meaning:"जो भी भव्य जीव इस चालीस पद की चालीसा को नित्य भक्तिभाव से गाता है, उसके घर में धर्मयुक्त सुख-संपत्ति की वृद्धि होती है। कवि 'चन्द्र' प्रभु आदिनाथ के युगल चरणों की शरण लेकर संसार के जन्म-मरण (आवागमन) से छूटकर मोक्ष-सुख प्राप्त करने की मंगल प्रार्थना करते हैं।"},{number:"सोरठा",lines:["सोरठा","पाठ करे चालीस दिन, नित चालीस ही बार।","चाँदखेड़ी में आय के, खेवे धूप अपार॥","जन्म दरिद्री होय जो, होय कुबेर समान।","नाम वंश जग में चले, जिनके नहीं संतान॥"],meaning:"जो भव्य जीव चालीस दिनों तक प्रतिदिन चालीस बार इस चालीसा का पाठ करता है अथवा चाँदखेड़ी अतिशय क्षेत्र में पधारकर प्रभु के समक्ष सुगंधित धूप खेता है—वह यदि जन्मांतर का निर्धन भी हो तो धनवान बन जाता है, और जिसके संतान न हो, उसके कुल और धर्म का यश संसार में फैलता है।"}]},"ajitnath-chalisa":{id:"ajitnath-chalisa",category:"chalisa",title:"श्री अजितनाथ चालीसा",subtitle:"द्वितीय तीर्थंकर भगवान अजितनाथ की पावन स्तुति",type:"structured",verses:[{number:"१",tag:"दोहा",lines:["अष्टकर्म को नाशकर, बने सिद्ध भगवान।","उनके चरणों में करूँ, शत-शत बार प्रणाम॥"],meaning:"ज्ञानावरणादि आठों घातिया और अघातिया कर्मों का समूल नाश करके जो अशरीरी सिद्ध परमात्मा बने हैं, उन सर्वज्ञ प्रभु के पावन चरणों में मैं सैकड़ों बार श्रद्धापूर्वक प्रणाम करता हूँ।"},{number:"२",tag:"दोहा",lines:["पुन: सरस्वती मात को, ज्ञानप्राप्ति के हेतु।","नमन करूँ सिर नाय के, श्रद्धा भक्ति समेत॥"],meaning:"सच्चे सम्यग्ज्ञान की प्राप्ति हेतु मैं द्वादशांग जिनवाणी माता (सरस्वती) को मस्तक झुकाकर, परम श्रद्धा और भक्तिभाव के साथ बारंबार नमन करता हूँ।"},{number:"३",tag:"दोहा",lines:["अजितनाथ भगवान ने, जीते विषय-कषाय।","उनकी गुणगाथा कहूँ, पद अजेय मिल जाय॥"],meaning:"द्वितीय तीर्थंकर भगवान श्री अजितनाथ स्वामी ने पाँचों इंद्रियों के विषयों और क्रोधादि कषायों को पूर्णतः जीत लिया। मैं उनकी पवित्र गुणगाथा का गान करता हूँ, जिससे मुझे भी अविनाशी, अजेय मोक्ष पद की प्राप्ति हो।"},{number:"४",tag:"चौपाई",lines:["श्री आदिनाथ को शीश नवाकर, माता सरस्वती को ध्याय।","शुरू करूँ श्री अजितनाथ का, चालीसा स्व-पर सुखदाय॥"],meaning:"प्रथम तीर्थंकर भगवान ऋषभदेव को शीश झुकाकर और जिनवाणी माता का ध्यान करके मैं भगवान अजितनाथ का यह पावन चालीसा प्रारंभ करता हूँ, जो स्वयं और अन्य सभी जीवों के लिए परम सुखदायक है।"},{number:"५",tag:"चौपाई",lines:["जय श्री अजितनाथ जिनराज, पावन चिह्न धरें 'गजराज'।","नगर अयोध्या करते राज, जितशत्रु नामक महाराज॥"],meaning:"हाथी (गजराज) के पावन लांछन को धारण करने वाले देवाधिदेव भगवान अजितनाथ की जय हो! पवित्र अयोध्या नगरी में जितशत्रु नामक प्रतापी और धर्मात्मा महाराज राज्य करते थे।"},{number:"६",tag:"चौपाई",lines:["विजयसेना उनकी महारानी, देखें सोलह स्वप्न ललामी।","दिव्य विमान विजय से चयकर, जननी उदर बसे प्रभु आकर॥"],meaning:"महाराज जितशत्रु की पट्टमहिषी महारानी विजयसेना थीं, जिन्होंने रात्रि के अंतिम प्रहर में तीर्थंकर के आगमन के सूचक सोलह मंगलकारी स्वप्न देखे। प्रभु अनुत्तर विजय विमान से चयकर माता के पावन गर्भ में पधारे।"},{number:"७",tag:"चौपाई",lines:["शुक्ला दशमी माघ मास की, जन्म जयन्ती अजित नाथ की।","इन्द्र प्रभु को शीशधार कर, गए सुमेरु हर्षित होकर॥"],meaning:"माघ शुक्ल दशमी के परम पावन दिन भगवान अजितनाथ का जन्म हुआ। सौधर्म इन्द्र ने प्रभु बालक को आदरपूर्वक अपने मस्तक पर धारण किया और अपार आनंद के साथ सुमेरु पर्वत की ओर प्रस्थान किया।"},{number:"८",tag:"चौपाई",lines:["नीर क्षीर सागर से लाकर, न्हवन करें भक्ति में भरकर।","वस्त्राभूषण दिव्य पहनाए, वापस लौट अयोध्या आए॥"],meaning:"क्षीरसागर के निर्मल जल से एक हजार आठ कलशों द्वारा सौधर्म इन्द्र ने प्रभु का जन्माभिषेक (न्हवन) किया, दिव्य वस्त्राभूषणों से अलंकृत किया और फिर आनंदपूर्वक अयोध्या नगरी में माता-पिता को सौंप दिया।"},{number:"९",tag:"चौपाई",lines:["अजितनाथ की शोभा न्यारी, वर्ण स्वर्ण सम कान्तिधारी।","बीता बचपन जब हितकारी, हुआ ब्याह तब मंगलकारी॥"],meaning:"भगवान अजितनाथ का दिव्य शरीर तपे हुए सुवर्ण के समान तेजस्वी कांति से दमकता था। जब उनका बाल्यकाल व्यतीत हुआ, तब सांसारिक मर्यादा के अनुसार उनका मंगल विवाह संपन्न हुआ।"},{number:"१०",tag:"चौपाई",lines:["कर्मबन्ध नहीं हो भोगों में, अन्तर्दृष्टि थी योगों में।","चंचल चपला देखी नभ में, हुआ वैराग्य निरन्तर मन में॥"],meaning:"सांसारिक राज-वैभव में रहते हुए भी वे जल में कमल की भाँति अनासक्त थे। आकाश में क्षणभर चमककर विलीन होने वाली बिजली (चपला) को देखकर उनके मन में संसार की अनित्यता का गहरा वैराग्य जाग्रत हो गया।"},{number:"११",tag:"चौपाई",lines:["राजपाट निज सुत को देकर, हुए दिगम्बर दीक्षा लेकर।","छ: दिन बाद हुआ आहार, करें श्रेष्ठि ब्रह्मा सत्कार॥"],meaning:"अपने पुत्र को राज्य का भार सौंपकर प्रभु ने दिगंबर मुनि दीक्षा धारण की। छः दिनों के उपवास के पश्चात साकेत नगर में श्रेष्ठि ब्रह्मा ने नवधाभक्ति पूर्वक प्रभु को प्रथम पारणा (आहार) कराया।"},{number:"१२",tag:"चौपाई",lines:["किये पंच अचरज देवों ने, पुण्योपार्जन किया सभी ने।","बारह वर्ष तपस्या कीनी, दिव्यज्ञान की सिद्धि नवीनी॥"],meaning:"देवों ने आकाश से रत्नवृष्टि, पुष्पवृष्टि आदि पंचाश्चर्य प्रकट किए। प्रभु ने बारह वर्षों तक मौन धारण कर घोर तपस्या की और शुक्लध्यान द्वारा चारों घातिया कर्मों का नाश कर केवलज्ञान प्राप्त किया।"},{number:"१३",tag:"चौपाई",lines:["धनपति ने इन्द्राज्ञा पाकर, रच दिया समोशरण हर्षाकर।","सभा विशाल लगी जिनवर की, दिव्यध्वनि खिरती प्रभुवर की॥"],meaning:"इन्द्र की आज्ञा पाकर कुबेर ने बारह योजन विस्तीर्ण भव्य समवसरण की रचना की। समवसरण में बारह सभाओं के मध्य प्रभु की ओंकारमयी कल्याणकारी दिव्यध्वनि खिरने लगी।"},{number:"१४",tag:"चौपाई",lines:["वाद–विवाद मिटाने हेतु, अनेकान्त का बाँधा सेतु।","हैं सापेक्ष यहाँ सब तत्व, अन्योन्याश्रित है उन सत्व॥"],meaning:"जगत के संशय और एकांतवादी विवादों को मिटाने के लिए प्रभु ने स्याद्वाद और अनेकांत का पावन सेतु बांधा, और बताया कि प्रत्येक द्रव्य नित्य-अनित्य, एक-अनेक आदि सापेक्ष धर्मों से युक्त है।"},{number:"१५",tag:"चौपाई",lines:["सब जीवों में हैं जो आतम, वे भी हो सकते शुद्धात्म।","ध्यान अग्नि का ताप मिले जब, केवल ज्ञान की ज्योति जले तब॥"],meaning:"संसार के प्रत्येक चेतन प्राणी में शुद्ध परमात्मा बनने की पूरी योग्यता है। जब आत्मा को भेदज्ञान और शुद्धोपयोग रूपी ध्यान की अग्नि का संबल मिलता है, तभी केवलज्ञान की शाश्वत ज्योति प्रज्वलित होती है।"},{number:"१६",tag:"चौपाई",lines:["मोक्ष मार्ग तो बहुत सरल है, लेकिन राही हुए विरल हैं।","हीरा तो सब ले नहीं पावें, सब्जी-भाजी भीड़ धरावें॥"],meaning:"रत्नत्रय रूपी मोक्षमार्ग परम ऋजु और सरल है, परंतु उस पर चलने वाले सच्चे वैरागी साधक विरले ही होते हैं; जैसे बहुमूल्य हीरे का ग्राहक कोई एक पारखी होता है, जबकि सांसारिक तुच्छ वस्तुओं की मंडी में भीड़ लगी रहती है।"},{number:"१७",tag:"चौपाई",lines:["दिव्यध्वनि सुन कर जिनवर की, खिली कली जन-जन के मन की।","प्राप्ति कर सम्यग्दर्शन की, बगिया महकी भव्य जनों की॥"],meaning:"जिनेन्द्र देव की अमृतमयी वाणी सुनकर उपस्थित भव्य जीवों के हृदय-कमल खिल उठे; सम्यग्दर्शन, सम्यग्ज्ञान और सम्यक्चारित्र को अंगीकार कर अनगिनत आत्माओं का कल्याण हुआ।"},{number:"१८",tag:"चौपाई",lines:["हिंसक पशु भी समता धारें, जन्म-जन्म का बैर निवारें।","पूर्ण प्रभावना हुई धर्म की, भावना शुद्ध हुई भविजन की॥"],meaning:"प्रभु के वीतराग समवसरण में सिंह और हरिण जैसे परस्पर हिंसक जीव भी अपना जन्म-जन्मांतरों का वैर भूलकर परम मैत्री भाव धारण कर शांत बैठते थे, जिससे जिनशासन की अपार प्रभावना हुई।"},{number:"१९",tag:"चौपाई",lines:["दूर-दूर तक हुआ विहार, सदाचार का हुआ प्रचार।","एक माह की उम्र रही जब, गए शिखर सम्मेद प्रभु तब॥"],meaning:"प्रभु ने आर्यावर्त में दूर-दूर तक पदविहार कर अहिंसा, सत्य और संयम का प्रसार किया। जब उनकी आयु का मात्र एक मास शेष रहा, तब वे श्री सम्मेद शिखरजी के पावन पर्वत पर पधारे।"},{number:"२०",tag:"चौपाई",lines:["अखण्ड मौन मुद्रा की धारण, कर्म अघाति हेतु निवारण।","शुक्ल ध्यान का हुआ प्रताप, लोक शिखर पर पहुँचे आप॥"],meaning:"वहाँ अखंड मौन धारण कर प्रभु ने अघातिया कर्मों के नाश हेतु अंतिम शुक्लध्यान लगाया। ध्यान के परम प्रताप से चैत्र शुक्ल पंचमी को समस्त कर्मों का क्षय कर वे सिद्धालय (लोक के शिखर) पर विराजमान हुए।"},{number:"२१",tag:"चौपाई (कूट महिमा)",lines:["'सिद्धवर कूट' की भारी महिमा, गाते सब प्रभु की गुण-गरिमा।","जो भी शिखरजी वंदन धावें, वे भव-सागर पार लगावें॥"],meaning:"सम्मेद शिखरजी के जिस 'सिद्धवर कूट' से भगवान अजितनाथ ने निर्वाण प्राप्त किया, उसकी महिमा तीनों लोकों में गाई जाती है। जो भव्य जीव श्रद्धापूर्वक इस कूट की वंदना करते हैं, वे संसार-समुद्र से पार हो जाते हैं।"},{number:"२२",tag:"दोहा (पूर्णाहुति)",lines:["विजित किए श्री अजित ने, अष्ट कर्म बलवान।","निहित आत्मगुण अमित हैं, 'अरुणा' सुख की खान॥","(जाप मंत्र: ॐ ह्रीं अर्हं श्री अजितनाथाय नमः)"],meaning:"भगवान अजितनाथ ने अत्यंत बलवान आठों कर्म-शत्रुओं को विजित कर लिया। उनकी आत्मा में अनंत आत्मिक सुख और ज्ञान के भंडार भरे हैं। कवयित्री 'अरुणा' कहती हैं कि प्रभु का यह नाम-स्मरण समस्त सुखों की शाश्वत खान है।"}]},"anantnath-chalisa":{id:"anantnath-chalisa",category:"chalisa",title:"श्री अनन्तनाथ चालीसा",subtitle:"चौदहवें तीर्थंकर भगवान श्री अनन्तनाथ स्वामी की भक्ति-स्तुति",type:"structured",verses:[{number:"१",tag:"दोहा",lines:["श्री अनन्त जिनराज हैं, गुण अनन्त की खान।","अंतक का भी अंत कर, बने सिद्ध भगवान॥"],meaning:"चौदहवें तीर्थंकर श्री अनन्तनाथ भगवान अनन्त आत्मिक गुणों के अक्षय भण्डार हैं। जिन्होंने जन्म-मरण रूप संसार (अंतक) का पूर्ण नाश करके शाश्वत सिद्ध पद प्राप्त किया है।"},{number:"२",tag:"दोहा",lines:["गुण अनन्त की प्राप्ति हित, करूँ अनन्त प्रणाम।","अनन्त गुणाकर नाथ! तुम, कर दो मम कल्याण॥"],meaning:"अपने भीतर अनन्त गुणों (अनन्त ज्ञान, दर्शन, सुख, वीर्य) को प्रकट करने के लिए मैं प्रभु के चरणों में बारम्बार नमन करता हूँ। हे अनन्त गुणों की खान जिनेन्द्र! मेरा कल्याण कीजिए।"},{number:"३",tag:"दोहा",lines:["विदुषी वागीश्वरी यदि, दे दें आशिर्वाद।","पूरा होवे शीघ्र ही, यह चालीसा पाठ॥"],meaning:"जिनवाणी माता (वागीश्वरी सरस्वती) के पावन आशीर्वाद से यह पवित्र चालीसा पाठ निर्विघ्न पूर्ण हो और भक्तों के हृदय में सम्यक्त्व का प्रकाश फैलाए।"},{number:"४",tag:"चौपाई",lines:["अनन्त चतुष्टय धारी 'अनन्त', अनन्त गुणों की खान 'अनन्त'।","सर्वशुद्ध ज्ञायक हैं अनन्त, हरण करें मम दोष अनन्त॥"],meaning:"अनन्त ज्ञान, अनन्त दर्शन, अनन्त सुख और अनन्त वीर्य रूप अनन्त चतुष्टय के धारक भगवान अनन्तनाथ सर्वशुद्ध ज्ञाता-दृष्टा हैं। वे मेरे अनन्त जन्मों के दोषों और पापों का हरण करें।"},{number:"५",tag:"चौपाई",lines:["नगर अयोध्या महा सुखकार, राज्य करें सिंहसेन अपार।","सर्वयशा महादेवी उनकी, जननी कहलाई जिनवर की॥"],meaning:"परम पावन अयोध्या नगरी में महाप्रतापी राजा सिंहसेन राज्य करते थे। उनकी पटरानी महारानी सर्वयशा थीं, जो तीर्थंकर अनन्तनाथ प्रभु की पूज्य माता बनीं।"},{number:"६",tag:"चौपाई",lines:["द्वादशी ज्येष्ठ कृष्ण सुखकारी, जन्मे तीर्थंकर हितकारी।","इन्द्र प्रभु को गोद में लेकर, न्हवन करें मेरु पर जाकर॥"],meaning:"ज्येष्ठ कृष्णा द्वादशी की मंगल वेला में जगत्कल्याणक तीर्थंकर प्रभु का जन्म हुआ। सौधर्म इन्द्र ने प्रभु को अपनी गोद में लेकर सुमेरु पर्वत पर ले जाकर क्षीरसागर के जल से जन्माभिषेक किया।"},{number:"७",tag:"चौपाई",lines:["नाम 'अनन्तनाथ' शुभ दीना, उत्सव करते नित्य नवीना।","सार्थक हुआ नाम प्रभुवर का, पार नहीं गुण के सागर का॥"],meaning:"देवराज इन्द्र ने प्रभु का शुभ नाम 'अनन्तनाथ' रखा और नित्य नए उत्सव मनाए। प्रभु के अनन्त गुणों के कारण उनका यह नाम पूर्णतः सार्थक हुआ, क्योंकि उनके गुण-सागर का कोई पार नहीं है।"},{number:"८",tag:"चौपाई",lines:["वर्ण सुवर्ण समान प्रभु का, ज्ञान धरें मति-श्रुत-अवधि का।","आयु तीस लख वर्ष उपाई, धनुष अर्धशत तन ऊंचाई॥"],meaning:"प्रभु का देह-वर्ण तपे हुए सुवर्ण के समान कान्तिमान था और वे जन्म से ही मति, श्रुत, अवधि ज्ञान के धनी थे। प्रभु की कुल आयु तीस लाख वर्ष थी तथा शरीर की ऊँचाई पचास धनुष थी।"},{number:"९",tag:"चौपाई",lines:["बचपन गया जवानी आई, राज्य मिला उनको सुखदाई।","हुआ विवाह उनका मंगलमय, जीवन था जिनवर का सुखमय॥"],meaning:"युवावस्था में प्रभु ने न्यायपूर्वक राज्य का संचालन किया। उनका पावन विवाह हुआ और प्रजा को धर्म तथा नीति का मार्ग दिखाते हुए उनका गृहस्थ जीवन आनन्दपूर्वक व्यतीत हुआ।"},{number:"१०",tag:"चौपाई",lines:["पन्द्रह लाख बरस बीते जब, उल्कापात से हुए विरत तब।","जग में सुख पाया किसने-कब, मन से त्याग राग भाव सब॥"],meaning:"पंद्रह लाख वर्ष बीतने पर आकाश में एक तारा टूटते (उल्कापात) देखकर प्रभु को संसार की क्षणभंगुरता का बोध हुआ और उनके मन में संसार के समस्त राग-भावों से परम वैराग्य जागृत हुआ।"},{number:"११",tag:"चौपाई",lines:["बारह भावना मन में भाये, ब्रह्मर्षि वैराग्य बढ़ाये।","'अनन्तविजय' सुत तिलक कराकर, देवोमई शिविका पधरा कर॥"],meaning:"प्रभु ने हृदय में अनित्य आदि बारह भावनाओं का चिंतन किया। लौकान्तिक देवों ने आकर वैराग्य की स्तुति की। अपने पुत्र अनन्तविजय को राजपद सौंपकर प्रभु देवों द्वारा लाई गई पालकी में सवार हुए।"},{number:"१२",tag:"चौपाई",lines:["गए सहेतुक वन जिनराज, दीक्षित हुए सहस नृप साथ।","द्वादशी कृष्ण ज्येष्ठ शुभ मास, तीन दिन का धारा उपवास॥"],meaning:"सहेतुक वन में पधारकर ज्येष्ठ कृष्णा द्वादशी के दिन एक हजार राजाओं के साथ प्रभु ने दिगम्बर जिनदीक्षा अंगीकार की और तीन दिन का निर्जल उपवास धारण किया।"},{number:"१३",tag:"चौपाई",lines:["गए अयोध्या प्रथम योग कर, धन्य 'विशाख' आहार करा कर।","मौन सहित रहते थे वन में, एक दिन तिष्ठे पीपल-तल में॥"],meaning:"तपस्या उपरांत प्रभु अयोध्या पधारे जहाँ विशाख राजा ने उन्हें प्रथम शुद्ध आहार कराकर पंचाश्चर्य प्राप्त किए। प्रभु वन में मौनपूर्वक आत्मध्यान में लीन रहते हुए एक दिन पीपल वृक्ष के नीचे ध्यानस्थ हुए।"},{number:"१४",tag:"चौपाई",lines:["अटल रहे निज योग ध्यान में, झलके लोकालोक ज्ञान में।","कृष्ण अमावस चैत्र मास की, रचना हुई शुभ समवशरण की॥"],meaning:"चार घातिया कर्मों का क्षय कर प्रभु ने केवलज्ञान प्राप्त किया, जिससे लोकालोक उनके ज्ञान में झलकने लगा। चैत्र कृष्णा अमावस्या को कुबेर द्वारा दिव्य समवशरण की रचना की गई।"},{number:"१५",tag:"चौपाई",lines:["जिनवर की वाणी जब खिरती, अमृत सम कानों को लगती।","चतुर्गति दुख चित्रण करते, भविजन सुन पापों से डरते॥"],meaning:"समवशरण में प्रभु की ओंकारमयी दिव्यध्वनि अमृत के समान झरती थी। जब प्रभु ने नरक, तिर्यंच आदि चारों गतियों के दुःखों का वर्णन किया, तो भव्य प्राणी पाप कर्मों से भयभीत होकर धर्म की शरण में आए।"},{number:"१६",tag:"चौपाई",lines:['"जो चाहो तुम मुक्ति पाना, निज आतम की शरण में जाना।','सम्यग्दर्शन-ज्ञान-चरित हैं, कहे व्यवहार में रतनत्रय हैं॥"'],meaning:"प्रभु ने देशना दी: 'यदि भव-बंधनों से मुक्ति चाहते हो तो अपनी शुद्ध आत्मा की शरण लो। व्यवहार नय से सम्यग्दर्शन, सम्यग्ज्ञान और सम्यक्चारित्र को रत्नत्रय कहा गया है।'"},{number:"१७",tag:"चौपाई",lines:['"निश्चय से शुद्धातम ध्याकर, शिवपद मिलता सुख रत्नाकर।"',"श्रद्धा करके भव्य जनों ने, यथाशक्ति व्रत धारे सबने॥"],meaning:"'निश्चय नय से अपनी शुद्धात्मा का ध्यान करने से ही शाश्वत मोक्ष सुख की प्राप्ति होती है।' इस उपदेश पर दृढ़ श्रद्धा कर सभी भव्य जीवों ने अपनी शक्ति अनुसार अणुव्रत और महाव्रत धारण किए।"},{number:"१८",tag:"चौपाई",lines:["हुआ विहार देश और प्रान्त, सत्पथ दर्शायें जिननाथ।","अन्त समय गए सम्मेदाचल, एक मास तक रहे सुनिश्चल॥"],meaning:"प्रभु ने अनेक देशों में विहार कर जीवों को धर्ममार्ग दिखाया। अंत समय में श्री सम्मेद शिखर जी पधारकर एक माह तक प्रतिमा योग धारण कर पूर्ण निश्चल ध्यान में लीन हो गए।"},{number:"१९",tag:"चौपाई",lines:["कृष्ण चैत्र अमावस पावन, मोक्षमहल पहुँचे मनभावन।","उत्सव करते सुरगण आकर, कूट स्वयंप्रभ मन में ध्याकर॥"],meaning:"चैत्र कृष्णा अमावस्या के पावन दिन प्रभु स्वयंप्रभ कूट से अघातिया कर्मों का नाश कर मोक्ष पधारे। देवों ने आकर मोक्षकल्याणक की महापूजा और उत्सव मनाया।"},{number:"२०",tag:"चौपाई",lines:["शुभ लक्षण प्रभुवर का 'सेही', शोभित होता प्रभु-पद में ही।","'अरुणा' अरज करे बस ये ही, पार करो भवसागर से ही॥"],meaning:"प्रभु के पावन चरणों में 'सेही' (साही / शल्यकी) का पावन चिह्न सुशोभित है। भक्त प्रार्थना करते हैं कि हे दयालु नाथ! मुझे इस जन्म-मरण रूपी अपार संसार सागर से पार उतार दीजिए।"},{number:"२१",tag:"चौपाई",lines:["हे प्रभु लोकालोक अनन्त, झलकें सब तुम ज्ञान अनन्त।","हुआ अनन्त भवों का अन्त, अद्भुत तुम महिमा है 'अनन्त'॥"],meaning:"हे प्रभु! आपके अनन्त केवलज्ञान में समस्त लोकालोक प्रतिपादित होता है। आपके दर्शन से अनन्त जन्म-मरण का अंत हो जाता है; हे अनन्तनाथ, आपकी महिमा वास्तव में अनन्त और अनिर्वचनीय है।"},{number:"२२",tag:"जाप मंत्र",lines:["॥ मूल मंत्र एवं जाप ॥","ॐ ह्रीं अर्हं श्री अनन्तनाथाय नमः।"],meaning:"अनन्त चतुष्टय के स्वामी, चौदहवें तीर्थंकर भगवान श्री अनन्तनाथ जी के पावन चरणों में मेरा बारम्बार नमस्कार हो।"}]},"aranath-chalisa":{id:"aranath-chalisa",category:"chalisa",title:"श्री अरहनाथ चालीसा",subtitle:"अठारहवें तीर्थंकर भगवान श्री अरहनाथ स्वामी की भक्ति-स्तुति",type:"structured",verses:[{number:"१",tag:"दोहा",lines:["अरहनाथ भगवान हैं, तीनलोक के नाथ।","ध्यानचक्र से मृत्यु को, किया पराजित आप॥"],meaning:"अठारहवें तीर्थंकर श्री अरहनाथ भगवान तीनों लोकों के स्वामी हैं। जिन्होंने आत्म-ध्यान रूपी सुदर्शन चक्र से जन्म-मरण रूपी संसार चक्र और मृत्यु को पराजित कर शाश्वत मोक्ष पद प्राप्त किया।"},{number:"२",tag:"दोहा",lines:["हस्तिनापुर तीर्थ पर, हुए चार कल्याण।","गर्भ-जन्म-तप और है, चौथा केवलज्ञान॥"],meaning:"परम पावन हस्तिनापुर तीर्थ भूमि पर प्रभु के चार महा कल्याणक—गर्भ, जन्म, तप और केवलज्ञान कल्याणक संपन्न हुए, जिससे यह धरा परम पावन बनी।"},{number:"३",tag:"दोहा",lines:["अरहनाथ तीर्थेश भी, त्रयपदवीयुत नाथ।","तीर्थंकर-चक्री तथा, कामदेव जगमान्य॥"],meaning:"प्रभु अरहनाथ एक ही भव में तीर्थंकर, चक्रवर्ती और कामदेव—इन तीन सर्वोच्च पदवियों से विभूषित होकर जगत में परम पूज्य एवं वन्दनीय हुए।"},{number:"४",tag:"दोहा",lines:["इनके ही गुणगान में, यह चालीसा पाठ।","लिखने की इच्छा हुई, कृपा करो श्रुतमात॥"],meaning:"ऐसे महान त्रिपदवीधारी प्रभु अरहनाथ के पावन गुणों का गान करने हेतु यह चालीसा पाठ रचा जा रहा है। हे श्रुतदेवी जिनवाणी माता! मुझ पर अपनी वात्सल्यमयी कृपा कीजिए।"},{number:"५",tag:"चौपाई",lines:["श्री अरहनाथ जिनेन्द्र गुणाकर, ज्ञान-दरस-सुख-बल रत्नाकर।","कल्पवृक्ष सम सुख के सागर, पार हुए निज आत्म ध्याकर॥"],meaning:"श्री अरहनाथ जिनेन्द्र अनन्त गुणों की खान हैं तथा अनन्त ज्ञान, दर्शन, सुख और वीर्य के रत्नाकर हैं। वे कल्पवृक्ष के समान भव्य जीवों को आत्मसुख प्रदान करने वाले और निज आत्मध्यान से संसार सागर पार करने वाले हैं।"},{number:"६",tag:"चौपाई",lines:["अरहनाथ वसु अरि के नाशक, हुए हस्तिनापुर के शासक।","माँ मित्रसेना पिता सुदर्शन, चक्रवर्ती बन किया दिग्दर्शन॥"],meaning:"आठ कर्म रूपी शत्रुओं का नाश करने वाले प्रभु अरहनाथ के पिता राजा सुदर्शन और माता महारानी मित्रसेना थीं। प्रभु ने हस्तिनापुर के चक्रवर्ती सम्राट् बनकर सम्पूर्ण छह खण्डों पर धर्ममय शासन किया।"},{number:"७",tag:"चौपाई",lines:["सहस चौरासी आयु प्रभु की, अवगाहना थी तीस धनुष की।","वर्ण सुवर्ण समान था पीत, रोग शोक थे तुमसे भीत॥"],meaning:"प्रभु की कुल आयु चौरासी हजार वर्ष और शरीर की ऊँचाई तीस धनुष थी। प्रभु का देह-वर्ण तपे हुए सुवर्ण के समान पीत-कांति लिए था तथा उनके प्रभाव से रोग-शोक कोसों दूर रहते थे।"},{number:"८",tag:"चौपाई",lines:["ब्याह हुआ जब प्रिय कुमार का, स्वप्न हुआ साकार पिता का।","राज्याभिषेक हुआ अरहजिन का, हुआ अभ्युदय चक्र रत्न का॥"],meaning:"युवावस्था में प्रभु का मंगल विवाह संपन्न हुआ और पिता का स्वप्न साकार हुआ। अरहनाथ का राज्याभिषेक हुआ और उनकी आयुधशाला में चौदह रत्नों में प्रमुख चक्ररत्न का अभ्युदय हुआ।"},{number:"९",tag:"चौपाई",lines:["एक दिन देखा शरद ऋतु में, मेघ विलीन हुए क्षण भर में।","उदित हुआ वैराग्य हृदय में, लौकान्तिक सुर आए पल में॥"],meaning:"शरद ऋतु में आकाश में बादलों को क्षण भर में विलीन होते देखकर प्रभु को संसार के भोगों की अनित्यता का बोध हुआ। हृदय में वैराग्य जागते ही लौकान्तिक देवों ने आकर उनके त्याग की स्तुति की।"},{number:"१०",tag:"चौपाई",lines:["'अरविन्द' पुत्र को देकर राज, गए सहेतुक वन जिनराज।","मंगसिर की दशमी उजियारी, परम दिगम्बर दीक्षाधारी॥"],meaning:"अपने सुपुत्र अरविन्द को राज्यभार सौंपकर प्रभु सहेतुक वन पधारे और मार्गशीर्ष शुक्ल दशमी के शुभ दिन एक हजार राजाओं के साथ निर्ग्रन्थ दिगम्बर दीक्षा धारण की।"},{number:"११",tag:"चौपाई",lines:["पंचमुष्टि उखाड़े केश, तन से ममत्व रहा नहीं लेश।","नगर चक्रपुर गए पारण हित, पड़गाहें भूपति अपराजित॥"],meaning:"प्रभु ने पंचमुष्टि केशलोंच किया और देह से किंचित् मात्र भी ममत्व नहीं रखा। पारणा हेतु चक्रपुर नगर पधारने पर राजा अपराजित ने नवधा भक्ति से पड़गाहन कर प्रभु को आहार दिया।"},{number:"१२",tag:"चौपाई",lines:["प्रासुक शुद्धाहार कराये, पंचाश्चर्य देव कराये।","कठिन तपस्या करते वन में, लीन रहें आत्म चिन्तन में॥"],meaning:"राजा अपराजित द्वारा प्रासुक शुद्ध आहार कराने पर देवों ने रत्नवृष्टि आदि पंचाश्चर्य किए। इसके उपरांत प्रभु वन में घोर तपस्या करते हुए सदैव आत्म-चिंतन में लीन रहे।"},{number:"१३",tag:"चौपाई",lines:["कार्तिक मास द्वादशी उज्जवल, प्रभु विराजे आम्र वृक्ष-तल।","अन्तर ज्ञान ज्योति प्रगटाई, हुए केवली श्री जिनराई॥"],meaning:"सोलह वर्ष की मौन तपस्या के बाद कार्तिक शुक्ल द्वादशी को आम्र वृक्ष के नीचे प्रभु ने चार घातिया कर्मों का नाश कर दिया और केवलज्ञान रूपी दिव्य सूर्य प्रगट हुआ।"},{number:"१४",tag:"चौपाई",lines:["देव करें उत्सव अति भव्य, समवसरण की रचना दिव्य।","सोलह वर्ष का मौनभंग कर, सप्तभंग जिनवाणी सुखकर॥"],meaning:"देवों ने केवलज्ञान कल्याणक का भव्य उत्सव मनाया और कुबेर ने दिव्य समवशरण की रचना की। प्रभु ने अपना मौन त्यागकर स्याद्वाद और सप्तभंग रूपी परम सुखकारी जिनवाणी की वर्षा की।"},{number:"१५",tag:"चौपाई",lines:["चौदह गुणस्थान बताये, मोह-काय-योग दर्शाये।","सत्तावन आश्रव बतलाये, इतने ही संवर गिनवाये॥"],meaning:"प्रभु ने आत्म-विकास के चौदह गुणस्थान, कषाय, योग, सत्तावन प्रकार के कर्म-आस्रव और कर्मों को रोकने वाले सत्तावन प्रकार के संवर का सूक्ष्म विवेचन किया।"},{number:"१६",tag:"चौपाई",lines:["संवर हेतु समता लाओ, अनुप्रेक्षा द्वादश मन भाओ।","हुए प्रबुद्ध सभी नर-नारी, दीक्षा व्रत धरि बहु भारी॥"],meaning:"प्रभु ने उपदेश दिया कि संवर की प्राप्ति के लिए मन में समता भाव लाओ और अनित्यादि बारह अनुप्रेक्षाओं का चिंतन करो। इस पावन देशना को सुनकर असंख्य नर-नारियों ने व्रत व दीक्षा ग्रहण की।"},{number:"१७",tag:"चौपाई",lines:["कुम्भार्प आदि गणधर तीस, अर्द्ध लक्ष थे सकल मुनीश।","सत्यधर्म का हुआ प्रचार, दूर-दूर तक हुआ विहार॥"],meaning:"प्रभु के समवशरण में कुम्भ आदि तीस प्रमुख गणधर और पचास हजार निर्ग्रन्थ मुनिराज थे। प्रभु ने दूर-दूर तक विहार कर सम्पूर्ण आर्यावर्त में अहिंसा और सत्य धर्म का प्रकाश फैलाया।"},{number:"१८",tag:"चौपाई",lines:["एक माह पहले निर्वेद, सहस मुनिसंग गए सम्मेद।","चैत्र कृष्ण एकादशी के दिन, मोक्ष गए श्री अरहनाथ जिन॥"],meaning:"आयु का एक माह शेष रहने पर प्रभु एक हजार मुनियों के साथ श्री सम्मेद शिखर जी पधारे और प्रतिमा योग धारण किया। चैत्र कृष्णा एकादशी को प्रभु ने निर्वाण पद प्राप्त किया।"},{number:"१९",tag:"चौपाई",lines:["नाटक कूट को पूजे देव, कामदेव-चक्री-जिनदेव।","जिनवर का लक्षण था मीन, धारो जैन धर्म समीचीन॥"],meaning:"शिखर जी के पावन 'नाटक कूट' से मोक्ष पधारने पर देवों ने मोक्षकल्याणक पूजा की। प्रभु का पावन लक्षण (लांछन) 'मत्स्य' (मीन) है; प्रभु की शरण पाकर सभी सम्यग्दर्शन धारण करें।"},{number:"२०",tag:"चौपाई",lines:["प्राणी मात्र का जैन धर्म है, जैन धर्म ही परम धर्म है।","पंचेन्द्रियों को जीतें जो नर, जिनेन्द्रिय वे बनते जिनवर॥"],meaning:"जैन धर्म सम्पूर्ण चराचर प्राणियों के कल्याण का सार्वभौमिक धर्म है। जो मानव अपनी पाँचों इन्द्रियों और मन को जीत लेते हैं, वे ही जितेन्द्रिय होकर जिनवर पद प्राप्त करते हैं।"},{number:"२१",tag:"चौपाई",lines:["त्याग धर्म की महिमा गाई, त्याग में ही सब सुख हों भाई।","त्याग कर सकें केवल मानव, संयम से पावें शिव वैभव॥"],meaning:"प्रभु ने त्याग धर्म की सर्वोच्च महिमा बताई कि वास्तव में त्याग और अनासक्ति में ही सच्चा सुख है। मनुष्य जन्म पाकर ही जीव संयम और त्याग द्वारा मोक्ष रूपी परम वैभव को प्राप्त कर सकता है।"},{number:"२२",tag:"चौपाई",lines:["हो स्वाधीन तजो तुम भाई, बन्धन में पीडा मन लाई।","हस्तिनापुर में दूसरी नशिया, कर्म जहाँ पर नसे घातिया॥"],meaning:"संसार के पराधीन बंधनों को त्यागकर अपनी आत्मा में स्वाधीन बनो। हस्तिनापुर तीर्थ की पावन निश्या जी की वन्दना करो, जहाँ प्रभु ने तपस्या कर चारों घातिया कर्मों का नाश किया था।"},{number:"२३",tag:"दोहा",lines:["जिनके चरणों में धरें, शीश सभी नरनाथ।","हम सब पूजे उन्हें, कृपा करें अरहनाथ॥"],meaning:"जिनके पावन चरणों में चक्रवर्ती और समस्त नरेन्द्र-सुरेन्द्र अपना मस्तक झुकाते हैं, हम सब उन दयालु भगवान अरहनाथ की वन्दना करते हैं; प्रभु हम पर अपनी कृपा दृष्टि बनाए रखें।"},{number:"२४",tag:"जाप मंत्र",lines:["॥ मूल मंत्र एवं ध्यान ॥","ॐ ह्रीं अर्हं श्री अरहनाथाय नमः।"],meaning:"अठारहवें तीर्थंकर, चक्रवर्ती एवं कामदेव पदधारी भगवान श्री अरहनाथ जी के पावन चरणों में मेरा अनंत बार नमन हो।"}]},"chandraprabhu-chalisa":{id:"chandraprabhu-chalisa",category:"chalisa",title:"श्री चन्द्रप्रभु चालीसा (दोहा, चौपाई एवं भावार्थ सहित)",subtitle:"अतिशय क्षेत्र तिजारा (देहरा) अष्टम तीर्थंकर चन्द्रप्रभु चालीसा",type:"structured",verses:[{number:"दोहा",lines:["दोहा","वीतराग सर्वज्ञ जिन, जिनवाणी को ध्याय।","लिखने का साहस करुं, चालीसा सिर नाय॥","देहरे के श्रीचन्द्र को, पूजौं मन वच काय।","ऋद्धि सिद्धि मंगल करें, विघ्न दूर हो जाय॥"],meaning:"वीतरागी, सर्वज्ञ भगवान जिनेन्द्र तथा मोक्षमार्ग-प्रकाशिनी जिनवाणी माता का ध्यान कर, शीश नवाकर इस चालीसा की रचना का उद्यम करता हूँ। तिजारा देहरा के चमत्कारी अष्टम तीर्थंकर श्री चन्द्रप्रभु भगवान की मन, वचन, काय से पूजा-अर्चना करता हूँ, वे हमारे जीवन में आत्मिक ऋद्धि-सिद्धि और मंगल करें तथा समस्त विघ्नों का नाश करें।"},{number:"१",lines:["चौपाई","जय श्रीचन्द्र दया के सागर। देहरे वाले ज्ञान उजागर॥","शांति छवि मूरति अति प्यारी। भेष दिगम्बर धारा भारी॥"],meaning:"हे करुणा के सागर श्री चन्द्रप्रभु भगवान! आपकी सदा जय हो। हे तिजारा देहरा में प्रगट केवलज्ञान-प्रकाशी प्रभु! आपकी शांत, वीतरागी और मनमोहक मुद्रा अत्यंत प्रिय है; आपने परिग्रह-मुक्त परम पावन दिगंबर भेष धारण किया है।"},{number:"२",lines:["नासा पर है दृष्टि तुम्हारी। मोहनी मूरति कितनी प्यारी॥","देवों के तुम देव कहावो। कष्ट भक्त के दूर हटावो॥"],meaning:"आपकी दृष्टि नासाग्र (नासिका के अग्रभाग) पर स्थिर होकर अंतर्मुखी आत्म-ध्यान में लीन है; आपकी यह सौम्य वीतराग मुद्रा हृदय को हरने वाली है। आप तीनों लोकों के देवों के भी पूज्य देवाधिदेव हैं, अपने भक्तों के सभी संकट व कष्टों का निवारण कीजिए।"},{number:"३",lines:["समन्तभद्र मुनिवर ने ध्याया। पिंडी फटी दर्श तुम पाया॥","तुम जग में सर्वज्ञ कहावो। अष्टम तीर्थंकर कहलावो॥"],meaning:"प्राचीन काल में वाराणसी में जब महान तार्किक आचार्य समन्तभद्र स्वामी ने भस्मक व्याधि निवारण हेतु 'स्वयंभू स्तोत्र' द्वारा आपका ध्यान किया, तो पाषाण की पिंडी फट गई और आपके साक्षात् चन्द्रप्रभु जिनबिंब के दर्शन हुए। आप संसार में सर्वज्ञ और जैन धर्म के आठवें तीर्थंकर कहलाते हैं।"},{number:"४",lines:["महासेन के राजदुलारे। मात सुलक्षणा के हो प्यारे॥","चन्द्रपुरी नगरी अति नामी। जन्म लिया चन्द्र-प्रभु स्वामी॥"],meaning:"आप इक्ष्वाकु वंशीय राजा महासेन के राजदुलारे पुत्र तथा महारानी सुलक्षणा देवी के नयनों के तारे (परम प्रिय) हैं। पावन गंगा तट पर स्थित प्रसिद्ध चन्द्रपुरी (चन्द्रावती) नगरी में आपने तीर्थंकर रूप में जन्म लिया।"},{number:"५",lines:["पौष वदी ग्यारस को जन्मे। नर नारी हरषे तब मन में॥","काम क्रोध तृष्णा दुखकारी। त्याग सुखद मुनि दीक्षा धारी॥"],meaning:"पौष कृष्ण एकादशी के मंगल दिन आपका जन्म हुआ, जिससे तीनों लोकों के देवों और नर-नारियों के मन में अपार हर्ष छा गया। युवावस्था में संसार के काम, क्रोध और तृष्णा रूपी दुःखों की असारता जानकर आपने राजवैभव त्यागकर परम कल्याणकारी दिगंबर मुनि दीक्षा धारण की।"},{number:"६",lines:["फाल्गुन वदी सप्तमी भाई। केवल ज्ञान हुआ सुखदाई॥","फिर सम्मेद शिखर पर जाके। मोक्ष गये प्रभु आप वहां से॥"],meaning:"घोर तपस्या के पश्चात फाल्गुन कृष्ण सप्तमी के पावन दिन आपको लोकालोक-प्रकाशी केवलज्ञान प्राप्त हुआ। तत्पश्चात समवसरण में धर्मोपदेश देकर सम्मेद शिखर जी के ललित कूट से आपने निर्वाण (मोक्ष) पद प्राप्त किया।"},{number:"७",lines:["लोभ मोह और छोड़ी माया। तुमने मान कषाय नसाया॥","रागी नहीं, नहीं तू द्वेषी। वीतराग तू हित उपदेशी॥"],meaning:"आपने माया, लोभ, मोह और मान आदि समस्त कषायों का समूल नाश कर दिया। आप न किसी के प्रति राग रखते हैं और न किसी से द्वेष; आप पूर्ण वीतरागी होकर प्राणिमात्र के परम हितैषी और हितोपदेशी हैं।"},{number:"८",lines:["पंचम काल महा दुखदाई। धर्म कर्म भूले सब भाई॥","अलवर प्रान्त में नगर तिजारा। होय जहां पर दर्शन प्यारा॥"],meaning:"वर्तमान पंचम काल (कलिकाल) अत्यंत दुःखदायी है, जिसमें संसारी प्राणी सच्चे धर्म और सदाचार के संस्कारों को भूलते जा रहे हैं। ऐसे समय में राजस्थान के अलवर जिले का तिजारा नगर वह पावन क्षेत्र बना, जहाँ प्रभु के इस अलौकिक रूप के दर्शन होते हैं।"},{number:"९",lines:["उत्तर दिशि में देहरा माहीं। वहां आकर प्रभुता प्रगटाई॥","सावन सुदि दशमि शुभ नामी। प्रकट भये त्रिभुवन के स्वामी॥"],meaning:"तिजारा के उत्तर दिशा में स्थित 'देहरा' नामक स्थान पर भूगर्भ से आपने अपनी प्रभुता प्रकट की। संवत २०१३ (सन १९५६ ई.) के श्रावण शुक्ल दशमी के पुण्य दिवस पर भूगर्भ से खुदाई के दौरान तीनों लोकों के स्वामी भगवान चन्द्रप्रभु का पावन जिनबिंब प्रकट हुआ।"},{number:"१०",lines:["चिह्न चन्द्र का लख नर नारी। चंद्रप्रभु की मूरती मानी॥","मूर्ति आपकी अति उजयाली। लगता हीरा भी है जाली॥"],meaning:"प्रतिमा की पाषाण-पीठिका पर अर्ध-चंद्रमा का पावन लांछन देखकर सभी नर-नारियों ने पहचाना कि यह आठवें तीर्थंकर श्री चन्द्रप्रभु की प्रतिमा है। श्वेत पाषाण की आपकी यह प्रतिमा इतनी उज्ज्वल, चमकीली और कांतिमान है कि उसके सामने बहुमूल्य हीरा भी फीका जान पड़ता है।"},{number:"११",lines:["अतिशय चन्द्र प्रभु का भारी। सुनकर आते यात्री भारी॥","फाल्गुन सुदी सप्तमी प्यारी। जुड़ता है मेला यहां भारी॥"],meaning:"तिजारा के श्री चन्द्रप्रभु का अतिशय और महिमा इतनी महान है कि देश-विदेश से लाखों श्रद्धालु यहाँ खिंचे चले आते हैं। फाल्गुन शुक्ल सप्तमी के पावन अवसर पर यहाँ विशाल वार्षिक मेला और रथोत्सव आयोजित होता है।"},{number:"१२",lines:["कहलाने को तो शशि धर हो। तेज पुंज रवि से बढ़कर हो॥","नाम तुम्हारा जग में सांचा। ध्यावत भागत भूत पिशाचा॥"],meaning:"यद्यपि आपका लांछन शांत चंद्रमा (शशि) है, किंतु आपके आत्म-तेज और प्रभाव का पुंज प्रखर सूर्य से भी अधिक तेजस्वी है। संसार में केवल आपका वीतराग नाम ही सच्चा सहारा है; आपका स्मरण करते ही समस्त भय, भूत, पिशाच और नकारात्मक शक्तियाँ दूर भाग जाती हैं।"},{number:"१३",lines:["राक्षस भूत प्रेत सब भागें। तुम सुमिरत भय कभी न लागे॥","कीर्ति तुम्हारी है अति भारी। गुण गाते नित नर और नारी॥"],meaning:"प्रभु का नाम लेते ही सभी प्रकार के उपद्रव, भय और दुष्ट बाधाएं नष्ट हो जाती हैं तथा साधक निर्भय हो जाता है। आपकी यश-कीर्ति तीनों लोकों में व्याप्त है, और भक्त नर-नारी नित्य श्रद्धा से आपके गुणों का गान करते हैं।"},{number:"१४",lines:["जिस पर होती कृपा तुम्हारी। संकट झट कटता ही भारी॥","जो भी जैसी आश लगाता। पूरी उसे तुरत कर पाता॥"],meaning:"जिस भव्य आत्मा पर आपकी वीतरागी करुणा और पुण्य-प्रताप की दृष्टि होती है, उसके बड़े से बड़े भारी संकट भी क्षणभर में कट जाते हैं। जो भक्त शुद्ध हृदय से जैसी शुभ कामना लेकर आपके द्वार आता है, उसकी वह धर्मयुक्त अभिलाषा शीघ्र पूर्ण होती है।"},{number:"१५",lines:["दुखिया दर पर जो आते हैं। संकट सब खो कर जाते हैं॥","खुला सभी हित प्रभु द्वार है। चमत्कार को नमस्कार है॥"],meaning:"संसार के सताए हुए दुखी प्राणी जब आपके पावन दरबार में आते हैं, तो अपने समस्त आधि-व्याधि-उपाधि रूपी कष्टों को यहीं छोड़कर आनंदपूर्वक लौटते हैं। प्राणिमात्र के कल्याण के लिए आपका द्वार सदा खुला है; आपके इस प्रत्यक्ष अतिशय को सारा संसार नतमस्तक होकर वंदन करता है।"},{number:"१६",lines:["अन्धा भी यदि ध्यान लगावे। उसके नेत्र शीघ्र खुल जावें॥","बहरा भी सुनने लग जावे। पगले का पागलपन जावे॥"],meaning:"यदि कोई दृष्टिहीन श्रद्धा से प्रभु का ध्यान करे तो उसकी अंतर और बाह्य दृष्टियां निर्मल हो जाती हैं। बहरे को श्रवण शक्ति प्राप्त होती है और मानसिक रोग से पीड़ित विक्षिप्त व्यक्ति का उन्माद शांत होकर उसे मानसिक स्वास्थ्य मिलता है।"},{number:"१७",lines:["अखंड ज्योति का घृत जो लगावे। संकट उसका सब कट जावे॥","चरणों की रज अति सुखकारी। दुख दरिद्र सब नाशनहारी॥"],meaning:"देहरा तिजारा में जलने वाली अखंड ज्योति का पवित्र घृत जो श्रद्धापूर्वक नेत्रों व अंगों पर लगाता है, उसके असाध्य रोग व कष्ट दूर होते हैं। प्रभु के चरणों की पावन रज परम सुखकारी है, जो जन्म-जन्मांतर के दुःख और दरिद्रता का नाश करने वाली है।"},{number:"१८",lines:["चालीसा जो मन से ध्यावे। पुत्र पौत्र सब सम्पति पावे॥","पार करो दुखियों की नैया। स्वामी तुम बिन नहीं खिवैया॥"],meaning:"जो भव्य जीव एकाग्र मन से इस चालीसा का नित्य पाठ करता है, उसे उत्तम संतान, कुल की वृद्धि और धर्मयुक्त वैभव प्राप्त होता है। हे नाथ! संसार रूपी अथाह समुद्र में डूबती हुई हम दुखियों की नैया को पार लगाइए, क्योंकि आपके अतिरिक्त हमारा कोई अन्य खेवनहार नहीं है।"},{number:"१९",lines:["प्रभु मैं तुम से कुछ नहिं चाहूं। दर्श तिहारा निश दिन पाऊँ॥","आवागमन मिटाओ मेरा। काटो प्रभु चौरासी फेरा॥"],meaning:"हे प्रभु! मैं आपसे कोई नश्वर सांसारिक भोग नहीं चाहता, केवल यही वरदान माँगता हूँ कि मुझे रात-दिन आपके वीतराग स्वरूप का दर्शन और स्मरण प्राप्त हो। मेरे चौरासी लाख योनियों के जन्म-मरण (आवागमन) का अंत कर मुझे अपनी शाश्वत मुक्ति का मार्ग दीजिए।"},{number:"२०",lines:["करुं वन्दना आपकी, श्रीचन्द्र प्रभु जिनराज।","जंगल में मंगल कियो, रखो 'सुरेश' की लाज॥"],meaning:"हे देवाधिदेव श्रीचन्द्रप्रभु जिनराज! मैं दोनों हाथ जोड़कर आपके पावन चरणों की वंदना करता हूँ। आपने तिजारा के निर्जन टीलों व जंगल में मंगलमय तीर्थ की रचना कर दी; मुझ दास 'सुरेश' की लाज रखकर मुझे अपनी शरण में विश्राम दीजिए।"},{number:"सोरठा",lines:["सोरठा","पाठ करे चालीस दिन, नित चालीस ही बार।","तिजारा में आय के, खेवे धूप अपार॥","होय कुबेर समान, जन्म दरिद्री होय जो।","जिसके नहिं संतान, नाम वंश जग में चले॥"],meaning:"जो भव्य जीव चालीस दिनों तक प्रतिदिन चालीस बार इस चालीसा का पाठ करता है अथवा अतिशय क्षेत्र तिजारा (देहरा) में आकर प्रभु के सन्मुख सुगंधित धूप खेता है—वह यदि जन्मांतर का दरिद्री भी हो तो धनवान बन जाता है, और जिसके संतान न हो, उसके कुल और धर्म की परंपरा संसार में सुशोभित होती है।"}]},"dharmanath-chalisa":{id:"dharmanath-chalisa",category:"chalisa",title:"श्री धर्मनाथ चालीसा",subtitle:"पंद्रहवें तीर्थंकर भगवान श्री धर्मनाथ स्वामी की भक्ति-स्तुति",type:"structured",verses:[{number:"१",tag:"दोहा",lines:["धर्मनाथ तीर्थेश को, वन्दूँ बारम्बार।","धर्मध्यान को प्राप्त कर, हो जाऊँ भवपार॥"],meaning:"पंद्रहवें तीर्थंकर भगवान श्री धर्मनाथ जी के पावन चरणों में बारम्बार वन्दन करता हूँ। प्रभु के पावन धर्मध्यान को हृदय में धारण कर मैं संसार-सागर से पार उतर जाऊँ।"},{number:"२",tag:"दोहा",lines:["धर्मनाथ भगवान का, चालीसा सुखकार।","पढ़ो सभी भव्यात्मा, करो आत्म उद्धार॥"],meaning:"भगवान धर्मनाथ का यह चालीसा पाठ परम सुख और शांति देने वाला है। सभी भव्य आत्माएँ इसका श्रद्धापूर्वक पाठ कर अपना आत्म-कल्याण करें।"},{number:"३",tag:"दोहा",lines:["धर्मनाथ भगवान हैं, धर्मचक्र के ईश।","इनके चरण सरोज को, नमूँ नमाकर शीश॥"],meaning:"भगवान धर्मनाथ धर्मचक्र के अधिपति और तीनों लोकों के नाथ हैं। उनके कमलवत पावन चरणों में मैं अपना शीश झुकाकर अनंत बार नमन करता हूँ।"},{number:"४",tag:"दोहा",lines:["धर्मध्वजा फहराई है, अखिल विश्व में नाथ!","शत इन्द्रों से वंद्य प्रभू जी, असुरों द्वारा पूज्य प्रभू जी॥"],meaning:"हे नाथ! आपने सम्पूर्ण विश्व में वीतराग धर्म की पावन ध्वजा फहराई है। आप सौ इन्द्रों और चारों निकाय के देवों द्वारा नित्य पूजित और वन्दनीय हैं।"},{number:"५",tag:"चौपाई",lines:["उत्तम क्षमा आदि दस धर्मी। प्रगटे मूर्तिमान श्रीधर्म।","जग से हरण करें सब अधर्म। शाश्वत सुख दें प्रभुवर धर्म॥"],meaning:"उत्तम क्षमादि दसलक्षण धर्म के साक्षात् स्वरूप भगवान धर्मनाथ संसार से समस्त अधर्म और अज्ञान का नाश करते हैं तथा भव्य जीवों को शाश्वत मोक्षसुख प्रदान करते हैं।"},{number:"६",tag:"चौपाई",lines:["नगर रत्नपुर के शासक थे। भूपति भानु प्रजापालक थे।","महादेवी सुव्रता अभिन्न। पुत्र-अभाव से रहतीं खिन्न॥"],meaning:"रत्नपुर नगर के परम न्यायप्रिय राजा भानु अपनी प्रजा का पुत्रवत पालन करते थे। उनकी पटरानी महारानी सुव्रता थीं, जो पुत्र न होने के कारण मन में खिन्न रहती थीं।"},{number:"७",tag:"चौपाई",lines:["'प्राचेतस' मुनि अवधिलीन। मात-पिता को धीरज दीन।",'"पुत्र तुम्हारे हों क्षेमकर। जग में कहलायें तीर्थंकर॥"'],meaning:"अवधिज्ञानी मुनिराज प्राचेतस ने माता-पिता को ढाढ़स बंधाते हुए कहा: 'हे राजन्! आपके कुल में सम्पूर्ण जगत का कल्याण करने वाले तीर्थंकर पुत्र का जन्म होगा।'"},{number:"८",tag:"चौपाई",lines:["धीरज हुआ दम्पति-मन में। साधु-वचन हों सत्य जगत में।","'मोह' 'सुरम्य' विमान से तजकर। जननी उदर बसे प्रभु आकर॥"],meaning:"मुनिराज के वचनों से माता-पिता को परम धैर्य प्राप्त हुआ। प्रभु वैजयंत विमान से च्युत होकर वैशाख शुक्ल सप्तमी को माता सुव्रता के गर्भ में पधारे।"},{number:"९",tag:"चौपाई",lines:["तत्क्षण सब देवों के परिकर। गर्भकल्याणक करें खुश होकर।","तेरस माघ मास उजियारी। जन्मे तीन ज्ञान के धारी॥"],meaning:"देवों ने आकर रत्नपुर में गर्भ कल्याणक महोत्सव मनाया। माघ शुक्ल त्रयोदशी के शुभ प्रभात में मति, श्रुत, अवधि ज्ञान के धारक तीर्थंकर बालक का जन्म हुआ।"},{number:"१०",tag:"चौपाई",lines:["तीन भुवन द्युति छाई न्यारी। सब ही जीवों को सुखकारी।","माता को निद्रा में सुलाकर। लिया शची ने गोद में आकर॥"],meaning:"तीनों लोकों में दिव्य ज्योति छा गई और नारकियों को भी क्षण भर के लिए शांति मिली। इन्द्राणी शची ने माता को योगनिद्रा में सुलाकर बालक को अपनी गोद में लिया।"},{number:"११",tag:"चौपाई",lines:["मेरु पर अभिषेक कराया। 'धर्मनाथ' शुभ नाम धराया।","देख शिशु-सौन्दर्य अपार। किये इन्द्र ने नयन हजार॥"],meaning:"सुमेरु पर्वत पर एक हजार आठ कलशों से प्रभु का जन्माभिषेक हुआ और प्रभु का नाम 'धर्मनाथ' रखा गया। प्रभु के अनुपम रूप को निहारने के लिए इन्द्र ने सहस्र नेत्र बना लिए।"},{number:"१२",tag:"चौपाई",lines:["बीता बचपन यौवन आया। अद्भुत आकर्षक तन पाया।","पिता ने तब युवराज बनाया। राज-काज उनको समझाया॥"],meaning:"बाल्यकाल व्यतीत होने पर प्रभु का सौन्दर्यमयी यौवन खिला। पिता राजा भानु ने उन्हें युवराज पद पर अभिषिक्त कर राज-काज का दायित्व सौंपा।"},{number:"१३",tag:"चौपाई",lines:["चित्र श्रृंगारवती का लेकर। दूत सभा में बैठा आकर।","स्वयंवर हेतु निमन्त्रण देकर। गया नाथ की स्वीकृति लेकर॥"],meaning:"राजकन्या शृंगारवती का चित्र लेकर दूत राजसभा में आया और स्वयंवर का निमंत्रण दिया। प्रभु की मौन स्वीकृति लेकर दूत आनंदपूर्वक लौटा।"},{number:"१४",tag:"चौपाई",lines:["मित्र प्रभाकर को संग लेकर। कुण्डिनपुर को गए धर्म-वर।","शृंगारवती ने वरा प्रभु को। पुष्पक यान पे आए घर को॥"],meaning:"मित्र प्रभाकर के साथ प्रभु कुण्डिनपुर पधारे जहाँ शृंगारवती ने प्रभु के गले में वरमाला डाली। पुष्पक विमान पर आरूढ़ होकर प्रभु राजधानी पधारे।"},{number:"१५",tag:"चौपाई",lines:["मात-पिता करें हार्दिक प्यार। प्रजाजनों ने किया सत्कार।","सर्वप्रिय था उनका शासन। नीति सहित करते प्रजापालन॥"],meaning:"माता-पिता और प्रजाजनों ने प्रभु का भावभीना स्वागत किया। प्रभु का शासन सर्वप्रिय, धर्ममय और न्याय-नीति से परिपूर्ण था।"},{number:"१६",tag:"चौपाई",lines:["उल्कापात देखकर एक दिन। भोग-विमुख हो गए श्री जिन।","सुत 'सुधर्म' को सौंपा राज। शिविका में प्रभु गए विराज॥"],meaning:"एक दिन उल्कापात देखकर प्रभु का मन संसार के क्षणभंगुर भोगों से विरक्त हो गया। अपने सुपुत्र सुधर्म को राज्य सौंपकर प्रभु देव-निर्मित पालकी में आरूढ़ हुए।"},{number:"१७",tag:"चौपाई",lines:["चलते संग सहस नृपराज। गए शालवन में जिनराज।","शुक्ल त्रयोदशी माघ महीना। सन्ध्या समय मुनि पदवी गहीना॥"],meaning:"एक हजार राजाओं के साथ शालवन पधारकर माघ शुक्ल त्रयोदशी की पावन संध्या में प्रभु ने दिगम्बर मुनि दीक्षा अंगीकार की।"},{number:"१८",tag:"चौपाई",lines:["दो दिन रहे ध्यान में लीना। दिव्य दीप्ति धरें वस्त्र विहीना।","तीसरे दिन हेतु आहार। पाटलिपुत्र को हुआ विहार॥"],meaning:"दो दिन तक निर्जल उपवास और आत्मध्यान में लीन रहकर तीसरे दिन प्रभु आहारचर्या हेतु पाटलिपुत्र नगर में पधारे।"},{number:"१९",tag:"चौपाई",lines:["अन्तराय बत्तीस निखार। धन्यसेन नृप दें आहार।","मौन अवस्था रहती प्रभु की। कठिन तपस्या दो वर्ष की॥"],meaning:"बत्तीस अंतरायों को टालकर राजा धन्यसेन ने प्रभु को प्रथम शुद्ध आहार कराया। प्रभु ने दो वर्षों तक मौनपूर्वक आत्मसाधना और घोर तप किया।"},{number:"२०",tag:"चौपाई",lines:["पूरणमासी पौष मास की। अनुभूति हुई दिव्याभास की।","चतुर्निकाय के सुरगण आये। उत्सव ज्ञानकल्याण मनाये॥"],meaning:"पौष पूर्णिमा के पावन दिन दधिसक्त वृक्ष के नीचे प्रभु को केवलज्ञान ज्योति प्रगट हुई। चारों निकाय के देवों ने आकर केवलज्ञान कल्याणक उत्सव मनाया।"},{number:"२१",tag:"चौपाई",lines:["समोशरण निर्माण करायें। अन्तरिक्ष में प्रभु पधराये।","निरक्षरी कल्याणी वाणी। कर्णपुटों से पीतें प्राणी॥"],meaning:"कुबेर ने दिव्य समवशरण रचा जहाँ प्रभु अधर विराजित हुए। प्रभु की निरक्षरी दिव्यध्वनि को भव्य प्राणी अमृत की तरह अपने कानों से पीने लगे।"},{number:"२२",tag:"चौपाई",lines:['"जीव जगत में जानो अनन्त। पुद्गल तो है अनन्तानन्त।','धर्म-अधर्म और नभ एक। काल समेत द्रव्य षट् देख॥"'],meaning:"प्रभु ने देशना दी: 'संसार में जीव अनन्त हैं, पुद्गल अनन्तानन्त हैं, धर्म-अधर्म-आकाश एक-एक अखंड द्रव्य हैं और काल असंख्यात समयवर्ती है। इन छह द्रव्यों से यह लोक बना है।'"},{number:"२३",tag:"चौपाई",lines:['"रागमुक्त हो जाने रूप। शिवसुख उसको मिले अनूप।"',"सुन कर बहुत हुए व्रतधारी। बहुतों ने जिन दीक्षाधारी॥"],meaning:"'जो जीव राग-द्वेष से मुक्त होकर अपने आत्मस्वरूप को पहचानता है, उसे अनुपम मोक्षसुख मिलता है।' इस देशना को सुनकर अगणित भव्यात्माओं ने व्रत व दीक्षा धारण की।"},{number:"२४",tag:"चौपाई",lines:["आर्यखण्ड में हुआ विहार। भूमण्डल में धर्म प्रचार।","गढ़ सम्मेद गए आखिर में। लीन हुए निज अन्तरंग में॥"],meaning:"प्रभु ने सम्पूर्ण आर्यखण्ड में विहार कर धर्म की प्रभावना की। अंत में श्री सम्मेद शिखर जी पधारकर एक मास का प्रतिमा योग धारण किया।"},{number:"२५",tag:"चौपाई",lines:["शुक्लध्यान का हुआ प्रताप। हुए अघाति-घात निष्पाप।","नष्ट किए जग के सन्ताप। मुक्तिमहल में पहुँचे आप॥"],meaning:"परम शुक्लध्यान के प्रभाव से शेष चार अघातिया कर्मों का नाश कर प्रभु पूर्ण निष्पाप हुए और संसार के समस्त संतापों को मिटाकर मोक्षमहल में पधारे।"},{number:"२६",tag:"चौपाई",lines:["ज्येष्ठ चतुर्थी शुक्ल पक्षवर। पूजा करें सुर, कूट सुदत्तवर।","लक्षण 'वज्रदण्ड' शुभ जान। हुआ धर्म से धर्म का 'मान'॥"],meaning:"ज्येष्ठ शुक्ल चतुर्थी को सुदत्त कूट से प्रभु ने निर्वाण प्राप्त किया। प्रभु का पावन लांछन 'वज्रदण्ड' (वज्र) है; धर्मनाथ प्रभु के धर्म से ही सम्पूर्ण संसार में धर्म की महिमा प्रतिष्ठित है।"},{number:"२७",tag:"दोहा",lines:["जो प्रतिदिन प्रभु के गुण गाते। 'अरुणा' वे भी शिवसुख पाते।","धर्मनाथ भगवान की जय हो। जन-जन के मन में अभय हो॥"],meaning:"जो भव्य जीव नित्य एकाग्रचित्त होकर धर्मनाथ प्रभु के पावन गुणों का गान करते हैं, वे शाश्वत मोक्षसुख को प्राप्त करते हैं। धर्मनाथ भगवान की जय हो, सभी को अभयदान मिले।"},{number:"२८",tag:"जाप मंत्र",lines:["॥ मूल मंत्र एवं ध्यान ॥","ॐ ह्रीं अर्हं श्री धर्मनाथाय नमः।"],meaning:"पंद्रहवें तीर्थंकर देवाधिदेव श्री धर्मनाथ भगवान के पावन चरणों में मेरा त्रिकाल नमन हो। प्रभु का वज्रदण्ड लांछन हमें सभी कर्मों को भेदने की आत्मिक शक्ति दे।"}]},"kunthunath-chalisa":{id:"kunthunath-chalisa",category:"chalisa",title:"श्री कुन्थुनाथ चालीसा",subtitle:"सत्रहवें तीर्थंकर भगवान श्री कुन्थुनाथ स्वामी की भक्ति-स्तुति",type:"structured",verses:[{number:"१",tag:"दोहा",lines:["सिद्धप्रभू को नमन कर, सिद्ध करूँ सब काम।","सत्रहवें तीर्थेश का, करना है गुणगान॥"],meaning:"अनन्त सिद्ध भगवान को नमन कर अपने सभी कार्यों को सिद्ध करता हूँ। अब सत्रहवें तीर्थंकर देवाधिदेव श्री कुन्थुनाथ भगवान के पावन गुणों का गान करता हूँ।"},{number:"२",tag:"दोहा",lines:["कुन्थुनाथ भगवान हैं, श्रीकांता के लाल।","कामदेव हैं तेरहवें, उनको करूँ प्रणाम॥"],meaning:"भगवान कुन्थुनाथ माता श्रीकांता (श्रीमती) और पिता राजा शूरसेन के नंदन हैं। वे तेरहवें कामदेव और छठे चक्रवर्ती भी हैं; ऐसे त्रिपदवीधारी प्रभु को मेरा कोटिशः प्रणाम।"},{number:"३",tag:"दोहा",lines:["श्रीजिनवाणी मात की, हो जावे शुभदृष्टि।","तभी पूर्ण हो जाएगी, गुणगाथा संक्षिप्त॥"],meaning:"यदि जिनवाणी माता की पावन कृपा-दृष्टि हो जाए, तभी प्रभु के अनंत गुणों की यह संक्षिप्त गाथा निर्विघ्न पूर्ण होकर भक्तों का कल्याण करेगी।"},{number:"४",tag:"चौपाई",lines:["दयासिन्धु कुन्थु जिनराज, भवसिन्धु तिरने को जहाज।","कामदेव-चक्री महाराज, दया करो हम पर भी आज॥"],meaning:"दया के सागर प्रभु कुन्थुनाथ संसार-समुद्र से पार उतरने के लिए सुदृढ़ नौका के समान हैं। हे कामदेव और चक्रवर्ती पदधारी जिनेन्द्र! आज हम पर भी अपनी करुणा दृष्टि कीजिए।"},{number:"५",tag:"चौपाई",lines:["जय श्री कुन्थुनाथ गुणखान, परम यशस्वी महिमावान।","हस्तिनापुर नगरी के भूपति, शूरसेन कुरुवंशी अधिपति॥"],meaning:"अनंत गुणों की खान, परम यशस्वी भगवान कुन्थुनाथ की जय हो। पावन हस्तिनापुर नगरी के कुरुवंशी अधिपति महाराज शूरसेन प्रभु के पूज्य पिता थे।"},{number:"६",tag:"चौपाई",lines:["महारानी थी श्रीमति उनकी, वर्षा होती थी रतनन की।","प्रतिपदा बैसाख उजियारी, जन्मे तीर्थंकर बलधारी॥"],meaning:"उनकी पटरानी महारानी श्रीमती थीं जिनके आँगन में कुबेर ने रत्नों की वर्षा की। वैशाख शुक्ल प्रतिपदा के पावन प्रभात में महाबलवान तीर्थंकर बालक का जन्म हुआ।"},{number:"७",tag:"चौपाई",lines:["गहन भक्ति अपने उर धारे, हस्तिनापुर आए सुर सारे।","इन्द्र प्रभु को गोद में लेकर, गए सुमेरु हर्षित होकर॥"],meaning:"हृदय में अगाध भक्ति धारण कर चारों निकाय के देव हस्तिनापुर पधारे। सौधर्म इन्द्र बाल तीर्थंकर को अपनी गोद में लेकर आनन्दपूर्वक सुमेरु पर्वत पर पहुँचे।"},{number:"८",tag:"चौपाई",lines:["न्हवन करें निर्मल जल लेकर, ताण्डव नृत्य करें भक्ति-भर।","कुन्थुनाथ नाम शुभ देकर, इन्द्र करें स्तवन मनोहर॥"],meaning:"क्षीरसागर के निर्मल जल से प्रभु का जन्माभिषेक कर इन्द्र ने भक्ति-भाव से तांडव नृत्य किया और प्रभु का नाम 'कुन्थुनाथ' रखकर उनकी अनुपम स्तुति की।"},{number:"९",tag:"चौपाई",lines:["दिव्य-वस्त्र-भूषण पहनाए, वापिस हस्तिनापुर को आए।","क्रम-क्रम से बढे बालेन्दु सम, यौवन शोभा धारें हितकार॥"],meaning:"दिव्य आभूषणों से सुसज्जित कर इन्द्र प्रभु को माता-पिता को सौंप गए। शुक्लपक्ष के बाल-चन्द्रमा के समान प्रभु प्रतिदिन वृद्धि को प्राप्त हुए और उनका हितकारी यौवन खिला।"},{number:"१०",tag:"चौपाई",lines:["धनु पैंतालीस उन्नत प्रभु-तन, उत्तम शोभा धारें अनुपम।","आयु पिचानवे वर्ष हजार, लक्षण 'अज' धारें हितकार॥"],meaning:"प्रभु के स्वर्ण-वर्ण शरीर की ऊँचाई पैंतालीस धनुष थी, कुल आयु पचानवे हजार वर्ष थी, और उनके पावन चरणों में 'अज' (बकरा/मृग) का शुभ लक्षण अंकित था।"},{number:"११",tag:"चौपाई",lines:["राज्याभिषेक हुआ विधिपूर्वक, शासन करें सुनीति पूर्वक।","चक्ररतन शुभ प्राप्त हुआ जब, चक्रवर्ती कहलाए प्रभु तब॥"],meaning:"विधिपूर्वक राज्याभिषेक होने पर प्रभु ने नीतिपूर्वक प्रजा का पालन किया। आयुधशाला में चक्ररत्न प्रकट होने पर प्रभु छह खण्डों के चक्रवर्ती सम्राट् बने।"},{number:"१२",tag:"चौपाई",lines:["एक दिन गए प्रभु उपवन में, शान्त मुनि इक देखें मग में।",'इंगित किया तभी अंगुलि से, "देखो मुनि को"—कहा मंत्री से॥'],meaning:"एक दिन उपवन जाते समय मार्ग में एक परम शांत दिगम्बर मुनिराज को देखकर प्रभु ने अंगुली से संकेत कर मंत्री से कहा: 'देखो, इन वीतराग मुनिराज को!'"},{number:"१३",tag:"चौपाई",lines:['मंत्री ने पूछा जब कारण, "किया मोक्षहित मुनिपद धारण"।','"कारण करें और स्पष्ट", "मुनिपद से ही कर्म हों नष्ट"॥'],meaning:"मंत्री द्वारा पूछने पर प्रभु ने समझाया कि संसार से मुक्ति हेतु ही मुनिपद धारण किया जाता है, क्योंकि मुनि धर्म की साधना से ही सम्पूर्ण कर्मों का क्षय संभव है।"},{number:"१४",tag:"चौपाई",lines:["मंत्री का तो हुआ बहाना, किया वस्तुत: निज कल्याणा।","चित्त विरक्त हुआ विषयों से, तत्व चिन्तन करते भावों से॥"],meaning:"मंत्री तो मात्र निमित्त बने, वास्तव में प्रभु का अंतर्मन स्वयं विरक्त था। समस्त इन्द्रिय विषयों से उदासीन होकर प्रभु आत्म-चिंतन में लीन हो गए।"},{number:"१५",tag:"चौपाई",lines:["निज सुत को सौंपा सब राज, गए सहेतुक वन जिनराज।","पंचमुष्टि से केशलौंचकर, धार लिया पद नगन दिगम्बर॥"],meaning:"अपने सुपुत्र को राज्यभार सौंपकर प्रभु सहेतुक वन पधारे। पंचमुष्टि केशलोंच कर एक हजार राजाओं के साथ निर्ग्रन्थ दिगम्बर जिनदीक्षा अंगीकार की।"},{number:"१६",tag:"चौपाई",lines:["तीन दिन बाद गए गजपुर को, धर्ममित्र पड़गाहें प्रभु को।","मौन रहे सोलह वर्षों तक, सहे शीत-वर्षा और आतप॥"],meaning:"तीन दिन के उपवास उपरांत हस्तिनापुर में राजा धर्ममित्र ने प्रभु को प्रथम आहार दिया। प्रभु ने सोलह वर्षों तक मौनपूर्वक शीत, वर्षा और ग्रीष्म के घोर परीषह सहे।"},{number:"१७",tag:"चौपाई",lines:["स्थिर हुए तिलक तरु-तल में, मगन हुए निज ध्यान अटल में।","आतम में बढ़ गई विशुद्धि, केवलज्ञान की हो गई सिद्धि॥"],meaning:"तिलक वृक्ष के नीचे अटल शुक्लध्यान में लीन होकर प्रभु ने चारों घातिया कर्मों का नाश कर दिया और चैत्र शुक्ल तृतीया को केवलज्ञान की परम सिद्धि प्राप्त की।"},{number:"१८",tag:"चौपाई",lines:["सूर्यप्रभा सम सोहें आप्त, दिग्मण्डल शोभा हुई व्याप्त।","समोशरण रचना सुखकार, ज्ञानतृषित बैठे नर-नार॥"],meaning:"प्रभु का तेजोमय स्वरूप कोटि सूर्यों के समान प्रकाशित हुआ। कुबेर द्वारा रचित समवशरण में ज्ञान के प्यासे नर-नारी और देवगण प्रभु की अमृत देशना सुनने बैठे।"},{number:"१९",tag:"चौपाई",lines:["विषय-भोग महा विषमय है, मन को कर देते तन्मय हैं।","विष से मरते एक जनम में, भोग विषाक्त मरे भव-भव में॥"],meaning:"प्रभु ने देशना दी: 'सांसारिक विषय-भोग कालकूट विष के समान भयानक हैं। विष तो केवल एक जन्म का नाश करता है, किन्तु भोगों का विष जीव को भव-भव में भटकाकर नष्ट करता है।'"},{number:"२०",tag:"चौपाई",lines:["क्षणभंगुर मानव का जीवन, विद्युतवत् विनसे अगले क्षण।","सान्ध्य लालिमा के सदृश्य ही, यौवन हो जाता अदृश्य ही॥"],meaning:"'मानव जीवन बिजली की चमक के समान क्षणभंगुर है और यौवन संध्याकाल की लाली की तरह पल भर में विलीन हो जाता है, अतः प्रमाद छोड़ आत्महित करो।'"},{number:"२१",tag:"चौपाई",lines:["जब तक आतम बुद्धि नही हो, तब तक दरश विशुद्धि नहीं हो।","पहले विजित करो पंचेन्द्रिय, आतमबल से बनो जितेन्द्रिय॥"],meaning:"'जब तक आत्म-स्वरूप की यथार्थ पहचान नहीं होती, तब तक सम्यग्दर्शन की विशुद्धि नहीं होती। सर्वप्रथम आत्मबल से पाँचों इन्द्रियों और मन को जीतकर जितेन्द्रिय बनो।'"},{number:"२२",tag:"चौपाई",lines:["भव्य भारती प्रभु की सुनकर, श्रावकजन आनन्दित होकर।","श्रद्धा से व्रत धारण करते, शुभ भावों का अर्जन करते॥"],meaning:"प्रभु की अमृतमयी वाणी सुनकर भव्य श्रावकगण आनन्दित हुए और उन्होंने अपनी शक्ति अनुसार अणुव्रत और महाव्रत धारण कर धर्म का संचय किया।"},{number:"२३",tag:"चौपाई",lines:["शुभायु एक मास रही जब, शैल सम्मेद पे वास किया तब।","धारा प्रतिमा योग वहाँ पर, काटा कर्मबन्ध सब प्रभुवर॥"],meaning:"आयु का एक माह शेष रहने पर प्रभु श्री सम्मेद शिखर जी पधारे और प्रतिमा योग धारण कर शेष अघातिया कर्मों का समूल नाश कर दिया।"},{number:"२४",tag:"चौपाई",lines:["मोक्षकल्याणक करते सुरगण, कूट ज्ञानधर करते पूजन।","चक्री-कामदेव-तीर्थंकर, कुन्थुनाथ थे परम हितंकर॥"],meaning:"वैशाख शुक्ल प्रतिपदा को ज्ञानधर कूट से प्रभु ने निर्वाण प्राप्त किया। देवों ने मोक्षकल्याणक पूजा की। चक्रवर्ती, कामदेव और तीर्थंकर पदधारी कुन्थुनाथ परम हितकारी हैं।"},{number:"२५",tag:"चौपाई",lines:["चालीसा जो पढ़े भाव से, स्वयंसिद्ध हों निज स्वभाव से।","धर्म चक्र के लिए प्रभु ने, चक्र सुदर्शन तज डाला॥"],meaning:"जो भव्य जीव भावपूर्वक इस चालीसा का पाठ करते हैं, वे अपने आत्म-स्वभाव में स्थित होते हैं। प्रभु ने धर्मचक्र के लिए छह खंडों के सुदर्शन चक्र का भी सहज त्याग कर दिया।"},{number:"२६",tag:"दोहा",lines:["इसी भावना ने अरुणा को, किया ज्ञान में मतवाला।","कुन्थुनाथ प्रभु पार लगाओ, भव-भव के संताप मिटाओ॥"],meaning:"प्रभु के इस परम वैराग्य ने भक्तों के हृदय को आत्मज्ञान के आनंद से भर दिया। हे भगवान कुन्थुनाथ! हमें संसार-सागर से पार लगाइए और हमारे जन्म-मरण के संताप मिटाइए।"},{number:"२७",tag:"जाप मंत्र",lines:["॥ मूल मंत्र एवं ध्यान ॥","ॐ ह्रीं अर्हं श्री कुन्थुनाथाय नमः।"],meaning:"सत्रहवें तीर्थंकर, कामदेव एवं चक्रवर्ती भगवान श्री कुन्थुनाथ जी के पावन चरणों में मेरा अनंत बार नमस्कार हो।"}]},"mahavir-chalisa":{id:"mahavir-chalisa",category:"chalisa",title:"श्री महावीर चालीसा (दोहा, चौपाई एवं भावार्थ सहित)",subtitle:"तीर्थंकर भगवान श्री महावीर स्वामी चालीसा (श्री महावीर जी अतिशय क्षेत्र)",type:"structured",verses:[{number:"दोहा",lines:["दोहा","शीश नवा अरिहन्त को, सिद्धन करूँ प्रणाम।","उपाध्याय आचार्य का, ले सुखकारी नाम॥","सर्व साधु और सरस्वती, जिन मन्दिर सुखकार।","महावीर भगवान को, मन-मन्दिर में धार॥"],meaning:"सर्वप्रथम अनन्त चतुष्टय से शोभित अरिहंत देवों को शीश नवाकर और अष्टकर्म मुक्त सिद्ध परमेष्ठी को प्रणाम करता हूँ। परम सुखकारी आचार्य, उपाध्याय एवं समस्त साधु परमेष्ठियों का स्मरण कर, सुखदायी जिनवाणी माता व जिन-मंदिर को वंदन करके चौबीसवें तीर्थंकर भगवान महावीर स्वामी को अपने हृदय-मंदिर में धारण करता हूँ।"},{number:"१",lines:["चौपाई","जय महावीर दयालु स्वामी। वीर प्रभु तुम जग में नामी॥","वर्धमान है नाम तुम्हारा। लगे हृदय को प्यारा प्यारा॥"],meaning:"हे परम दयालु स्वामी महावीर भगवान! आपकी सदा जय हो। हे वीर प्रभु! आप तीनों लोकों में विख्यात हैं। बाल्यकाल से ही आपका नाम 'वर्धमान' है, जो प्रत्येक भक्त के हृदय को अत्यंत प्रिय और आनंददायी लगता है।"},{number:"२",lines:["शांत छवि और मोहनी मूरत। शान हँसीली सोहनी सूरत॥","तुमने वेश दिगम्बर धारा। कर्म-शत्रु भी तुम से हारा॥"],meaning:"आपकी वीतरागी छवि अत्यंत शांत, मनोहारी और सौम्य है। आपने परिग्रह-मुक्त परम पावन दिगंबर भेष धारण किया और अपनी आत्म-साधना के बल से घातिया कर्मरूपी प्रबल शत्रुओं को पराजित कर केवलज्ञान प्राप्त किया।"},{number:"३",lines:["क्रोध मान अरु लोभ भगाया। महा-मोह तुमसे डर खाया॥","तू सर्वज्ञ सर्व का ज्ञाता। तुझको दुनिया से क्या नाता॥"],meaning:"आपने काम, क्रोध, मान, माया और लोभ को समूल नष्ट कर दिया; आपसे महा-मोहनीय कर्म भी भयभीत होकर भाग गया। आप लोकालोक के समस्त पदार्थों को युगपत् जानने वाले सर्वज्ञ हैं, अतः इस नश्वर संसार के राग-द्वेष से आपका कोई संबंध नहीं रहा।"},{number:"४",lines:["तुझमें नहीं राग और द्वेष। वीतराग तू हितोपदेश॥","तेरा नाम जगत में सच्चा। जिसको जाने बच्चा बच्चा॥"],meaning:"आप राग और द्वेष से सर्वथा रहित पूर्ण वीतरागी हैं। आपकी दिव्यध्वनि समस्त जीवों का कल्याण करने वाली हितोपदेशी है। संसार में आपका पावन नाम ही सच्चा और मंगलकारी है, जिसे बालक-वृद्ध सभी जानते हैं।"},{number:"५",lines:["भूत प्रेत तुम से भय खावें। व्यन्तर राक्षस सब भग जावें॥","महा व्याधि मारी न सतावे। महा विकराल काल डर खावे॥"],meaning:"आपके नाम-स्मरण के प्रभाव से भूत, प्रेत, पिशाच, व्यंतर और राक्षस आदि दुष्ट शक्तियाँ भयभीत होकर भाग जाती हैं। महामारियाँ, असाध्य रोग और विकराल संकट भी आपके भक्त को पीड़ित नहीं कर पाते।"},{number:"६",lines:["काला नाग होय फन धारी। या हो शेर भयंकर भारी॥","ना हो कोई बचाने वाला। स्वामी तुम्हीं करो प्रतिपाला॥"],meaning:"चाहे कालकूट विष उगलने वाला भयंकर फणधारी काला नाग हो अथवा वन में दहाड़ता हुआ खूंखार सिंह; जब संकट में कोई बचाने वाला नहीं होता, तब हे स्वामी! आपका स्मरण ही भक्त की रक्षा और प्रतिपाल करता है।"},{number:"७",lines:["अग्नि दावानल सुलग रही हो। तेज हवा से भड़क रही हो॥","नाम तुम्हारा सब दुख खोवे। आग एकदम ठण्डी होवे॥"],meaning:"प्रचंड वायु के झोंकों से चारों ओर धधकती हुई जंगल की भयानक दावानल अग्नि भी, आपके पावन नाम का स्मरण करते ही क्षण भर में शांत और शीतल हो जाती है।"},{number:"८",lines:["हिंसामय था भारत सारा। तब तुमने कीना निस्तारा॥","जनम लिया कुण्डलपुर नगरी। हुई सुखी तब प्रजा सगरी॥"],meaning:"जब संपूर्ण भारतवर्ष में यज्ञ-हवन आदि के नाम पर मूक पशुओं की बलि और हिंसा व्याप्त थी, तब आपने 'अहिंसा परमो धर्मः' का उपदेश देकर जगत का उद्धार किया। आपने पवित्र कुंडलपुर नगरी में जन्म लिया, जिससे संपूर्ण प्रजा आनंदित और सुखी हुई।"},{number:"९",lines:["सिद्धारथ जी पिता तुम्हारे। त्रिशला के आँखों के तारे॥","छोड़ सभी झंझट संसारी। स्वामी हुए बाल-ब्रह्मचारी॥"],meaning:"राजा सिद्धार्थ आपके पूज्य पिता और माता त्रिशला के आप प्राणप्रिय नंदन हैं। आपने युवावस्था में ही संसार के समस्त वैभव और बंधनों को त्यागकर बाल-ब्रह्मचारी के रूप में जिनदीक्षा धारण की।"},{number:"१०",lines:["पंचम काल महा-दुखदाई। चाँदनपुर महिमा दिखलाई॥","टीले में अतिशय दिखलाया। एक गाय का दूध गिराया॥"],meaning:"इस अत्यंत दुखदायी पंचमकाल (कलियुग) में आपने राजस्थान के चाँदनपुर (वर्तमान श्री महावीर जी अतिशय क्षेत्र) में अपनी अलौकिक महिमा प्रकट की; जहाँ एक टीले पर कामधेनु जैसी गाय स्वतः अपना दूध बहा देती थी।"},{number:"११",lines:["सोच हुआ मन में ग्वाले के। पहुँचा एक फावड़ा लेके॥","सारा टीला खोद लगाया। तब तुमने दर्शन दिखलाया॥"],meaning:"गाय द्वारा नित्य दूध गिराए जाने पर चकित ग्वाले ने फावड़ा लेकर उस टीले की खुदाई प्रारंभ की, तब टीले के भीतर से आपकी परम शांत, पद्मासन वीतरागी प्रतिमा प्रकट हुई और आपने जगत को दर्शन दिए।"},{number:"१२",lines:["जोधराज को दुख ने घेरा। उसने नाम जपा जब तेरा॥","ठंडा हुआ तोप का गोला। तब सब ने जयकारा बोला॥"],meaning:"जब जयपुर के दीवान अमरचंद/जोधराज को घोर संकट व युद्ध की विभीषिका ने घेरा, तब उन्होंने अनन्य भाव से आपका नाम जपा; आपके चमत्कार से दुश्मन की तोप का गोला ठंडा हो गया और सभी ने एक स्वर में प्रभु महावीर का जयकारा लगाया।"},{number:"१३",lines:["मंत्री ने मन्दिर बनवाया। राजा ने भी द्रव्य लगाया॥","बड़ी धर्मशाला बनवाई। तुमको लाने को ठहराई॥"],meaning:"श्रद्धा से ओत-प्रोत होकर दीवान और राजा ने मिलकर विशाल जिन-मंदिर और यात्रियों के लिए भव्य धर्मशालाओं का निर्माण करवाया और प्रतिमाजी को नगर में विराजमान करने का विचार किया।"},{number:"१४",lines:["तुमने तोड़ी बीसों गाड़ी। पहिया खसका नहीं अगाड़ी॥","ग्वाले ने जो हाथ लगाया। फिर तो रथ चलता ही पाया॥"],meaning:"प्रतिमाजी को ले जाने के लिए कई मजबूत गाड़ियाँ टूट गईं किंतु रथ का पहिया तनिक भी आगे न बढ़ा; जब उसी निष्पाप ग्वाले ने श्रद्धा से हाथ लगाया, तब रथ सुगमता से आगे चलने लगा।"},{number:"१५",lines:["पहिले दिन बैशाख बदी के। रथ जाता है तीर नदी के॥","मीना गूजर सब ही आते। नाच-कूद सब चित उमगाते॥"],meaning:"प्रतिवर्ष वैशाख कृष्णा प्रतिपदा के पावन दिन आपका भव्य रथ गंभीर नदी के पावन तट पर जाता है, जहाँ मीना, गुर्जर आदि सर्व समाज के श्रद्धालु अपार उमंग और भक्तिभाव से नाचते-गाते सम्मिलित होते हैं।"},{number:"१६",lines:["स्वामी तुमने प्रेम निभाया। ग्वाले का बहु मान बढ़ाया॥","हाथ लगे ग्वाले का जब ही। स्वामी रथ चलता है तब ही॥"],meaning:"हे स्वामी! आपने अपने निष्कपट भक्त ग्वाले का प्रेम निभाया और उसका मान बढ़ाया; आज भी परंपरा अनुसार जब ग्वाले का वंशज हाथ लगाता है, तभी रथ आगे प्रस्थान करता है।"},{number:"१७",lines:["मेरी है टूटी सी नैया। तुम बिन कोई नहीं खिवैया॥","मुझ पर स्वामी जरा कृपा कर। मैं हूँ प्रभु तुम्हारा चाकर॥"],meaning:"हे प्रभु! संसाररूपी महासमुद्र में मेरी जीवनरूपी नैया डगमगा रही है, आपके अतिरिक्त मेरा अन्य कोई खेवनहार नहीं है। मुझ दीन सेवक पर कृपा दृष्टि कीजिए, मैं आपका अनन्य सेवक हूँ।"},{number:"१८",lines:["तुम से मैं अरु कछु नहीं चाहूँ। जन्म-जन्म तेरे दर्शन पाऊँ॥","चालीसे को 'चन्द्र' बनावे। वीर प्रभु को शीश नवावे॥"],meaning:"हे भगवान! मैं सांसारिक नश्वर सुखों की कामना नहीं करता; मेरी यही अभिलाषा है कि मुझे जन्म-जन्मांतरों में आपके पावन चरणों का दर्शन और भक्ति प्राप्त हो। कवि 'चन्द्र' इस चालीसा को रचकर वीर प्रभु के चरणों में नतमस्तक होते हैं।"},{number:"सोरठा",lines:["सोरठा","नित चालीसहिं बार, पाठ करे चालीस दिन।","खेय सुगन्ध अपार, वर्धमान के सामने॥","होय कुबेर समान, जन्म दरिद्री होय जो।","जिसके नहिं संतान, नाम वंश जग में चले॥"],meaning:"जो भव्य भक्त भगवान महावीर के सम्मुख उत्तम सुगंधित धूप खेकर निरंतर चालीस दिनों तक चालीस बार इस चालीसा का पाठ करता है, यदि वह जन्म का दरिद्री भी हो तो कुबेर के समान समृद्ध हो जाता है, और निःसंतान के घर उत्तम संतान जन्म लेकर कुल-वंश की कीर्ति फैलाती है।"}]},"mallinath-chalisa":{id:"mallinath-chalisa",category:"chalisa",title:"श्री मल्लिनाथ चालीसा",subtitle:"उन्नीसवें तीर्थंकर भगवान श्री मल्लिनाथ स्वामी की भक्ति-स्तुति",type:"structured",verses:[{number:"१",tag:"दोहा",lines:["मल्लिनाथ महाराज का, चालीसा मनहार।","चालीस दिन तुम नियम से, पढ़िये चालीस बार॥"],meaning:"उन्नीसवें तीर्थंकर भगवान श्री मल्लिनाथ का यह चालीसा पाठ मन को हरने वाला और शांति प्रदाता है। जो भव्य जीव चालीस दिनों तक नियमपूर्वक इसका पाठ करते हैं, वे आत्मिक सुख पाते हैं।"},{number:"२",tag:"दोहा",lines:["दर्शन को चलते समय, करिये इसका पाठ।","दुःख-चिन्ता, बाधा मिटे, उपजै 'सुमत' विचार॥"],meaning:"जिनेन्द्र दर्शन हेतु जाते समय इस पावन चालीसा का पाठ करने से जीवन के समस्त दुःख, भय और संकट मिट जाते हैं तथा मन में सुमति और सम्यग्ज्ञान का प्रकाश होता है।"},{number:"३",tag:"चौपाई",lines:["मोहमल्ल मद-मर्दन करते, मन्मथ दुर्द्धर का मद हरते।","धैर्य खड्ग से कर्म निवारे, बालयति को नमन हमारे॥"],meaning:"मोह रूपी महा मल्ल और कामदेव के अहंकार का मर्दन करने वाले, तथा धैर्य रूपी तलवार से कर्मों को काटने वाले बालब्रह्मचारी तीर्थंकर मल्लिनाथ प्रभु को हमारा कोटिशः नमन है।"},{number:"४",tag:"चौपाई",lines:["बिहार प्रान्त में मिथिला नगरी, राज्य करें कुम्भ काश्यप गोत्री।","प्रभावती महारानी उनकी, वर्षा होती थी रत्नों की॥"],meaning:"पवित्र मिथिला नगरी में काश्यप गोत्रीय महाराज कुम्भ राज्य करते थे। उनकी पटरानी महारानी प्रभावती थीं, जिनके आँगन में कुबेर ने साढ़े बारह करोड़ रत्नों की वर्षा की।"},{number:"५",tag:"चौपाई",lines:["अपराजित विमान को तजकर, जननी उदर बसे प्रभु आकर।","मंगसिर शुक्ल एकादशी शुभ दिन, जन्मे तीन ज्ञान युत श्री जिन॥"],meaning:"अपराजित अनुत्तर विमान से च्युत होकर प्रभु माता के गर्भ में पधारे। मार्गशीर्ष शुक्ल एकादशी के मंगल दिन मति, श्रुत, अवधि ज्ञान से संपन्न होकर तीर्थंकर बालक का जन्म हुआ।"},{number:"६",tag:"चौपाई",lines:["पूनम चन्द्र समान हों शोभित, इन्द्र न्हवन करते हो मोहित।","ताण्डव नृत्य करें खुश होकर, निरखें प्रभुको विस्मित होकर॥"],meaning:"पूर्ण चन्द्रमा के समान कांतिमान प्रभु को देखकर देवराज इन्द्र मुग्ध हो गए। सुमेरु पर्वत पर जन्माभिषेक कर इन्द्र ने भक्तिपूर्वक तांडव नृत्य किया।"},{number:"७",tag:"चौपाई",lines:["बढ़े प्यार से मल्लि कुमार, तन की शोभा हुई अपार।","पचपन सहस आयु प्रभुवर की, पच्चीस धनु अवगाहन वपु की॥"],meaning:"राजमहल में बालक मल्लि कुमार लाड़-प्यार से बड़े हुए। प्रभु की कुल आयु पचपन हजार वर्ष तथा नील वर्ण सुवर्णमय शरीर की ऊँचाई पच्चीस धनुष थी।"},{number:"८",tag:"चौपाई",lines:["देख पुत्र की योग्य अवस्था, पिता ब्याह की करें व्यवस्था।","मिथिलापुरी को खूब सजाया, कन्या पक्ष सुन कर हर्षाया॥"],meaning:"युवावस्था में पिता ने विवाह की तैयारी की और सम्पूर्ण मिथिला नगरी को सजाया गया। अनेक राजा अपनी कन्याओं के साथ संबंध हेतु उत्सुक हुए।"},{number:"९",tag:"चौपाई",lines:["निज मन में करते प्रभु मन्थन, है विवाह एक मीठा बन्धन।","विषय भोग रुपी ये कर्दम, आत्मज्ञान को करदे दुर्गम॥"],meaning:"किन्तु प्रभु ने अंतर्मन में विचार किया कि संसार का भोग-विलास और विवाह आत्मा के लिए बंधन है। विषय-भोग रूपी कीचड़ आत्मज्ञान के मार्ग को दुर्गम बना देता है।"},{number:"१०",tag:"चौपाई",lines:["नहीं आसक्त हुए विषयन में, हुए विरक्त गए प्रभु वन में।","मंगसिर शुक्ल एकादशी पावन, स्वामी दीक्षा करते धारण॥"],meaning:"विषयों से सर्वथा अनासक्त होकर प्रभु ने वैराग्य अंगीकार किया और मार्गशीर्ष शुक्ल एकादशी को सहेतुक वन में एक हजार राजाओं के साथ दिगम्बर दीक्षा धारण की।"},{number:"११",tag:"चौपाई",lines:["दो दिन का धरा उपवास, वन में ही फिर किया निवास।","तीसरे दिन प्रभु करें विहार, नन्दिषेण नृप दें आहार॥"],meaning:"दो दिन का निर्जल उपवास धारण कर प्रभु वन में ध्यानस्थ रहे। तीसरे दिन मिथिला नगरी में राजा नन्दिषेण ने नवधा भक्ति से प्रभु को प्रथम शुद्ध आहार कराया।"},{number:"१२",tag:"चौपाई",lines:["पात्रदान से हर्षित होकर, अचरज पाँच करें सुर आकर।","मल्लिनाथ जी लौटे वन में, लीन हुए आतम चिन्तन में॥"],meaning:"उत्तम पात्रदान देखकर देवों ने रत्नवृष्टि आदि पंचाश्चर्य किए। इसके पश्चात प्रभु पुनः वन में पधारकर आत्म-ध्यान में लीन हो गए।"},{number:"१३",tag:"चौपाई",lines:["आत्मशुद्धि का प्रबल प्रमाण, अल्प समय में उपजा ज्ञान।","केवलज्ञानी हुए छः दिन में, घण्टे बजने लगे स्वर्ग में॥"],meaning:"अपूर्व आत्मविशुद्धि के बल पर प्रभु ने मात्र छह दिनों के भीतर चारों घातिया कर्मों का नाश कर केवलज्ञान प्राप्त कर लिया। स्वर्गों में देवों की दुन्दुभियाँ बज उठीं।"},{number:"१४",tag:"चौपाई",lines:["समोशरण की रचना साजे, अन्तरिक्ष में प्रभु विराजे।","विशाक्ष आदि अट्ठाइस गणधर, चालीस सहस थे ज्ञानी मुनिवर॥"],meaning:"कुबेर ने दिव्य समवशरण की रचना की जहाँ प्रभु अंतरिक्ष में चार अंगुल ऊपर विराजित हुए। विशाख आदि अट्ठाईस गणधर और चालीस हजार मुनिराज समवशरण में उपस्थित थे।"},{number:"१५",tag:"चौपाई",lines:["पथिकों को सत्पथ दिखलाया, शिवपुर का सन्मार्ग बताया।","औषधि-शास्त्र-अभय-आहार, दान बताए चार प्रकार॥"],meaning:"संसार के भटके पथिकों को मोक्ष का सन्मार्ग दिखाते हुए प्रभु ने आहार दान, औषधि दान, ज्ञान (शास्त्र) दान और अभय दान—इन चार प्रकार के दानों की महत्ता समझाई।"},{number:"१६",tag:"चौपाई",lines:["पंच समिति और लब्धि पाँच, पाँचों पैताले हैं साँच।","षट् लेश्या जीव षट्काय, षट् द्रव्य कहते समझाय॥"],meaning:"प्रभु ने पाँच समिति, पाँच लब्धि, छह लेश्या, छह काय के जीव और छह द्रव्यों (जीव, पुद्गल, धर्म, अधर्म, आकाश, काल) का यथार्थ स्वरूप उद्घाटित किया।"},{number:"१७",tag:"चौपाई",lines:["सात तत्त्व का वर्णन करते, सात नरक सुन भविमन डरते।","सातों नय को मन में धारें, उत्तम जन सन्देह निवारें॥"],meaning:"प्रभु ने सात तत्त्वों (जीव, अजीव, आस्रव, बंध, संवर, निर्जरा, मोक्ष) और सात नयों का निरूपण किया, जिससे भव्य जीवों के संशय दूर हुए और वे पापों से विरक्त हुए।"},{number:"१८",tag:"चौपाई",lines:["दीर्घ काल तक दिए उपदेश, वाणी में कटुता नहीं लेश।","आयु रहने पर एक मास, शिखर सम्मेद पे करते वास॥"],meaning:"प्रभु ने दीर्घकाल तक आर्यावर्त में वीतराग धर्म की प्रभावना की। अंत में आयु का एक माह शेष रहने पर श्री सम्मेद शिखर जी पधारे।"},{number:"१९",tag:"चौपाई",lines:["योग निरोध का करते पालन, प्रतिमा योग करें प्रभु धारण।","कर्म नष्ट कीने जिनराई, तत्क्षण मुक्ति-रमा परणाई॥"],meaning:"प्रतिमा योग धारण कर प्रभु ने मन, वचन, काय के योगों का निरोध किया और शेष चार अघातिया कर्मों का नाश कर शाश्वत मोक्ष-लक्ष्मी को प्राप्त किया।"},{number:"२०",tag:"चौपाई",lines:["फाल्गुन शुक्ल पंचमी न्यारी, सिद्ध हुए जिनवर अविकारी।","मोक्ष कल्याणक सुर-नर करते, संवल कूट की पूजा करते॥"],meaning:"फाल्गुन शुक्ल पंचमी के पावन दिन प्रभु सम्मेद शिखर जी के 'संबल (मन्दार) कूट' से मोक्ष पधारे। देवों और मनुष्यों ने मिलकर मोक्षकल्याणक महापूजा की।"},{number:"२१",tag:"चौपाई",lines:["चिन्ह 'कलश' था मल्लिनाथ का, जीवन महापावन था उनका।","नरपुंगव थे वे जिनश्रेष्ठ, दिगम्बर परम्परा में ज्येष्ठ॥"],meaning:"प्रभु का पावन लांछन मंगलकारी 'कलश' (कुंभ) है। प्रभु परम पुरुषोत्तम, बालब्रह्मचारी और दिगम्बर तीर्थंकर परम्परा में महान आदर्श हैं।"},{number:"२२",tag:"चौपाई",lines:["महाबली थे वे शूरवीर, आत्म शत्रु जीते धर-धीर।","अनुकम्पा से प्रभु मल्लि की, अल्पायु हो भव-वल्लि की॥"],meaning:"प्रभु ने धैर्यपूर्वक अंतरंग काम-क्रोधादि शत्रुओं को जीतकर जिनत्व प्राप्त किया। प्रभु मल्लिनाथ की अनुकम्पा से हमारी सांसारिक जन्म-मरण की लता शीघ्र सूख जाए।"},{number:"२३",tag:"दोहा",lines:["अरज यही है बस हम सब की, दृष्टि रहे सब पर करुणा की।","मल्लिनाथ भगवान की जय हो, निज आत्म-ज्ञान का उदय हो॥"],meaning:"हे प्रभु! हम सभी भक्तों पर आपकी करुणा-दृष्टि सदैव बनी रहे। मल्लिनाथ भगवान की सदा जय हो और हमारे भीतर सम्यग्ज्ञान का नित्य उदय हो।"},{number:"२४",tag:"जाप मंत्र",lines:["॥ मूल मंत्र एवं ध्यान ॥","ॐ ह्रीं अर्हं श्री मल्लिनाथाय नमः।"],meaning:"उन्नीसवें तीर्थंकर भगवान श्री मल्लिनाथ जी के पावन चरणों में मेरा त्रिकाल नमन हो। प्रभु का कलश लांछन हमारे जीवन को धर्म रूपी अमृत से परिपूर्ण करे।"}]},"munisuvratnath-chalisa":{id:"munisuvratnath-chalisa",category:"chalisa",title:"श्री मुनिसुव्रतनाथ चालीसा",subtitle:"बीसवें तीर्थंकर भगवान श्री मुनिसुव्रतनाथ स्वामी की भक्ति-स्तुति",type:"structured",verses:[{number:"१",tag:"दोहा",lines:["पंचनमस्कृति मंत्र है, सर्व सुखों की खान।","पंचपदों युत मंत्र को, वंदूँ शीश नवाय॥"],meaning:"सर्व पापनाशक णमोकार महामंत्र समस्त सुखों और सिद्धियों का अक्षय भण्डार है। इस पंचपदयुक्त पावन अनादिनिधन मंत्र को मैं शीश झुकाकर वन्दन करता हूँ।"},{number:"२",tag:"दोहा",lines:["पंचपरमगुरु को नमूँ, पंचमगति मिल जाए।","रोग-शोक बाधा टलें, सुख अनन्त मिल जाए॥"],meaning:"अरिहंत, सिद्ध, आचार्य, उपाध्याय और सर्वसाधु रूप पंचपरमेष्ठी को नमन करता हूँ ताकि पंचम गति (मोक्ष) की प्राप्ति हो, समस्त रोग-शोक दूर हों और अनन्त आत्मिक सुख मिले।"},{number:"३",tag:"दोहा",lines:["श्रीमुनिसुव्रतनाथ का, यह चालीसा पाठ।","पढ़ लेवें जो भव्यजन, शनिग्रह होवें शांत॥"],meaning:"बीसवें तीर्थंकर भगवान मुनिसुव्रतनाथ जी का यह चालीसा पाठ जो भव्य प्राणी श्रद्धा से पढ़ते हैं, उनके समस्त संकट, शनि ग्रह जनित पीड़ा और अरिष्ट शांत हो जाते हैं।"},{number:"४",tag:"दोहा",lines:["शारद माता तुम मुझे, दे दो आशिर्वाद।","तभी पूर्ण हो पाएगा, यह जिनवर गुणगान॥"],meaning:"हे जिनवाणी माता सरस्वती! मुझ पर अपना मंगल आशीर्वाद दीजिए, जिससे बीसवें तीर्थंकर मुनिसुव्रतनाथ प्रभु का यह पवित्र गुणगान निर्विघ्न संपन्न हो।"},{number:"५",tag:"चौपाई",lines:["अरिहंत सिद्ध आचार्य को करुं प्रणाम।","उपाध्याय सर्वसाधू करते स्वपर कल्याण॥"],meaning:"सर्वप्रथम अरिहंत, अशरीरी सिद्ध और संघनायक आचार्यों को प्रणाम करता हूँ। ज्ञानदाता उपाध्याय और आत्मलीन सर्व साधु जो स्व और पर का कल्याण करते हैं, उन्हें नमन करता हूँ।"},{number:"६",tag:"चौपाई",lines:["जिनधर्म, जिनागम, जिनमंदिर पवित्र धाम।","वीतराग की प्रतिमा को कोटि-कोटि प्रणाम॥"],meaning:"अहिंसामयी जैन धर्म, द्वादशांग जिनागम, पवित्र जिनमंदिर और वीतरागी जिनबिम्ब को मेरा मन, वचन, काय से कोटि-कोटि प्रणाम है।"},{number:"७",tag:"चौपाई",lines:["जय मुनिसुव्रत दया के सागर, नाम प्रभु का लोक उजागर।","सुमित्रा राजा के तुम नन्दा, मां शामा की आंखो के चन्दा॥"],meaning:"हे दया के सागर मुनिसुव्रतनाथ प्रभु, आपकी जय हो! आपका नाम तीनों लोकों में प्रसिद्ध है। आप राजगृह के राजा सुमित्र के आत्मज और माता पद्मावती (शामा) के नयनतारे हैं।"},{number:"८",tag:"चौपाई",lines:["श्यामवर्ण मूरत प्रभू की प्यारी, गुणगान करें निशदिन नर नारी।","मुनिसुव्रत जिन हो अन्तरयामी, श्रद्धा भाव सहित तुम्हें प्रणामी॥"],meaning:"प्रभु का देह-वर्ण नीलमणि (श्याम) के समान दिव्य और मनोहारी है। सभी नर-नारी आपके पावन गुणों का गान करते हैं। हे अंतर्यामी प्रभु! हम श्रद्धा सहित आपको प्रणाम करते हैं।"},{number:"९",tag:"चौपाई",lines:["भक्ति आपकी जो निशदिन करता, पाप ताप भय संकट-हरता।","प्रभू संकटमोचन नाम तुम्हारा, दीन दुखी जीवों का सहारा॥"],meaning:"जो नित्य आपकी भक्ति करता है, उसके समस्त पाप, ताप, भय और संकट नष्ट हो जाते हैं। हे प्रभु! आप संकटमोचन हैं और संसार के दीन-दुःखी जीवों के एकमात्र सच्चे सहारे हैं।"},{number:"१०",tag:"चौपाई",lines:["कोई दरिद्री या तन का रोगी, प्रभू दर्शन से होते हैं निरोगी।","मिथ्या तिमिर भयो अति भारी, भव भव की बाधा हरो हमारी॥"],meaning:"चाहे कोई दरिद्र हो या शारीरिक व्याधियों से पीड़ित, प्रभु के दर्शन मात्र से वह निरोगी और सुखी हो जाता है। हमारे मिथ्यात्व रूपी घने अन्धकार और भव-भव की बाधाओं को हर लीजिए।"},{number:"११",tag:"चौपाई",lines:["यह संसार महा दुख दाई, सुख नहीं यहां दुख की खाई।","मोह जाल में फंसा है बंदा, काटो प्रभु भव भव का फंदा॥"],meaning:"यह संसार महा दुःखदाई और दुःखों की गहरी खाई है, यहाँ वास्तविक सुख नहीं है। सांसारिक प्राणी मोहजाल में फँसा हुआ है; हे प्रभु, हमारे इस भव-भव के फंदे को काट दीजिए।"},{number:"१२",tag:"चौपाई",lines:["रोग शोक भय व्याधि मिटावो, भव सागर से पार लगावो।","घिरा कर्म से चौरासी भटका, मोह माया बन्धन में अटका॥"],meaning:"हमारे सभी रोग, शोक, भय और आधिव्याधियों को मिटाकर हमें भवसागर से पार लगाइए। चौरासी लाख योनियों में भटकता हुआ यह जीव कर्मों और माया के बंधन में अटका हुआ है।"},{number:"१३",tag:"चौपाई",lines:["संयोग-वियोग भव भव का नाता, राग द्वेष जग में भटकाता।","हित मित प्रित प्रभू की वाणी, स्वपर कल्याण करें मुनि ध्यानी॥"],meaning:"संसार में संयोग और वियोग का चक्र चलता रहता है और राग-द्वेष ही भटकाते हैं। प्रभु की हित, मित और प्रिय वाणी सुनकर मुनिराज आत्म-कल्याण और जगत का उपकार करते हैं।"},{number:"१४",tag:"चौपाई",lines:["भव सागर बीच नाव हमारी, प्रभु पार करो यह विरद तिहारी।","मन विवेक मेरा अब जागा, प्रभु दर्शन से कर्ममल भागा॥"],meaning:"संसार-सागर के बीच हमारी जीवन-नौका डगमगा रही है; पतितपावन का अपना विरद संभालकर हमें पार कीजिए। प्रभु दर्शन से अंतःकरण में विवेक जागा और कर्ममल दूर हुआ।"},{number:"१५",tag:"चौपाई",lines:["नाम आपका जपे जो भाई, लोका लोक सुख सम्पदा पाई।","कृपा दृष्टी जब आपकी होवे, धन आरोग्य सुख समृधि पावे॥"],meaning:"जो भक्त आपका पावन नाम जपता है, वह लौकिक और पारलौकिक सुख-सम्पदा पाता है। आपकी कृपा-दृष्टि होने पर धर्म, आरोग्य, सुख और आत्मिक शांति की प्राप्ति होती है।"},{number:"१६",tag:"चौपाई",lines:["प्रभु चरणन में जो जो आवे, श्रद्धा भक्ति फल वांच्छित पावे।","प्रभु आपका चमत्कार है न्यारा, संकट मोचन प्रभु नाम तुम्हारा॥"],meaning:"जो भी प्रभु के पावन चरणों में आता है, वह अपनी सच्ची श्रद्धा और भक्ति का यथेष्ट फल पाता है। हे नाथ! आपका वीतराग अतिशय अद्भुत है, आप संकटों के नाशक हैं।"},{number:"१७",tag:"चौपाई",lines:["सर्वज्ञ अनंत चतुष्टय के धारी, मन वच तन वंदना हमारी।","सम्मेद शिखर से मोक्ष सिधारे, उद्धार करो मैं शरण तिहांरे॥"],meaning:"अनन्त ज्ञान, दर्शन, सुख, वीर्य के धारक सर्वज्ञ प्रभु को मेरी त्रियोग वन्दना है। श्री सम्मेद शिखर जी से मोक्ष पधारे हे प्रभु, मैं आपकी शरण में हूँ, मेरा उद्धार कीजिए।"},{number:"१८",tag:"चौपाई",lines:["महाराष्ट्र का पैठण तीर्थ, सुप्रसिद्ध यह अतिशय क्षेत्र।","मनोज्ञ मन्दिर बना है भारी, वीतराग की प्रतिमा सुखकारी॥"],meaning:"महाराष्ट्र का पैठण अतिशय क्षेत्र विश्वविख्यात है, जहाँ विशाल और मनोहारी जिनमंदिर में भगवान मुनिसुव्रतनाथ की सुखकारी वीतराग प्रतिमा विराजमान है।"},{number:"१९",tag:"चौपाई",lines:["चतुर्थ कालीन मूर्ति है निराली, मुनिसुव्रत प्रभू की छवि है प्यारी।","मानस्तंभ उत्तंग की शोभा न्यारी, देखत गलत मान कषाय भारी॥"],meaning:"चतुर्थ काल की वह अनुपम प्रतिमा प्रभु की परम शांत छवि दर्शाती है। मंदिर के समक्ष गगनचुंबी मानस्तंभ को देखते ही जीवों का मान कषाय गल जाता है।"},{number:"२०",tag:"चौपाई",lines:["मुनिसुव्रत शनिग्रह अधिष्ठाता, दुख संकट हरे देवे सुख साता।","शनि अमावस की महिमा भारी, दूर-दूर से आते नर नारी॥"],meaning:"प्रभु मुनिसुव्रतनाथ की आराधना से शनि ग्रह जनित समस्त बाधाएँ दूर होती हैं और शांति मिलती है। शनिश्चरी अमावस्या पर दूर-दूर से श्रद्धालु आकर प्रभु का अभिषेक करते हैं।"},{number:"२१",tag:"चौपाई",lines:["मुनिसुव्रत दर्शन महा हितकारी, मन वच तन वंदना हमारी।","कच्छप लक्षण प्रभु पद राजे, त्रैलोक्य में डंका बाजे॥"],meaning:"प्रभु का दर्शन परम हितकारी है। प्रभु के पावन चरणों में 'कूर्मा' (कच्छप/कछुआ) का मंगल चिन्ह सुशोभित है; तीनों लोकों में प्रभु के वीतराग धर्म का डंका बजता है।"},{number:"२२",tag:"सोरठा",lines:["सम्यक् श्रद्धा से चालीसा, चालीस दिन पढिये नर-नार।","मुक्ति पथ के राही बन, भक्ति से होवे भव पार॥"],meaning:"सम्यक् श्रद्धा और एकाग्रता के साथ जो भव्य स्त्री-पुरुष चालीस दिनों तक इस चालीसा का पाठ करते हैं, वे मोक्षमार्ग के पथिक बनकर संसार-समुद्र से पार उतर जाते हैं।"},{number:"२३",tag:"जाप मंत्र",lines:["॥ मूल मंत्र एवं ध्यान ॥","ॐ ह्रीं अर्हं श्री मुनिसुव्रतनाथाय नमः।"],meaning:"बीसवें तीर्थंकर, संकटमोचक देवाधिदेव श्री मुनिसुव्रतनाथ स्वामी के पावन चरणों में मेरा अनंत बार नमन हो।"}]},"naminath-chalisa":{id:"naminath-chalisa",category:"chalisa",title:"श्री नमिनाथ चालीसा",subtitle:"इक्कीसवें तीर्थंकर भगवान श्री नमिनाथ स्वामी की भक्ति-स्तुति",type:"structured",verses:[{number:"१",tag:"दोहा",lines:["सतत पूज्यनीय भगवान, नमिनाथ जिन महिभावान।","भक्त करें जो मन में ध्याय, पा जाते मुक्ति-वरदान॥"],meaning:"इक्कीसवें तीर्थंकर भगवान श्री नमिनाथ सर्वथा पूज्य और अनन्त महिमावान हैं। जो भक्तजन एकाग्रचित्त होकर उनका ध्यान करते हैं, वे मोक्ष का परम वरदान प्राप्त करते हैं।"},{number:"२",tag:"दोहा",lines:["जय श्री नमिनाथ जिन स्वामी।","वसु गुण मण्डित प्रभु प्रणमामि॥"],meaning:"हे देवाधिदेव श्री नमिनाथ स्वामी! आपकी सदा जय हो। सिद्धों के आठों आत्मिक गुणों से मण्डित प्रभु के पावन चरणों में मैं नतमस्तक होकर प्रणाम करता हूँ।"},{number:"३",tag:"चौपाई",lines:["मिथिला नगरी प्रान्त बिहार।","श्री विजय राज्य करें हितकार॥"],meaning:"प्राचीन बिहार प्रान्त की पावन मिथिला नगरी में परम धर्मात्मा और प्रजावत्सल महाराज श्री विजय राज्य करते थे।"},{number:"४",tag:"चौपाई",lines:["विप्रा देवी महारानी थीं।","रूप गुणों की वे खानि थीं॥"],meaning:"उनकी पटरानी महारानी विप्रा (वप्रिला) देवी थीं, जो शील, सदाचार, अनुपम रूप और पावन गुणों की साक्षात् खान थीं।"},{number:"५",tag:"चौपाई",lines:["कृष्णाश्विन द्वितीया सुखदाता।","षोडश स्वप्न देखती माता॥"],meaning:"आश्विन कृष्णा द्वितीया की सुखदायी रात्रि में महारानी विप्रा देवी ने तीर्थंकर अवतरण को सूचित करने वाले मंगलकारी सोलह स्वप्न देखे।"},{number:"६",tag:"चौपाई",lines:["अपराजित विमान को तजकर।","जननी उदर बसे प्रभु आकर॥"],meaning:"अपराजित अनुत्तर विमान से च्युत होकर प्रभु माता के गर्भ में पधारे। देवों ने मिथिला में आकर गर्भकल्याणक महोत्सव मनाया।"},{number:"७",tag:"चौपाई",lines:["कृष्ण असाढ़-दशमी सुखकार।","भूतल पर हुआ प्रभु-अवतार॥"],meaning:"आषाढ़ कृष्णा दशमी के मंगल प्रभात में तीनों लोकों को सुख देने वाले तीर्थंकर बालक नमिनाथ का भूतल पर प्राकट्य हुआ।"},{number:"८",tag:"चौपाई",lines:["आयु सहस दस वर्ष प्रभु की।","धनु पन्द्रह अवगाहना उनकी॥"],meaning:"प्रभु का देह-वर्ण स्वर्ण के समान द्युतिमान था, उनकी कुल आयु दस हजार वर्ष और शरीर की ऊँचाई पंद्रह धनुष थी।"},{number:"९",tag:"चौपाई",lines:["तरुण हुए जब राजकुमार।","हुआ विवाह तब आनन्दकार॥"],meaning:"युवावस्था में माता-पिता की आज्ञा से राजकुमार नमिनाथ का विवाह संपन्न हुआ और वे धर्मपूर्वक गृहस्थ जीवन व्यतीत करने लगे।"},{number:"१०",tag:"चौपाई",lines:["एक दिन भ्रमण करें उपवन में।","वर्षा ऋतु में हर्षित मन में॥"],meaning:"वर्षा ऋतु में एक दिन जब प्रभु राजोद्यान में भ्रमण कर रहे थे, तब प्रकृति के परिवर्तनों को देखकर उनका मन आत्म-चिंतन में लीन हुआ।"},{number:"११",tag:"चौपाई",lines:["नमस्कार करके दो देव।","कारण कहने लगे स्वयमेव॥"],meaning:"उसी समय अंतरिक्ष से दो देवों ने आकर प्रभु के चरणों में नमन किया और अपने आने का पावन कारण स्वयं निवेदन किया।"},{number:"१२",tag:"चौपाई",lines:["ज्ञात हुआ है क्षेत्र विदेह में।","“भावी तीर्थंकर तुम जग में॥”"],meaning:"देवों ने कहा: 'विदेह क्षेत्र में तीर्थंकर सीमंधर स्वामी के समवशरण से ज्ञात हुआ है कि आप इस भरतक्षेत्र के भावी तीर्थंकर हैं।'"},{number:"१३",tag:"चौपाई",lines:["देवों से सुन कर ये बात।","राजमहल लौटे नमिनाथ॥"],meaning:"देवों के मुख से यह उद्घोष सुनकर प्रभु नमिनाथ राजमहल लौटे और उनका अंतःकरण तीव्र वैराग्य रस से परिपूर्ण हो गया।"},{number:"१४",tag:"चौपाई",lines:["सोच हुआ भव-भव में भ्रमण का।","चिन्तन करते रहे मोचन का॥"],meaning:"संसार के जन्म-मरण के चक्र और भव-भ्रमण का चिंतन करते हुए प्रभु आत्मा को कर्म बंधनों से मुक्त कराने का विचार करने लगे।"},{number:"१५",tag:"चौपाई",lines:["परम दिगम्बर व्रत करूँ अर्जन।","रतनत्रयधन करूँ उपार्जन॥"],meaning:"प्रभु ने निश्चय किया कि मैं सर्वसंग परित्याग कर परम दिगम्बर मुनि दीक्षा धारण करूँगा और सम्यग्दर्शन-ज्ञान-चारित्र रूपी रत्नत्रय धन का संचय करूँगा।"},{number:"१६",tag:"चौपाई",lines:["सुप्रभ सुत को राज सौंपकर।","गए चित्रवन में श्रीजिनवर॥"],meaning:"अपने सुपुत्र सुप्रभ को राज्य का भार सौंपकर प्रभु देवों द्वारा लाई गई उत्तरकुरु पालकी में सवार होकर चित्रवन पधारे।"},{number:"१७",tag:"चौपाई",lines:["दशमी असाढ़ मास की कारी।","सहस नृपति संग दीक्षाधारी॥"],meaning:"आषाढ़ कृष्णा दशमी के शुभ दिन एक हजार राजाओं के साथ प्रभु ने पंचमुष्टि केशलोंच कर दिगम्बर दीक्षा धारण की।"},{number:"१८",tag:"चौपाई",lines:["दो दिन का उपवास धारकर।","आतम लीन हुए श्री प्रभुवर॥"],meaning:"दो दिन का निर्जल उपवास धारण कर प्रभु वन में मौनपूर्वक आत्मध्यान में पूर्णतः तन्मय हो गए।"},{number:"१९",tag:"चौपाई",lines:["तीसरे दिन जब किया विहार।","भूप वीरपुर दें आहार॥"],meaning:"तीसरे दिन पारणा हेतु वीरपुर नगर में पधारने पर राजा दत्त (वीरपुर नरेश) ने नवधा भक्ति से प्रभु को प्रथम शुद्ध आहार कराया।"},{number:"२०",tag:"चौपाई",lines:["नौ वर्षों तक तप किया वन में।","एक दिन मौलिश्री तरु तल में॥"],meaning:"नौ वर्षों तक वन में मौनपूर्वक घोर तपस्या करने के बाद एक दिन प्रभु मौलिश्री (बकुल) वृक्ष के नीचे शुक्लध्यान में लीन हुए।"},{number:"२१",tag:"चौपाई",lines:["अनुभूति हुई दिव्याभास।","शुक्ल एकादशी मंगसिर मास॥"],meaning:"मार्गशीर्ष शुक्ल एकादशी के पावन दिन प्रभु ने चारों घातिया कर्मों का नाश किया और लोकालोक को प्रकाशित करने वाला केवलज्ञान उदित हुआ।"},{number:"२२",tag:"चौपाई",lines:["नमिनाथ हुए ज्ञान के सागर।","ज्ञानोत्सव करते सुर आकर॥"],meaning:"प्रभु केवलज्ञान के अक्षय सागर बन गए। स्वर्गों से इन्द्र और देवगण पधारे और उन्होंने केवलज्ञान कल्याणक का महामहोत्सव मनाया।"},{number:"२३",tag:"चौपाई",lines:["समोशरण था सभा विभूषित।","मानस्तम्भ थे चार सुशोभित॥"],meaning:"कुबेर ने दिव्य समवशरण की रचना की, जिसके चारों दिशाओं में रत्नमयी मानस्तंभ सुशोभित थे और बारह सभाओं में श्रोता उपस्थित थे।"},{number:"२४",tag:"चौपाई",lines:["हुआ मौनभंग दिव्य ध्वनि से।","सब दुख दूर हुए अवनि से॥"],meaning:"प्रभु की ओंकारमयी दिव्यध्वनि खिरी, जिसने पृथ्वी के समस्त जीवों के अज्ञान और संताप को दूर कर दिया।"},{number:"२५",tag:"चौपाई",lines:["आत्म पदार्थ से सत्ता सिद्ध।","करता तन में 'अहम्' प्रसिद्ध॥"],meaning:"प्रभु ने देशना दी: 'आत्मा एक स्वतंत्र चेतन्य पदार्थ है। अज्ञानी जीव नश्वर शरीर में 'अहंकार' और 'ममकार' कर संसार में भटकता है।'"},{number:"२६",tag:"चौपाई",lines:["बाह्येन्द्रियों में करण के द्वारा।","अनुभव से कर्ता स्वीकारा॥"],meaning:"'इन्द्रियों और मन के द्वारा जीव पर-पदार्थों का कर्ता और भोक्ता बनता है, जबकि निश्चय से वह केवल ज्ञाता-दृष्टा है।'"},{number:"२७",tag:"चौपाई",lines:["पर-परिणति से ही यह जीव।","चतुर्गति में भ्रमे सदीव॥"],meaning:"'पर-द्रव्यों में राग-द्वेष करने रूप पर-परिणति के कारण ही यह संसारी जीव चारों गतियों में अनादिकाल से भटक रहा है।'"},{number:"२८",tag:"चौपाई",lines:["रहे नरक-सागर पर्यन्त।","सहें भूख-प्यास तिर्यंच॥"],meaning:"'नरक गति में जीव सागरों पर्यंत असह्य शारीरिक व मानसिक यातनाएँ भोगते हैं और तिर्यंच गति में भूख, प्यास, सर्दी, गर्मी और परतंत्रता का दुःख सहते हैं।'"},{number:"२९",tag:"चौपाई",lines:["हुआ मनुज तो भी संक्लेश।","देवों में भी ईर्ष्या-द्वेष॥"],meaning:"'मनुष्य पर्याय में भी रोग, वियोग और अनेक क्लेश हैं, और देव गति में भी पटल-वैभव देखकर ईर्ष्या और मरणकाल में घोर पश्चाताप होता है।'"},{number:"३०",tag:"चौपाई",lines:["नहीं सुखों का कहीं ठिकाना।","सच्चा सुख तो मोक्ष में माना॥"],meaning:"'चारों गतियों में सच्चा सुख किंचित् भी नहीं है; वास्तविक, अविनाशी और निराकुल सुख तो केवल सिद्ध पद (मोक्ष) में ही है।'"},{number:"३१",tag:"चौपाई",lines:["मोक्ष गति का द्वार है एक।","नरभव से ही पायें नेक॥"],meaning:"'मोक्ष प्राप्ति का एकमात्र साधन रत्नत्रय धर्म है, जिसे दुर्लभ मनुष्य भव पाकर ही साधना द्वारा सिद्ध किया जा सकता है।'"},{number:"३२",tag:"चौपाई",lines:["सुन कर मगन हुए सब सुरगण।","व्रत धारण करते श्रावक जन॥"],meaning:"प्रभु के दिव्य उपदेश सुनकर देव और मनुष्य आनन्दमग्न हो गए और भव्य श्रावकों ने सम्यग्दर्शन पूर्वक अणुव्रत अंगीकार किए।"},{number:"३३",tag:"चौपाई",lines:["हुआ विहार जहाँ भी प्रभु का।","हुआ वहीं कल्याण सभी का॥"],meaning:"जहाँ-जहाँ प्रभु के चरण कमल पड़े, वहाँ-वहाँ अकाल, दुर्भिक्ष और रोग दूर हो गए और सभी प्राणियों का आध्यात्मिक कल्याण हुआ।"},{number:"३४",tag:"चौपाई",lines:["करते रहे विहार जिनेश।","एक मास रही आयु शेष॥"],meaning:"दीर्घकाल तक धर्म प्रभावना करने के बाद आयु का एक माह शेष रहने पर प्रभु श्री सम्मेद शिखर जी पधारे।"},{number:"३५",tag:"चौपाई",lines:["शिखर सम्मेद के ऊपर जाकर।","प्रतिमा योग धरा हर्षा कर॥"],meaning:"सम्मेद शिखर की पावन शिला पर पद्मासन लगाकर प्रभु ने प्रतिमा योग धारण किया और आत्मलीन हो गए।"},{number:"३६",tag:"चौपाई",lines:["शुक्ल ध्यान की अग्नि प्रजारी।","हने अघाति कर्म दुखकारी॥"],meaning:"परम शुक्लध्यान की प्रचंड अग्नि प्रज्वलित कर प्रभु ने शेष चार अघातिया कर्मों को पूर्णतः भस्म कर दिया।"},{number:"३७",tag:"चौपाई",lines:["अजर-अमर-शाश्वत पद पाया।","सुर-नर सबका मन हर्षाया॥"],meaning:"वैशाख कृष्णा चतुर्दशी के दिन प्रभु ने जन्म-मरण रहित अजर-अमर सिद्ध पद प्राप्त किया, जिससे तीनों लोकों में अपार हर्ष छा गया।"},{number:"३८",tag:"चौपाई",lines:["शुभ निर्वाण महोत्सव करते।","कूट मित्रधर पूजन करते॥"],meaning:"इन्द्रों और देवों ने शिखर जी के पावन 'मित्रधर कूट' की वन्दना कर प्रभु का मोक्षकल्याणक महामहोत्सव मनाया।"},{number:"३९",tag:"चौपाई",lines:["प्रभु हैं नीलकमल से अलंकृत।","हम हों उत्तम फल से उपकृत॥"],meaning:"प्रभु के पावन चरणों में 'नीलोत्पल' (नीलकमल) का दिव्य लांछन अंकित है; प्रभु की शरण पाकर हम मोक्ष रूपी उत्तम फल से उपकृत हों।"},{number:"४०",tag:"चौपाई",lines:["नमिनाथ स्वामी जगवन्दन।","'अरुणा' करती प्रभु-अभिवन्दन॥"],meaning:"तीनों लोकों द्वारा वन्दनीय देवाधिदेव श्री नमिनाथ स्वामी के पावन चरणों में हम शत-शत अभिवन्दन और प्रणाम करते हैं।"},{number:"४१",tag:"जाप मंत्र",lines:["॥ मूल मंत्र एवं ध्यान ॥","ॐ ह्रीं अर्हं श्री नमिनाथाय नमः।"],meaning:"इक्कीसवें तीर्थंकर भगवान श्री नमिनाथ जी के पावन चरणों में मेरा त्रिकाल नमन हो। प्रभु का नीलकमल लांछन हमारे चित्त में वैराग्य और विशुद्धि का कमल खिलाए।"}]},"namokar-chalisa":{id:"namokar-chalisa",category:"chalisa",title:"णमोकार महामंत्र चालीसा",subtitle:"अनादिनिधन मूल महामंत्र की महिमामयी भक्ति-स्तुति",type:"structured",verses:[{number:"१",tag:"दोहा",lines:["वंदूँ श्रीअरिहंत पद, सिद्ध नाम सुखकार।","सूरी पाठक साधुगण, हैं जग के आधार॥"],meaning:"सर्वप्रथम अनन्त चतुष्टय सम्पन्न अरिहंतों के पावन चरणों में वन्दन करता हूँ, अशरीरी सिद्धों का नाम परम सुखकारी है। आचार्य (सूरी), उपाध्याय (पाठक) और सर्व साधुगण जगत में धर्म के सच्चे आधार हैं।"},{number:"२",tag:"दोहा",lines:["इन पाँचों परमेष्ठि से, सहित मूल यह मंत्र।","अपराजित व अनादि है, णमोकार शुभ मंत्र॥"],meaning:"इन पाँचों परमेष्ठियों को समर्पित यह मूल महामंत्र अनादि-अनन्त और किसी भी शक्ति से कभी पराजित न होने वाला, जगत का सर्वोच्च मंगलकारी अपराजित मंत्र है।"},{number:"३",tag:"दोहा",lines:["णमोकार महामंत्र को, नमन करूँ शतबार।","चालीसा पढ़कर लहूँ, स्वात्मधाम साकार॥"],meaning:"णमोकार महामंत्र को मैं शत-शत बार नमन करता हूँ। इस पावन चालीसा का श्रद्धापूर्वक पाठ कर अपने निज आत्मस्वरूप (स्वात्मधाम) की साक्षात् अनुभूति प्राप्त करूँ।"},{number:"४",tag:"चौपाई",lines:["हो जैवन्त अनादिमंत्रम्, णमोकार अपराजित मंत्रम्।","पंच पदों से युक्त सुयंत्रम्, सर्वमनोरथ सिद्धि सुतंत्रम्॥"],meaning:"अनादिनिधन, अपराजित णमोकार महामंत्र सदा जयवन्त रहे! यह पाँच पावन पदों से युक्त वह सर्वश्रेष्ठ आध्यात्मिक यंत्र व तंत्र है जो आत्मा के समस्त मनोरथों को सिद्ध करता है।"},{number:"५",tag:"चौपाई",lines:["पैंतिस अक्षर माने इसमें, अट्ठावन मात्राएँ भी हैं।","अतिशयकारी मंत्र जगत में, सब मंगल में कहा प्रथम है॥"],meaning:"इस महामंत्र में पैंतीस प्राकृत अक्षर और अट्ठावन मात्राएँ हैं। यह त्रिभुवन में सर्वाधिक अतिशयकारी है और सभी मंगलों में इसे प्रथम तथा सर्वोच्च मंगल कहा गया है।"},{number:"६",tag:"चौपाई",lines:["जिसने इसका ध्यान लगाया, मनमन्दिर में इसे बिठाया।","उसका बेड़ा पार हो गया, भवदधि से उद्धार हो गया॥"],meaning:"जिस भी भव्य आत्मा ने इस महामंत्र को अपने हृदय-मन्दिर में स्थापित कर एकाग्र ध्यान लगाया, उसका संसार-समुद्र से पूर्ण उद्धार हो गया और बेड़ा पार लग गया।"},{number:"७",tag:"चौपाई",lines:["अंजन बना निरंजन क्षण में, शूली बदली सिंहासन में।","नाग बना फूलों की माला, हो गई शीतल अग्नी ज्वाला॥"],meaning:"इस मंत्र के प्रभाव से अंजन तस्कर पल भर में निरंजन सिद्ध बन गया, सेठ सुदर्शन की सूली स्वर्ण-सिंहासन में बदल गई, विषधर सर्प पुष्पमाला बन गया और धधकती अग्नि शीतल जल बन गई।"},{number:"८",tag:"चौपाई",lines:["जीवन्धर से इसी मंत्र को, सुना श्वान ने मरणासन्न हो।","शांतभाव से काया तजकर, पाया पद यक्षेन्द्र हुआ तब॥"],meaning:"मरणासन्न अवस्था में जीवन्धर कुमार द्वारा सुनाए गए णमोकार मंत्र को सुनकर कुत्ते ने शांत भाव से देह त्यागी और यक्षेन्द्र (सुरेन्द्र) का वैभवशाली देव पद प्राप्त किया।"},{number:"९",tag:"चौपाई",lines:["एक बैल ने मंत्र सुना था, राजघराने में जन्मा था।","जातिस्मरण हुआ जब उसको, उसने खोजा उपकारी को॥"],meaning:"मरते हुए बैल ने जब मुनिराज से णमोकार मंत्र सुना तो वह अगले भव में राजघराने में उत्पन्न हुआ और जातिस्मरण ज्ञान होने पर उसने अपने पूर्वभव के उपकारी की खोज की।"},{number:"१०",tag:"चौपाई",lines:["पद्मरुची को गले लगाया, आगे मैत्री भाव निभाया।","कालान्तर में वही पद्मरुचि, राम बने तब बहुत धर्मरुचि॥"],meaning:"उसने उपकारी सेठ पद्मरुचि को गले लगाकर अटूट मैत्री निभाई। कालांतर में वही धर्मात्मा पद्मरुचि का जीव मर्यादा पुरुषोत्तम श्री रामचन्द्र के रूप में अवतरित हुआ।"},{number:"११",tag:"चौपाई",lines:["बैल बना सुग्रीव बन्धुवर! दोनों के सम्बन्ध मित्रवर।","रामायण की सत्य कथा है, णमोकार से मिटी व्यथा है॥"],meaning:"वह बैल का जीव राजा सुग्रीव बना और दोनों में निस्वार्थ मैत्री रही। रामायण की यह प्रसिद्ध कथा साक्षी है कि णमोकार मंत्र ने सभी भव-भव की व्यथा मिटा दी।"},{number:"१२",tag:"चौपाई",lines:["ऐसी ही कितनी घटनाएँ, नए पुराने ग्रन्थ बताएँ।","इस जग में इस मंत्र की महिमा, कही सभी ने इसकी गरिमा॥"],meaning:"प्राचीन जिनागम और पुराणों में इस महामंत्र के अद्भुत चमत्कारों की अनगिनत कथाएँ भरी पड़ी हैं। सभी आचार्यों और ज्ञानियों ने एक स्वर से इसकी गरिमा का गुणगान किया है।"},{number:"१३",tag:"चौपाई",lines:["हो अपवित्र पवित्र दशा में, सदा करें संस्मरण हृदय में।","जपें शुद्धतन से जो माला, वे पाते हैं सौख्य निराला॥"],meaning:"पवित्र अथवा अपवित्र किसी भी अवस्था में इस मंत्र का हृदय से स्मरण किया जा सकता है। जो शुद्ध मन, वचन, काय से इसकी माला जपते हैं, वे अलौकिक आत्मिक सुख पाते हैं।"},{number:"१४",tag:"चौपाई",lines:["अन्तर्मन पावन होता है, बाहर का अघमल धोता है।","णमोकार के पैंतिस व्रत हैं, श्रावक करते श्रद्धायुत हैं॥"],meaning:"यह मंत्र अंतःकरण को परम पावन बनाता है और समस्त पापमल को धो डालता है। णमोकार मंत्र के पैंतीस अक्षरों के निमित्त से श्रद्धालु श्रावक पैंतीस उपवास आदि व्रत धारण करते हैं।"},{number:"१५",tag:"चौपाई",lines:["हर घर के दरवाजे पर तुम, महामंत्र को लिखो जैनगण।","जैनी संस्कृति दर्शाएगा, सुख समृद्धि भी दिलवाएगा॥"],meaning:"समस्त जैन बंधु अपने-अपने गृह-द्वार पर इस पावन महामंत्र को अंकित करें; यह जिन-संस्कृति का गौरव बढ़ाएगा और घर-परिवार में सुख, शांति और समृद्धि लाएगा।"},{number:"१६",tag:"चौपाई",lines:["एक तराजू के पलड़े पर, सारे गुण भी रख देने पर।","दूजा पलड़ा मंत्र सहित जो, उठा न पाए कोई उसको॥"],meaning:"यदि तराजू के एक पलड़े पर संसार के समस्त मंत्र और गुण रख दिए जाएँ और दूसरे पर केवल णमोकार महामंत्र, तो णमोकार का पलड़ा ही सदा भारी और अनुपम रहेगा।"},{number:"१७",tag:"चौपाई",lines:["उठते चलते सभी क्षणों में, जंगल पर्वत या महलों में।","महामंत्र को कभी न छोड़ो, सदा इसी से नाता जोड़ो॥"],meaning:"उठते-बैठते, चलते-फिरते, वन में, पर्वत पर या महलों में—प्रत्येक पल इस महामंत्र का आश्रय रखो और अपनी आत्मा का नाता सदा इसी से जोड़कर रखो।"},{number:"१८",tag:"चौपाई",lines:["देखो! इक सुभौम चक्री था, उसने मन में इसे जपा था।","देव मार नहिं पाया उसको, तब छल युक्ति बताई नृप को॥"],meaning:"जब सुभौम चक्रवर्ती मन में णमोकार मंत्र का स्मरण कर रहा था, तब वैरी देव भी उसका बाल बाँका न कर सका; तब देव ने छलपूर्वक राजा को बहकाया।"},{number:"१९",tag:"चौपाई",lines:["उसके चंगुल में फस करके, लिखा मंत्र राजा ने जल में।","ज्यों ही उस पर कदम रख दिया, देव की शक्ती प्रगट कर दिया॥"],meaning:"देव के झाँसे में आकर राजा ने जल पर पत्ते पर मंत्र लिखा और ज्यों ही उस पर पैर रखा, मंत्र की अविनय होते ही देव ने उस पर प्रहार कर दिया।"},{number:"२०",tag:"चौपाई",lines:["देव ने उसको मार गिराया, नरक धरा को नृप ने पाया।","मंत्र का यह अपमान कथानक, सचमुच ही है हृदय विदारक॥"],meaning:"देव ने चक्रवर्ती को समुद्र में डुबो दिया और वह सातवें नरक पहुँचा। यह कथानक सिखाता है कि महामंत्र की कभी स्वप्न में भी अविनय नहीं करनी चाहिए।"},{number:"२१",tag:"चौपाई",lines:["भावों से भी न अविनय करना, सदा मंत्र पर श्रद्धा करना।","इसके लेखन में भी फल है, हाथ नेत्र हो जाएं सफल है॥"],meaning:"मन से भी कभी अविनय न करें और सदा इस मंत्र पर अडिग श्रद्धा रखें। णमोकार मंत्र का एक-एक अक्षर लिखने से हाथ और नेत्र पवित्र व सफल हो जाते हैं।"},{number:"२२",tag:"चौपाई",lines:["णमोकार की बैंक खुली है, ज्ञानमती प्रेरणा मिली है।","जम्बूद्वीप-हस्तिनापुर में, मंत्रों का व्यापक संग्रह है॥"],meaning:"पूज्य गणिनीप्रमुख ज्ञानमती माताजी की प्रेरणा से हस्तिनापुर जम्बूद्वीप में णमोकार बैंक की स्थापना हुई, जहाँ करोड़ों भक्तों द्वारा हस्तलिखित मंत्रों का संचय है।"},{number:"२३",tag:"चौपाई",lines:["इसकी किरण प्रभा से जग में, फैले सुख शांती जन-जन में।","मन-वच-तन से इसे नमन है, महामंत्र का करूं स्मरण मैं॥"],meaning:"इस महामंत्र के आध्यात्मिक प्रकाश से सम्पूर्ण संसार के जन-जन में सुख और शांति फैले। मैं मन, वचन, काय से इस अनादिनिधन महामंत्र को कोटिशः नमन व स्मरण करता हूँ।"},{number:"२४",tag:"जाप मंत्र",lines:["॥ अनादिनिधन मूल णमोकार महामंत्र ॥","णमो अरिहंताणं।","णमो सिद्धाणं।","णमो आयरियाणं।","णमो उवज्झायाणं।","णमो लोए सव्वसाहूणं॥","एसो पंचणमोक्कारो, सव्वपावप्पणासणो। मंगलाणं च सव्वेसिं, पढमं हवइ मंगलं॥"],meaning:"अरिहंतों को नमस्कार हो, सिद्धों को नमस्कार हो, आचार्यों को नमस्कार हो, उपाध्यायों को नमस्कार हो, लोक के सर्व साधुओं को नमस्कार हो। यह पंच नमस्कार मंत्र सभी पापों का नाश करने वाला है और सभी मंगलों में प्रथम मंगल है।"}]},"neminath-chalisa":{id:"neminath-chalisa",category:"chalisa",title:"श्री नेमिनाथ चालीसा (दोहा, चौपाई एवं भावार्थ सहित)",subtitle:"२२वें तीर्थंकर नेमिनाथ भगवान (गिरनार तीर्थ) - ४० पद्य स्तुति, दोहा, चौपाई व भावार्थ सहित",type:"structured",verses:[{number:"दोहा",lines:["दोहा","बाइसवें तीर्थेश के, चालीसा का पाठ।","पढ़ने से हो जाएगा, तुमको भी वैराग॥","विद्यादेवी को नमूँ, वो ही देंगी ज्ञान।","बिना ज्ञान कैसे करूँ, नेमिनाथ गुणगान॥"],meaning:"बाइसवें तीर्थंकर भगवान नेमिनाथ स्वामी के इस पावन चालीसा का श्रद्धापूर्वक पाठ करने से आत्मा में संसार, शरीर और भोगों के प्रति सच्चा वैराग्य उत्पन्न होता है। ज्ञान की अधिष्ठात्री जिनवाणी माँ विद्यादेवी को नमन करता हूँ, क्योंकि उनकी कृपा के बिना प्रभु नेमिनाथ के अनन्त वीतरागी गुणों का स्तवन करना संभव नहीं है।"},{number:"१",lines:["चौपाई","श्री जिनवाणी शीश धार कर, सिद्ध प्रभु का करके ध्यान।","लिखूँ नेमि-चालीसा सुखकार, नेमिप्रभु की शरण में आन॥"],meaning:"द्वादशांग जिनवाणी माता को अपने शीश पर धारण करके और अष्टकर्म मुक्त सिद्ध परमेष्ठियों का ध्यान धरते हुए, मैं भगवान नेमिनाथ की शरण में आकर आत्मिक सुख प्रदान करने वाले इस पावन चालीसा की रचना करता हूँ।"},{number:"२",lines:["समुद्रविजय यादव कुलराई, शौरीपुर रजधानी कहाई।","शिवादेवी उनकी महारानी, षष्ठी कार्तिक शुक्ल बखानी॥"],meaning:"यदुवंश के शिरोमणि धर्मात्मा राजा समुद्रविजय शौरीपुर (शौरीपुरी) के प्रतापी नरेश थे। उनकी परम पूज्य पटरानी महारानी शिवादेवी थीं, जिनके गर्भ में कार्तिक शुक्ल षष्ठी के दिन तीर्थंकर प्रभु नेमिनाथ का पावन अवतरण हुआ।"},{number:"३",lines:["सुख से शयन करें शय्या पर, सपने देखे सोलह सुन्दर।","तज विमान जयंत अवतारे, हुए मनोरथ पूरण सारे॥"],meaning:"माता शिवादेवी ने शय्या पर सुखपूर्वक शयन करते हुए रात्रि के अंतिम पहर में तीर्थंकर जन्म सूचक सोलह मंगल स्वप्न देखे। प्रभु जयंत अनुत्तर विमान के दिव्य सुखों को त्यागकर माता के गर्भ में पधारे, जिससे माता-पिता व सम्पूर्ण जगत के मनोरथ पूर्ण हो गए।"},{number:"४",lines:["प्रतिदिन महल में रतन बरसते, यदुवंशी निज मन में हरषते।","दिन षष्ठी श्रावण शुक्ला का, हुआ अभ्युदय पुत्र रतन का॥"],meaning:"देवों द्वारा छह माह पूर्व से ही प्रतिदिन राजप्रासाद में रत्नों की वर्षा की जाती थी, जिससे समस्त यदुवंशी अत्यंत हर्षित थे। श्रावण शुक्ल षष्ठी के मंगलमय प्रभात पर जगत को प्रकाशित करने वाले तीर्थंकर पुत्र-रत्न का जन्म हुआ।"},{number:"५",lines:["तीन लोक में आनंद छाया, प्रभु को मेरु पर पधराया।","न्हवन हेतु जल ले क्षीरसागर, मणियों के थे कलश मनोहर॥"],meaning:"प्रभु के जन्म से तीनों लोकों में अपार आनंद छा गया। देवराज सौधर्म इन्द्र प्रभु को ऐरावत हाथी पर बैठाकर सुमेरु पर्वत की पांडुकशिला पर ले गए और क्षीरसागर के पवित्र जल से भरे मणिमय कलशों से जन्माभिषेक किया।"},{number:"६",lines:["कर अभिषेक किया परणाम, अरिष्टनेमि दिया शुभ नाम।","शोभित तुमसे सत्य मराल, जीता तुमने काल कराल॥"],meaning:"इन्द्रों ने 1008 कलशों से महाभिषेक कर प्रभु के चरणों में प्रणाम किया और अरिष्टों (संकटों) का नाश करने के कारण आपका शुभ नाम 'अरिष्टनेमि' रखा। हे प्रभु! आपने सत्य और अहिंसा के मार्ग पर चलकर काल के भयंकर चक्र को जीत लिया।"},{number:"७",lines:["सहस अष्ट लक्षण सुललाम, नीलकमल सम वर्ण अभिराम।","वज्र शरीर दस धनुष उतंग, लज्जित तुम छवि देव अनंग॥"],meaning:"आपका दिव्य शरीर एक हजार आठ शुभ लक्षणों से सुशोभित था, और आपका वर्ण नीलकमल के समान परम सुंदर और मनमोहक था। दस धनुष ऊँची वज्र-वृषभ-नाराच संहनन वाली काया की वीतराग शोभा देखकर कामदेव का रूप-गर्व भी लज्जित हो जाता था।"},{number:"८",lines:["चाचा–ताऊ रहते साथ, नेमि–कृष्ण चचेरे भ्रात।","धरा जब यौवन जिनराई, राजुल के संग हुई सगाई॥"],meaning:"शौरीपुर में महाराज समुद्रविजय और वासुदेव जी सप्रेम साथ रहते थे; इस प्रकार नेमिनाथ प्रभु और नारायण श्रीकृष्ण परस्पर चचेरे भाई थे। जब प्रभु ने यौवन में प्रवेश किया, तब जूनागढ़ के राजा उग्रसेन की रूपवती सुपुत्री राजुल (राजीमती) के साथ आपका विवाह संबंध तय हुआ।"},{number:"९",lines:["जूनागढ़ को चली बरात, छप्पन कोटि यादव साथ।","सुना वहाँ पशुओं का क्रन्दन, तोड़ा मोर–मुकुट और कंगन॥"],meaning:"छप्पन करोड़ यादवों के विशाल वैभव और ठाठ-बाट के साथ प्रभु नेमिनाथ की भव्य बारात जूनागढ़ पहुँची। वहाँ तोरण द्वार के समीप भोजन हेतु बाड़े में बंद मूक पशुओं का दारुण क्रन्दन सुनकर प्रभु का करुणा-हृदय द्रवित हो उठा; उन्होंने तत्काल विवाह का मोर-मुकुट और कंगन उतार फेंका।"},{number:"१०",lines:["बाड़ा खोल दिया पशुओं का, धारा वेष दिगम्बर मुनि का।","कितना अद्भुत संयम मन में, ज्ञानीजन अनुभव करें मन में॥"],meaning:"प्रभु ने समस्त पशुओं को बंधनमुक्त कराकर अभयदान दिया और विवाह-मंडप से ही रथ मोड़कर गिरनार पर्वत की ओर प्रस्थान किया। आपने राजसी वस्त्र त्यागकर निर्ग्रन्थ दिगम्बर मुनि दीक्षा अंगीकार की; आपके मन का यह अलौकिक वैराग्य और संयम केवल ज्ञानीजन ही अनुभव कर सकते हैं।"},{number:"११",lines:["नौ-नौ आँसू राजुल रोवे, बारम्बार मूर्छित होवे।","फेंक दिया दुल्हन श्रृंगार, रो-रो कर यों करे पुकार॥"],meaning:"नेमिनाथ को विरक्त होकर मुनि बनते देख राजुल वियोग की तीव्र वेदना में फूट-फूटकर रोने लगी और बार-बार मूर्छित होने लगी। उसने अपना सारा दुल्हन का श्रृंगार उतार फेंका और विलाप करते हुए पुकारने लगी।"},{number:"१२",lines:["नौ भव की तोड़ी क्यों प्रीत, कैसी है ये धर्म की रीत।","नेमि दें उपदेश त्याग का, उमड़ा सागर वैराग्य का॥"],meaning:"राजुल ने कहा—हे स्वामी! हमारे पिछले नौ भवों की अनन्य प्रीति को आपने एक पल में क्यों तोड़ दिया? तब प्रभु नेमिनाथ ने संसार की असारता और मोक्षमार्ग का पावन उपदेश दिया, जिससे राजुल के अंतर्मन में भी वैराग्य का अगाध सागर उमड़ पड़ा।"},{number:"१३",lines:["राजुल ने भी ले ली दीक्षा, हुई संयम उत्तीर्ण परीक्षा।","दो दिन रहकर के निराहार, तीसरे दिन करें स्वामी विहार॥"],meaning:"राजुल ने भी समस्त सांसारिक मोह त्यागकर आर्यिका दीक्षा ग्रहण की और कठिन संयम की परीक्षा में उत्तीर्ण हुई। इधर प्रभु नेमिनाथ ने दो दिन का निर्जल उपवास कर तीसरे दिन मुनि-चर्या हेतु विहार किया।"},{number:"१४",lines:["वरदत्त महीपति दें आहार, पंचाश्चर्य हुए सुखकार।","रहे मौन से छप्पन दिन तक, तपते रहे कठिनतम तप व्रत॥"],meaning:"राजा वरदत्त ने परम भक्तिभाव से मुनिराज को विशुद्ध आहार दान देकर अपना जीवन धन्य किया, जिस पर देवों ने पंचाश्चर्य किए। प्रभु गिरनार पर छप्पन दिनों तक मौनपूर्वक ध्यानस्थ रहकर कठिन तपश्चर्या में लीन रहे।"},{number:"१५",lines:["प्रतिपदा आश्विन उजियारी, हुए केवली प्रभु अविकारी।","समोशरण की रचना करते, सुरगण ज्ञान की पूजा करते॥"],meaning:"आश्विन शुक्ल प्रतिपदा के पावन दिन मेषश्रृंग (बांस) वृक्ष के नीचे घातिया कर्मों का क्षय कर प्रभु निर्विकार केवलज्ञानी बने। कुबेर ने दिव्य समवसरण रचा और इन्द्रादिक देवों ने प्रभु के दिव्य केवलज्ञान की महापूजा की।"},{number:"१६",lines:["भवि जीवों के पुण्य प्रभाव से, दिव्य ध्वनि खिरती सद्भाव से।","जो भी होता है आत्मज्ञ, वो ही होता है सर्वज्ञ॥"],meaning:"भव्य जीवों के महान पुण्योदय से समवसरण में प्रभु की ओंकारमयी दिव्य देशना खिरी। प्रभु ने समझाया कि जो अपनी शुद्ध आत्मा को यथार्थ रूप से जान लेता है, वही आगे चलकर लोकालोक का ज्ञाता सर्वज्ञ बनता है।"},{number:"१७",lines:["ज्ञानी निज आतम को निहारे, अज्ञानी पर्याय संवारे।","है अद्भुत वैरागी दृष्टि, स्वाश्रित हो तजते सब सृष्टि॥"],meaning:"ज्ञानी साधक सदैव अपने ध्रुव, त्रिकाली शुद्ध चैतन्य आत्म-तत्व का अवलोकन करता है, जबकि अज्ञानी मिथ्यादृष्टि बाह्य नश्वर पर्यायों को ही सजाने-संवारने में जीवन व्यर्थ गंवा देता है। प्रभु की स्वाश्रित वीतराग दृष्टि ने सम्पूर्ण भौतिक सृष्टि से अनासक्त होना सिखाया।"},{number:"१८",lines:["जैन धर्म तो धर्म सभी का, है निजधर्म ये प्राणीमात्र का।","जो भी पहचाने जिनदेव, वो ही जाने आतम देव॥"],meaning:"वीतराग जैन धर्म किसी संप्रदाय विशेष का नहीं, बल्कि सम्पूर्ण चराचर जगत के प्राणीमात्र का स्वभाव-धर्म (अहिंसा व आत्म-धर्म) है। जो वीतरागी जिनदेव के स्वरूप को यथार्थ पहचानता है, वही अपने भीतर विराजमान परमात्मा आत्म-देव को जान पाता है।"},{number:"१९",lines:["रागादि के उन्मूलन को, पूजें सब जिनदेवचरण को।","देश-विदेश में हुआ विहार, गए अन्त में गढ़ गिरनार॥"],meaning:"आत्मा के राग, द्वेष और मोह रूपी विकारों को समूल नष्ट करने हेतु सभी भव्य जीव जिनदेव के पावन चरणों की पूजा करते हैं। धर्म की अपार प्रभावना करते हुए प्रभु का भव्य विहार हुआ और अंत में वे गिरनार जी की उर्जयंत कूट पधारे।"},{number:"२०",lines:["सब कर्मों का करके नाश, प्रभु ने पाया पद अविनाश।","जो भी प्रभु की शरण में आते, उनको मनवांछित मिल जाते॥"],meaning:"आषाढ़ शुक्ल अष्टमी के पावन दिन अघातिया कर्मों का पूर्ण क्षय कर प्रभु नेमिनाथ गिरनार जी के पाँचवें टोंक से मोक्ष पधारे और अविनाशी सिद्ध पद प्राप्त किया। जो भी भक्त निष्काम भाव से प्रभु की शरण में आता है, उसे आत्मकल्याण और परम शांति प्राप्त होती है।"},{number:"दोहा",lines:["दोहा","ज्ञानार्जन करके शास्त्रों से, अर्पण करते श्रद्धा से।","'अरुणा' बस ये ही वर चाहे, निज आतम दर्शन हो जाए॥","(जाप: ॐ ह्रीं अर्हं श्री नेमिनाथाय नमः)"],meaning:"जिनवाणी शास्त्रों से स्वाध्याय व ज्ञानार्जन करके यह चालीसा प्रभु के पावन चरणों में पूर्ण श्रद्धा से समर्पित है। हे प्रभु! हम सांसारिक वैभव नहीं मांगते, केवल यही मंगल वरदान मांगते हैं कि हमें अपने शुद्ध आत्म-स्वरूप के प्रत्यक्ष दर्शन हो जाएं और हम संसार-बंधन से मुक्त हों।"}]},"padmaprabhu-chalisa":{id:"padmaprabhu-chalisa",category:"chalisa",title:"श्री पद्मप्रभु चालीसा (दोहा, चौपाई एवं भावार्थ सहित)",subtitle:"पद्मपुरा अतिशय क्षेत्र - ४० पद्य स्तुति, दोहा, चौपाई व सोरठा सहित",type:"structured",verses:[{number:"दोहा",lines:["दोहा","शीश नवा अरिहंत को, सिद्धन करूँ प्रणाम।","उपाध्याय आचार्य का, ले गुणकारी नाम॥","सर्व साधु और सरस्वती, जिनमन्दिर सुखकार।","पदमपुरी के पद्म को, मन मंदिर में धार॥"],meaning:"अनंत चतुष्टय से शोभायमान अरिहंत देव को शीश नवाकर और अष्टकर्म मुक्त सिद्ध परमेष्ठी को प्रणाम करके, मोक्षमार्ग के मार्गदर्शक आचार्य एवं उपाध्याय परमेष्ठी के पावन नाम का स्मरण करता हूँ। समस्त साधु परमेष्ठी, जिनवाणी सरस्वती माता और आत्मकल्याणकारी जिनमंदिरों को नमन करते हुए, पदमपुरा अतिशय क्षेत्र के अधिपति भगवान पद्मप्रभु को अपने मन-मंदिर में धारण करता हूँ।"},{number:"१",lines:["चौपाई","जय श्री पद्मप्रभु गुणकारी, भविजनों को तुम हो हितकारी।","देवों के तुम देव कहाओ, छठे तीर्थंकर कहलाओ॥"],meaning:"हे अनन्त गुणों के धारक श्री पद्मप्रभु भगवान! आपकी जय हो। आप संसार के सभी भव्य जीवों का कल्याण करने वाले परम हितैषी हैं। आप इन्द्रादिक समस्त देवों के भी पूज्य देव हैं और इस अवसर्पिणी काल के छठे तीर्थंकर के रूप में सुशोभित हैं।"},{number:"२",lines:["तीन काल तिहुँ जग को जानो, सब बातों को क्षण में पहचानो।","वेष दिगंबर धारण हारे, तुमसे कर्म शत्रु भी हारे॥"],meaning:"आप तीनों कालों (भूत, भविष्य, वर्तमान) और तीनों लोकों के समस्त चराचर पदार्थों को एक साथ, एक क्षण में प्रत्यक्ष जानने वाले सर्वज्ञ देव हैं। आपने परिग्रह-रहित निर्ग्रन्थ दिगम्बर भेष धारण किया और अपनी आत्मसाधना से प्रबल कर्म-शत्रुओं को पूर्णतः पराजित कर दिया।"},{number:"३",lines:["मूर्ति तुम्हारी कितनी सुन्दर, दृष्टि सुखद जमती नासा पर।","क्रोध मान मद लोभ भगाया, राग द्वेष का लेश ना पाया॥"],meaning:"हे प्रभु! आपकी वीतरागी प्रतिमा कितनी अनुपम, शांत और दिव्य है! आपकी सुखदायी दृष्टि नासिका के अग्रभाग पर निश्चल रूप से टिकी हुई है। आपने क्रोध, मान, माया और लोभ रूपी चारों कषायों को समूल नष्ट कर दिया है, आपके भीतर राग और द्वेष का लेशमात्र भी अंश शेष नहीं है।"},{number:"४",lines:["वीतराग तुम कहलाते हो, सब जग के मन को भाते हो।","कौशाम्बी नगरी कहलाए, राजा धारण जी बतलाए॥"],meaning:"समस्त सांसारिक विकारों और मोह से परे होने के कारण आप वीतराग कहलाते हैं; आपकी यह परम शांत मुद्रा तीनों लोकों के भव्य जीवों के मन को आनंदित करती है। आपका गर्भ एवं जन्म कल्याणक पवित्र कौशाम्बी नगरी में हुआ, जहाँ के धर्मात्मा राजा धरण आपके पिता थे।"},{number:"५",lines:["सुन्दर नाम सुसीमा उनके, जिनके उर से स्वामी जन्मे।","कितनी लम्बी उमर कहाई, तीस लाख पूरब बतलाई॥"],meaning:"आपकी परम पूज्या माता का शुभ नाम महारानी सुसीमा था, जिनकी पवित्र कोख से जगत्कल्याणक तीर्थंकर प्रभु का जन्म हुआ। शास्त्रों में आपकी पावन आयु तीस लाख पूर्व की बताई गई है, जो धर्म प्रभावना और आत्म-कल्याण से परिपूर्ण रही।"},{number:"६",lines:["इक दिन हाथी बंधा निरख कर, झट आया वैराग्य उमड़कर।","कार्तिक सुदी त्रयोदशी भारी, तुमने मुनि पद दीक्षा धारी॥"],meaning:"एक दिन सांकलों में बंधे हाथी को देखकर आपके हृदय में संसार की अनित्यता और पराधीनता का गहरा बोध जागृत हुआ और तीव्र वैराग्य उमड़ पड़ा। इसके पश्चात कार्तिक शुक्ला त्रयोदशी के मंगलकारी दिन आपने समस्त राज-वैभव त्यागकर परम पावन दिगम्बर मुनि दीक्षा धारण की।"},{number:"७",lines:["सारे राज-पाट को तज कर, तभी मनोहर वन में पहुँचे।","तप कर केवलज्ञान उपाया, चैत्र सुदी पूनम कहलाया॥"],meaning:"समस्त राजसी सुखों और परिग्रह को तृण समान त्यागकर आप मनोहर वन में पधारे और ध्यान में लीन हो गए। घोर तपस्या के पश्चात चैत्र शुक्ल पूर्णिमा के दिन आपने चार घातिया कर्मों का नाश कर लोकालोक-प्रकाशी केवलज्ञान (दिव्य ज्ञान) प्राप्त किया।"},{number:"८",lines:["एक सौ दस गणधर बतलाए, मुख्य वज्र चामर कहलाए।","लाखों मुनि आर्यिका लाखों, श्रावक और श्राविका लाखों॥"],meaning:"आपके समवसरण में एक सौ दस मुख्य गणधर मुनिराज थे, जिनमें प्रमुख गणधर वज्रचामर जी थे। आपके चतुर्विध संघ में लाखों वीतरागी मुनिराज, लाखों आर्यिका माताएं, और लाखों संयमी श्रावक-श्राविकाएं मोक्षमार्ग पर आरूढ़ थीं।"},{number:"९",lines:["असंख्यात तिर्यंच बताए, देवी-देव गिनत नहीं पाए।","फिर सम्मेद शिखर पर जाकर, शिवरमणी को ली परणाकर॥"],meaning:"समवसरण में आपकी दिव्य देशना श्रवण करने के लिए असंख्यात तिर्यंच जीव तथा अगणित देव-देवियाँ भक्तिभाव से उपस्थित होते थे। धर्म-प्रचार पूर्ण कर अंत में श्री सम्मेद शिखर जी के पावन मोक्ष-कूट से आपने निर्वाण प्राप्त कर शाश्वत मोक्ष-लक्ष्मी को वरण किया।"},{number:"१०",lines:["पंचम काल महादुखदायी, जब तुमने महिमा दिखलाई।","जयपुर राज ग्राम बाड़ा है, स्टेशन शिवदासपुरा है॥"],meaning:"इस पंचम काल (कलिकाल) के घोर संकटमय और दुखदायी युग में, आपने अपनी असीम अतिशयकारी महिमा से भक्तों का उद्धार किया। राजस्थान के जयपुर राज्य में शिवदासपुरा स्टेशन के निकट 'बाड़ा' नामक एक पावन गाँव स्थित है।"},{number:"११",lines:["मूला नाम जाट का लड़का, घर की नींव खोदने लगा।","खोदत-खोदत मूर्ति दिखाई, उसने जनता को दिखलाई॥"],meaning:"उस बाड़ा ग्राम में मूला नामक एक जाट युवक जब अपने घर के निर्माण के लिए ज़मीन की नींव खोद रहा था, तब भूमि के भीतर से प्रभु की एक चमत्कारी और अत्यंत सुंदर प्राचीन जिनप्रतिमा प्रकट हुई, जिसे उसने सभी ग्रामवासियों को दिखाया।"},{number:"१२",lines:["चिन्ह कमल लख लोग-लुगाई, पद्मप्रभु की मूर्ति बताई।","मन में अति हर्षित होते हैं, अपने मन का मल धोते हैं॥"],meaning:"प्रतिमा के चरण-कमलों पर कमल का पावन लांछन (चिन्ह) देखकर सभी नर-नारियों ने श्रद्धापूर्वक पहचान लिया कि यह साक्षात् छठे तीर्थंकर भगवान पद्मप्रभु हैं। सभी श्रद्धालु अत्यंत आनंदित होकर दर्शन करते हैं और अपने पाप-मल को धोकर अंतःकरण को पवित्र करते हैं।"},{number:"१३",lines:["तुमने यह अतिशय दिखलाया, भूत-प्रेत को दूर भगाया।","जब गंधोदक छींटे मारें, भूत-प्रेत तब आप बकारें॥"],meaning:"हे पदमपुरा के पद्मप्रभु स्वामी! आपने यह प्रत्यक्ष चमत्कार दिखाया कि आपके स्मरण मात्र से भूत-प्रेत और नकारात्मक शक्तियाँ दूर भाग जाती हैं। जब पीड़ित व्यक्ति पर आपकी प्रतिमा का पावन गंधोदक छिड़का जाता है, तब समस्त दुष्ट उपद्रव स्वतः शांत हो जाते हैं।"},{number:"१४",lines:["जपने से जप नाम तुम्हारा, भूत-प्रेत वो करे किनारा।","ऐसी महिमा बतलाते हैं, अंधे भी आँखें पाते हैं॥"],meaning:"जो भी भक्त श्रद्धापूर्वक आपके नाम का निरंतर जाप करता है, बुरी शक्तियाँ और संकट उससे दूर रहते हैं। आपकी ऐसी अलौकिक महिमा है कि प्रभु की कृपा से दृष्टिहीन लोगों को भी दृष्टि प्राप्त हो जाती है और उनके जीवन का अंधकार दूर होता है।"},{number:"१५",lines:["प्रतिमा श्वेत वर्ण कहलाए, देखत ही हृदय को भाए।","ध्यान तुम्हारा जो धरता है, इस भव से वो नर तरता है॥"],meaning:"पद्मासन मुद्रा में आपकी श्वेत वर्ण की पाषाण प्रतिमा इतनी मनमोहक है कि देखते ही हृदय में भक्ति और वैराग्य का संचार हो जाता है। जो भी प्राणी एकाग्रचित्त होकर आपका ध्यान करता है, वह इस संसार-सागर के दुखों से सहज ही पार उतर जाता है।"},{number:"१६",lines:["अंधा देखे गूंगा गावे, लंगड़ा पर्वत पर चढ़ जावे।","बहरा सुन-सुन खुश होवे, जिस पर कृपा तुम्हारी होवे॥"],meaning:"हे कृपानिधान! जिस भक्त पर आपकी अनुकंपा हो जाती है, अंधा देखने लगता है, मूक वाणी पाकर आपकी स्तुति गाने लगता है, पंगु भी विशाल पर्वत लांघ जाता है और बधिर भी आनंदित होकर सुनता है; आपके प्रताप से असंभव भी संभव हो जाता है।"},{number:"१७",lines:["भव-भव के सब संकट टारो, शरण गहे की लाज सम्हारो।","रोग-शोक सब दूर नसाओ, सुख-संपति घर-घर उपजाओ॥"],meaning:"हे प्रभु! हमारे जन्म-जन्मांतर के संकटों और पापों को नष्ट कीजिए। हम आपकी शरण में आए हैं, हमारी लाज रखिए। हमारे समस्त शारीरिक रोगों और मानसिक संतापों का नाश कर घर-घर में धर्म, सुख, शांति और आध्यात्मिक समृद्धि का संचार कीजिए।"},{number:"१८",lines:["दुःख दारिद्र विपत्ति हर लीजे, अविरल भक्ति प्रभु की दीजे।","सच्चे मार्ग पर हमें चलाओ, मोक्ष-महल का पंथ दिखाओ॥"],meaning:"हे जिनराज! हमारे सांसारिक दुःख, दरिद्रता और विपदाओं का हरण कीजिए तथा हमें अपनी अविचल वीतरागी भक्ति प्रदान कीजिए। हमें कुमार्ग और मिथ्यात्व से बचाकर सम्यक दर्शन-ज्ञान-चारित्र के सच्चे मोक्षमार्ग की ओर अग्रसर कीजिए।"},{number:"१९",lines:["तुम सम देव न जग में कोई, तुमसे ही सब कारज होई।","दिन-रात तेरे गुण गाऊँ, जन्म-मरण से मुक्ति पाऊँ॥"],meaning:"हे पद्मप्रभु! तीनों लोकों में आपके समान अन्य कोई वीतरागी और कल्याणकारी देव नहीं है। आपकी आराधना से सभी विघ्न शांत होते हैं। मैं अहर्निश आपके पावन गुणों का गान करता रहूँ और संसार के जन्म-मरण के बंधन से सदा के लिए मुक्त हो जाऊँ।"},{number:"२०",lines:["मैं हूँ स्वामी दास तुम्हारा, मेरी नैया कर दो पार।","चालीसे को 'चन्द्र' बनाए, पद्मप्रभु को शीश नवाए॥"],meaning:"हे प्रभु! मैं आपका विनम्र दास और अनन्य भक्त हूँ, भवसागर में डगमगाती मेरी जीवन-नैया को पार लगा दीजिए। कवि 'चन्द्र' ने अत्यंत भक्तिभाव से इस पावन चालीसा की रचना की है और वे भगवान पद्मप्रभु के चरणों में नतमस्तक होकर बारंबार प्रणाम करते हैं।"},{number:"सोरठा",lines:["सोरठा","नित ही चालीस बार, पाठ करे चालीस दिन।","खेय सुगंध अपार, पदमपुरी में आय के॥","होय कुबेर समान, जन्म दरिद्र होय जो।","जिसके नहीं संतान, नाम वंश जग में चले॥"],meaning:"जो भी श्रद्धालु पदमपुरा अतिशय क्षेत्र में आकर धूप-सुगंधि खेते हुए, चालीस दिनों तक नित्य चालीस बार इस चालीसा का श्रद्धापूर्वक पाठ करता है; यदि वह जन्म से निर्धन भी हो तो कुबेर के समान वैभव संपन्न बन जाता है, और निःसंतान व्यक्ति को सुपुत्र प्राप्त होकर उसका कुल-वंश संसार में यश पाता है।"}]},"parshvanath-chalisa":{id:"parshvanath-chalisa",category:"chalisa",title:"श्री पार्श्वनाथ चालीसा",subtitle:"अहिच्छत्र पार्श्वनाथ चालीसा (दोहा, चौपाई एवं भावार्थ सहित)",type:"structured",verses:[{number:"दोहा",lines:["दोहा","शीश नवा अरिहंत को, सिद्धन करूं प्रणाम।","उपाध्याय आचार्य का, ले सुखकारी नाम॥","सर्व साधु और सरस्वती, जिन मंदिर सुखकार।","अहिच्छत्र और पार्श्व को, मन मंदिर में धार॥"],meaning:"पंचपरमेष्ठी (अरिहंत, सिद्ध, आचार्य, उपाध्याय, साधु), ज्ञानमयी सरस्वती (जिनवाणी) एवं शांतिप्रदाता जिनमंदिर को शीश नवाकर वंदन करते हुए, अतिशय क्षेत्र अहिच्छत्र एवं तेईसवें तीर्थंकर भगवान पार्श्वनाथ को अपने हृदय-मंदिर में धारण करता हूँ।"},{number:"१",lines:["चौपाई","पार्श्वनाथ जगत हितकारी। हो स्वामी तुम व्रत के धारी॥","सुर नर असुर करें तुम सेवा। तुम ही सब देवन के देवा॥"],meaning:"हे भगवान पार्श्वनाथ! आप समस्त संसार का कल्याण करने वाले हैं तथा महाव्रतों के निष्ठावान धारी हैं। देव, मनुष्य और असुर सभी आपके पावन चरणों की सेवा करते हैं; आप देवों के भी देव देवाधिदेव हैं।"},{number:"२",lines:["तुमसे करम शत्रु भी हारा। तुम कीना जग का निस्तारा॥","अश्वसेन के राजदुलारे। वामा की आँखों के तारे॥"],meaning:"आपने अपनी आत्मसाधना से समस्त कर्मरूपी शत्रुओं को पराजित किया और भव्य जीवों का संसार-सागर से उद्धार किया। आप वाराणसी के राजा अश्वसेन के राजदुलारे पुत्र तथा माता वामादेवी के नयनों के तारे (परम प्रिय) हैं।"},{number:"३",lines:["काशी जी के स्वामी कहाये। सारी परजा मौज उड़ाए॥","इक दिन सब मित्रों को लेके। सैर करन को वन में पहुँचे॥"],meaning:"आप काशी (वाराणसी) नगरी के राजकुमार व स्वामी कहलाए, आपके पुण्य-प्रताप से सारी प्रजा आनंदपूर्वक जीवन व्यतीत करती थी। एक दिन आप अपने सखा-मित्रों के साथ विहार व सैर करने के लिए वन में पधारे।"},{number:"४",lines:["हाथी पर कसकर अम्बारी। इक जंगल में गई सवारी॥","एक तपस्वी देख वहाँ पर। उससे बोले वचन सुनाकर॥"],meaning:"हाथी पर भव्य हौदा (अंबारी) कसकर प्रभु की सवारी जंगल की ओर आगे बढ़ी। वहाँ उन्होंने एक तपस्वी (कमठ/महिपाल) को पंचाग्नि तप करते देखा, तब करुणावश प्रभु ने उससे सत्य वचन कहे।"},{number:"५",lines:["तपसी! तुम क्यों पाप कमाते। इस लक्कड़ में जीव जलाते॥","तपसी तभी कुदाल उठाया। उस लक्कड़ को चीर गिराया॥"],meaning:"प्रभु ने कहा—'हे तपस्वी! तुम तपस्या के नाम पर व्यर्थ ही यह घोर पाप क्यों कमा रहे हो? इस जलती हुई लकड़ी (काष्ठ) के भीतर सूक्ष्म जीव जल रहे हैं।' यह सुनकर क्रोधी तपस्वी ने तुरंत कुदाल उठाकर उस जलती लकड़ी को चीरकर गिराया।"},{number:"६",lines:["निकले नाग-नागनी कारे। मरने के थे निकट बिचारे॥","रहम प्रभु के दिल में आया। तभी मंत्र नवकार सुनाया॥"],meaning:"चीरते ही उस काष्ठ से एक काला नाग और नागिन का युगल तड़पते हुए निकला, जो अग्नि की ज्वाला से मृत्यु के निकट थे। कुमार पार्श्व के हृदय में अपार करुणा उमड़ आई और उन्होंने तुरंत उन्हें परम पावन णमोकार महामंत्र सुनाया।"},{number:"७",lines:["मरकर वो पाताल सिधाए। पद्मावती धरणेन्द्र कहाए॥","तपसी मरकर देव कहाया। नाम कमठ ग्रंथों में गाया॥"],meaning:"महामंत्र के प्रभाव से शांत भाव सहित देह त्यागकर वह नाग युगल पाताल लोक में धरणेन्द्र और पद्मावती देव-देवी बने। उधर मिथ्या तप और क्रोध के कारण तपस्वी मरकर संक्लेश परिणाम से भवनत्रिक देव (असुर) बना, जिसे शास्त्रों में 'कमठ' का जीव कहा गया है।"},{number:"८",lines:["एक समय श्री पारस स्वामी। राज छोड़कर वन की ठानी॥","तप करते थे ध्यान लगाए। इक दिन कमठ वहाँ पर आए॥"],meaning:"कालान्तर में वैराग्य जागृत होने पर श्री पार्श्वनाथ स्वामी ने राजपाट त्यागकर जिनदीक्षा अंगीकार की और वन में ध्यानस्थ हो गए। एक दिन जब प्रभु वन में ध्यानमग्न थे, तब पूर्वभव के वैरी कमठ का जीव (शंबर असुर) आकाश मार्ग से वहाँ से निकला।"},{number:"९",lines:["फौरन ही प्रभु को पहिचाना। बदला लेना दिल में ठाना॥","बहुत अधिक बारिश बरसाई। बादल गरजे बिजली गिराई॥"],meaning:"उसने नीचे तपस्या में लीन प्रभु पार्श्वनाथ को तुरंत पहचान लिया और पूर्व जन्म का बैर याद कर बदला लेने की ठानी। उसने भयंकर उपद्रव रचते हुए घनघोर मूसलाधार वर्षा की, बादल गर्जाए और बिजली गिराई।"},{number:"१०",lines:["बहुत अधिक पत्थर बरसाए। स्वामी तन को नहीं हिलाए॥","पद्मावती धरणेन्द्र भी आए। प्रभु की सेवा में चित लाए॥"],meaning:"कमठ के असुर ने भयंकर आंधी, शिलाओं और पत्थरों की वर्षा की, किन्तु भगवान पार्श्वनाथ अपने आत्म-ध्यान से लेशमात्र भी विचलित नहीं हुए। प्रभु पर हो रहे उपसर्ग को जानकर धरणेन्द्र और पद्मावती तुरंत भक्तिपूर्वक वहाँ पहुँचे।"},{number:"११",lines:["धरणेन्द्र ने फन फैलाया। प्रभु के सिर पर छत्र बनाया॥","पद्मावती ने फन फैलाया। उस पर स्वामी को बैठाया॥"],meaning:"धरणेन्द्र देव ने प्रभु के ऊपर अपने सहस्र फण फैलाकर छत्र का रूप बना दिया जिससे शिलाएँ और जल प्रभु को न छू सकें, तथा पद्मावती ने प्रभु के चरणों के नीचे कमल/फण बिछाकर रक्षा की।"},{number:"१२",lines:["कर्मनाश प्रभु ज्ञान उपाया। समोशरण देवेन्द्र रचाया॥","यही जगह अहिच्छत्र कहाए। पात्र केशरी जहाँ पर आए॥"],meaning:"उपसर्ग सहते हुए प्रभु ने चारों घातिया कर्मों का नाश कर दिया और उन्हें केवलज्ञान (अनंत ज्ञान) प्रकट हुआ। इन्द्रों ने भक्ति-भाव से दिव्य समवसरण की रचना की। सर्प के फण के छत्र से रक्षित होने के कारण यह पवित्र भूमि 'अहिच्छत्र' कहलाई, जहाँ महान विद्वान पात्रकेसरी स्वामी आए।"},{number:"१३",lines:["शिष्य पाँच सौ संग विद्वाना। जिनको जाने सकल जहाना॥","पार्श्वनाथ का दर्शन पाया। सबने जैन धरम अपनाया॥"],meaning:"महान तार्किक पात्रकेसरी अपने पाँच सौ प्रकांड विद्वान शिष्यों के साथ समवसरण में पधारे। प्रभु पार्श्वनाथ के दर्शन एवं दिव्यध्वनि का श्रवण कर उन सभी ने जैन धर्म और दिगंबर मुनि दीक्षा स्वीकार की।"},{number:"१४",lines:["अहिच्छत्र श्री सुन्दर नगरी। जहाँ सुखी थी परजा सगरी॥","राजा श्री वसुपाल कहाए। वो इक जिन मंदिर बनवाए॥"],meaning:"अहिच्छत्र एक अत्यंत समृद्ध और रमणीक नगरी थी, जहाँ की संपूर्ण प्रजा सुख-शांति से रहती थी। वहाँ के धर्मात्मा राजा वसुपाल ने प्रभु पार्श्वनाथ की भक्ति में एक विशाल और भव्य जिन-मंदिर का निर्माण कराया।"},{number:"१५",lines:["प्रतिमा पर पालिश करवाया। फौरन इक मिस्त्री बुलवाया॥","वह मिस्तरी मांस था खाता। इससे पालिश था गिर जाता॥"],meaning:"राजा ने जिनबिंब की प्रतिष्ठा के समय प्रतिमा पर स्वर्ण-पॉलिश (लेप) कराने के लिए एक शिल्पकार (कारीगर) को बुलाया। किंतु वह कारीगर मांसाहारी व व्यसनी था, जिसके कारण प्रतिमा पर पॉलिश टिकती नहीं थी और बार-बार गिर जाती थी।"},{number:"१६",lines:["मुनि ने उसे उपाय बताया। पारस दर्शन व्रत दिलवाया॥","मिस्त्री ने व्रत पालन कीना। फौरन ही रंग चढ़ा नवीना॥"],meaning:"तब एक पूज्य दिगंबर मुनिराज ने राजा और कारीगर को उपाय बताया कि पवित्रता के बिना जिनबिंब पर रंग नहीं चढ़ता। कारीगर को मांसाहार त्यागकर प्रभु पार्श्वनाथ के नित्य दर्शन और सदाचार का नियम दिलवाया गया। नियम लेते ही प्रतिमा पर नवीन अलौकिक रंग व कांति चढ़ गई।"},{number:"१७",lines:["गदर सतावन का किस्सा है। इक माली का यों लिक्खा है॥","वह माली प्रतिमा को लेकर। झट छुप गया कुँए के अन्दर॥"],meaning:"सन १८५७ के गदर (विद्रोह) के समय जब उपद्रवी मंदिर पर आक्रमण करने लगे, तब एक धर्मनिष्ठ माली ने प्रभु की पावन प्रतिमा की रक्षा हेतु उसे लेकर तुरंत एक सुरक्षित बावड़ी/कुएं में छिपा दिया।"},{number:"१८",lines:["उस पानी का अतिशय भारी। दूर होय सारी बीमारी॥","जो अहिच्छत्र हृदय से ध्यावे। सो नर उत्तम पदवी पावे॥"],meaning:"प्रभु के स्पर्श से उस बावड़ी/कुएं का जल अत्यंत पावन और चमत्कारी बन गया, जिसके पान और प्रक्षाल से भक्तों के रोग-कष्ट दूर होने लगे। जो भी भव्य जीव अहिच्छत्र पार्श्वनाथ का सच्चे हृदय से ध्यान करता है, वह संसार में उत्तम पद और सद्गति प्राप्त करता है।"},{number:"१९",lines:["पुत्र संपदा की बढ़ती हो। पापों की इकदम घटती हो॥","है तहसील आँवला भारी। स्टेशन पर मिले सवारी॥"],meaning:"प्रभु की भक्ति से संतान-सुख और धर्म-सम्मत संपत्ति की वृद्धि होती है तथा पूर्वोपार्जित पापों का क्षय होता है। यह पावन तीर्थ उत्तर प्रदेश के बरेली जिले की आंवला तहसील के निकट स्थित है, जहाँ स्टेशन से आवागमन के साधन सुलभ हैं।"},{number:"२०",lines:["रामनगर इक ग्राम बराबर। जिसको जाने सब नारी-नर॥","चालीसे को 'चन्द्र' बनाए। हाथ जोड़कर शीश नवाए॥"],meaning:"आंवला के पास रामनगर नामक प्रसिद्ध ऐतिहासिक ग्राम है जिसे सब जानते हैं। कवि 'चन्द्र' ने अत्यंत भक्ति-भाव से इस चालीस पद की चालीसा की रचना की है और दोनों हाथ जोड़कर प्रभु के चरणों में शीश नवाते हैं।"},{number:"सोरठा",lines:["सोरठा","नित चालीसहिं बार, पाठ करे चालीस दिन।","खेय सुगंध अपार, अहिच्छत्र में आय के॥","होय कुबेर समान, जन्म दरिद्री होय जो।","जिसके नहिं संतान, नाम वंश जग में चले॥"],meaning:"जो भव्य जीव चालीस दिनों तक प्रतिदिन चालीस बार इस चालीसा का पाठ करता है अथवा अहिच्छत्र अतिशय क्षेत्र में आकर प्रभु के सन्मुख अपार सुगंधित धूप खेता है—वह यदि जन्मांतर का दरिद्री भी हो तो धन-कुबेर के समान समृद्ध हो जाता है, और जिसके संतान न हो, उसके कुल और धर्म का यश जग में फैलता है।"}]},"pushpadanta-chalisa":{id:"pushpadanta-chalisa",category:"chalisa",title:"श्री पुष्पदन्त (सुविधिनाथ) चालीसा (दोहा, चौपाई एवं भावार्थ सहित)",subtitle:"९वें तीर्थंकर सुविधिनाथ - ४० पद्य स्तुति, दोहा, चौपाई व भावार्थ सहित",type:"structured",verses:[{number:"दोहा",lines:["दोहा","दुख से तप्त मरुस्थल भव में, सघन वृक्ष सम छायाकार।","पुष्पदन्त पद-छत्र-छाँव में, हम आश्रय पावें सुखकार॥"],meaning:"दुखों से तप्त इस संसार रूपी मरुस्थल में भगवान पुष्पदन्त का पावन चरण-कमल सघन वृक्ष की शीतल छाया के समान सुखदायी है। हम प्रभु के चरण-कमलों रूपी छत्र की पावन छाँव में शरण लेकर परम आत्मिक शांति और सुख प्राप्त करते हैं।"},{number:"१",lines:["चौपाई","जम्बूद्वीप के भरत क्षेत्र में, काकन्दी नामक नगरी में।","राज्य करें सुग्रीव बलधारी, जयरामा रानी थी प्यारी॥"],meaning:"जम्बूद्वीप के पवित्र भरत क्षेत्र की सुप्रसिद्ध काकन्दी (काकंदीपुर) नगरी में महाबलशाली धर्मात्मा राजा सुग्रीव न्यायपूर्वक राज्य करते थे। उनकी परम प्रिय और धर्मपरायण पटरानी का नाम महारानी जयरामा (रामा देवी) था।"},{number:"२",lines:["नवमी फाल्गुन कृष्ण बखानी, षोडश स्वप्न देखती रानी।","सुत तीर्थंकर गर्भ में आएं, गर्भ कल्याणक देव मनायें॥"],meaning:"फाल्गुन मास के कृष्ण पक्ष की नवमी तिथि को महारानी जयरामा ने रात्रि के अंतिम पहर में ऐरावत हाथी आदि सोलह मंगलकारी स्वप्न देखे। तीनों लोकों के स्वामी तीर्थंकर सुत के माता के उदर में आते ही देवराज इन्द्र सहित सुरगणों ने आकर प्रथम 'गर्भ कल्याणक' महोत्सव मनाया।"},{number:"३",lines:["प्रतिपदा मंगसिर उजियारी, जन्मे पुष्पदन्त हितकारी।","जन्मोत्सव की शोभा न्यारी, स्वर्गपुरी सम नगरी प्यारी॥"],meaning:"मार्गशीर्ष (अगहन) शुक्ल प्रतिपदा के पावन प्रभात पर समस्त जगत का कल्याण करने वाले नौवें तीर्थंकर भगवान पुष्पदन्त का जन्म हुआ। प्रभु के जन्मोत्सव पर इन्द्रों ने सुमेरु पर्वत पर जन्माभिषेक किया और काकन्दी नगरी स्वर्गपुरी के समान दिव्य वैभव से सुशोभित हो उठी।"},{number:"४",lines:["आयु थी दो लक्ष पूर्व की, ऊँचाई शत एक धनुष की।","थामी जब राज्य बागडोर, क्षेत्र वृद्धि हुई चहुँ ओर॥"],meaning:"भगवान पुष्पदन्त की पावन देह-आयु दो लाख पूर्व की तथा शरीर की दिव्य अवगाहना (ऊँचाई) एक सौ धनुष थी। युवावस्था में जब आपने न्याय और धर्म के साथ राज्य की बागडोर संभाली, तब चारों दिशाओं में प्रजा की सुख-समृद्धि और धर्म क्षेत्र का विस्तार हुआ।"},{number:"५",lines:["इच्छाएँ उनकी सीमित, मित्र प्रभु के हुए असीमित।","एक दिन उल्कापात देखकर, दृष्टिपात किया जीवन पर॥"],meaning:"आपके अंतःकरण में सांसारिक भोगों के प्रति कोई आसक्ति नहीं थी, आपकी इच्छाएँ अत्यंत सीमित थीं और जगत के सभी प्राणी आपके मित्र थे। एक दिन आकाश में एक तारे को टूटते (उल्कापात) देखकर आपने जीवन और संसार की क्षणभंगुरता पर गहरा विचार किया।"},{number:"६",lines:["स्थिर कोई पदार्थ न जग में, मिले न सुख किंचित् भवमग में।","ब्रह्मलोक से सुरगण आए, जिनवर का वैराग्य बढ़ाएं॥"],meaning:"आपने चिंतन किया कि इस जगत में कोई भी भौतिक पदार्थ स्थिर और नित्य नहीं है, संसार के इस चक्रव्यूह में सच्चा आत्मिक सुख किंचित् भी नहीं है। तभी ब्रह्मलोक से लौकांतिक देवों ने आकर प्रभु के इस निर्मल वैराग्य की स्तुति की।"},{number:"७",lines:["सुमति पुत्र को देकर राज, शिविका में प्रभु गए विराज।","पुष्पक वन में गए हितकार, दीक्षा ली संग भूप हज़ार॥"],meaning:"अपने सुयोग्य पुत्र सुमति को न्यायपूर्वक राज्य सौंपकर प्रभु सर्वार्थसिद्धि पालकी में विराजमान होकर पुष्पक वन पधारे। मार्गशीर्ष शुक्ल प्रतिपदा के दिन एक सहस्र राजाओं के साथ आपने सर्व-परिग्रह-मुक्त दिगम्बर मुनि दीक्षा अंगीकार की।"},{number:"८",lines:["गए शैलपुर दो दिन बाद, हुआ आहार वहाँ निराबाध।","पात्रदान से हर्षित होकर, पंचाश्चर्य करे सुर आकर॥"],meaning:"दो दिन के निर्जल उपवास के पश्चात प्रभु मुनिराज आहार चर्या हेतु शैलपुर नगर पधारे, जहाँ राजा पुष्पमित्र ने विधिपूर्वक पड़गाहन कर निर्दोष आहार कराया। उत्तम पात्र को दान देकर धन्य हुए नगर में देवों ने रत्नों और पुष्पों की वर्षा कर पंचाश्चर्य किए।"},{number:"९",lines:["प्रभुवर लौट गए उपवन को, तत्पर हुए कर्म-छेदन को।","लगी समाधि नाग वृक्ष तल, केवलज्ञान उपाया निर्मल॥"],meaning:"आहारोपरांत प्रभु पुनः उपवन में लौट आए और चार घातिया कर्मों के समूल नाश हेतु घोर तपश्चर्या में लीन हो गए। नाग (पाटल) वृक्ष के नीचे ध्यानस्थ होकर कार्तिक शुक्ल द्वितीया के दिन आपने निर्मल और लोकालोक-प्रकाशी केवलज्ञान प्राप्त किया।"},{number:"१०",lines:["इन्द्राज्ञा से समोशरण की, धनपति ने आकर रचना की।","दिव्य देशना होती प्रभु की, ज्ञान पिपासा मिटी जगत की॥"],meaning:"देवराज इन्द्र की आज्ञा से कुबेर ने अत्यंत भव्य बारह योजन वाले समवसरण की रचना की। प्रभु की ओंकारमयी दिव्य देशना (वाणी) प्रवाहित हुई, जिससे सम्पूर्ण जगत के भव्य जीवों की आध्यात्मिक और आत्मिक ज्ञान-पिपासा तृप्त हुई।"},{number:"११",lines:["अनुप्रेक्षा द्वादश समझाई, धर्म स्वरूप विचारो भाई।","शुक्ल ध्यान की महिमा गाई, शुक्ल ध्यान से हों शिवराई॥"],meaning:"समवसरण में प्रभु ने बारह अनुप्रेक्षाओं (अनित्य, अशरण आदि बारह भावनाओं) तथा अहिंसा, सत्य, अचौर्य, ब्रह्मचर्य और अपरिग्रह रूपी धर्म का मर्म समझाया। आपने बताया कि शुक्ल ध्यान की साधना से ही आत्मा समस्त कर्म-बंधनों को काटकर मोक्ष की महारानी (शिवराई) बन सकती है।"},{number:"१२",lines:["चारों भेद सहित धारो मन, मोक्षमहल में पहुँचो तत्क्षण।","मोक्ष मार्ग दर्शाया प्रभु ने, हर्षित हुए सकल जन मन में॥"],meaning:"शुक्ल ध्यान के चारों पावन भेदों (पृथक्त्व-वितर्क, एकत्व-वितर्क, सूक्ष्म-क्रिया, समुच्छिन्न-क्रिया) को चित्त में धारण कर जीव मोक्षमहल को प्राप्त करता है। प्रभु द्वारा उद्घाटित इस वीतरागी मोक्षमार्ग को समझकर समस्त भव्य जीवों का अंतःकरण परम हर्ष से भर गया।"},{number:"१३",lines:["इन्द्र करें प्रार्थना जोड़ कर, सुखद विहार हुआ श्री जिनवर।","गए अन्त में शिखर सम्मेद, ध्यान में लीन हुए निरखेद॥"],meaning:"इन्द्रों और देवों की करबद्ध प्रार्थना पर भगवान पुष्पदन्त का देश-देशांतर में भव्य विहार हुआ। अंत में आयु का अंतिम समय निकट जानकर आप पावन तीर्थ श्री सम्मेद शिखर जी पधारे और समस्त प्रवृत्तियों को रोककर निर्विकल्प शुक्ल ध्यान में लीन हो गए।"},{number:"१४",lines:["शुक्ल ध्यान से किया कर्मक्षय, सन्ध्या समय पाया पद अक्षय।","अश्विन अष्टमी शुक्ल महान, मोक्ष कल्याणक करें सुर आन॥"],meaning:"शुक्ल ध्यान के अंतिम चरण द्वारा आपने शेष चारों अघातिया कर्मों का क्षय कर सन्ध्या काल में अविनाशी, शाश्वत सिद्ध पद प्राप्त किया। आश्विन शुक्ल अष्टमी के महान दिवस पर समस्त देवों ने आकर प्रभु का पावन मोक्ष कल्याणक महोत्सव मनाया।"},{number:"१५",lines:["सुप्रभ कूट की करते पूजा, सुविधि नाथ नाम है दूजा।","मगरमच्छ है लक्षण प्रभु का, मंगलमय जीवन था उनका॥"],meaning:"सम्मेद शिखर जी की 'सुप्रभ कूट' से प्रभु का निर्वाण हुआ, जिसकी आज भी श्रद्धालु भावपूर्वक वंदना करते हैं। धर्म की विधि का विधान करने के कारण आपका दूसरा पावन नाम 'सुविधिनाथ' भी है। आपके चरण-कमलों का शुभ लांछन (चिन्ह) मगरमच्छ (नक्र) है।"},{number:"१६",lines:["शिखर सम्मेद में भारी अतिशय, प्रभु प्रतिमा है चमत्कारमय।","कलियुग में भी आते देव, प्रतिदिन नृत्य करें स्वयमेव॥"],meaning:"श्री सम्मेद शिखर जी के इस सुप्रभ कूट पर भारी अतिशय विद्यमान है; भगवान की प्रतिमा अलौकिक चमत्कारों से परिपूर्ण है। मान्यता है कि इस पंचम काल में भी अदृश्य देवगण आकर प्रभु की स्तुति में प्रतिदिन भक्ति-नृत्य करते हैं।"},{number:"१७",lines:["घुंघरू की झंकार गूंजती, सब के मन को मोहित करती।","ध्वनि सुनी हमने कानों से, पूजा की बहु उपमानों से॥"],meaning:"कूट के समीप मध्यरात्रि में देवों के दिव्य घुंघरुओं की झंकार गूंजती है जो साधकों के मन को आह्लादित कर देती है। अनेक श्रद्धालुओं ने इस अलौकिक ध्वनि को प्रत्यक्ष सुनकर प्रभु पुष्पदन्त की नाना प्रकार के उपमानों और स्तुतियों से पूजा-अर्चना की है।"},{number:"१८",lines:["हमको है ये दृढ़ श्रद्धान, भक्ति से पायें शिवथान।","भक्ति में शक्ति है न्यारी, राह दिखायें करुणाधारी॥"],meaning:"हमें प्रभु के वचनों और जैन दर्शन पर दृढ़ सम्यक श्रद्धान है कि वीतराग प्रभु की सच्ची भक्ति से ही शाश्वत मोक्ष स्थान (शिवथान) प्राप्त होता है। जिनभक्ति में अनुपम आत्मिक शक्ति है, हे करुणासिंधु पुष्पदन्त भगवान! हमें मुक्ति का सच्चा मार्ग दिखाइए।"},{number:"१९",lines:["पाप-ताप सब दूर भगाओ, भव-सागर से पार लगाओ।","पुष्पदन्त प्रभु शरण तिहारी, मेटो जन्म-मरण दुःख भारी॥"],meaning:"हे प्रभु! हमारे समस्त पापों, संतापों और मानसिक व्याधियों को दूर भगाइए और हमें इस अथाह भव-सागर से पार उतारिए। हे भगवान पुष्पदन्त! हम आपकी अनन्य शरण में आए हैं, हमारे जन्म-मरण के दारुण दुखों को समूल नष्ट कर दीजिए।"},{number:"२०",lines:["नित-प्रति जो प्रभु ध्यान लगावे, मनवांछित उत्तम फल पावे।","सुविधिनाथ स्वामी सुखकारी, जय-जय-जय जिनवर अविकारी॥"],meaning:"जो भव्य प्राणी प्रतिदिन एकाग्रचित्त होकर भगवान पुष्पदन्त का ध्यान करता है, वह मनवांछित आत्मिक सुख और धर्म, अर्थ, काम, मोक्ष रूपी उत्तम फल प्राप्त करता है। हे आनंददाता सुविधिनाथ स्वामी! हे निर्विकार परम प्रभु! आपकी सदा जय हो, जय हो, जय हो!"},{number:"दोहा",lines:["दोहा","पुष्पदन्त गुणगान से, निश्चित हो कल्याण।","हम सब अनुक्रम से मिले, अन्तिम पद निर्वाण॥"],meaning:"नौवें तीर्थंकर भगवान पुष्पदन्त (सुविधिनाथ) के पावन गुणों का निष्काम भाव से गान करने पर निश्चय ही आत्मकल्याण की प्राप्ति होती है। हम सभी भव्य साधकों को क्रमशः रत्नत्रय की पूर्णता प्राप्त हो और अंततः शाश्वत निर्वाण पद की प्राप्ति हो।"}]},"sambhavnath-chalisa":{id:"sambhavnath-chalisa",category:"chalisa",title:"श्री संभवनाथ चालीसा (दोहा, चौपाई एवं भावार्थ सहित)",subtitle:"तृतीय तीर्थंकर संभवनाथ - ४० पद्य स्तुति, दोहा, चौपाई व शंभु छंद सहित",type:"structured",verses:[{number:"दोहा",lines:["दोहा","श्री संभव जिनराज का, करने से गुणगान।","कोई असंभव कार्य भी, संभव हो तत्काल॥","चालीसा का पाठ मैं, लिखना चाहूँ आज।","वागीश्वरी माँ शारदा, दे दो आशीर्वाद॥"],meaning:"तृतीय तीर्थंकर भगवान श्री संभवनाथ जी का अनन्य भक्तिभाव से गुणगान करने पर संसार का कठिन से कठिन असंभव कार्य भी प्रभु कृपा से तत्काल संभव हो जाता है। आज मैं प्रभु संभवनाथ के चरणों में समर्पित यह पावन चालीसा लिखना चाहता हूँ; हे जिनवाणी-स्वरूपा वागीश्वरी सरस्वती माता! मुझे अपनी दिव्य बुद्धि और आशीर्वाद प्रदान कीजिए।"},{number:"१",lines:["चौपाई","संभव जिन की भक्ति कर लो, भववारिधि से तिरना हो तो।","नगरी श्रावस्ती अति प्यारी, मात सुषेणा वहाँ की रानी॥"],meaning:"यदि संसार रूपी अथाह भवसागर के दुखों से पार उतरना चाहते हो, तो श्रद्धापूर्वक भगवान संभवनाथ की वीतराग भक्ति करो। प्राचीन काल में अत्यंत रमणीक एवं वैभवशाली श्रावस्ती नगरी थी, जहाँ की धर्मपरायण पटरानी महारानी सुषेणा थीं।"},{number:"२",lines:["पुण्यशालि पितु दृढ़रथ राजा, जिनका नरभव सफल हुआ था।","संभव जिनवर ग्रैवेयक तज, आए मात गरभ में जिस दिन॥"],meaning:"श्रावस्ती के न्यायप्रिय, महाप्रतापी और पुण्यशाली राजा दृढ़रथ प्रभु के परम पूज्य पिता थे, जिनका मनुष्य भव तीर्थंकर-पिता बनकर सफल हो गया। भगवान संभवनाथ स्वर्ग के नव-ग्रैवेयक विमान के सुखों को त्यागकर महारानी सुषेणा के पवित्र गर्भ में पधारे।"},{number:"३",lines:["वह दिन फाल्गुन सुदि अष्टमी का, शुभ मंगलमय पावन क्षण था।","कार्तिक पूर्णिमा में प्रभु जन्मे, कीर्ति सुरभि व्यापी तिहुँ जग में॥"],meaning:"वह फाल्गुन शुक्ल अष्टमी का अत्यंत मंगलमय और पावन दिवस था, जब आपका गर्भ कल्याणक महोत्सव देवों द्वारा मनाया गया। इसके पश्चात कार्तिक शुक्ल पूर्णिमा के पावन नक्षत्र में प्रभु का अवतरण हुआ और आपकी यश-सुगंधि तीनों लोकों में फैल गई।"},{number:"४",lines:["चार सौ धनुष तनु ऊँचाई, साठ लाख पूरब थी आयु।","जन्मत ही दश अतिशय प्रगटे, प्रभु को सुर-विद्याधर नमते॥"],meaning:"भगवान संभवनाथ के कंचन समान शरीर की ऊँचाई चार सौ धनुष थी और आपकी पावन आयु साठ लाख पूर्व थी। जन्म लेते ही आपके शरीर में जन्म के दस दिव्य अतिशय प्रकट हुए; समस्त देव, इन्द्र और विद्याधर नतमस्तक होकर आपके चरणों की वंदना करते थे।"},{number:"५",lines:["राजा बनकर धर्मनीति से, राज्य किया बहु कुशल रीति से।","इक दिन मेघों का विभ्रम लख, प्रभु ने छोड़ दिया वैभव सब॥"],meaning:"युवावस्था में पिता द्वारा राज्य सौंपे जाने पर आपने उत्तम नीति और दया-धर्म से कुशलपूर्वक राज्य का संचालन किया। एक दिन आकाश में क्षणभर में विलीन होते बादलों (मेघ-पटल) को देखकर आपको संसार की अनित्यता का गहरा बोध हुआ और आपने समस्त राज-वैभव का त्याग कर दिया।"},{number:"६",lines:["दीक्षा के शुभ भाव हो गए, आत्मज्ञान से पूर्ण हो गए।","तजा परिग्रह केश लौंच कर, ध्यान धरा पूरब को मुख कर॥"],meaning:"आपके अंतर्मन में परम वैराग्य और दिगम्बर मुनि दीक्षा के पावन भाव जागृत हुए और आप आत्म-स्वरूप में लीन हो गए। समस्त बाह्य व अंतरंग परिग्रह त्यागकर, केश-लोंच करके आपने पूर्व दिशा की ओर मुख कर ध्यान लगाया।"},{number:"७",lines:["धारण कर उस दिन उपवास, वन में ही फिर किया निवास।","आत्मशुद्धि का प्रबल प्रमाण, तत्क्षण हुआ मनःपर्यय ज्ञान॥"],meaning:"दीक्षा के दिन बेला (उपवास) धारण कर आप सहेतुक वन में आत्म-साधना में लीन रहे। आपकी तीव्र आत्मशुद्धि के फलस्वरुप उसी क्षण आपको दूसरों के मनोभावों को प्रत्यक्ष जानने वाला 'मनःपर्यय ज्ञान' प्रकट हो गया।"},{number:"८",lines:["प्रथमाहार हुआ मुनिवर का, धन्य हुआ जीवन ‘सुरेन्द्र’ का।","पंचाश्चर्यो से देवों के, हुए प्रजाजन सुखी नगर के॥"],meaning:"तपस्या के उपरांत जब प्रभु मुनिराज का प्रथम पारणा हुआ, तब राजा सुरेन्द्र (श्रावस्ती नरेश) ने अत्यंत भक्तिपूर्वक पड़गाहन कर आहार दान देकर अपना जीवन धन्य किया। देवों द्वारा आकाश से रत्नों, पुष्पों व सुवर्ण की वर्षा रूपी पंचाश्चर्य किए गए, जिससे सम्पूर्ण प्रजा आनंदित हो उठी।"},{number:"९",lines:["चौदह वर्ष की आत्म-सिद्धि, स्वयं ही उपजी केवल ऋद्धि।","कृष्ण चतुर्थी कार्तिक सार, समोशरण रचना हितकार॥"],meaning:"चौदह वर्षों तक मौनपूर्वक कठोर तप और ध्यान साधना करने के उपरांत कार्तिक कृष्ण चतुर्थी के पावन दिन घातिया कर्मों का नाश हुआ और साक्षात् लोकालोक-प्रकाशी केवलज्ञान (दिव्य ज्ञान) रूपी सर्वोत्कृष्ट ऋद्धि प्रकट हुई।"},{number:"१०",lines:["खिरती सुखकारी जिनवाणी, निज भाषा में समझे प्राणी।","“विषयभोग हैं विषसम विषमय, इनमें मत होना तुम तन्मय॥"],meaning:"कुबेर द्वारा रचित समवसरण में प्रभु की कल्याणकारी दिव्य ध्वनि खिरी, जिसे प्रत्येक प्राणी अपनी भाषा में सहज समझता था। प्रभु ने उपदेश दिया कि संसार के समस्त पंचेंद्रिय विषय-भोग हलाहल विष के समान आत्मघाती हैं, इनमें कभी आसक्त मत होना।"},{number:"११",lines:["तृष्णा बढ़ती है भोगों से, काया घिरती है रोगों से।","जिनलिंग से निज को पहचानो, अपना शुद्धातम सरधानो॥"],meaning:"भोगों का उपभोग करने से तृष्णा की अग्नि और अधिक धधकती है तथा शरीर नाना प्रकार की व्याधियों व रोगों से घिर जाता है। अतः दिगम्बर जिन-मुद्रा और वीतराग मार्ग अपनाकर अपने शुद्ध चिदानंद आत्म-स्वरूप को पहचानो और उसका सच्चा श्रद्धान करो।"},{number:"१२",lines:["दर्शन ज्ञान चरित्र बतावे, मोक्ष मार्ग एकत्व दिखाये।","जीवों का सन्मार्ग बताया, भव्यों का उद्धार कराया॥"],meaning:"सम्यक दर्शन, सम्यक ज्ञान और सम्यक चारित्र रूपी रत्नत्रय की एकता ही मोक्ष का साक्षात् मार्ग है। प्रभु ने संसार-भ्रमण से मुक्ति का सच्चा मार्ग बताकर अनगिनत भव्य जीवों का उद्धार किया।"},{number:"१३",lines:["गणधर एक सौ पाँच प्रभु के, मुनिवर पन्द्रह सहस संघ के।","देवी-देव-मनुज बहुतेरे, सभा में थे तिर्यंच घनेरे॥"],meaning:"आपके समवसरण में चारुसेन आदि एक सौ पाँच प्रधान गणधर मुनिराज थे तथा संघ में पन्द्रह सहस्र दिगम्बर मुनिराज थे। समवसरण की बारह सभाओं में अगणित देव-देवियाँ, मनुष्य और वैर-भाव भूलकर बैठे हुए तिर्यंच (पशु-पक्षी) धर्मोपदेश का लाभ लेते थे।"},{number:"१४",lines:["एक महीना उम्र रही जब, पहुँच गए सम्मेद शिखर तब।","अचल हुए खड्गासन में प्रभु, कर्म नाश कर हुए स्वयम्भु॥"],meaning:"जब अपनी पावन आयु का केवल एक माह शेष रहा, तब प्रभु विहार कर श्री सम्मेद शिखर जी के पवित्र तीर्थ पर पधारे। वहाँ खड्गासन मुद्रा में निश्चल ध्यानस्थ होकर आपने समस्त अघातिया कर्मों का समूल क्षय किया और स्वयं-भू सिद्ध परमात्मा बन गए।"},{number:"१५",lines:["चैत सुदी षष्ठी थी न्यारी, धवल कूट की महिमा भारी।","साठ लाख पूर्व का जीवन, पग में अश्व का था शुभ लक्षण॥"],meaning:"चैत्र शुक्ल षष्ठी के मंगलमय दिवस पर श्री सम्मेद शिखर जी की पवित्र 'धवल कूट' से आपका मोक्ष कल्याणक हुआ। साठ लाख पूर्व की आयु पूर्ण कर प्रभु मुक्त हुए; आपके पावन चरण-कमलों का शुभ लांछन (चिन्ह) अश्व (घोड़ा) है।"},{number:"१६",lines:["श्रावस्ती के संभव स्वामी, तुम हो घट-घट के अंतर्यामी।","जो भी प्रभु की शरण में आवे, सब संकट पल में मिट जावे॥"],meaning:"हे श्रावस्ती के अधिपति भगवान संभवनाथ! आप समस्त चराचर जगत के घट-घट को प्रत्यक्ष जानने वाले सर्वज्ञ परमात्मा हैं। जो भी आकुल-व्याकुल प्राणी आपकी वीतराग शरण में आता है, उसके जन्म-जन्मांतर के संकट और संताप क्षणभर में नष्ट हो जाते हैं।"},{number:"१७",lines:["अश्व चिन्ह पद-पद्म विराजे, रूप देख सुर-नर मन लाजे।","पाप-ताप सब दूर भगाओ, भवसागर से पार लगाओ॥"],meaning:"आपके पावन चरणों में उत्तम अश्व का लांछन शोभायमान है और आपकी वीतरागी, शांत जिनमुद्रा को देखकर कामदेव का मान भी गलित हो जाता है। हे प्रभु! हमारे मानसिक पापों और शारीरिक तापों को दूर भगाकर हमें भवसागर से पार उतारिए।"},{number:"१८",lines:["मैं अज्ञान-अंध में भूला, मोह-जाल में निशदिन झूला।","दया दृष्टि मुझ पर भी कीजे, अविरल भक्ति प्रभु की दीजे॥"],meaning:"हे दीनानाथ! मैं अनादिकाल से अज्ञान रूपी अंधकार में भटकता रहा हूँ और संसार के मोह-जाल में दिन-रात झूलता रहा। मुझ दीन सेवक पर भी अपनी करुणा-दृष्टि कीजिए और मुझे अपनी अविचल, निष्काम जिनभक्ति का वरदान दीजिए।"},{number:"१९",lines:["चालीसा श्री संभवनाथ, पाठ करो श्रद्धा के साथ।","मनवांछित सब पूरण होवे, जनम-मरण सब दुःख खोवे॥"],meaning:"भगवान श्री संभवनाथ जी के इस पावन चालीसा का जो भी भव्य जीव अनन्य श्रद्धा और पवित्र अंतःकरण से पाठ करता है, उसकी सभी आत्मिक व सात्विक अभिलाषाएँ पूर्ण होती हैं और उसके जन्म-मरण के दारुण दुःख नष्ट हो जाते हैं।"},{number:"२०",lines:["चालीसा जो भाव से गावे, रिद्धि-सिद्धि-सुख-संपति पावे।","संभव जिनवर मंगलकारी, वंदन बारंबार हमारी॥"],meaning:"जो श्रद्धालु भाव-विभोर होकर प्रभु संभवनाथ की इस स्तुति का गान करता है, वह सांसारिक सुख-शांति के साथ-साथ मोक्षमार्ग की आत्मिक संपदा प्राप्त करता है। हे परम मंगलकारी संभवनाथ भगवान! आपको हमारे मन, वचन और काय से कोटि-कोटि वंदन है।"},{number:"शंभु छंद",lines:["शंभु छंद","यह संभव प्रभु का चालीसा, पढ़ लेना तुम चालीस दिन तक।","इक-दो बार नहीं भव्यों! चालीस बार पढ़ना प्रतिदिन॥","इसको पढ़ने से कार्य-असंभव भी, संभव हो जाएगा।","संभव जिनवर का वंदन भी, बेड़ा पार लगाएगा॥"],meaning:"भव्य आत्मन्! भगवान संभवनाथ के इस अतिशयकारी चालीसा का चालीस दिन तक एकाग्रचित्त होकर पाठ करो; प्रतिदिन चालीस बार इसका श्रद्धापूर्वक पारायण करो। इसके प्रभाव से जीवन का असाध्य और असंभव कार्य भी संभव हो जाता है, और भगवान संभवनाथ का पावन वंदन-स्मरण भवसागर से बेड़ा पार लगा देता है।"}]},"shantinath-chalisa":{id:"shantinath-chalisa",category:"chalisa",title:"श्री शान्तिनाथ चालीसा (दोहा, चौपाई एवं भावार्थ सहित)",subtitle:"सोलहवें तीर्थंकर भगवान शान्तिनाथ चालीसा",type:"structured",verses:[{number:"दोहा",lines:["दोहा","शीश नवा अरिहंत को, सिद्धन करूं प्रणाम।","उपाध्याय आचार्य का, ले सुखकारी नाम॥","सर्व साधु और सरस्वती, जिन मंदिर सुखकार।","शान्तिनाथ भगवान को, मन मंदिर में धार॥"],meaning:"सर्वप्रथम अरिहंत परमेष्ठी को शीश नवाकर और सिद्ध प्रभु को प्रणाम करता हूँ। सुखकारी उपाध्याय व आचार्य परमेष्ठी का स्मरण कर, समस्त साधु, जिनवाणी माता एवं सुखदायी जिनमंदिर को वंदन करके सोलहवें तीर्थंकर भगवान शान्तिनाथ को अपने मन-मंदिर में धारण करता हूँ।"},{number:"१",lines:["चौपाई","जय श्री शान्तिनाथ जिन स्वामी। तीन लोक के अंतरयामी॥","सोलहवें तीर्थंकर भारी। महिमा गावे सब नर-नारी॥"],meaning:"हे भगवान श्री शान्तिनाथ स्वामी! आपकी जय-जयकार हो। आप तीनों लोकों के समस्त चराचर को जानने वाले अंतर्यामी हैं। आप जैन धर्म के सोलहवें महान तीर्थंकर हैं, जिनकी पावन महिमा का गुणगान देव, मनुष्य और सभी नर-नारी नित्य करते हैं।"},{number:"२",lines:["कामदेव चक्रेश कहाए। शांति-सुधा जग में बरसाए॥","माता ऐरा के नंदन प्यारे। विश्वसेन के राजदुलारे॥"],meaning:"आप एक ही भव में कामदेव (पंचम), चक्रवर्ती (षष्ठम) और तीर्थंकर (सोलहवें)—इन तीनों सर्वोच्च पदों के धारी हुए और संसार में शांति का अमृत बरसाया। आप माता अचिरा (ऐरा) देवी के नंदन तथा हस्तिनापुर के प्रतापी राजा विश्वसेन के राजदुलारे पुत्र हैं।"},{number:"३",lines:["हस्तिनापुर नगरी सुखकारी। जन्म लिया प्रभु पर-उपकारी॥","ज्येष्ठ वदी चौदस सुखदाई। जन्मे त्रिभुवन शांति सवाई॥"],meaning:"पवित्र हस्तिनापुर नगरी में परोपकारी प्रभु ने अवतार लिया। ज्येष्ठ कृष्ण चतुर्दशी के मंगलकारी दिन आपका जन्म हुआ, जिससे तीनों लोकों में अपार शांति और आनंद का संचार हुआ।"},{number:"४",lines:["रूप अनूपम काम लजावे। लख सुर-नर सब शीश नवावे॥","सुवर्ण वर्ण मनोहर काया। मृग लांछन प्रभु चरण सुहाया॥"],meaning:"आपका रूप-सौंदर्य इतना अनुपम और दिव्य था कि साक्षात् कामदेव भी लज्जित हो जाए; देव और मनुष्य आपके दर्शन कर नतमस्तक हो जाते थे। आपकी देह की कांति स्वर्ण के समान दमकती थी और आपके पावन चरणों में शांति का प्रतीक हिरण (मृग) का शुभ लांछन सुशोभित था।"},{number:"५",lines:["चक्रवर्ती पदवी जब पाई। चौदह रत्न नवनिधि आई॥","छह खंडों पर राज चलाया। फिर भी मन में मोह न लाया॥"],meaning:"जब आपको षष्ठम चक्रवर्ती का पद प्राप्त हुआ, तब चौदह रत्न और नौ निधियाँ आपके अधीन हुईं। आपने अखंड छह खंडों पर चक्रवर्ती के रूप में धर्मपूर्वक शासन किया, किंतु उस असीम वैभव में भी आपके वीतरागी मन में लेशमात्र भी मोह या आसक्ति नहीं उपजी।"},{number:"६",lines:["एक दिन दर्पण मुख अवलोका। क्षणभंगुर संसार विलोका॥","झट मन में वैराग्य समाया। राज-पाट तज वन को धाया॥"],meaning:"एक दिन दर्पण में अपना मुख देखते समय आपको संसार और शरीर की क्षणभंगुरता का बोध हुआ। क्षणभर में आपके हृदय में उत्कृष्ट वैराग्य उत्पन्न हो गया, और आपने समस्त राजवैभव त्यागकर वन में जिनदीक्षा का मार्ग चुना।"},{number:"७",lines:["ज्येष्ठ वदी चौदस तिथि पावन। लीनी दीक्षा त्यागे भवन॥","सहस्र नृपति संग दीक्षा लीनी। घोर तपस्या वन में कीनी॥"],meaning:"ज्येष्ठ कृष्ण चतुर्दशी के पावन दिन आपने महल त्यागकर दिगंबर मुनि दीक्षा ग्रहण की। आपके वैराग्य से प्रेरित होकर एक सहस्र राजाओं ने भी दीक्षा ली, और आपने वन में एकांत आत्म-ध्यानपूर्वक घोर तपस्या की।"},{number:"८",lines:["मौन धार आतम रस पीया। परिषह सब समता से सहिया॥","पौष सुदी दशमी जब आई। केवलज्ञान हुआ सुखदाई॥"],meaning:"आपने मौन व्रत धारण कर शुद्ध आत्म-रस का आस्वादन किया तथा भूख, प्यास, शीत, ग्रीष्म आदि समस्त बाइस परिषहों को परम समताभाव से सहन किया। तपस्या की पूर्णता पर पौष शुक्ल दशमी के मंगल दिन आपको केवलज्ञान प्रकट हुआ।"},{number:"९",lines:["इन्द्रों ने समवसरण रचाया। द्वादश सभा में धर्म सुनाया॥","दिव्यध्वनि प्रभु की मुख गाजी। भव्य जनों की बगिया राजी॥"],meaning:"सौधर्म इन्द्र आदि देवों ने भक्तिपूर्वक दिव्य समवसरण की रचना की। प्रभु की बारह सभाओं में आपकी ओंकारमयी दिव्यध्वनि खिरी, जिससे संसार के असंख्य भव्य जीवों के आत्म-कल्याण का मार्ग प्रशस्त हुआ।"},{number:"१०",lines:["शांति-मंत्र जग में फैलाया। प्राणिमात्र पर प्रेम सिखाया॥","व्याधि महामारी दुख टारे। सब जीवों के कष्ट निवारे॥"],meaning:"आपने विश्व को अहिंसा, शांति और सर्वोदयी प्रेम का अमर संदेश दिया। आपके तीर्थंकर काल में संसार से भयंकर आधि-व्याधि, महामारियाँ और अकाल शांत हो गए, और समस्त जीवों को शांति व अभय प्राप्त हुआ।"},{number:"११",lines:["राजा मेघप्रभ भव माहीं। कबूतर बाज कथा प्रगटाई॥","दीना निज तन का सब मांसा। पूरी करी बाज की आंसा॥"],meaning:"पूर्व भव में राजा मेघरथ के रूप में आपने शरण में आए भयभीत कबूतर की रक्षा हेतु शिकारी बाज की क्षुधा शांत करने के लिए अपने शरीर का मांस तराजू पर तौलकर अर्पित कर दिया था। आपकी इस अनुपम करुणा की परीक्षा स्वयं देवों ने ली थी।"},{number:"१२",lines:["दया धर्म का मर्म सिखाया। शरणागत का प्राण बचाया॥","ऐसी करुणा के तुम सागर। शांतिनाथ प्रभु ज्ञान उजागर॥"],meaning:"आपने अपने जीवन से यह सिखाया कि शरणागत की रक्षा और प्राणिमात्र पर दया ही सच्चा धर्म है। हे ज्ञान-प्रकाशी भगवान शांतिनाथ! आप दया, क्षमा और करुणा के अगाध महासागर हैं।"},{number:"१३",lines:["सम्मेद शिखर पर प्रभु जी आए। ध्यान लगा कूट सुविराजे॥","ज्येष्ठ वदी चौदस कल्याणी। पाई मुक्ति अमर सुखदानी॥"],meaning:"आयु के अंत में विहार करते हुए प्रभु सम्मेद शिखर जी पधारे और ध्यानस्थ होकर अपने कर्मों का क्षय किया। ज्येष्ठ कृष्ण चतुर्दशी के पावन दिन आपने शाश्वत सिद्धपद (मोक्ष) प्राप्त किया।"},{number:"१४",lines:["गर्भ जनम तप ज्ञान निर्वाण। पंचकल्याणक जग कल्यान॥","तीन काल में शांति विधाता। तुम ही त्रिभुवन के सुखदाता॥"],meaning:"आपके गर्भ, जन्म, तप, ज्ञान और मोक्ष—इन पाँचों कल्याणकों से समस्त जगत का मंगल हुआ। आप भूत, वर्तमान और भविष्य तीनों कालों में शांति के विधाता तथा तीनों लोकों के जीवों को आत्मिक सुख देने वाले हैं।"},{number:"१५",lines:["जो जन प्रभु का ध्यान लगावे। शांति-सुधा आतम में पावे॥","भूत-पिशाच डाकिनी भागें। संकट सब छिन भर में भागे॥"],meaning:"जो भव्य आत्मा एकाग्र चित्त से आपका ध्यान करती है, उसे आंतरिक शांति और आत्मिक आनंद की प्राप्ति होती है। आपके नाम-स्मरण के प्रभाव से समस्त नकारात्मक शक्तियाँ, भय और संकट क्षणमात्र में पलायन कर जाते हैं।"},{number:"१६",lines:["रोग-शोक संताप नशावे। शांतिनाथ जब नाम सुनावै॥","अंधा देखे कोढ़ी काया। कंचन बन जावे प्रभु माया॥"],meaning:"प्रभु शांतिनाथ के नामोच्चार से शारीरिक रोग, शोक और मानसिक संताप नष्ट हो जाते हैं। प्रभु के अतिशय और पुण्य के प्रभाव से नेत्रहीनों को ज्योति और असाध्य रोगियों को कंचन जैसी निरोगी काया प्राप्त होती है।"},{number:"१७",lines:["निर्धन को धनवान बनावे। बांझिन नारी सुत कुल पावे॥","जहाँ-जहाँ प्रभु चरण पधारे। शांति-सुगंध चहूँ दिशि पसरे॥"],meaning:"प्रभु की भक्ति से निर्धन को संतोष व वैभव प्राप्त होता है, तथा सुयोग्य संतान की प्राप्ति होती है। जहाँ-जहाँ प्रभु के चरण कमल पड़ते हैं, वहाँ चारों दिशाओं में शांति और सद्भाव की सुगंध फैल जाती है।"},{number:"१८",lines:["हस्तिनापुर अतिशय सुखकारी। निसिदिन पूजा होय तुम्हारी॥","दूर-दूर से यात्री आवें। वंदन कर मनवांछित पावें॥"],meaning:"आपकी जन्मभूमि हस्तिनापुर आज भी परम कल्याणकारी अतिशय क्षेत्र है, जहाँ नित्य आपकी अष्टद्रव्य से मंगल पूजा होती है। देश-विदेश से श्रद्धालु यात्री आकर आपके दर्शन करते हैं और मनोवांछित धर्म-फल प्राप्त करते हैं।"},{number:"१९",lines:["चालीसा चालीस दिन गावे। निश्चय सुख-संपत्ति वो पावे॥","पापों की सब बेड़ी टूटे। जनम-मरण का बंधन छूटे॥"],meaning:"जो भव्य जीव चालीस दिनों तक इस चालीसा का श्रद्धापूर्वक पाठ करता है, उसे लौकिक सुख-समृद्धि प्राप्त होती है। उसके अनादि काल के पापों की शृंखला टूट जाती है और संसार के आवागमन से मुक्ति का मार्ग मिलता है।"},{number:"२०",lines:["हम सब हैं प्रभु शरण तिहारी। काटो सब संकट अविकारी॥","'चन्द्र' प्रभु के चरण मनावै। आवागमन मिटा सुख पावै॥"],meaning:"हे निष्काम, विकार-रहित शांत प्रभु! हम सब आपकी पावन शरण में हैं, हमारे समस्त भव-भव के संकटों को दूर कीजिए। कवि प्रभु के युगल चरणों की शरण लेकर जन्म-मरण के चक्र से मुक्त होकर शाश्वत मोक्ष सुख की प्रार्थना करते हैं।"},{number:"सोरठा",lines:["सोरठा","नित चालीसहिं बार, पाठ करे चालीस दिन।","खेय सुगंध अपार, श्री शान्तिनाथ के सामने॥","होय कुबेर समान, जन्म दरिद्री होय जो।","जिसके नहिं संतान, नाम वंश जग में चले॥"],meaning:"जो भव्य जीव चालीस दिनों तक प्रतिदिन चालीस बार इस चालीसा का पाठ करता है अथवा श्री शांतिनाथ भगवान के सन्मुख अपार सुगंधित धूप खेता है—वह यदि जन्मांतर का निर्धन भी हो तो कुबेर के समान समृद्ध हो जाता है, और जिसके संतान न हो, उसके कुल और धर्म का यश संसार में फैलता है।"}]},"sheetalnath-chalisa":{id:"sheetalnath-chalisa",category:"chalisa",title:"श्री शीतलनाथ चालीसा (दोहा, चौपाई एवं भावार्थ सहित)",subtitle:"१०वें तीर्थंकर शीतलनाथ स्वामी - ४० पद्य स्तुति, दोहा, चौपाई व भावार्थ सहित",type:"structured",verses:[{number:"दोहा",lines:["दोहा","शीतल हैं शीतल वचन, चंदन से अधिकाई।","कल्प वृक्ष सम प्रभु चरण, हैं सबको सुखकाई॥"],meaning:"दसवें तीर्थंकर भगवान शीतलनाथ के पावन वचन मलयगिरि के चंदन से भी अधिक शांति और शीतलता प्रदान करने वाले हैं। प्रभु के श्रीचरण कल्पवृक्ष के समान हैं, जो उनकी शरण में आने वाले सभी भव्य जीवों को परम आत्मिक सुख प्रदान करते हैं।"},{number:"१",lines:["चौपाई","जय श्री शीतलनाथ गुणाकर, महिमा मंडित करुणासागर।","भद्दिलापुर के दृढ़रथ राय, भूप प्रजावत्सल कहलाए॥"],meaning:"हे अनन्त गुणों की खान, महिमा-मंडित और करुणा के अगाध सागर भगवान श्री शीतलनाथ जी! आपकी जय हो। प्राचीन भद्दिलपुर (भद्रिकापुरी) नगरी के धर्मात्मा और प्रजावत्सल राजा दृढ़रथ आपके परम पूज्य पिता थे।"},{number:"२",lines:["रमणी रत्न सुनंदा रानी, गर्भ आए श्री जिनवर ज्ञानी।","द्वादशी माघ बदी को जन्मे, हर्ष लहर उठी त्रिभुवन में॥"],meaning:"सती-शिरोमणि महारानी सुनंदा आपकी पूज्या माता थीं, जिनके पावन गर्भ में चैत्र कृष्ण अष्टमी को तीन लोक के ज्ञाता प्रभु पधारे। इसके पश्चात माघ कृष्ण द्वादशी के शुभ दिवस पर प्रभु का जन्म हुआ, जिससे तीनों लोकों में अपार हर्ष की लहर दौड़ गई।"},{number:"३",lines:["उत्सव करते देव अनेक, मेरु पर करते अभिषेक।","नाम दिया शिशु जिन को शीतल, भीष्म ज्वाल अध होती शीतल॥"],meaning:"इन्द्रादिक समस्त देवों ने सुमेरु पर्वत पर ले जाकर प्रभु का 1008 कलशों से जन्माभिषेक महोत्सव मनाया। प्रभु के प्रभाव से गर्भकाल में माता की असह्य दाह-ज्वर की भयंकर ज्वाला शांत होकर शीतल हो गई थी, इसलिए देवों ने बाल तीर्थंकर का शुभ नाम 'शीतलनाथ' रखा।"},{number:"४",lines:["एक लक्ष पूर्वायु प्रभु की, नब्बे धनुष अवगाहना वपु की।","वर्ण स्वर्ण सम उज्ज्वलपीत, दया धर्म था उनका मीत॥"],meaning:"भगवान शीतलनाथ की पावन आयु एक लाख पूर्व की थी तथा आपके दिव्य शरीर की ऊँचाई नब्बे धनुष थी। आपका वर्ण तपाये हुए सुवर्ण के समान अत्यंत मनोहर पीत-कांति वाला था और प्राणिमात्र पर दया व अहिंसा धर्म आपके अंतरंग मित्र थे।"},{number:"५",lines:["निरसक्त थे विषय भोगों में, रत रहते थे आत्म योग में।","एक दिन गए भ्रमण को वन में, करे प्रकृति दर्शन उपवन में॥"],meaning:"राजकुमार अवस्था में भी आप संसार के पंचेंद्रिय भोगों से सर्वथा विरक्त रहते थे और आपका मन निरंतर आत्म-साधना में लीन रहता था। एक दिन ऋतु-परिवर्तन के समय आप वन विहार हेतु पधारे और उपवन के प्राकृतिक सौंदर्य का अवलोकन करने लगे।"},{number:"६",lines:["लगे ओसकन मोती जैसे, लुप्त हुए सब सूर्योदय से।","देख हृदय में हुआ वैराग्य, आत्म राग में छोड़ा राग॥"],meaning:"घास के तिनकों पर मोतियों के समान चमकती ओस की बूँदों को सूर्य की पहली किरण पड़ते ही क्षणभर में विलीन होते देखकर, प्रभु के हृदय में तीव्र वैराग्य जागृत हुआ कि यह संसार और इसके वैभव ओस-कणों की भाँति नश्वर हैं; उन्होंने संसार का राग त्यागकर आत्म-राग को अपना लिया।"},{number:"७",lines:["तप करने का निश्चय करते, ब्रह्मर्षि अनुमोदन करते।","विराजे सुप्रभा शिविका में, गए सहेतुक वन में जिनवर॥"],meaning:"संसार त्यागकर आत्म-तप करने का निश्चय करते ही लौकांतिक देवों ने आकर आपके वैराग्य की अनुमोदना की। आप 'सुप्रभा' नामक दिव्य पालकी में आरूढ़ होकर सहेतुक वन पधारे।"},{number:"८",lines:["संध्या समय ली दीक्षा अनुक्षण, चार ज्ञान धारी हुए तत्क्षण।","दो दिन का व्रत करके इष्ट, प्रथमाहार हुआ नगर अरिष्ट॥"],meaning:"माघ कृष्ण द्वादशी की पावन संध्या वेला में एक सहस्र राजाओं के साथ आपने निर्ग्रन्थ दिगम्बर दीक्षा धारण की और उसी क्षण मनःपर्यय ज्ञान से युक्त होकर चार ज्ञान के धारी बने। दो दिन के उपवास के उपरांत अरिष्टपुर नगर में प्रभु का प्रथम आहार हुआ।"},{number:"९",lines:["दिया आहार पुनर्वसु नृप ने, पंचाश्चर्य किए देवों ने।","किया तीन वर्ष तप घोर, शीतलता फैली चहुं ओर॥"],meaning:"अरिष्टपुर के राजा पुनर्वसु ने अत्यंत भक्तिपूर्वक पड़गाहन कर मुनिराज को विशुद्ध आहार दान दिया, जिस पर देवों ने रत्न-वृष्टि आदि पंचाश्चर्य किए। इसके पश्चात प्रभु ने तीन वर्ष तक कठोर मौन तपश्चर्या की, जिससे सम्पूर्ण जगत में आध्यात्मिक शीतलता फैल गई।"},{number:"१०",lines:["कृष्ण चतुर्दशी पौष विख्याता, केवलज्ञानी हुए जगतज्ञाता।","रचना हुई तब समोशरण की, दिव्यदेशना खिरी प्रभु की॥"],meaning:"पौष कृष्ण चतुर्दशी के पावन दिवस पर ध्यानावस्था में घातिया कर्मों का समूल क्षय कर आप लोकालोक-प्रकाशी केवलज्ञान से विभूषित होकर जगत के ज्ञाता-दृष्टा बने। इन्द्र की आज्ञा से समवसरण रचा गया और प्रभु की अमृतमयी दिव्य देशना प्रवाहित हुई।"},{number:"११",lines:["आतम हित का मार्ग बताया, शंकित चित्त समाधान कराया।","तीन प्रकार आत्मा जानो, बहिरातम अंतरतम मानो॥"],meaning:"समवसरण में आपने समस्त भव्य जीवों को आत्मकल्याण का सच्चा मार्ग दिखाया और उनके सभी संशयों का निवारण किया। प्रभु ने उपदेश दिया कि आत्मा की तीन अवस्थाएँ होती हैं—बहिरात्मा, अंतरात्मा और परमात्मा।"},{number:"१२",lines:["निश्चय करके निज आतम का, चिंतन कर लो परमातम का।","मोह महामद से मोहित जो, परमातम को नहीं माने वो॥"],meaning:"अपने शुद्ध आत्म-स्वरूप का निश्चय करके परमात्मा के वीतराग स्वरूप का चिंतन करो। जो अज्ञानी जीव देह, कुटुंब और परिग्रह रूपी मोह के महा-मद में अंधा रहता है, वह अपनी विशुद्ध परमात्म-सत्ता को नहीं पहचान पाता।"},{number:"१३",lines:["वे ही भव भव में भटकाते, वे ही बहिरातम कहलाते।","पर पदार्थ से ममता तज के, परमातम में श्रद्धा कर के॥"],meaning:"जो शरीर को ही आत्मा मानकर बाह्य पदार्थों में राग-द्वेष करते हैं, वे 'बहिरात्मा' हैं और वे ही चौरासी लाख योनियों में निरंतर भटकते हैं। इसके विपरीत, जो पर-द्रव्यों से ममत्व त्यागकर शुद्ध आत्मा में दृढ़ श्रद्धान करते हैं—"},{number:"१४",lines:["जो नित आतम ध्यान लगाते, वे अंतर आतम कहलाते।","गुण अनंत के धारी हैं जो, कर्मों के परिहारी हैं जो॥"],meaning:"जो सदैव आत्म-तत्व का मनन और ध्यान करते हैं, वे ज्ञानी साधक 'अंतरात्मा' कहलाते हैं। और जो अनंत दर्शन, ज्ञान, सुख, वीर्य आदि अनंत गुणों के धारी हैं तथा जिन्होंने आठों कर्मों का समूल नाश कर दिया है—"},{number:"१५",lines:["लोक शिखर के वासी हैं वे, परमातम अविनाशी हैं वे।","जिनवाणी पर श्रद्धा धर के, पार उतरते भविजन भव से॥"],meaning:"वे ही सिद्धशिला (लोक के शिखर) पर विराजमान अविनाशी, अमूर्त 'परमात्मा' हैं। इस प्रकार माँ जिनवाणी के वचनों पर सम्यक श्रद्धान रखकर भव्य जीव संसार-समुद्र से सहज ही पार उतर जाते हैं।"},{number:"१६",lines:["श्री जिन के इक्यासी गणधर, एक लक्ष थे पूज्य मुनिवर।","अंत समय में गए सम्मेदचल, योग धार कर हो गए निश्चल॥"],meaning:"भगवान शीतलनाथ के समवसरण में प्रमुख गणधर नंदीषेण सहित इक्यासी गणधर थे और संघ में एक लाख पूज्य दिगम्बर मुनिराज थे। आयु का अंतिम समय जानकर प्रभु श्री सम्मेद शिखर जी पधारे और योग-निरोध कर शैल-शिखर पर अचल ध्यानस्थ हो गए।"},{number:"१७",lines:["आश्विन शुक्ल अष्टमी आई, मुक्तिमहल पहुँचे जिनराई।","लक्षण प्रभु का कल्पवृक्ष था, त्याग सकल सुख वरा मोक्ष था॥"],meaning:"आश्विन शुक्ल अष्टमी के पावन प्रभात पर समस्त अघातिया कर्मों का नाश कर प्रभु ने मुक्ति-महल में प्रवेश किया। आपके चरण-कमलों का पावन लांछन (चिन्ह) कल्पवृक्ष (श्रीवत्स) है; आपने संसार के क्षणिक सुखों को त्यागकर शाश्वत मोक्ष-सुख को वरण किया।"},{number:"१८",lines:["शीतल चरण शरण में आओ, कूट विद्युतवर शीश झुकाओ।","भव-दावानल ताप मिटाओ, परम शांति का मार्ग लखाओ॥"],meaning:"हे भव्य जीवों! भगवान शीतलनाथ के पावन चरणों की शरण लो और सम्मेद शिखर जी की 'विद्युतवर कूट' (जहाँ से प्रभु मोक्ष पधारे) पर श्रद्धा से शीश नवाओ। प्रभु की भक्ति संसार रूपी दावानल की त्रिविध ज्वालाओं को शांत कर परम वीतरागी शांति प्रदान करती है।"},{number:"१९",lines:["जो नर शीतल चालीसा गावे, सब संकट से मुक्ति पावे।","पुत्र-पौत्र धन-धान्य बढ़ावे, अंत समय में शिवपद पावे॥"],meaning:"जो भी श्रद्धालु भगवान शीतलनाथ के इस पवित्र चालीसा का नित्य पाठ करता है, वह सभी प्रकार के आधि-व्याधि-उपाधि और संकटों से मुक्त हो जाता है। उसे सांसारिक सुख, उत्तम संतति और धन-धान्य की प्राप्ति होती है तथा अंततः मोक्ष पद प्राप्त होता है।"},{number:"२०",lines:["दसवें तीर्थंकर सुखकारी, वंदन बारंबार हमारी।","कृपा करो हे दीनदयाला, काटो भव-बंधन का जाला॥"],meaning:"हे दसवें तीर्थंकर सुखदाता शीतलनाथ प्रभु! आपको हमारे मन, वचन और काय से बारंबार नमस्कार है। हे दीनदयाल! हम पर अपनी वीतराग कृपा कीजिए और अनादिकाल से जकड़े हुए हमारे सांसारिक कर्म-बंधनों के जाल को काट दीजिए।"},{number:"दोहा",lines:["दोहा","शीतल जिन शीतल करें, सबके भव आतप।","अरुणा के मन में बसे, हरे सकल संताप॥"],meaning:"भगवान शीतलनाथ संसार के समस्त भव्य जीवों के भव-भव के त्रिविध तापों (दैहिक, दैविक, भौतिक दुखों) को शांत कर शीतल बना दें। वे हमारे अंतःकरण में सदा विराजमान रहें और हमारे समस्त मानसिक संतापों और कष्टों का हरण करें।"}]},"shreyansnath-chalisa":{id:"shreyansnath-chalisa",category:"chalisa",title:"श्री श्रेयांसनाथ चालीसा",subtitle:"ग्यारहवें तीर्थंकर भगवान श्री श्रेयांसनाथ स्वामी की भक्ति-स्तुति",type:"structured",verses:[{number:"१",tag:"दोहा",lines:["श्रेयांसनाथ भगवान को, नाऊँ निशदिन शीश।","काटो सकल क्लेश मम, तुम ही हो जगदीश॥"],meaning:"ग्यारहवें तीर्थंकर भगवान श्री श्रेयांसनाथ जी के पावन चरणों में मैं प्रतिदिन शीश नवाता हूँ। हे जगदीश्वर प्रभु! हमारे समस्त सांसारिक क्लेशों, संकटों और कर्म बंधनों को काट दीजिए।"},{number:"२",tag:"दोहा",lines:["सिंहपुर नगरी भली, विष्णुराज भूपाल।","वेणुदेवी मात थी, उपजे दीनदयाल॥"],meaning:"सारनाथ के समीप पावन सिंहपुरी नगरी के धर्मपरायण राजा विष्णुराज प्रभु के पूज्य पिता थे तथा महारानी वेणुदेवी (विष्णुकान्ता) माता थीं, जिनके आँगन में दीनदयाल तीर्थंकर प्रभु का जन्म हुआ।"},{number:"३",tag:"चौपाई",lines:["जय श्री श्रेयांसनाथ गुणखान, तुम हो ग्यारहवें भगवान।","गैंडा चिह्न चरण के माहीं, लखत ही पाप रहे कछु नाहीं॥"],meaning:"अनंत गुणों की खान ग्यारहवें तीर्थंकर भगवान श्रेयांसनाथ की जय हो! प्रभु के पावन चरणों में 'खड्गी' (गैंडा/खड्ग) का मंगल चिह्न सुशोभित है, जिसके दर्शन मात्र से समस्त पाप दूर हो जाते हैं।"},{number:"४",tag:"चौपाई",lines:["अस्सी धनुष मान तन सोहे, कनक वरण लख मन मोहे।","चौरासी लाख वर्ष की आयु, पूर्ण करन मोक्ष सिधायु॥"],meaning:"प्रभु के सुवर्ण-वर्ण शरीर की ऊँचाई अस्सी धनुष थी और कुल आयु चौरासी लाख वर्ष की थी। अपनी सम्पूर्ण आयु को धर्म और ध्यान में व्यतीत कर प्रभु मोक्ष पधारे।"},{number:"५",tag:"चौपाई",lines:["फाल्गुन कृष्ण त्रयोदशी भाई, दीक्षा ले वन खण्ड जो जाई।","माघ बदी अमावस भारी, केवलज्ञान हुआ हितकारी॥"],meaning:"फाल्गुन कृष्णा त्रयोदशी को एक हजार राजाओं के साथ मनोहर वन में प्रभु ने दिगम्बर दीक्षा अंगीकार की और माघ कृष्णा अमावस्या को तेन्दू वृक्ष के नीचे परम केवलज्ञान प्राप्त किया।"},{number:"६",tag:"चौपाई",lines:["धर्मोपदेश दिया तुम भारी, भव्य जीवों की विपदा टारी।","श्रावण शुक्ला पूरणमासी, मोक्ष गए तुम अविनाशी॥"],meaning:"समवशरण में प्रभु ने अहिंसा और अनेकांत का पावन धर्मोपदेश देकर भव्य जीवों के सांसारिक संकट दूर किए। श्रावण शुक्ल पूर्णिमा को सम्मेद शिखर के संकुल कूट से प्रभु अविनाशी मोक्ष पधारे।"},{number:"७",tag:"चौपाई",lines:["जो जन तुमको नित प्रति ध्यावे, जनम-मरण के फन्द नसावे।","रोग-शोक नहिं आवे नेरे, रहे सर्वदा सुख घनेरे॥"],meaning:"जो भव्य प्राणी नित्य प्रति भगवान श्रेयांसनाथ का ध्यान करते हैं, उनके जन्म-मरण के समस्त फंदे कट जाते हैं। उनके निकट कोई रोग-शोक नहीं आता और वे शाश्वत सुख पाते हैं।"},{number:"८",tag:"दोहा",lines:["श्रेयांसनाथ के चरण में, नमन करूँ शत बार।","दास जान अपना प्रभु, कर दीजे भव पार॥"],meaning:"भगवान श्रेयांसनाथ के पावन चरणों में मैं शत-शत बार नमन करता हूँ। हे करुणानिधान प्रभु! मुझे अपना अनन्य सेवक मानकर इस भवसागर से पार उतार दीजिए।"},{number:"९",tag:"जाप मंत्र",lines:["॥ मूल मंत्र एवं ध्यान ॥","ॐ ह्रीं अर्हं श्री श्रेयांसनाथाय नमः।"],meaning:"ग्यारहवें तीर्थंकर देवाधिदेव श्री श्रेयांसनाथ भगवान के पावन चरणों में मेरा त्रिकाल नमन हो। प्रभु का खड्ग लांछन हमें संसार के सभी मोहजालों को भेदने की शक्ति प्रदान करे।"}]},"sumatinath-chalisa":{id:"sumatinath-chalisa",category:"chalisa",title:"श्री सुमतिनाथ चालीसा",subtitle:"पंचम तीर्थंकर भगवान श्री सुमतिनाथ स्वामी की भक्ति-स्तुति",type:"structured",verses:[{number:"१",tag:"दोहा",lines:["सुमतिनाथ जिनराज को, नमूँ जोरि कर हाथ।","सुमति दीजिए आप प्रभु, तुम ही त्रिभुवन नाथ॥"],meaning:"पंचम तीर्थंकर भगवान श्री सुमतिनाथ जी के पावन चरणों में दोनों हाथ जोड़कर शीश नवाता हूँ। हे तीनों लोकों के स्वामी जिनेन्द्र! हमें सन्मति और सम्यग्ज्ञान प्रदान कीजिए।"},{number:"२",tag:"दोहा",lines:["अयोध्या नगरी भली, मेघरथ नृप विख्यात।","मंगला रानी मात थी, उपजे त्रिभुवन तात॥"],meaning:"परम पावन अयोध्या नगरी के सुप्रसिद्ध राजा मेघरथ प्रभु के पूज्य पिता थे तथा महारानी मंगला देवी माता थीं, जिनके आँगन में त्रिभुवन के पालक तीर्थंकर प्रभु का जन्म हुआ।"},{number:"३",tag:"चौपाई",lines:["जय श्री सुमतिनाथ भगवान, पाँचवें तुम तीर्थंकर जान।","चकवा चिह्न चरण के माहीं, लखत ही पाप रहे कछु नाहीं॥"],meaning:"पाँचवें तीर्थंकर भगवान श्री सुमतिनाथ की जय हो! प्रभु के पावन चरण-कमलों में 'चकवा' (कोक/चक्रवाक) का मंगल चिह्न सुशोभित है, जिसके दर्शन मात्र से समस्त पाप नष्ट हो जाते हैं।"},{number:"४",tag:"चौपाई",lines:["तप्त सुवर्ण वरण तन सोहे, तीन सौ धनुष मान मन मोहे।","चालीस लाख पूर्व की आयु, भोग निराले मोक्ष सिधायु॥"],meaning:"प्रभु का देह-वर्ण तपे हुए सुवर्ण के समान कान्तिमान था और शरीर की ऊँचाई तीन सौ धनुष थी। प्रभु की कुल आयु चालीस लाख पूर्व की थी, जिसे भोगों से विरक्त रहकर प्रभु ने मोक्ष में परिणत किया।"},{number:"५",tag:"चौपाई",lines:["वैशाख सुदी नवमी को भाई, तप कल्याणक महिमा गाई।","चैत्र सुदी एकादशी जानो, केवलज्ञान हुआ परमानो॥"],meaning:"वैशाख शुक्ल नवमी को प्रभु ने सहेतुक वन में एक हजार राजाओं के साथ दिगम्बर दीक्षा अंगीकार की और चैत्र शुक्ल एकादशी को प्रियंगु वृक्ष के नीचे परम केवलज्ञान प्राप्त किया।"},{number:"६",tag:"चौपाई",lines:["धर्म तीर्थ का प्रवर्तन कीना, भव्य जीवों को तारन कीना।","चैत्र सुदी एकादशी आई, मोक्ष गए प्रभु मंगलदाई॥"],meaning:"समवशरण में प्रभु ने अहिंसा और अनेकांत रूपी पावन धर्मतीर्थ का प्रवर्तन कर अनगिनत भव्य जीवों का उद्धार किया। अंत में चैत्र शुक्ल एकादशी को श्री सम्मेद शिखर जी से मोक्ष पधारे।"},{number:"७",tag:"चौपाई",lines:["जो जन तुमको निशदिन ध्यावे, वो नर निश्चय शिवपुर जावे।","संकट-विघ्न सभी टल जावे, घर में सुख-सम्पत्ति आवे॥"],meaning:"जो भव्य प्राणी प्रतिदिन प्रभु का ध्यान करते हैं, वे नियम से संसार के बंधनों से छूटकर मोक्ष प्राप्त करते हैं। उनके जीवन के समस्त संकट, विघ्न और भय टल जाते हैं तथा आत्मिक शांति मिलती है।"},{number:"८",tag:"दोहा",lines:["सुमतिनाथ के चरण में, जो नित नावे शीश।","'चन्द्र' कहे कर जोड़ के, तुम ही हो जगदीश॥"],meaning:"भगवान सुमतिनाथ के पावन चरणों में जो नित्य श्रद्धा से अपना शीश झुकाते हैं, वे भव-सागर पार उतर जाते हैं। हे जगदीश्वर प्रभु! हम दोनों हाथ जोड़कर आपके चरणों में वन्दन करते हैं।"},{number:"९",tag:"जाप मंत्र",lines:["॥ मूल मंत्र एवं ध्यान ॥","ॐ ह्रीं अर्हं श्री सुमतिनाथाय नमः।"],meaning:"पंचम तीर्थंकर देवाधिदेव श्री सुमतिनाथ भगवान के पावन चरणों में मेरा त्रिकाल नमन हो। प्रभु का चकवा लांछन हमारे हृदय में सम्यग्ज्ञान और कुमति के नाश का वरदान दे।"}]},"suparshvanath-chalisa":{id:"suparshvanath-chalisa",category:"chalisa",title:"श्री सुपार्श्वनाथ चालीसा",subtitle:"सप्तम तीर्थंकर भगवान श्री सुपार्श्वनाथ स्वामी की भक्ति-स्तुति",type:"structured",verses:[{number:"१",tag:"दोहा",lines:["सुपार्श्वनाथ जिनराज को, वन्दूँ शीश नवाय।","जिन सुमिरन से होत है, सब पातक नश जाय॥"],meaning:"सातवें तीर्थंकर देवाधिदेव श्री सुपार्श्वनाथ भगवान को शीश झुकाकर वन्दन करता हूँ, जिनके पावन स्मरण मात्र से समस्त पाप, भय और संताप नष्ट हो जाते हैं।"},{number:"२",tag:"दोहा",lines:["वाराणसी नगरी भली, सुप्रतिष्ठ महाराज।","पृथिवी देवी मात थीं, सफल भयो सब काज॥"],meaning:"परम पावन वाराणसी नगरी के धर्मपरायण राजा सुप्रतिष्ठ प्रभु के पूज्य पिता थे तथा महारानी पृथ्वी (सुप्रभा) माता थीं, जिनके गर्भ से अवतरित होकर प्रभु ने जगत का कल्याण किया।"},{number:"३",tag:"चौपाई",lines:["जय श्री सुपार्श्वनाथ जन-प्यारे, सातवें तीर्थंकर कहलाए।","स्वास्तिक चिह्न चरण में सोहे, लखत ही सुर-नर मन को मोहे॥"],meaning:"भक्तवत्सल प्रभु सुपार्श्वनाथ की जय हो, जो सातवें तीर्थंकर के रूप में प्रसिद्ध हुए। प्रभु के पावन चरणों में 'स्वास्तिक' का मंगलकारी चिह्न सुशोभित है, जो सुर-असुर और मनुष्यों के मन को मोह लेता है।"},{number:"४",tag:"चौपाई",lines:["हरित वरण तन शोभा भारी, दो सौ धनुष मान अविकारी।","बीस लाख पूर्व की आयु, भोग सकल सुख मोक्ष सिधायु॥"],meaning:"प्रभु के निर्विकार शरीर की कान्ति पन्ना मणि के समान हरित वर्ण की थी तथा ऊँचाई दो सौ धनुष थी। बीस लाख पूर्व की कुल आयु पूर्ण कर प्रभु ने मोक्ष-लक्ष्मी को प्राप्त किया।"},{number:"५",tag:"चौपाई",lines:["ज्येष्ठ सुदी द्वादशी को भाई, दीक्षा ले प्रभु वन को जाई।","फाल्गुन कृष्ण षष्ठी को जानो, केवलज्ञान हुआ परमानो॥"],meaning:"ज्येष्ठ शुक्ल द्वादशी को सहेतुक वन में एक हजार राजाओं के साथ प्रभु ने दिगम्बर दीक्षा धारण की और फाल्गुन कृष्णा षष्ठी को शिरीष वृक्ष के नीचे लोकालोक-प्रकाशी केवलज्ञान प्राप्त किया।"},{number:"६",tag:"चौपाई",lines:["धर्म देशना प्रभु की हुई, भव्य जीवों की मति सुधि भई।","फाल्गुन कृष्ण सप्तमी आई, मोक्ष पधारे जिनवराई॥"],meaning:"समवशरण में प्रभु की अमृतमयी देशना सुनकर भव्य जीवों को आत्मज्ञान की निर्मल सुधि प्राप्त हुई। अंत में फाल्गुन कृष्णा सप्तमी को श्री सम्मेद शिखर जी के प्रभास कूट से प्रभु सिद्ध पद पधारे।"},{number:"७",tag:"चौपाई",lines:["जो जन तुमको नित प्रति ध्यावे, आधि-व्याधि सब दूर नसावे।","पुत्र-पौत्र सुख-सम्पत्ति पावे, अन्त समय शिवपुर को जावे॥"],meaning:"जो प्राणी नित्य नियम से प्रभु का ध्यान करते हैं, उनकी सभी मानसिक चिंताएँ और शारीरिक व्याधियाँ दूर हो जाती हैं। उन्हें लौकिक सुख-शांति मिलती है और अंत में वे मोक्ष प्राप्त करते हैं।"},{number:"८",tag:"दोहा",lines:["सुपार्श्वनाथ के चरण में, नमन करूँ बारम्बार।","दास जान अपना प्रभु, कर दीजे भव पार॥"],meaning:"भगवान सुपार्श्वनाथ के पावन चरणों में बारम्बार नमन करता हूँ। हे दयालु नाथ! मुझे अपना अनन्य सेवक जानकर इस भवसागर से पार उतार दीजिए।"},{number:"९",tag:"जाप मंत्र",lines:["॥ मूल मंत्र एवं ध्यान ॥","ॐ ह्रीं अर्हं श्री सुपार्श्वनाथाय नमः।"],meaning:"सप्तम तीर्थंकर देवाधिदेव श्री सुपार्श्वनाथ भगवान के पावन चरणों में मेरा त्रिकाल नमन हो। प्रभु का स्वास्तिक लांछन हमारे जीवन में चतुर्गति भ्रमण का नाश कर परमकल्याण प्रदान करे।"}]},"vasupujya-chalisa":{id:"vasupujya-chalisa",category:"chalisa",title:"श्री वासुपूज्य चालीसा",subtitle:"बारहवें तीर्थंकर भगवान श्री वासुपूज्य स्वामी की भक्ति-स्तुति",type:"structured",verses:[{number:"१",tag:"दोहा",lines:["वासुपूज्य जिनराज को, वन्दूँ शीश नवाय।","जिन सुमिरन से होत है, सब पातक नश जाय॥"],meaning:"बारहवें तीर्थंकर देवाधिदेव भगवान श्री वासुपूज्य स्वामी को शीश झुकाकर वन्दन करता हूँ, जिनके पावन स्मरण मात्र से समस्त पाप, ताप और संताप नष्ट हो जाते हैं।"},{number:"२",tag:"दोहा",lines:["चम्पापुर नगरी भली, वासुपूज्य महाराज।","जयावती रानी मात थीं, सफल भयो सब काज॥"],meaning:"पावन चम्पापुर नगरी के राजा वासुपूज्य प्रभु के पूज्य पिता थे तथा महारानी जयावती (विजया) माता थीं, जिनके आँगन में बाल ब्रह्मचारी तीर्थंकर प्रभु का प्राकट्य हुआ।"},{number:"३",tag:"चौपाई",lines:["जय श्री वासुपूज्य जिनराई, बारहवें तीर्थंकर भाई।","महिष चिह्न चरण में सोहे, लखत ही सुर-नर मन को मोहे॥"],meaning:"बारहवें तीर्थंकर भगवान वासुपूज्य की जय हो! प्रभु के पावन चरण-कमलों में 'महिष' (भैंसा) का मंगल चिह्न सुशोभित है, जो सुर, असुर और मनुष्यों के चित्त को आकर्षित करता है।"},{number:"४",tag:"चौपाई",lines:["रक्त वरण तन शोभा भारी, सत्तर धनुष मान अविकारी।","बहत्तर लाख वर्ष की आयु, भोग सकल सुख मोक्ष सिधायु॥"],meaning:"प्रभु के निर्विकार देह की कान्ति लाल पद्मराग मणि (रक्त वर्ण) के समान शोभायमान थी और ऊँचाई सत्तर धनुष थी। बहत्तर लाख वर्ष की पूर्ण आयु भोगकर प्रभु मोक्ष पधारे।"},{number:"५",tag:"चौपाई",lines:["फाल्गुन बदी अमावस भाई, दीक्षा ले प्रभु वन को जाई।","माघ सुदी दूज को जानो, केवलज्ञान हुआ परमानो॥"],meaning:"फाल्गुन कृष्णा अमावस्या को प्रभु ने बालब्रह्मचारी अवस्था में चम्पापुर के सहेतुक वन में दिगम्बर दीक्षा अंगीकार की और माघ शुक्ल द्वितीया को पाटल वृक्ष के नीचे केवलज्ञान प्राप्त किया।"},{number:"६",tag:"चौपाई",lines:["धर्म देशना प्रभु की हुई, भव्य जीवों की मति सुधि भई।","आषाढ़ सुदी चौदस आई, मोक्ष पधारे जिनवराई॥"],meaning:"प्रभु की दिव्य देशना से असंख्य भव्य जीवों को आत्मज्ञान की निर्मल प्रतीति हुई। आषाढ़ शुक्ल चतुर्दशी के पावन दिन चम्पापुरी की पावन धरा से ही प्रभु सिद्धालय पधारे।"},{number:"७",tag:"चौपाई",lines:["जो जन तुमको नित प्रति ध्यावे, आधि-व्याधि सब दूर नसावे।","पुत्र-पौत्र सुख-सम्पत्ति पावे, अन्त समय शिवपुर को जावे॥"],meaning:"जो भव्य प्राणी नित्य प्रति भगवान वासुपूज्य का ध्यान करते हैं, उनकी समस्त शारीरिक और मानसिक व्याधियाँ नष्ट हो जाती हैं। उन्हें सद्गति, सुख और अंत में मोक्ष मिलता है।"},{number:"८",tag:"दोहा",lines:["वासुपूज्य के चरण में, नमन करूँ बारम्बार।","दास जान अपना प्रभु, कर दीजे भव पार॥"],meaning:"भगवान वासुपूज्य के पावन चरणों में मैं बारम्बार नमन करता हूँ। हे चम्पापुरी के नाथ! मुझे अपना अनन्य सेवक जानकर संसार-सागर से पार लगा दीजिए।"},{number:"९",tag:"जाप मंत्र",lines:["॥ मूल मंत्र एवं ध्यान ॥","ॐ ह्रीं अर्हं श्री वासुपूज्य जिनेन्द्राय नमः।"],meaning:"बारहवें तीर्थंकर, पंचकल्याणक तीर्थ चम्पापुरी के स्वामी भगवान श्री वासुपूज्य जी के पावन चरणों में मेरा त्रिकाल नमन हो।"}]},"vimalnath-chalisa":{id:"vimalnath-chalisa",category:"chalisa",title:"श्री विमलनाथ चालीसा",subtitle:"तेरहवें तीर्थंकर भगवान श्री विमलनाथ स्वामी की भक्ति-स्तुति",type:"structured",verses:[{number:"१",tag:"दोहा",lines:["विमलनाथ भगवान की, महिमा है अपरम्पार।","चालीसा के पाठ से, होवे बेड़ा पार॥"],meaning:"तेरहवें तीर्थंकर देवाधिदेव श्री विमलनाथ भगवान की महिमा अपरंपार और अनिर्वचनीय है। इस पावन चालीसा के नित्य पाठ से भक्त संसार-समुद्र से पार उतर जाते हैं।"},{number:"२",tag:"दोहा",lines:["कांपिल्य नगरी विषै, कृतवर्मा भूपाल।","माता जयश्यामा तने, उपजे दीनदयाल॥"],meaning:"परम पावन काम्पिल्य (काम्पिला) नगरी के इक्ष्वाकुवंशी महाराज कृतवर्मा प्रभु के पूज्य पिता थे तथा महारानी जयश्यामा माता थीं, जिनके आँगन में दीनदयाल तीर्थंकर प्रभु अवतरित हुए।"},{number:"३",tag:"चौपाई",lines:["जय श्री विमलनाथ जिनराई, महिमा तीन लोक में छाई।","साठ लाख वर्ष की आयु, समचतुरस्र मूरत सुखदायी॥"],meaning:"भगवान विमलनाथ की जय हो, जिनका निर्मल यश तीनों लोकों में व्याप्त है। प्रभु की कुल आयु साठ लाख वर्ष थी तथा उनका शरीर समचतुरस्र संस्थान से युक्त परम सुखकारी था।"},{number:"४",tag:"चौपाई",lines:["साठ धनुष तन काया धारी, वराह चिह्न प्रभु पद हितकारी।","स्वर्ण वरण तन सोहें प्यारा, निरावरण सब जग को निहारा॥"],meaning:"प्रभु के स्वर्ण-वर्ण शरीर की ऊँचाई साठ धनुष थी तथा पावन चरणों में 'वराह' (सूकर) का मंगल चिह्न सुशोभित था। प्रभु ने केवलज्ञान से संपूर्ण लोकालोक को निरावरण प्रत्यक्ष देखा।"},{number:"५",tag:"चौपाई",lines:["शुक्ल ध्यान धर कर्म नसाए, केवल ज्ञान प्रकाश कराए।","सम्मेद शिखर तें मोक्ष पधारे, सुर नर मुनि सब वंदन धारे॥"],meaning:"माघ शुक्ल चतुर्दशी को जामुन वृक्ष के नीचे शुक्लध्यान द्वारा घातिया कर्मों का नाश कर प्रभु केवली बने। अंत में श्री सम्मेद शिखर जी के मन्दार कूट से मोक्ष पधारे।"},{number:"६",tag:"चौपाई",lines:["जो कोई तुमको मन से ध्यावे, रिद्धि-सिद्धि सुख संपत्ति पावे।","संकट कटें मिटें सब बाधा, पूरण होवे मन की साधा॥"],meaning:"जो भव्य प्राणी एकाग्रचित्त होकर प्रभु विमलनाथ का ध्यान करते हैं, वे आध्यात्मिक रिद्धि-सिद्धि और आत्मिक शांति पाते हैं। उनके समस्त विघ्न-बाधाएँ कट जाती हैं।"},{number:"७",tag:"चौपाई",lines:["पुत्र हीन को पुत्र हो जावे, निर्धन भी धन-दौलत पावे।","रोग-शोक नहिं आवे पास, पूरण होवे सबकी आस॥"],meaning:"प्रभु की वीतरागी भक्ति के प्रभाव से सांसारिक दारिद्र्य और रोग-शोक दूर भागते हैं तथा अंतःकरण में धर्म और सम्यक्त्व रूपी सच्ची लक्ष्मी का वास होता है।"},{number:"८",tag:"दोहा",lines:["मैं हूँ प्रभु! दास तुम्हारा, कर दीजे भव से निस्तारा।","'चन्द्र' प्रभु के गुण गावे, भक्ति भाव से शीश नवावे॥"],meaning:"हे प्रभु! मैं आपका अनन्य सेवक हूँ, मुझे इस जन्म-मरण रूपी भव-भ्रमण से मुक्त कीजिए। आपके पावन चरणों में बारम्बार भक्तिभाव से शीश झुकाता हूँ।"},{number:"९",tag:"जाप मंत्र",lines:["॥ मूल मंत्र एवं ध्यान ॥","ॐ ह्रीं अर्हं श्री विमलनाथाय नमः।"],meaning:"तेरहवें तीर्थंकर देवाधिदेव श्री विमलनाथ भगवान के पावन चरणों में मेरा त्रिकाल नमन हो। प्रभु का वराह लांछन हमारे अंतःकरण को समस्त कर्ममल से विमल और पावन बनाए।"}]},"simandhar-chalisa":{id:"simandhar-chalisa",category:"chalisa",title:"श्री सीमंधर स्वामी चालीसा",subtitle:"विद्यमान बीस तीर्थंकरों में ज्येष्ठ श्री सीमंधर स्वामी की भक्ति-स्तुति",type:"structured",verses:[{number:"१",tag:"दोहा",lines:["विदेह क्षेत्र के नाथ तुम, त्रिभुवन पति भगवान।","सीमंधर स्वामी नमो, दीजे केवलज्ञान॥"],meaning:"वर्तमान में महाविदेह क्षेत्र में साक्षात् समवशरण में विराजमान तीनों लोकों के स्वामी भगवान श्री सीमंधर स्वामी को मेरा नमन है; प्रभु हमें आत्मिक केवलज्ञान की प्राप्ति का मार्ग दीजिए।"},{number:"२",tag:"दोहा",lines:["अष्ट कर्म के नाश को, ध्याऊँ चरण सुजान।","चालीसा गाऊँ सदा, करिये कृपा निधान॥"],meaning:"अपने आठों कर्मों के समूल नाश हेतु मैं प्रभु के पावन चरणों का ध्यान करता हूँ और नित्य चालीसा का पाठ करता हूँ। हे कृपानिधान स्वामी! मुझ पर अपनी करुणा दृष्टि कीजिए।"},{number:"३",tag:"चौपाई",lines:["जय श्री सीमंधर सुखकारी, विदेह क्षेत्र के अवतारी।","पुण्डरीकिणी नगरी प्यारी, राजा श्रेयांस के दुलारी॥"],meaning:"महाविदेह क्षेत्र में साक्षात् विचरने वाले सुखदाता भगवान सीमंधर स्वामी की जय हो। रमणीय पुण्डरीकिणी नगरी के न्यायप्रिय राजा श्रेयांस के आप सुपुत्र हैं।"},{number:"४",tag:"चौपाई",lines:["सत्यकी माता उर प्रगटाये, सुर-नर मिलकर मंगल गाये।","बाल्यकाल से ही वैरागी, आत्म ज्ञान के परम अनुरागी॥"],meaning:"महारानी सत्यकी के गर्भ से तीर्थंकर बालक का जन्म हुआ और देव-मनुष्यों ने मंगल गान किए। प्रभु बाल्यावस्था से ही विरक्त और शुद्धात्म ज्ञान के परम अनुरागी थे।"},{number:"५",tag:"चौपाई",lines:["भोग विलास त्याग वन आये, घोर तपस्या ध्यान लगाये।","घातिया कर्म विनाश कराये, केवलज्ञान महोत्सव पाये॥"],meaning:"राजवैभव त्यागकर प्रभु वन पधारे, घोर तपस्या की और चारों घातिया कर्मों का नाश कर परम केवलज्ञान प्राप्त किया, जिसका देवों ने महामहोत्सव मनाया।"},{number:"६",tag:"चौपाई",lines:["धनुष पांच सौ काया सोहे, लख सुर-नर का मानस मोहे।","स्वर्ण वर्ण देही अति प्यारी, नमो नमो जग तारणहारी॥"],meaning:"प्रभु के सुवर्ण-वर्ण दिव्य देह की ऊँचाई पाँच सौ धनुष है, जो सुर-नर के मन को मोह लेती है। हे जगत्तारक जिनेन्द्र! आपके पावन चरणों में मेरा बारम्बार नमन है।"},{number:"७",tag:"चौपाई",lines:["जो कोई सीमंधर गुण गावे, उसके सब संताप नसावे।","मन मंदिर में ध्यान लगावे, सम्यग्दर्शन शीघ्रहि पावे॥"],meaning:"जो प्राणी सीमंधर स्वामी के पावन गुणों का गान करता है, उसके समस्त संताप मिट जाते हैं। जो प्रभु को हृदय में स्थापित करता है, उसे शीघ्र सम्यग्दर्शन प्राप्त होता है।"},{number:"८",tag:"चौपाई",lines:["विदेह क्षेत्र महिमा अति भारी, जहाँ विराजे प्रभु अविकारी।","भरत क्षेत्र से वन्दन करते, प्रभु चरणों में शीश धरते॥"],meaning:"महाविदेह क्षेत्र की महिमा अपार है जहाँ प्रभु साक्षात् अविकारी रूप में विराजते हैं। हम भरत क्षेत्र में रहकर भी भावों से प्रभु के चरणों में अपना मस्तक झुकाते हैं।"},{number:"९",tag:"चौपाई",lines:["काम क्रोध मद लोभ विडारे, जनम-जनम के पाप निवारे।","अहिंसा का पाठ पढ़ाया, जीव दया का पंथ सिखाया॥"],meaning:"प्रभु ने काम, क्रोध, मान, माया, लोभ रूपी आंतरिक शत्रुओं को जीतकर जन्म-जन्म के पापों को काट दिया और जगत को अहिंसा एवं प्राणिमात्र पर करुणा का पावन मार्ग सिखाया।"},{number:"१०",tag:"चौपाई",lines:["दिव्यध्वनि प्रभु अमृत धारा, शांत करे भव-ताप अपारा।","समवसरण शोभा अति भारी, द्वादश सभा बैठे अविकारी॥"],meaning:"प्रभु की अमृतमयी दिव्यध्वनि संसार के अपार ताप को शांत करती है। कुबेर द्वारा रचित दिव्य समवशरण में बारह सभाओं के प्राणी वीतराग देशना का श्रवण करते हैं।"},{number:"११",tag:"चौपाई",lines:["इन्द्र फणीन्द्र चंवर ढुरकावें, जय-जयकार शब्द उच्चारें।","तीन छत्र सिर पर सोहावें, भामंडल छवि लखि हरषावें॥"],meaning:"सौधर्म इन्द्र और धरणेन्द्र चँवर ढुलकाते हैं और जय-जयकार करते हैं। प्रभु के मस्तक पर तीन छत्र और पृष्ठभाग में कोटि सूर्यों को लज्जित करने वाला दिव्य भामंडल सुशोभित है।"},{number:"१२",tag:"चौपाई",lines:["चौंसठ चंवर ढुरें सुखदाई, जय जिनेंद्र बोले सुखदाई।","अशोक वृक्ष तरु छाया भारी, सुर-पुष्पों की वृष्टि सुखकारी॥"],meaning:"चौंसठ चँवर ढुलते हैं, गगनचुम्बी अशोक वृक्ष की शीतल छाया है और देवगण निरंतर सुगंधित सुर-पुष्पों की वृष्टि करते हैं।"},{number:"१३",tag:"चौपाई",lines:["दुंदुभी बाजे गगन मंझारी, देव-दुंदुभी शब्द प्रसारी।","जो जन प्रभु की शरण समावें, तिनके संकट दूर पलावे॥"],meaning:"आकाश में देव-दुंदुभियों की गम्भीर ध्वनि गूँजती है। जो भी प्राणी प्रभु की पावन शरण ग्रहण करते हैं, उनके समस्त संकट तत्काल भाग जाते हैं।"},{number:"१४",tag:"चौपाई",lines:["व्याधि रोग सब दूर भगावें, मनवांछित आनंद उपजावें।","अंधे को प्रभु दृष्टि दिवायें, कोढ़ी की काया चमकावें॥"],meaning:"प्रभु भक्ति से समस्त आधिव्याधियाँ दूर होती हैं और अलौकिक आनंद की प्राप्ति होती है। अज्ञान के अंधे को सम्यग्दृष्टि और कुकर्मी को आत्मविशुद्धि मिलती है।"},{number:"१५",tag:"चौपाई",lines:["निर्धन को धन-धान्य बढ़ावें, बाँझिन को सुत-रत्न दिलावें।","कारागार से मुक्त करावें, शत्रु-भय तत्काल मिटावें॥"],meaning:"प्रभु के स्मरण से आत्मिक निर्धनता दूर होकर धर्म रूपी लक्ष्मी मिलती है, संसार के जन्म-मरण रूप कारागार से मुक्ति मिलती है और कर्म-शत्रुओं का भय मिट जाता है।"},{number:"१६",tag:"चौपाई",lines:["भूत-प्रेत डाकिनी नसावें, पिशाच बाधा पास न आवें।","विषधर का विष तुरत उतारे, अग्नि-भय से प्रभु उबारे॥"],meaning:"प्रभु नाम के प्रभाव से समस्त कुयोनियों और भय का शमन होता है, सांसारिक काम-विष उतर जाता है और त्रिताप रूपी दावानल से जीव की रक्षा होती है।"},{number:"१७",tag:"चौपाई",lines:["सागर में नैया पार लगावें, संकट में जो नाम ध्यावें।","श्री सीमंधर दया के सागर, ज्ञान-सिंधु गुण-गण के आगर॥"],meaning:"संसार-सागर में डगमगाती जीवन-नौका को प्रभु पार लगाते हैं। भगवान सीमंधर साक्षात् करुणा के सागर और अनन्त ज्ञान व गुणों के आगार हैं।"},{number:"१८",tag:"चौपाई",lines:["हम सेवक प्रभु द्वार तुम्हारे, शरण पड़े हैं दीन पुकारे।","मोह तिमिर मम दूर नसाओ, सम्यग्ज्ञान प्रकाश जगाओ॥"],meaning:"हे स्वामी! हम आपके सेवक बनकर आपके द्वार पर पुकार रहे हैं। हमारे अंतःकरण से अज्ञान रूपी घने अंधकार को मिटाकर सम्यग्ज्ञान का दिव्य प्रकाश प्रगट कीजिए।"},{number:"१९",tag:"चौपाई",lines:["पंच महाव्रत की रुचि उपजे, रत्नत्रय का मार्ग जो सूझे।","राग-द्वेष के बंधन छूटें, भव-भव के सब बन्धन टूटें॥"],meaning:"हमारे मन में पाँच महाव्रतों के प्रति रुचि जगे और रत्नत्रय का सन्मार्ग स्पष्ट दिखे, जिससे राग-द्वेष के समस्त जाल कटें और भव-भव के बंधन टूट जाएँ।"},{number:"२०",tag:"चौपाई",lines:["विदेह क्षेत्र में जाऊँ ध्याऊँ, साक्षात् प्रभु दर्शन पाऊँ।","अष्टद्रव्य से पूजा कीजे, आरती भाव सहित कर लीजे॥"],meaning:"भावना भाते हैं कि हम विदेह क्षेत्र में जाकर प्रभु के साक्षात् दर्शन करें और अष्टद्रव्य से पूजा व भावभीनी आरती कर अपने जीवन को सफल बनाएँ।"},{number:"२१",tag:"चौपाई",lines:["सीमंधर प्रभु अंतर्यामी, हम सेवक तुम हो जग स्वामी।","नित-प्रति जो चालीसा गावे, सब सुख पाकर मोक्ष सिधावे॥"],meaning:"हे अंतर्यामी त्रैलोक्यनाथ सीमंधर स्वामी! जो प्राणी नित्य इस चालीसा का पाठ करता है, वह समस्त सुखों को प्राप्त कर अंत में शाश्वत मोक्ष पाता है।"},{number:"२२",tag:"चौपाई",lines:["चालीस दिन चालीस ही बारा, पाठ करे पावे भव पारा।","अक्षय सुख का भोगी होवे, भवसागर के बंधन खोवे॥"],meaning:"जो चालीस दिनों तक नियमपूर्वक इस चालीसा का पाठ करता है, वह संसार-समुद्र से पार उतरकर सिद्धालय के अक्षय अव्याबाध सुख का भागीदार बनता है।"},{number:"२३",tag:"दोहा",lines:["विदेह बिहारी नाथ तुम, सुनो हमारी टेर।","भव-भव के संकट हरो, करो न प्रभुवर देर॥"],meaning:"महाविदेह क्षेत्र में साक्षात् विचरने वाले हे नाथ! हमारी प्रार्थना सुनिए और हमारे जन्म-मरण के सांसारिक संकटों का शीघ्र हरण कीजिए।"},{number:"२४",tag:"दोहा",lines:["श्री सीमंधर जिनचरण में, वन्दन बारम्बार।","मोक्ष-महल की राह दो, मेटो भव-संसार॥"],meaning:"भगवान श्री सीमंधर स्वामी के पावन चरणों में मेरा बारम्बार वन्दन है। हमें मोक्षमार्ग का प्रकाश दीजिए और संसार-परिभ्रमण का नाश कीजिए।"},{number:"२५",tag:"जाप मंत्र",lines:["॥ मूल मंत्र एवं ध्यान ॥","ॐ ह्रीं अर्हं श्री सीमंधर स्वामिने नमः।"],meaning:"विद्यमान बीस तीर्थंकरों में प्रमुख, वर्तमान में साक्षात् केवलज्ञानी देवाधिदेव श्री सीमंधर स्वामी के पावन चरणों में मेरा त्रिकाल नमन हो।"}]},"jinendra-chalisa":{id:"jinendra-chalisa",category:"chalisa",title:"श्री जिनेन्द्र चालीसा",subtitle:"सर्व जिनेन्द्र भगवान की सामूहिक भक्ति एवं स्तुति पाठ",type:"structured",verses:[{number:"१",tag:"दोहा",lines:["शीश नवा अरिहन्त को, सिद्धन करूँ प्रणाम।","उपाध्याय आचार्य का, ले सुखकारी नाम॥"],meaning:"सर्वप्रथम अनन्त चतुष्टय धारी अरिहंतों के आगे शीश झुकाता हूँ और अशरीरी सिद्धों को प्रणाम करता हूँ। संघनायक आचार्यों और ज्ञानदाता उपाध्यायों का सुखकारी नाम स्मरण करता हूँ।"},{number:"२",tag:"दोहा",lines:["सर्व साधु और सरस्वती, जिनवाणी सुखकार।","जिनेन्द्र प्रभु की भक्ति का, गाऊँ मंगलाचार॥"],meaning:"समस्त दिगम्बर साधुओं और द्वादशांग जिनवाणी माता को नमन कर मैं तीनों लोकों के नाथ जिनेन्द्र भगवान की पावन भक्ति का मंगलाचार गान करता हूँ।"},{number:"३",tag:"चौपाई",lines:["जय जिनवर त्रिभुवन के स्वामी, अंतरयामी सुख के धामी।","तीन लोक में महिमा भारी, भव-भय भंजन मंगलकारी॥"],meaning:"तीनों लोकों के स्वामी, अंतर्यामी और अनंत सुख के धाम जिनेन्द्र प्रभु की जय हो! त्रिभुवन में आपकी महिमा अपरंपार है; आप संसार के जन्म-मरण रूपी भय का नाश करने वाले परम मंगलकारी हैं।"},{number:"४",tag:"चौपाई",lines:["ऋषभदेव से वीर जिनेशा, चौबीसों जिन हरें कलेशा।","गर्भ जन्म तप केवल ज्ञाना, मोक्ष पधारे प्रभु कल्याणा॥"],meaning:"प्रथम तीर्थंकर भगवान ऋषभदेव से लेकर अंतिम तीर्थंकर भगवान महावीर स्वामी तक सभी चौबीसों जिनेन्द्र हमारे समस्त क्लेशों को हरें। पाँचों पावन कल्याणकों को पूर्ण कर प्रभु मोक्ष पधारे हैं।"},{number:"५",tag:"चौपाई",lines:["समवसरण प्रभु अति सुखदायी, दिव्यध्वनी अमृत बरसाई।","अहिंसा का सन्देश सुनाया, जन-जन को जिनधर्म सिखाया॥"],meaning:"प्रभु का समवशरण समस्त जीवों को परम सुख व शांति देने वाला है, जहाँ से दिव्यध्वनि रूपी अमृत की वर्षा होती है। प्रभु ने अहिंसा परमो धर्म का अमर संदेश देकर जगत को जिनधर्म सिखाया।"},{number:"६",tag:"चौपाई",lines:["क्रोध मान माया मद त्यागो, आत्म ज्ञान के पथ पर जागो।","जीव मात्र पर करुणा धारो, निज आतम का रूप निहारो॥"],meaning:"क्रोध, मान, माया, लोभ और अहंकार को त्यागकर आत्मज्ञान के पावन मार्ग पर जाग्रत होओ। प्राणिमात्र पर दया का भाव रखो और अपनी शुद्ध चैतन्य आत्मा का साक्षात्कार करो।"},{number:"७",tag:"चौपाई",lines:["राग-द्वेष के बंधन तोड़े, निज स्वभाव से नाता जोड़े।","अष्ट कर्म का नाश कराया, परम दिगम्बर वेश सजाया॥"],meaning:"राग और द्वेष के विकारी बंधनों को तोड़कर अपने शुद्धात्म स्वभाव से नाता जोड़ो। प्रभु ने परम वीतराग दिगम्बर मुद्रा धारण कर आठों कर्मों का समूल नाश कर दिया।"},{number:"८",tag:"चौपाई",lines:["अरिहंत पद पाए सुखकारी, सिद्ध शिला बिराजे अविकारी।","आचार्य संघ का ध्यान धरें, मुनिजन संयम पालन करें॥"],meaning:"प्रभु ने पहले सकल परमात्मा अरिहंत पद और फिर सिद्धशिला पर विराजमान होकर निष्कल अविकारी सिद्ध पद पाया। आचार्य संघ का मार्गदर्शन करते हैं और मुनिराज कठोर संयम पालते हैं।"},{number:"९",tag:"चौपाई",lines:["उपाध्याय गुरु ज्ञान सिखावें, साधु मोक्ष का पंथ बतावें।","पंच परमेष्ठी पावन नाम, जपो निरंतर आठों याम॥"],meaning:"उपाध्याय गुरुदेव जिनागम का यथार्थ ज्ञान सिखाते हैं और साधु मोक्षमार्ग का प्रत्यक्ष आचरण दिखाते हैं। इन पंचपरमेष्ठियों के पावन नामों का आठों पहर निरंतर जाप करो।"},{number:"१०",tag:"चौपाई",lines:["जो जिनवर का ध्यान लगावे, मनवांछित फल निश्चय पावे।","दुःख दरिद्र सब दूर नसावे, सुख शांति आनंद बढ़ावे॥"],meaning:"जो प्राणी एकाग्र होकर वीतरागी जिनेन्द्र का ध्यान करता है, वह निश्चित रूप से आत्मिक शांति व मनोरथ पाता है। उसके जीवन से दुःख और दारिद्र्य दूर भागते हैं तथा सुख-शांति बढ़ती है।"},{number:"११",tag:"चौपाई",lines:["भक्ति भाव से जो गुण गावे, भव-भव के पातक कट जावे।","रत्नत्रय का मार्ग मिलावे, सम्यग्दर्शन ज्ञान जगावे॥"],meaning:"सच्ची भक्ति से जिनेन्द्र प्रभु के गुणों का गान करने पर जन्म-जन्मांतर के संचित पाप कट जाते हैं। जीव को सम्यग्दर्शन, सम्यग्ज्ञान और सम्यक्चारित्र रूपी रत्नत्रय मार्ग प्राप्त होता है।"},{number:"१२",tag:"चौपाई",lines:["सत्य अहिंसा व्रत अपनाओ, शील सदाचार मन लाओ।","अपरिग्रह अचौर्य सुखदाई, जिनवाणी माँ की बलिहारी॥"],meaning:"सत्य, अहिंसा, अचौर्य, ब्रह्मचर्य और अपरिग्रह—इन पाँच महाव्रतों/अणुव्रतों को अपने जीवन में धारण करो। जिनवाणी माता का यह उपदेश समस्त आत्माओं का परम हितकारी है।"},{number:"१३",tag:"चौपाई",lines:["प्रातः उठ जो चालीसा गावे, सब संकट से मुक्ति पावे।","विद्या बुद्धि विनय विशाला, होवे जनम-मरण उजियाला॥"],meaning:"जो भव्य जीव प्रातःकाल उठकर इस पावन चालीसा का पाठ करता है, वह समस्त संकटों से मुक्त हो जाता है। उसे सद्बुद्धि, विद्या और विनय की प्राप्ति होती है।"},{number:"१४",tag:"चौपाई",lines:["घर-आँगन में मंगल छावे, रिद्धि-सिद्धि नित बढ़ती जावे।","जिनवर कृपा रहे अनुदिन, कटे पाप सब छिन ही छिन॥"],meaning:"घर-परिवार में धर्ममय वातावरण और मंगल का वास होता है, आत्मिक रिद्धि-सिद्धि बढ़ती है। जिनेन्द्र प्रभु की कृपा-दृष्टि से क्षण भर में अशुभ कर्मों की निर्जरा हो जाती है।"},{number:"१५",tag:"चौपाई",lines:["नित जिन मंदिर दर्शन कीजे, पावन जिन अभिषेक करीजे।","पूजन अष्टद्रव्य सज ल्यावे, प्रभु चरणों में शीश नवावे॥"],meaning:"प्रतिदिन जिनमंदिर जाकर वीतराग प्रभु के दर्शन और अभिषेक करें। अष्टद्रव्य से सुसज्जित थाल लेकर भक्तिपूर्वक पूजा करें और प्रभु चरणों में शीश झुकाएँ।"},{number:"१६",tag:"चौपाई",lines:["शांतिधारा का फल पावे, सर्व व्याधि तत्काल नसावे।","जो भविजन यह पाठ करे, भवसागर से पार तरे॥"],meaning:"जिन-अभिषेक व शांतिधारा के दर्शन से समस्त शारीरिक और मानसिक व्याधियाँ तत्काल शांत हो जाती हैं। जो भव्य आत्मा यह पाठ करती है, वह संसार-समुद्र से पार उतर जाती है।"},{number:"१७",tag:"चौपाई",lines:["चालीस दिन नित नियम से, पाठ करे जो कोय।","मनवांछित सब कार्य सिद्ध, विघ्न न कोई होय॥"],meaning:"जो कोई चालीस दिनों तक नियमपूर्वक इस पावन चालीसा का पाठ करता है, उसके समस्त धार्मिक कार्य निर्विघ्न सिद्ध होते हैं और कोई बाधा नहीं आती।"},{number:"१८",tag:"चौपाई",lines:["भूत पिशाच निकट नहीं आवें, जिनवर का जब नाम सुनावें।","विषधर का विष तुरत बिलावे, जिनवर मंत्र जपे सुख पावे॥"],meaning:"जिनेन्द्र प्रभु का नाम सुनते ही समस्त भय और कुयोनियों का संत्रास दूर हो जाता है। विष का प्रभाव उतर जाता है और जिनवर के मंत्र जाप से परम शांति मिलती है।"},{number:"१९",tag:"चौपाई",lines:["अग्नि-नीर का भय मिट जावे, संकट-मोचन जिन कहलावें।","राज-द्वार में विजय करावे, शत्रु-सैन्य भयभीत भगावे॥"],meaning:"अग्नि, जल, तूफान और चोर-शत्रुओं का भय मिट जाता है। वीतराग जिनेन्द्र वास्तव में संकटमोचन हैं, जो आत्मा को सभी कर्म-शत्रुओं से सुरक्षित करते हैं।"},{number:"२०",tag:"चौपाई",lines:["अंधे को प्रभु दृष्टि दिलावें, कोढ़ी का तन कंचन बनावें।","पुत्र-पौत्र सुख संपति छावे, घर-घर मंगल गान सुनावे॥"],meaning:"प्रभु भक्ति से अज्ञानियों को सम्यग्ज्ञान रूपी दिव्य दृष्टि और कलुषित आत्मा को कंचन जैसी विशुद्धि मिलती है। घर-आँगन में सुख, शांति और धर्म का प्रकाश होता है।"},{number:"२१",tag:"चौपाई",lines:["अंत समय में समाधि पावे, स्वर्ग-मोक्ष के सुख बरसावे।","जिन शासन की ध्वजा फहरावे, धर्म-प्रभावना नित्य बढ़ावे॥"],meaning:"जीवन के अंत समय में शांत समाधिमरण की प्राप्ति होती है और स्वर्ग-मोक्ष के सुख मिलते हैं। भक्त जिनशासन की पावन ध्वजा फहराकर धर्म की प्रभावना बढ़ाता है।"},{number:"२२",tag:"चौपाई",lines:["भक्त 'दास' प्रभु शरण तिहारी, मेटो भव के कष्ट करारी।","यह चालीसा चालीस प्रकाशा, पूरण होय मन की सब आशा॥"],meaning:"हे जिनेन्द्र देव! हम आपके चरणों की शरण में हैं, हमारे जन्म-मरण के दारुण कष्टों को मिटा दीजिए। यह चालीस पद्यों का प्रकाश हमारी सभी आध्यात्मिक आशाओं को पूर्ण करे।"},{number:"२३",tag:"दोहा",lines:["जिनवाणी माता नमो, दूर करो अज्ञान।","पाऊँ मोक्ष महान सुख, दीजे केवलज्ञान॥"],meaning:"हे जिनवाणी माता! आपको मेरा बारम्बार नमन है, हमारे अज्ञान को दूर कीजिए और हमें मोक्ष के अनुपम सुख व केवलज्ञान की प्राप्ति का संबल दीजिए।"},{number:"२४",tag:"दोहा",lines:["जिनेन्द्र चालीसा पढ़े, जो कोई धरे ध्यान।","ऋद्धि सिद्धि संपति लहे, पावे पद निर्वान॥"],meaning:"जो कोई एकाग्रचित्त होकर जिनेन्द्र चालीसा का पाठ व ध्यान करता है, वह धर्म-ध्यान की आत्मिक ऋद्धि-सिद्धि पाता है और अंत में शाश्वत निर्वाण पद को प्राप्त करता है।"},{number:"२५",tag:"जाप मंत्र",lines:["॥ मूल मंत्र एवं ध्यान ॥","ॐ ह्रीं श्री जिनेन्द्राय नमः।"],meaning:"सकल ज्ञायक, चौबीसों तीर्थंकर देवाधिदेव जिनेन्द्र भगवान के पावन चरणों में मेरा अनंत बार नमन हो।"}]},"adinath-chalisa-chandkhedi":{id:"adinath-chalisa-chandkhedi",category:"chalisa",title:"श्री आदिनाथ चालीसा (चाँदखेड़ी)",subtitle:"अतिशय क्षेत्र चाँदखेड़ी (झालावाड़) प्रथम तीर्थंकर आदिनाथ चालीसा",type:"structured",verses:[{number:"१",tag:"दोहा",lines:["चाँदखेड़ी अतिशय भलो, आदिनाथ जिनराज।","दर्शन पावत ही सरें, भक्तन के सब काज॥"],meaning:"राजस्थान के चाँदखेड़ी अतिशय क्षेत्र में विराजमान भगवान श्री आदिनाथ का अतिशय अनुपम है; उनके पावन दर्शन मात्र से भक्तों के समस्त कार्य निर्विघ्न सिद्ध होते हैं।"},{number:"२",tag:"दोहा",lines:["कोटा प्रान्त सुहावना, खानपुर के पास।","आदिनाथ स्वामी करें, संकट सब का नाश॥"],meaning:"कोटा-झालावाड़ अंचल में खानपुर के निकट स्थित इस पावन तीर्थ पर विराजमान आदिनाथ प्रभु अपने शरणागत भक्तों के समस्त संकटों और भयों का नाश करते हैं।"},{number:"३",tag:"चौपाई",lines:["जय जय आदिनाथ सुखदाई, चाँदखेड़ी में प्रभुता छाई।","श्यामवर्ण मूरत मन भावे, कोटि भानु की छटा लजावे॥"],meaning:"सुखदाता भगवान आदिनाथ की जय हो, जिनका अतिशय चाँदखेड़ी में विश्वविख्यात है। प्रभु की श्यामवर्ण पाषाणमयी भव्य पद्मासन प्रतिमा करोड़ों सूर्यों की कांति को भी लज्जित करती है।"},{number:"४",tag:"चौपाई",lines:["नाभिराज मरुदेवी नंदन, कोटि-कोटि सुर करते वंदन।","प्रथम तीर्थंकर प्रथम जिनेशा, काटो प्रभु जी सकल कलेशा॥"],meaning:"महाराजा नाभिराज और माता मरुदेवी के नंदन प्रभु आदिनाथ को करोड़ों देव वन्दन करते हैं। हे इस अवसर्पिणी काल के प्रथम तीर्थंकर! हमारे समस्त सांसारिक क्लेशों को काट दीजिए।"},{number:"५",tag:"चौपाई",lines:["भूमिगर्भ से प्रगटे स्वामी, तीन भुवन के अंतरयामी।","संवत सत्रह सौ इकतीस मंझार, प्रगटे आदिनाथ करतार॥"],meaning:"विक्रम संवत् १७३१ में तीनों लोकों के अंतर्यामी प्रभु भूमि के गर्भ से दिव्य अतिशय के साथ प्रकट हुए, जिससे इस क्षेत्र की ख्याति दिशा-दिशा में फैल गई।"},{number:"६",tag:"चौपाई",lines:["किशनदास व्यापारी ध्यायो, स्वप्न देख अतिशय प्रगटायो।","खोदी भूमि पाषाण हटायो, दिव्य रूप जिनवर का पायो॥"],meaning:"श्रद्धालु व्यापारी किशनदास को रात्रि में स्वप्न का आदेश मिला; भूमि खोदकर पाषाण हटाने पर भगवान आदिनाथ की अनुपम और तेजस्वी पद्मासन प्रतिमा प्राप्त हुई।"},{number:"७",tag:"चौपाई",lines:["रथ में मूरत बैठाई जब, रथ न हिले विस्मित जन सब।","भूपति ने तब विनय पुकारी, यहीं विराजो प्रभु अविकारी॥"],meaning:"जब प्रतिमा को अन्यत्र ले जाने हेतु रथ में विराजमान किया गया, तो रथ तनिक भी न हिला। यह देखकर राजा और जनता ने विनयपूर्वक प्रार्थना की कि हे नाथ! आप यहीं विराजें।"},{number:"८",tag:"चौपाई",lines:["मंदिर भव्य बन्यो सुखकारी, गूंजे जय जयकार तुम्हारी।","जो जन चाँदखेड़ी आवे, मनवांछित सब वैभव पावे॥"],meaning:"वहाँ विशाल और भव्य भूगर्भ जिनालय का निर्माण हुआ जहाँ प्रभु की जय-जयकार गूँजती है। जो भी श्रद्धालु यहाँ दर्शनार्थ आता है, वह मनोवांछित फल पाता है।"},{number:"९",tag:"चौपाई",lines:["अंधे नयन मिले सुख पावें, कोढ़ी काया कंचन पावें।","निर्धन धनवान बने सुखदायी, बांझिन सुत पावे हरषाई॥"],meaning:"प्रभु के अतिशय से भक्तों की शारीरिक व सांसारिक पीड़ाएँ दूर होती हैं; अज्ञानियों को सम्यग्ज्ञान रूपी नेत्र मिलते हैं और आत्मा कंचनवत शुद्ध हो जाती है।"},{number:"१०",tag:"चौपाई",lines:["भूत पिशाच निकट नहिं आवे, आदिनाथ जब नाम सुनावें।","व्याधि उपाधि रोग नशावें, संकट मोचन नाम कहावें॥"],meaning:"भगवान आदिनाथ का नाम स्मरण करते ही समस्त भय, विघ्न और उपद्रव शांत हो जाते हैं। प्रभु सभी आधि-व्याधि को नष्ट करने वाले सच्चे संकटमोचन हैं।"},{number:"११",tag:"चौपाई",lines:["अमृत कुण्ड नीर सुखदाई, चरणामृत सब पीवें भाई।","पंचामृत अभिषेक करावें, अष्टद्रव्य से अर्घ चढ़ावें॥"],meaning:"मंदिर के पवित्र अमृत कुण्ड का जल अत्यंत पावन है। भक्तजन भक्तिभाव से अभिषेक और गंधोदक ग्रहण कर अष्टद्रव्य से प्रभु के चरणों में अर्घ्य समर्पित करते हैं।"},{number:"१२",tag:"चौपाई",lines:["दीपमालिका ज्योति जगावें, भक्ति भाव से शीश नवावें।","ऋषभदेव प्रभु करुणा कीजे, भव-सागर से तारन दीजे॥"],meaning:"आरती की दीपमाला प्रज्वलित कर भक्त प्रभु के चरणों में शीश नवाते हैं। हे भगवान ऋषभदेव! हम पर अपनी करुणा कीजिए और हमें इस संसार-सागर से पार उतारिए।"},{number:"१३",tag:"चौपाई",lines:["इन्द्र चन्द्र नित सेवा आवें, सुर-नर मुनिवर महिमा गावें।","सकल कषाय मिटावन हारे, आत्म-धर्म जगावन हारे॥"],meaning:"सौधर्म इन्द्र आदि देवगण जिनकी वन्दना करते हैं, वे आदिनाथ प्रभु सभी कषायों को मिटाने वाले और अंतःकरण में आत्म-धर्म की ज्योति जगाने वाले हैं।"},{number:"१४",tag:"चौपाई",lines:["काम-क्रोध मद-लोभ विनाशी, वीतराग आनंद अविनाशी।","समवशरण की शोभा भारी, द्वादश सभा बैठे अविकारी॥"],meaning:"काम, क्रोध, मान, माया, लोभ का समूल नाश करने वाले वीतरागी प्रभु के समवशरण की शोभा अद्वितीय थी, जहाँ बारह सभाओं में समस्त जीव निर्वैर भाव से बैठते थे।"},{number:"१५",tag:"चौपाई",lines:["दिव्यध्वनी से संशय तोड़ा, जिनशासन से जग को जोड़ा।","भरत-बाहुबली सुत सुखदाई, ब्राह्मी-सुन्दरी विद्या पाई॥"],meaning:"प्रभु ने दिव्यध्वनि से प्राणियों के समस्त संशय मिटा दिए। चक्रवर्ती भरत और कामदेव बाहुबली जैसे पुत्र तथा ब्राह्मी और सुन्दरी जैसी विदुषी पुत्रियों को धर्म व विद्या का मार्ग दिखाया।"},{number:"१६",tag:"चौपाई",lines:["अहिंसा परम धर्म सिखलाया, जग को मुक्ति-पंथ दिखाया।","चाँदखेड़ी तीरथ अति पावन, दर्शन से निर्मल हो पावन॥"],meaning:"अहिंसा को सर्वोच्च धर्म घोषित कर प्रभु ने मुक्ति का मार्ग प्रशस्त किया। चाँदखेड़ी का यह पावन अतिशय क्षेत्र दर्शन मात्र से आत्मा को परम पवित्र बना देता है।"},{number:"१७",tag:"चौपाई",lines:["दूर-दूर से यात्री आवें, पूजा कर आनंद बढ़ावें।","ध्वजा पताका मंदिर सोहे, शिखर देख मन सबका मोहे॥"],meaning:"देशभर से श्रद्धालु यहाँ आकर पूजा-अर्चना करते हैं। मंदिर के गगनचुंबी शिखर पर फहराती जिनशासन की धर्मध्वजा को देखकर मन श्रद्धा से भर जाता है।"},{number:"१८",tag:"चौपाई",lines:["घंटा घड़ियाल नगाड़े बाजे, आरती में जयकारा गाजे।","जो नर पाठ करे चालीस, पावे पद निर्भय अवनिपति॥"],meaning:"मंदिर में बजते घंटे, घड़ियाल और नगाड़ों के बीच मंगल आरती होती है। जो नियम से चालीस पाठ करता है, वह निर्भय आत्मपद प्राप्त करता है।"},{number:"१९",tag:"चौपाई",lines:["चालीसा चालीस दिन गावे, निश्चय भवसागर तिर जावे।","पुत्र-पौत्र सुख संपति बाढ़े, विघ्न भागें सब दुःख भागे॥"],meaning:"चालीस दिनों तक श्रद्धा से चालीसा गाने वाला भवसागर से पार उतर जाता है; उसके घर में सुख-समृद्धि बढ़ती है और सभी विघ्न-दुःख पलायन कर जाते हैं।"},{number:"२०",tag:"चौपाई",lines:["मैं मूरख अज्ञान अपारा, प्रभु बिन कौन करे निस्तारा।","अपनी शरण में मुझको लीजे, भव-भव की यह बाधा छीजे॥"],meaning:"हे आदिनाथ स्वामी! मैं अज्ञानी हूँ, आपके अतिरिक्त संसार से मेरा उद्धार करने वाला कोई नहीं है। मुझे अपनी पावन शरण में लेकर मेरी भव-भव की बाधाएँ मिटा दीजिए।"},{number:"२१",tag:"चौपाई",lines:["निसिदिन ध्यान धरूँ प्रभु तेरा, मेटो जनम मरण का फेरा।","विद्या बुद्धि विमल सुख दीजे, आतम रस में मगन करीजे॥"],meaning:"मैं प्रतिदिन आपका ध्यान करूँ और मेरा जन्म-मरण का यह चक्र समाप्त हो। मुझे सम्यग्ज्ञान, निर्मल बुद्धि और आत्म-रस में लीन रहने का वरदान दीजिए।"},{number:"२२",tag:"चौपाई",lines:["आदिनाथ प्रभु अंतरयामी, तुम हो मेरे पूरण स्वामी।","चाँदखेड़ी की जय जयकार, आदिनाथ प्रभु बेड़ा पार॥"],meaning:"हे अंतर्यामी आदिनाथ प्रभु! आप मेरे सच्चे स्वामी हैं। चाँदखेड़ी तीर्थ और आदिनाथ भगवान की सदा जय हो, जो जीवों का बेड़ा पार लगाने वाले हैं।"},{number:"२३",tag:"दोहा",lines:["चाँदखेड़ी आदिनाथ का, जो ध्यावे दिन-रैन।","सकल अमंगल दूर हों, पावे शाश्वत चैन॥"],meaning:"जो भी भव्य प्राणी दिन-रात चाँदखेड़ी के आदिनाथ प्रभु का ध्यान करता है, उसके समस्त अमंगल दूर हो जाते हैं और वह शाश्वत आत्मिक शांति प्राप्त करता है।"},{number:"२४",tag:"दोहा",lines:["हाथ जोड़ विनती करूँ, सुनिये आदि जिनेश।","जिनवाणी सेवा करूँ, हरो सकल क्लेश॥"],meaning:"हे आदि जिनेश्वर! दोनों हाथ जोड़कर प्रार्थना करता हूँ कि मुझे सदा जिनवाणी की सेवा का अवसर मिले और मेरे समस्त कर्म-क्लेश नष्ट हों।"},{number:"२५",tag:"जाप मंत्र",lines:["॥ मूल मंत्र एवं ध्यान ॥","ॐ ह्रीं श्री चाँदखेड़ी आदिनाथाय नमः।"],meaning:"अतिशय क्षेत्र चाँदखेड़ी के अधिष्ठाता, प्रथम तीर्थंकर देवाधिदेव श्री आदिनाथ भगवान के पावन चरणों में मेरा त्रिकाल नमन हो।"}]},"parshvanath-chalisa-ahichchhatra":{id:"parshvanath-chalisa-ahichchhatra",category:"chalisa",title:"श्री पार्श्वनाथ चालीसा (अहिच्छत्र)",subtitle:"तप-केवलज्ञान कल्याणक स्थली अहिच्छत्र (रामनगर, बरेली) पार्श्वनाथ चालीसा",type:"structured",verses:[{number:"१",tag:"दोहा",lines:["अहिच्छत्र पावन मही, तप-कल्याणक धाम।","पार्श्वनाथ प्रभु को नमन, कोटि-कोटि परनाम॥"],meaning:"तप और केवलज्ञान कल्याणक की परम पावन धरा अहिच्छत्र तीर्थ (रामनगर, आँवला-बरेली) के अधिपति भगवान श्री पार्श्वनाथ के चरणों में मेरा कोटि-कोटि प्रणाम है।"},{number:"२",tag:"दोहा",lines:["कमठ-उपसर्ग निवार के, प्रगट्यो केवलज्ञान।","धरणेन्द्र-पद्मावती सेवे, पूजें सकल जहान॥"],meaning:"कमठ के घोर उपसर्ग को परम क्षमा व समता भाव से जीतकर प्रभु ने यहीं केवलज्ञान प्राप्त किया। धरणेन्द्र और पद्मावती ने प्रभु के ऊपर फणों का छत्र बनाया; सम्पूर्ण विश्व प्रभु की पूजा करता है।"},{number:"३",tag:"चौपाई",lines:["जय जय पार्श्वनाथ सुखदाता, भक्त जनों के भाग्य विधाता।","अश्वसेन वामा के नंदन, काशीपति त्रिभुवन के वंदन॥"],meaning:"सुखदाता भगवान पार्श्वनाथ की जय हो, जो भक्तों के भाग्य के विधाता हैं। आप काशी नरेश राजा अश्वसेन और माता वामादेवी के नंदन तथा तीनों लोकों द्वारा वन्दनीय हैं।"},{number:"४",tag:"चौपाई",lines:["नील वर्ण तनु अतिशय सोहे, सर्प चिन्ह लख मानस मोहे।","वैराग्य उमग्यो अंतर्यामी, वन में ध्यान लगायो स्वामी॥"],meaning:"प्रभु का नीलकमल सम देह-वर्ण और चरणों में सर्प का मंगल चिह्न मन को मोह लेता है। युवावस्था में ही तीव्र वैराग्य जागने पर प्रभु ने वन में दिगम्बर दीक्षा लेकर ध्यान लगाया।"},{number:"५",tag:"चौपाई",lines:["अहिच्छत्र वन पावन भारी, प्रभु तपस्या कीन्ह अपारी।","पूर्व जनम का वैरी आया, कमठ असुर ने मेघ डिगाया॥"],meaning:"अहिच्छत्र के सघन वन में जब प्रभु कायोत्सर्ग ध्यान में लीन थे, तब पूर्व जन्मों का वैरी कमठ का जीव शम्बर मेघमाली बनकर आया और भयंकर उत्पात मचाया।"},{number:"६",tag:"चौपाई",lines:["घोर घटा नभ में छिटकाई, मूसलधार वृष्टि बरसाई।","शिला गिरे अति गर्जन भारी, पवन चले अति तीव्र विकारी॥"],meaning:"कमठ ने आकाश में काली घटाएँ फैलाकर मूसलधार जल बरसाया, भारी शिलाएँ गिराईं, भयंकर वज्रपात किया और प्रचंड आंधी-तूफान चलाए।"},{number:"७",tag:"चौपाई",lines:["नासाग्र दृष्टि प्रभु धारी, अचल रहे जैसे गिरि भारी।","जल से भर गई धरती सारी, प्रभु पद छूने आई जल-धारी॥"],meaning:"किन्तु प्रभु नासाग्र दृष्टि लगाए सुमेरु पर्वत की तरह पूर्णतः अडिग रहे। बाढ़ का जल जब प्रभु के नासिका तक पहुँचने लगा, तब भी प्रभु समता में लीन रहे।"},{number:"८",tag:"चौपाई",lines:["धरणेन्द्र पद्मावती धाये, फण फैलाय छत्र सजाये।","कमठ हार कर शीश झुकायो, प्रभु ने समता भाव बढ़ायो॥"],meaning:"तब नागराज धरणेन्द्र और देवी पद्मावती ने आकर प्रभु के मस्तक पर फणों का छत्र सजाया और कमठ पराजित होकर नतमस्तक हुआ। प्रभु ने वैरी पर भी समता रखी।"},{number:"९",tag:"चौपाई",lines:["घातिया कर्म किए सब क्षीना, प्रगट भयो केवल सुख लीना।","अहिच्छत्र तब तीर्थ कहायो, सकल जगत में अतिशय छायो॥"],meaning:"चारों घातिया कर्मों का समूल नाश कर प्रभु ने केवलज्ञान और अनन्त आत्मसुख प्राप्त किया। इस घटना से यह क्षेत्र 'अहिच्छत्र' नाम से जगतप्रसिद्ध तीर्थ बना।"},{number:"१०",tag:"चौपाई",lines:["मंदिर भव्य बन्यो सुखकारी, पद्मावती माँ पहरेदारी।","अतिशयकारी पारस स्वामी, दूर करें संकट सब नामी॥"],meaning:"अहिच्छत्र में विशाल भव्य जिनालय बना है जहाँ पद्मावती माता शासन रक्षक हैं। अतिशयकारी पार्श्वनाथ प्रभु अपने भक्तों के समस्त कष्टों को दूर करते हैं।"},{number:"११",tag:"चौपाई",lines:["जो जन अहिच्छत्र में जावे, मनवांछित सब फल सो पावे।","रोग-दोष सब दूर नसावें, भूत-प्रेत सब भाग जावें॥"],meaning:"जो भी श्रद्धालु इस पावन अहिच्छत्र तीर्थ पर आता है, वह मनोवांछित फल पाता है। उसके असाध्य रोग-शोक, भय और सभी उपद्रव शांत हो जाते हैं।"},{number:"१२",tag:"चौपाई",lines:["सर्प-भय विष-दोष निवारक, पार्श्वनाथ संकट के तारक।","अहिच्छत्र की माटी पावन, जो छुए होवे मन भावन॥"],meaning:"भगवान पार्श्वनाथ सर्प-भय, विष-दोष और जन्म-मरण के संताप को हरने वाले हैं। अहिच्छत्र की पवित्र रज का स्पर्श करते ही मन पावन हो जाता है।"},{number:"१३",tag:"चौपाई",lines:["चारों ओर हरियाली सोहे, शांत वातावरण मन मोहे।","अखंड ज्योति मंदिर में जागे, अंधकार अज्ञान का भागे॥"],meaning:"तीर्थ क्षेत्र का शांत और सुरम्य प्राकृतिक वातावरण चित्त को समाधि देता है। मंदिर में अखंड दीपक की ज्योति अज्ञान के अंधकार को दूर भगाती है।"},{number:"१४",tag:"चौपाई",lines:["अभिषेक जल मस्तक धारें, जनम-जनम के पाप निवारें।","धूप दीप नैवेद्य चढ़ावें, भाव भक्ति से चालीसा गावें॥"],meaning:"प्रभु के पावन अभिषेक का गंधोदक मस्तक पर लगाने से जन्म-जन्म के पाप कटते हैं। धूप, दीप, नैवेद्य समर्पित कर भावपूर्वक यह चालीसा गाएँ।"},{number:"१५",tag:"चौपाई",lines:["तेईसवें तीर्थंकर कहलाये, जग को मुक्ति मार्ग दिखाये।","अहिंसा दया का दीप जलाया, जियो और जीने दो समझाया॥"],meaning:"तेईसवें तीर्थंकर भगवान पार्श्वनाथ ने जगत को 'जियो और जीने दो' तथा अहिंसा, सत्य, अस्तेय, ब्रह्मचर्य और अपरिग्रह का मार्ग दिखाया।"},{number:"१६",tag:"चौपाई",lines:["चतुर्विध संघ की स्थापना कीनी, मुनि-श्रावक को शिक्षा दीनी।","सम्मेद शिखर से मोक्ष सिधारे, कोटि-कोटि मुनि भव से तारे॥"],meaning:"मुनि, आर्यिका, श्रावक और श्राविका रूप चतुर्विध संघ की स्थापना कर अंत में श्री सम्मेद शिखर जी के स्वर्णभद्र कूट से प्रभु सिद्धालय पधारे।"},{number:"१७",tag:"चौपाई",lines:["अहिच्छत्र पार्श्वनाथ गुण गाऊँ, चरण-शरण में शीश नवाऊँ।","मैं पापी प्रभु शरण तिहारी, मेटो मेरी विपदा भारी॥"],meaning:"अहिच्छत्र पार्श्वनाथ के गुणों का गान कर उनके चरणों में शीश झुकाता हूँ। हे पतितपावन प्रभु! मैं आपकी शरण में हूँ, मेरी विपदाओं को हर लीजिए।"},{number:"१८",tag:"चौपाई",lines:["धन-वैभव विद्या सुख दीजे, सम्यग्दर्शन उज्ज्वल कीजे।","जो चालीस दिन पाठ करावे, घर में मंगल मोद बढ़ावे॥"],meaning:"हे प्रभु! हमें सम्यग्ज्ञान, विनय और निर्मल सम्यग्दर्शन दीजिए। जो चालीस दिनों तक नियम से पाठ करता है, उसके घर में मंगल और आनंद का वास होता है।"},{number:"१९",tag:"चौपाई",lines:["पुत्र-पौत्र सुख संपति पावे, संकट कोई पास न आवे।","दुखिया के सब दुःख मिटाते, बिगड़े काम प्रभु बन जाते॥"],meaning:"भक्तों के संकट कट जाते हैं, दुखियों के दुःख मिटते हैं और प्रभु की वीतरागी कृपा से आत्मिक विशुद्धि व लौकिक शांति सहज प्राप्त होती है।"},{number:"२०",tag:"चौपाई",lines:["सच्चे मन से जो कोई ध्यावे, भव-भव के बंधन कट जावे।","पारस प्रभु सम वीतराग, जो पूजे जागे अनुराग॥"],meaning:"सच्चे अंतःकरण से जो प्रभु का ध्यान करता है, उसके जन्म-मरण के बंधन कट जाते हैं। वीतरागी पारस प्रभु की पूजा से हृदय में आत्म-अनुराग जागता है।"},{number:"२१",tag:"चौपाई",lines:["अहिच्छत्र तीरथ महान, जहँ प्रगटे पारस भगवान।","कृपा करो प्रभु दीनदयाला, काटहु कर्मों का यह जाला॥"],meaning:"अहिच्छत्र महान तीर्थ है जहाँ पारस प्रभु की तपस्या फलीभूत हुई। हे दीनदयाल स्वामी! हमारे कर्मों के इस जाले को ज्ञान-खड्ग से काट दीजिए।"},{number:"२२",tag:"चौपाई",lines:["नित प्रति पारस नाम जपूँ, पावन पद में चित्त रखूँ।","अहिच्छत्र के पार्श्व जिनेश, मेटो जग के सकल क्लेश॥"],meaning:"प्रतिदिन पार्श्वनाथ प्रभु का पावन नाम जपूँ और उनके कमल चरणों में अपना चित्त लगाऊँ। हे अहिच्छत्र के पार्श्व जिनेश्वर! हमारे सकल क्लेश मेट दीजिए।"},{number:"२३",tag:"दोहा",lines:["अहिच्छत्र पार्श्वनाथ को, ध्यावे जो मन लाय।","ऋद्धि-सिद्धि सुख-संपदा, सहज मिले घर आय॥"],meaning:"जो भी भव्य प्राणी एकाग्रचित्त होकर अहिच्छत्र पार्श्वनाथ का ध्यान करता है, उसे धर्म की ऋद्धि-सिद्धि और अलौकिक सुख-शांति सहज ही प्राप्त होती है।"},{number:"२४",tag:"दोहा",lines:["कमठ-निवारक पारस प्रभु, देहु ज्ञान प्रकाश।","चरण कमल में दास के, पूरण हो अभिलाष॥"],meaning:"कमठ के उपसर्ग को क्षमा से जीतने वाले हे पारस प्रभु! हमें सम्यग्ज्ञान का प्रकाश दीजिए और आपके चरण-कमलों की अनन्य भक्ति की अभिलाषा पूर्ण हो।"},{number:"२५",tag:"जाप मंत्र",lines:["॥ मूल मंत्र एवं ध्यान ॥","ॐ ह्रीं श्री अहिच्छत्र पार्श्वनाथाय नमः।"],meaning:"तप और केवलज्ञान तीर्थ अहिच्छत्र के अधिपति, तेईसवें तीर्थंकर भगवान श्री पार्श्वनाथ जी के पावन चरणों में मेरा त्रिकाल नमन हो।"}]},"parshvanath-chalisa-badagaon":{id:"parshvanath-chalisa-badagaon",category:"chalisa",title:"श्री पार्श्वनाथ चालीसा (बड़ागांव)",subtitle:"त्रिलोक तीर्थ बड़ागांव (बागपत) चिंतामणि पार्श्वनाथ चालीसा",type:"structured",verses:[{number:"१",tag:"दोहा",lines:["बड़ागांव त्रिलोक तीर्थ, पावन अतिशय धाम।","पार्श्वनाथ चिंतामणि, वंदूँ आठों याम॥"],meaning:"उत्तर प्रदेश के बागपत जिले में स्थित त्रिलोक तीर्थ बड़ागांव परम पावन अतिशय धाम है। यहाँ विराजमान चिंतामणि पार्श्वनाथ भगवान को मैं आठों पहर वन्दन करता हूँ।"},{number:"२",tag:"दोहा",lines:["बागपत पावन धरा, प्रगटे पारस नाथ।","शरणागत के शीश पर, राखो प्रभु निज हाथ॥"],meaning:"बागपत की पावन धरा से प्रकट हुए चिंतामणि पारस प्रभु अपने शरणागत भक्तों के मस्तक पर अपना वरदहस्त रखकर सदैव उनकी रक्षा करते हैं।"},{number:"३",tag:"चौपाई",lines:["जय जय पार्श्वनाथ दयाला, बड़ागांव के दीनदयाला।","चिंतामणि पारस कहलाते, भक्तों के संकट हर जाते॥"],meaning:"बड़ागांव के दयालु भगवान पार्श्वनाथ की जय हो! चिंतामणि रत्न के समान भक्तों की सर्व चिंताओं को हरने वाले पारस प्रभु सभी संकटों का निवारण करते हैं।"},{number:"४",tag:"चौपाई",lines:["अतिशयकारी मूरत सोहे, दिव्य तेज लख जग मन मोहे।","भूमि खोदकर मूरत पाई, जन-जन में जयकार मचाई॥"],meaning:"प्रभु की मनोहारी अतिशययुक्त प्रतिमा का दिव्य तेज त्रिभुवन के मन को मोह लेता है। भूमि से प्रकट होने पर अपार जनसमूह ने हर्षोल्लास से जय-जयकार की।"},{number:"५",tag:"चौपाई",lines:["त्रिलोक तीर्थ धाम सुहावन, तीनों लोक का रूप पावन।","नंदीश्वर जिन धाम बनायो, शिखर गगन में फहरायो॥"],meaning:"यहाँ गणिनीप्रमुख आर्यिका ज्ञानमती माताजी की प्रेरणा से तीनों लोकों की अद्वितीय जैन भूगोल रचना और नंदीश्वर द्वीप जिनालय का निर्माण हुआ है।"},{number:"६",tag:"चौपाई",lines:["सुमेरु पर्वत सम रचना भारी, देखत थकित होंय नर-नारी।","पार्श्वनाथ स्वामी सुखकारी, काटत जनम-मरण की बारी॥"],meaning:"सुमेरु पर्वत और जम्बूद्वीप आदि की गगनचुंबी संरचना देखकर दर्शक विस्मृत हो जाते हैं। सुखदाता पार्श्वनाथ प्रभु जन्म-मरण के सांसारिक फेरे को काट देते हैं।"},{number:"७",tag:"चौपाई",lines:["जो नर बड़ागांव में आवें, चिंतामणि का दर्शन पावें।","सकल मनोरथ पूरण होते, पाप-ताप सब धुलते धोते॥"],meaning:"जो भी प्राणी बड़ागांव त्रिलोक तीर्थ पर आकर चिंतामणि पारस प्रभु के दर्शन करता है, उसके समस्त मनोरथ सिद्ध होते हैं और पाप-ताप धुल जाते हैं।"},{number:"८",tag:"चौपाई",lines:["व्यापार में जो घाटा पावे, दर्शन कर धन-धान्य बढ़ावे।","संतान हीन को सुत मिल जाता, निर्बल जन बलवान कहाता॥"],meaning:"प्रभु के पावन दर्शन से सांसारिक बाधाएँ दूर होती हैं; निर्धन को धर्म-धन, दुर्बल को आत्मबल और गृहस्थ को सुख-शांति की प्राप्ति होती है।"},{number:"९",tag:"चौपाई",lines:["काल-सर्प का दोष नशावे, पारस प्रभु जब मन में ध्यावे।","असाध्य रोग तुरंत मिटावें, कृपा-सिंधु पारस कहलावे॥"],meaning:"कालसर्प दोष और ग्रहपीड़ा प्रभु स्मरण से शांत हो जाती है। करुणा के सागर पार्श्वनाथ प्रभु असाध्य रोगों को भी क्षण भर में दूर कर देते हैं।"},{number:"१०",tag:"चौपाई",lines:["पद्मावती माता संग बिराजें, धरणेन्द्र देव चरण में साजे।","अखंड दीप की ज्योति सुहानी, गूंजे मधुर जिनेंद्र की वाणी॥"],meaning:"प्रभु चरणों में नागराज धरणेन्द्र और पद्मावती माता शासन रक्षक के रूप में सुशोभित हैं। अखंड ज्योति जलती है और मधुर जिनवाणी की देशना गूँजती है।"},{number:"११",tag:"चौपाई",lines:["अभिषेक जल जो कोई छींटे, दुख-दारिद्र्य पल में बीटे।","अष्टद्रव्य से पूजा कीजे, जन्म सफल निज कर लीजे॥"],meaning:"प्रभु के अभिषेक का गंधोदक ग्रहण करने से दारिद्र्य और व्याधियाँ मिटती हैं। अष्टद्रव्य से पूजा-अर्चना कर भक्त अपना मनुष्य जन्म सफल बनाते हैं।"},{number:"१२",tag:"चौपाई",lines:["बड़ागांव अति पावन नगरी, मिटे जहाँ भक्तों की कगरी।","शांति-धारा जो कोई करावे, परम शांति निज घर में पावे॥"],meaning:"बड़ागांव परम पवित्र तीर्थ है जहाँ भक्तों के संकट मिटते हैं। शांतिधारा कराने वाले श्रावक के घर-परिवार में अलौकिक शांति और समृद्धि छा जाती है।"},{number:"१३",tag:"चौपाई",lines:["कमठ-विनाशक पारस स्वामी, घट-घट वासी अंतरयामी।","तीन लोक के नाथ कहावो, भटके नर को राह दिखावो॥"],meaning:"कमठ के उपसर्ग को क्षमा से शांत करने वाले अंतर्यामी पारस स्वामी तीनों लोकों के नाथ हैं; वे संसार में भटके प्राणियों को मुक्ति की सच्ची राह दिखाते हैं।"},{number:"१४",tag:"चौपाई",lines:["अहिंसा धर्म की ध्वजा उठाई, सत्य दया की जोत जलाई।","राग-द्वेष मद-मोह नसाया, केवलज्ञान प्रकाश जगाया॥"],meaning:"प्रभु ने अहिंसा, सत्य और दया की पावन ज्योति जलाई, राग-द्वेष और मोह को नष्ट कर आत्मिक केवलज्ञान का अनुपम प्रकाश फैलाया।"},{number:"१५",tag:"चौपाई",lines:["सम्मेद शिखर जा शिवपद पायो, सिद्धक्षेत्र जग को दिखलायो।","बड़ागांव में अतिशय भारी, नित-प्रति आवें नर और नारी॥"],meaning:"श्री सम्मेद शिखर जी से मोक्ष प्राप्त कर प्रभु सिद्धालय में विराजे। बड़ागांव में प्रभु का अद्भुत अतिशय जाग्रत है जहाँ प्रतिदिन अगणित श्रद्धालु आते हैं।"},{number:"१६",tag:"चौपाई",lines:["मेला लगे जहाँ भारी-भारी, जय-जयकार करे संसारी।","जो जन चालीसा चालीस दिन गावे, मनवांछित आनंद वो पावे॥"],meaning:"तीर्थ पर भव्य मेले आयोजित होते हैं और जय-जयकार गूँजती है। जो चालीस दिन तक इस चालीसा का पाठ करता है, वह इच्छित आत्मिक आनंद पाता है।"},{number:"१७",tag:"चौपाई",lines:["संकट मोचन पारस नाथ, रखो सदा सिर पर निज हाथ।","विद्या-बुद्धि का दान दीजिये, पावन सम्यक्त्व हृदय कीजिय॥"],meaning:"हे संकटमोचन पारस प्रभु! हमारे सिर पर सदा अपनी कृपा का हाथ रखिए, हमें विद्या, विवेक और विशुद्ध सम्यग्दर्शन का पावन दान दीजिए।"},{number:"१८",tag:"चौपाई",lines:["मोह-महामद नाश करो, आत्म-रस से हृदय भरो।","मैं अज्ञान शरण में आया, पारस प्रभु ने पार लगाया॥"],meaning:"हमारे मोह और अहंकार का नाश कर हृदय को आत्मरस से भर दीजिए। अज्ञानतावश मैं आपकी शरण में आया हूँ, हे प्रभु! मुझे भवसागर पार लगाइए।"},{number:"१९",tag:"चौपाई",lines:["दीन-हीन पर दया करो, ज्ञान-दीप उर में धरो।","घर-घर में सुख-शांति विराजे, पारस नाम सदा उर गाजे॥"],meaning:"हे दीनबंधु! हमारे हृदय में ज्ञान का दीपक प्रज्वलित कीजिए; घर-घर में सुख-शांति विराजे और अंतःकरण में सदा पार्श्वनाथ का नाम गूँजता रहे।"},{number:"२०",tag:"चौपाई",lines:["बड़ागांव त्रिलोक की जय, पारस प्रभु हरते जग भय।","चरण-कमल में ध्यान लगाऊँ, मुक्ति-वधु का वर बन जाऊँ॥"],meaning:"बड़ागांव त्रिलोक तीर्थ और पारस प्रभु की जय हो, जो संसार के समस्त भयों का नाश करते हैं। आपके चरण-कमलों का ध्यान कर मैं मोक्षपद को प्राप्त करूँ।"},{number:"२१",tag:"दोहा",lines:["बड़ागांव के पारस प्रभु, चिंतामणि अवतार।","जो जन चरणों में नमे, होवे बेड़ा पार॥"],meaning:"बड़ागांव के चिंतामणि पारस प्रभु के पावन चरणों में जो भी नतमस्तक होता है, उसका संसार-समुद्र से बेड़ा पार हो जाता है।"},{number:"२२",tag:"दोहा",lines:["त्रिलोक तीर्थ धाम में, गूंजे पारस नाम।","सब सुख संपति दीजिए, पूरण कीजे काम॥"],meaning:"त्रिलोक तीर्थ धाम में नित्य पार्श्वनाथ प्रभु का पावन नाम गूँजता है; प्रभु सभी को आत्मिक सुख-शांति दें और धर्म-कार्यों को पूर्ण करें।"},{number:"२३",tag:"जाप मंत्र",lines:["॥ मूल मंत्र एवं ध्यान ॥","ॐ ह्रीं श्री चिंतामणि पार्श्वनाथाय नमः।"],meaning:"त्रिलोक तीर्थ बड़ागांव के चिंतामणि पार्श्वनाथ भगवान के पावन चरणों में मेरा त्रिकाल नमन हो।"}]},"bahubali-chalisa":{id:"bahubali-chalisa",category:"chalisa",title:"श्री बाहुबली चालीसा",subtitle:"प्रथम कामदेव एवं मोक्षगामी भगवान बाहुबली (गोम्मटेश्वर) स्वामी चालीसा",type:"structured",verses:[{number:"१",tag:"दोहा",lines:["शीश नवा अरिहंत को, सिद्धन करूं प्रणाम।","बाहुबली प्रभु की कृपा, पूरण हो सब काम॥"],meaning:"अरिहंतों और सिद्धों को शीश नवाकर प्रणाम करता हूँ। प्रथम कामदेव भगवान बाहुबली स्वामी की कृपा से हमारे समस्त धर्म-कार्य निर्विघ्न संपन्न हों।"},{number:"२",tag:"दोहा",lines:["ऋषभदेव के लाड़ले, भरत-अनुज बलवान।","श्रवणबेलगोला मही, विराजे भगवान॥"],meaning:"भगवान ऋषभदेव के आत्मज, चक्रवर्ती भरत के अनुज और अतुल्य आत्मबल के धनी भगवान बाहुबली स्वामी श्रवणबेलगोला (कर्नाटक) के विन्ध्यगिरि पर विशाल प्रतिमा रूप में सुशोभित हैं।"},{number:"३",tag:"चौपाई",lines:["जय बाहुबली बल के धामा, कामदेव तुम अनुपम नामा।","पौरुष के प्रतिमान जिनेशा, काटो प्रभु जी सकल कलेशा॥"],meaning:"अपार आत्मबल और बाहुबल के धाम भगवान बाहुबली की जय हो! आप प्रथम कामदेव और पौरुष व त्याग के सर्वोच्च आदर्श हैं; हे प्रभु, हमारे समस्त सांसारिक क्लेशों को काटिए।"},{number:"४",tag:"चौपाई",lines:["पोदनपुर में राज सँभाला, न्याय नीति का दीप उझाला।","चक्ररत्न जब चक्रवर्ती पाया, छह खंडों पर राज जमाया॥"],meaning:"पोदनपुर के राजा के रूप में आपने धर्म और न्यायपूर्वक प्रजा का पालन किया। चक्रवर्ती भरत ने जब छह खण्डों को जीता और चक्ररत्न अयोध्या के द्वार पर रुक गया।"},{number:"५",tag:"चौपाई",lines:["भरत-बाहुबली युद्ध ठना जब, तीन युद्ध में जीते प्रभु तब।","दृष्टि-युद्ध में नयन न मोड़े, जल-युद्ध में जल-कण छोड़े॥"],meaning:"सेनाओं का संहार टालने हेतु दोनों भाइयों में दृष्टि-युद्ध, जल-युद्ध और मल्ल-युद्ध हुआ। दृष्टि-युद्ध और जल-युद्ध दोनों में बाहुबली स्वामी विजयी रहे।"},{number:"६",tag:"चौपाई",lines:["मल्ल-युद्ध में भरत उठाया, तब मन में वैराग्य जगाया।","यह संसार असार अनित्य, क्षणभंगुर सब राज प्रपञ्च॥"],meaning:"मल्ल-युद्ध में जब बाहुबली ने भरत को भुजाओं पर उठा लिया, तभी उनके मन में संसार की अनित्यता और इस नश्वर राजवैभव के प्रति वैराग्य जाग्रत हुआ।"},{number:"७",tag:"चौपाई",lines:["भरत को क्षमादान दे दीना, तजकर राज संन्यास लीना।","वन में जाकर खड़े हुवे प्रभु, कायोत्सर्ग मुद्रा साधे विभु॥"],meaning:"प्रभु ने भरत को सादर भूमि पर उतारकर क्षमा माँगी, सर्वस्व राज्य त्याग दिया और वन में जाकर दिगम्बर दीक्षा ले निश्चल कायोत्सर्ग ध्यान लगाया।"},{number:"८",tag:"चौपाई",lines:["एक वर्ष पर्यन्त तपस्या, अडिग रहे जैसे गिरि शृंगा।","देह-लता पर बेल चढ़ाई, सर्प-बिच्छू ने बांबी बनाई॥"],meaning:"एक वर्ष तक सुमेरु पर्वत के समान अडिग खड़े रहकर घोर तप किया। देह पर माधवी लताएँ लिपट गईं और चरणों के पास सर्पों ने बांबियाँ बना लीं।"},{number:"९",tag:"चौपाई",lines:["पक्षी बैठ घोंसला कीन्हा, प्रभु ने किंचित ध्यान न दीन्हा।","मान कषाय का लेश रहा जब, भरत नमन करने आये तब॥"],meaning:"जटाओं में पक्षियों ने घोंसले बना लिए किन्तु प्रभु आत्मलीन रहे। 'मैं भरत की भूमि पर खड़ा हूँ'—इस सूक्ष्म मान का चिंतन मिटाने हेतु भरत स्वयं वन्दन करने आए।"},{number:"१०",tag:"चौपाई",lines:["‘यह भूमि तो भरत की भाई’, भरत ने आ प्रभुता गाई।","जैसे ही अभिमान बिलाया, तत्क्षण केवलज्ञान उपाया॥"],meaning:"भरत चक्रवर्ती ने चरणों में गिरकर स्तुति की। अंतःकरण से सूक्ष्म मान का लेश गलते ही प्रभु को लोकालोक-प्रकाशी केवलज्ञान प्रगट हो गया।"},{number:"११",tag:"चौपाई",lines:["प्रथम मोक्षगामी कहलाये, सिद्धक्षेत्र शिवपद को पाये।","श्रवणबेलगोला के माहीं, चामुंडराय ने प्रतिमा कराई॥"],meaning:"इस अवसर्पिणी काल में भरतक्षेत्र से प्रथम मोक्षगामी बनकर प्रभु सिद्धालय पधारे। महासेनापति चामुण्डराय ने श्रवणबेलगोला में प्रभु की अनुपम पाषाण प्रतिमा प्रतिष्ठित कराई।"},{number:"१२",tag:"चौपाई",lines:["सत्तावन फुट मूरत सोहे, कोटि-कोटि भविकों को मोहे।","महामस्तकाभिषेक जब होवे, देव-इंद्र आ मस्तक धोवे॥"],meaning:"सत्तावन फुट ऊँची एकाश्म पाषाण प्रतिमा संसार के करोड़ों भव्य जीवों को विस्मित और मुग्ध करती है। प्रत्येक बारह वर्ष में यहाँ विश्वप्रसिद्ध महामस्तकाभिषेक होता है।"},{number:"१३",tag:"चौपाई",lines:["दूध दही केशर की धारा, अद्भुत दृश्य लगे जग सारा।","गोम्मटेश्वर प्रभु नाम तुम्हारा, पापी जन को भव से तारा॥"],meaning:"दूध, दधि, केसर और स्वर्ण कलशों से होता अभिषेक स्वर्गिक दृश्य प्रस्तुत करता है। हे गोम्मटेश्वर भगवान! आपने अगणित प्राणियों को संसार से पार उतारा है।"},{number:"१४",tag:"चौपाई",lines:["जो जन बाहुबली गुण गावे, अष्टसिद्धि नवनिधि घर पावे।","अहंकार का नाश करावें, समता रस उर में बरसावें॥"],meaning:"जो प्राणी बाहुबली के पावन गुणों का गान करता है, उसका अहंकार गल जाता है और उसके हृदय में परम समता रस की अमृत वर्षा होती है।"},{number:"१५",tag:"चौपाई",lines:["शत्रु मित्र सम भाव जगावें, आतम-विद्या सहज सिखावें।","त्याग तपस्या के अवतारी, जय बाहुबली प्रभु अविकारी॥"],meaning:"प्रभु शत्रु और मित्र में समभाव रखने की अनुपम आत्म-विद्या सिखाते हैं। त्याग, तपस्या और वैराग्य के साक्षात् अवतार अविकारी बाहुबली प्रभु की जय हो।"},{number:"१६",tag:"चौपाई",lines:["काम-क्रोध के नाशन हारे, भव-भव के संताप विडारे।","निर्भय पद के दाता स्वामी, नमो नमो प्रभु अंतरयामी॥"],meaning:"काम और क्रोध को नष्ट करने वाले प्रभु जन्म-मरण के संताप को मिटाते हैं। निर्भय मोक्ष पद के दाता अंतर्यामी प्रभु को मेरा बारम्बार नमन है।"},{number:"१७",tag:"चौपाई",lines:["जो नर चालीसा चित्त लावे, जनम-मरण का कष्ट नशावे।","बाहुबली प्रभु कृपा कीजे, सम्यग्ज्ञान हृदय में दीजे॥"],meaning:"जो प्राणी एकाग्र चित्त से इस चालीसा का पाठ करता है, उसके जन्म-मरण के कष्ट मिट जाते हैं। हे बाहुबली प्रभु! हम पर कृपा कर सम्यग्ज्ञान प्रदान कीजिए।"},{number:"१८",tag:"चौपाई",lines:["तन-बल मन-बल आत्म-बल, तुम सम बने हृदय निर्मल।","रोग-शोक सब दूर भगाओ, जीवन में सुख-शांति लाओ॥"],meaning:"प्रभु हमें शारीरिक, मानसिक और आत्मिक बल दें, जिससे हमारा हृदय निर्मल बने। हमारे समस्त रोग-शोक दूर कर जीवन में सुख-शांति लाइए।"},{number:"१९",tag:"चौपाई",lines:["गृहस्थ धर्म का मर्म सिखाया, श्रमण धर्म का रूप दिखाया।","त्याग बिना नहिं मुक्ति पावे, बाहुबली संदेश सुनावें॥"],meaning:"प्रभु ने पहले आदर्श गृहस्थ और फिर सर्वोच्च श्रमण दिगम्बर चर्या का आदर्श प्रस्तुत किया कि त्याग और वीतरागता के बिना मोक्ष संभव नहीं है।"},{number:"२०",tag:"चौपाई",lines:["विद्यासागर सम मुनि ध्यावें, कुंदकुंद प्रभु महिमा गावें।","बाहुबली भगवान की जय, निर्भय पद दे हरहु भय॥"],meaning:"आचार्य कुंदकुंद और आचार्य विद्यासागर जैसे महामुनिराज प्रभु के पावन चरणों का ध्यान करते हैं। भगवान बाहुबली की सदा जय हो, जो भय हरकर निर्भय पद देते हैं।"},{number:"२१",tag:"दोहा",lines:["बाहुबली भगवान को, जो ध्यावे दिन-रैन।","अहंकार सब दूर हो, पावे शाश्वत चैन॥"],meaning:"भगवान बाहुबली का जो दिन-रात ध्यान करता है, उसका समस्त मान-अहंकार नष्ट हो जाता है और वह शाश्वत आत्मिक आनंद प्राप्त करता है।"},{number:"२२",tag:"दोहा",lines:["गोम्मटेश्वर जिनराज नमो, पूरण कीजे काज।","आत्म-ज्ञान प्रकाश दे, राखो मेरी लाज॥"],meaning:"हे गोम्मटेश्वर भगवान! आपको मेरा नमन है, हमारे धर्म-कार्यों को पूर्ण कीजिए, आत्मज्ञान का प्रकाश दीजिए और हमारी आध्यात्मिक प्रतिष्ठा की रक्षा कीजिए।"},{number:"२३",tag:"जाप मंत्र",lines:["॥ मूल मंत्र एवं ध्यान ॥","ॐ ह्रीं श्री बाहुबली स्वामिने नमः।"],meaning:"प्रथम कामदेव, तपमूर्ति देवाधिदेव भगवान श्री बाहुबली स्वामी (गोम्मटेश्वर) के पावन चरणों में मेरा त्रिकाल नमन हो।"}]},"padmavati-chalisa":{id:"padmavati-chalisa",category:"chalisa",title:"श्री पद्मावती चालीसा",subtitle:"भगवान पार्श्वनाथ की शासनदेवी पद्मावती माता की भक्ति-स्तुति",type:"structured",verses:[{number:"१",tag:"दोहा",lines:["पार्श्वनाथ प्रभु के चरण, ध्याऊँ बारंबार।","पद्मावती माता करहु, नैया भव से पार॥"],meaning:"तेईसवें तीर्थंकर भगवान श्री पार्श्वनाथ के पावन चरणों का बारम्बार ध्यान करता हूँ। हे जिनशासन संरक्षिका पद्मावती माता! धर्म-मार्ग पर हमारी रक्षा करते हुए भवसागर से पार उतारिए।"},{number:"२",tag:"दोहा",lines:["धरणेन्द्र की पटरानी, शासनदेवी नाम।","शरणागत की रक्षा कर, पूरण कीजे काम॥"],meaning:"नागराज धरणेन्द्र की पटरानी और भगवान पार्श्वनाथ की पावन शासनदेवी पद्मावती माता अपने शरणागत भक्तों के धर्म-कार्यों की रक्षा कर उनके मनोरथ सिद्ध करती हैं।"},{number:"३",tag:"चौपाई",lines:["जय जय पद्मावती वरदानी, पार्श्वनाथ की सेविका मानी।","कमठ-उपसर्ग निवारण कीन्हा, पारस प्रभु को आसन दीन्हा॥"],meaning:"वरदायिनी पद्मावती माता की जय हो, जो पार्श्वनाथ प्रभु की परम भक्त हैं। कमठ के घोर उपसर्ग के समय धरणेन्द्र संग आकर प्रभु के चरणों में कमल का आसन सजाया।"},{number:"४",tag:"चौपाई",lines:["कमल नयन पद्मासन साजे, मुकुट मनोहर शीश विराजे।","चार भुजायें अतिशय सोहें, अंकुश पाश फल मन मोहें॥"],meaning:"कमल समान नयन, पद्मासन मुद्रा और मस्तक पर मनोहर मुकुट सुशोभित है। आपकी चारों भुजाओं में पाश, अंकुश, फल और वरद मुद्रा शोभायमान हैं।"},{number:"५",tag:"चौपाई",lines:["स्वर्ण वर्ण तन ज्योति अपारा, कोटि चन्द्र सम तेज पसारा।","सर्प-छत्र मस्तक पर सोहे, पद्मावती छवि जग को मोहे॥"],meaning:"स्वर्ण के समान दमकता दिव्य शरीर करोड़ों चंद्रमाओं की शीतल कांति बिखेरता है। मस्तक पर सर्प-फणों का छत्र सुशोभित है जो त्रिभुवन के मन को मोह लेता है।"},{number:"६",tag:"चौपाई",lines:["जो ध्यावे पद्मावती माता, सुख-संपति वैभव सब पाता।","विपदा-संकट सब टल जावें, मात कृपा जब घर में पावें॥"],meaning:"जो भी श्रावक श्रद्धा से पद्मावती माता का स्मरण करता है, उसे धर्म और शांति की प्राप्ति होती है। माता की अनुकम्पा से समस्त बाधाएँ और विघ्न दूर हो जाते हैं।"},{number:"७",tag:"चौपाई",lines:["दुष्ट-ग्रहों की पीड़ा भागे, शुभ मंगल का दीपक जागे।","व्यापार में लाभ करावे, निर्धन को धनवान बनावे॥"],meaning:"अनिष्ट ग्रहों की पीड़ा शांत होती है और घर-आँगन में मंगल का प्रकाश होता है। धार्मिक पुरुषार्थ करने वालों को सुख, शांति और समृद्धि मिलती है।"},{number:"८",tag:"चौपाई",lines:["संतान हीन को गोदी भारे, दुखियों के सब संकट टारे।","विद्या बुद्धि यश की दाता, जय जय पद्मावती माता॥"],meaning:"माता दुखियों के संकट हरती हैं और सन्मार्ग पर चलने वालों को विद्या, बुद्धि और यश प्रदान करती हैं। हे मंगलमयी पद्मावती माता! आपकी सदा जय हो।"},{number:"९",tag:"चौपाई",lines:["अहिच्छत्र तिजारा धाम, गूंजे मात तुम्हारा नाम।","सम्मेद शिखर जी में बिराजें, घंटा-घड़ियाल मधुर बाजे॥"],meaning:"अहिच्छत्र, तिजारा, हम्बूज और श्री सम्मेद शिखर जी जैसे पावन तीर्थों पर माता की पावन उपस्थिति है, जहाँ मधुर घंटा-घड़ियालों के बीच जिनभक्ति होती है।"},{number:"१०",tag:"चौपाई",lines:["अष्टगंध से पूजा कीजे, लाल पुष्प माता को दीजे।","धूप दीप नैवेद्य सजावें, आरती मंगल भाव सुनावें॥"],meaning:"अष्टगंध, धूप, दीप और नैवेद्य सजाकर वीतराग पार्श्वनाथ प्रभु की पूजा उपरांत शासनदेवी पद्मावती का सत्कार व मंगल आरती की जाती है।"},{number:"११",tag:"चौपाई",lines:["काल-सर्प का दोष नशाती, जीवन में सुख-शांति लाती।","भूत-प्रेत पिशाच डरावें, पद्मावती नाम से जावें॥"],meaning:"माता के स्मरण से कालसर्प दोष, विष-दोष और समस्त प्रकार के भय व उपद्रव शांत होते हैं तथा जीवन में आत्मिक शांति का संचार होता है।"},{number:"१२",tag:"चौपाई",lines:["रोग-शोक सब दूर भगावे, जो माता की शरण में आवे।","भक्त-वत्सला दया की मूरत, शांत सौम्य कल्याणी सूरत॥"],meaning:"जो माता की शरण में आता है, उसके शारीरिक व मानसिक रोग-शोक मिटते हैं। आप दया की साक्षात् मूरत और परम सौम्य व कल्याणी स्वरूप वाली हैं।"},{number:"१३",tag:"चौपाई",lines:["पार्श्वनाथ के संग विराजो, जिनशासन की शोभा साजो।","सम्यक्त्व रक्षा मात कराती, मिथ्यामत का नाश कराती॥"],meaning:"पार्श्वनाथ प्रभु के चरण-कमलों में रहकर आप जिनशासन की शोभा बढ़ाती हैं। आप भक्तों के सम्यग्दर्शन की रक्षा कर मिथ्यात्व के अंधकार को नष्ट करती हैं।"},{number:"१४",tag:"चौपाई",lines:["जो चालीस दिन पाठ करावे, मात कृपा निज घर में पावे।","पुत्र-पौत्र सुख संपति बाढ़े, विघ्न भागें सब दुःख काढ़े॥"],meaning:"जो नियमपूर्वक चालीस दिनों तक इस पावन चालीसा का पाठ करता है, उसके घर में धर्म-वृद्धि होती है और समस्त विघ्न-बाधाएँ स्वतः समाप्त हो जाती हैं।"},{number:"१५",tag:"चौपाई",lines:["मैं अज्ञान दास हूँ तेरा, काटो जनम-मरण का फेरा।","भूल-चूक सब क्षमा करीजे, अपनी पावन शरण में लीजे॥"],meaning:"हे माता! मैं अज्ञानी हूँ, मेरी सभी भूलों को क्षमा कर मुझे अपनी वात्सल्यमयी छत्रछाया में लीजिए ताकि मैं धर्ममार्ग पर चलकर भवसागर पार कर सकूँ।"},{number:"१६",tag:"चौपाई",lines:["सच्चे मन से जो कोई ध्यावे, जीवन में आनंद बढ़ावे।","घर में अन्न-वस्त्र भर दीजे, सुख-संतोष का सागर कीजे॥"],meaning:"सच्चे हृदय से माता का ध्यान करने पर जीवन में धर्म का आनंद बढ़ता है। घर-परिवार में संतोष, शांति और धर्ममय वातावरण का वास होता है।"},{number:"१७",tag:"चौपाई",lines:["जयति जयति पद्मावती देवी, सुर-नर मुनिजन चरणन सेवी।","धरणेन्द्र संग मंगलकारी, रक्षा करतीं सदा हमारी॥"],meaning:"देव, मनुष्य और श्रद्धालु जिनकी वन्दना करते हैं, वे धरणेन्द्र संग विराजने वाली पद्मावती देवी सदा जिनभक्तों की रक्षा करती हैं।"},{number:"१८",tag:"चौपाई",lines:["अंधकार अज्ञान नशाओ, ज्ञान-दीप उर बीच जलाओ।","धर्म-कर्म में मन को लगाओ, सन्मार्ग की राह दिखाओ॥"],meaning:"हे माता! हमारे अज्ञान को मिटाकर हृदय में सम्यग्ज्ञान का दीप जलाइए और हमारे मन को सदा धर्म-ध्यान एवं वीतराग सन्मार्ग में लगाए रखिए।"},{number:"१९",tag:"चौपाई",lines:["पारस प्रभु की भक्ति पाऊँ, जनम-जनम गुण तेरे गाऊँ।","ह्रीं क्लीं ब्लूं मन्त्र सुहावन, जपत मिटे सब पाप सुपावन॥"],meaning:"मुझे सदा भगवान पार्श्वनाथ की निष्काम भक्ति मिले। आपका पावन बीजाक्षर मंत्र जपने से पापों का क्षय और अंतःकरण की शुद्धि होती है।"},{number:"२०",tag:"चौपाई",lines:["निसिदिन मात तुम्हारा ध्यान, पावें सुख-वैभव निर्वान।","पद्मावती चालीसा गावें, भव-सागर से पार लगावें॥"],meaning:"जो नित्य माता का स्मरण करते हुए पार्श्वनाथ प्रभु की आराधना करते हैं, वे सांसारिक संतापों से छूटकर अंत में मोक्ष सुख को प्राप्त करते हैं।"},{number:"२१",tag:"दोहा",lines:["पद्मावती माता कृपा, कीजे सदा सहाय।","संकट-विपदा सब टलें, मंगल मोद बढ़ाय॥"],meaning:"हे पद्मावती माता! हम पर अपनी कृपा बनाए रखिए, जिससे हमारे समस्त संकट टलें और जीवन में धर्म, शांति और आनंद की वृद्धि हो।"},{number:"२२",tag:"दोहा",lines:["पार्श्वनाथ के चरण में, पद्मावती का वास।","‘जिनवाणी’ उर में रहे, पूरण हो अभिलाष॥"],meaning:"प्रभु पार्श्वनाथ के चरणों में माता पद्मावती सदा सेवा में लीन रहती हैं। हमारे हृदय में जिनवाणी माता का वास रहे और हमारी मोक्षमार्गी अभिलाषा पूर्ण हो।"},{number:"२३",tag:"जाप मंत्र",lines:["॥ मूल मंत्र एवं ध्यान ॥","ॐ ह्रीं श्रीं क्लीं ब्लूं पद्मावती देव्यै नमः।"],meaning:"भगवान पार्श्वनाथ की शासन संरक्षिका देवी पद्मावती माता के चरणों में मेरा सादर नमन हो।"}]},"saraswati-chalisa":{id:"saraswati-chalisa",category:"chalisa",title:"श्री जिनवाणी / सरस्वती चालीसा",subtitle:"द्वादशांग जिनवाणी माता (श्रुतदेवी सरस्वती) की पावन भक्ति-स्तुति",type:"structured",verses:[{number:"१",tag:"दोहा",lines:["ज्ञानमयी जिन भारती, वंदूँ बारंबार।","बुद्धि विशुद्ध प्रदान कर, मेटहु मोहांधकार॥"],meaning:"ज्ञानमयी जिनवाणी माता (सरस्वती) के पावन चरणों में मैं बारम्बार वन्दन करता हूँ। हे माँ! हमें निर्मल सम्यग्बुद्धि प्रदान कीजिए और अज्ञान रूपी घने अंधकार को नष्ट कीजिए।"},{number:"२",tag:"दोहा",lines:["द्वादशांग जिनवाणी माता, भव-सागर से तार।","अक्षर-अक्षर मोक्षमय, सुख की खान अपार॥"],meaning:"ग्यारह अंग और चौदह पूर्व रूप द्वादशांग जिनवाणी माता संसार-समुद्र से पार उतारने वाली नौका है। जिसका एक-एक अक्षर मोक्षमार्ग को प्रकाशित करने वाला और आत्मसुख का अक्षय भण्डार है।"},{number:"३",tag:"चौपाई",lines:["जय जिनवाणी ज्ञान की खानी, तीन लोक में अमृत वाणी।","अरिहंतों के मुख से निकली, गणधरों ने उर में धर ली॥"],meaning:"ज्ञान की खान जिनवाणी माता की जय हो! यह तीनों लोकों में अमृतमयी वाणी है जो तीर्थंकर अरिहंतों की दिव्यध्वनि से खिरी और जिसे गणधर देवों ने अपने हृदय में ग्रंथित किया।"},{number:"४",tag:"चौपाई",lines:["आचार्य परम्परा से आई, जग को मुक्ति-राह दिखाई।","द्वादशांग जिनवाणी माता, तू है भव-जल तारण-त्राता॥"],meaning:"आचार्यों की अविच्छिन्न श्रुत-परम्परा द्वारा यह पावन ज्ञान हम तक पहुँचा और इसने संसार को मुक्ति का मार्ग दिखाया। हे जिनवाणी माँ! तू ही भवसागर से पार लगाने वाली सच्ची त्राता है।"},{number:"५",tag:"चौपाई",lines:["प्रथमानुयोग चरित सिखलावे, पुण्य-पाप का भेद बतावे।","करणानुयोग लोक-गति गाये, कर्म-प्रकृति की चाल दिखाये॥"],meaning:"प्रथमानुयोग तीर्थंकरों और महापुरुषों के चरित्र द्वारा पुण्य-पाप का फल समझाता है, और करणानुयोग तीनों लोकों की रचना तथा कर्म-प्रकृतियों की सूक्ष्म गति दर्शाता है।"},{number:"६",tag:"चौपाई",lines:["चरणानुयोग आचार सिखावे, श्रावक-मुनि का व्रत बतलावे।","द्रव्यानुयोग तत्व समझाये, आत्मा का निज रूप लखाये॥"],meaning:"चरणानुयोग मुनियों और श्रावकों के सदाचार व व्रतों का विधान करता है, और द्रव्यानुयोग छह द्रव्यों व सात तत्त्वों का भेद समझाकर शुद्धात्मा का साक्षात्कार कराता है।"},{number:"७",tag:"चौपाई",lines:["षट्द्रव्यों का ज्ञान करावे, सात तत्व का भेद बतावे।","जीव-अजीव की भिन्नता गाये, नय प्रमाण की बात समझाये॥"],meaning:"जीव, अजीव, धर्म, अधर्म, आकाश, काल—इन छह द्रव्यों का ज्ञान कराती है; जीव और देह की भिन्नता दर्शाती है तथा नय व प्रमाण के द्वारा वस्तु के यथार्थ स्वरूप को समझाती है।"},{number:"८",tag:"चौपाई",lines:["स्याद्वाद की ध्वजा उड़ाई, अनेकांत की जोत जलाई।","कुंदकुंद ने समयसार लिखा, अमृतचंद्र ने टीका सिखा॥"],meaning:"स्याद्वाद की पावन ध्वजा फहराकर अनेकांत की ज्योति प्रज्वलित की। आचार्य कुंदकुंद देव ने समयसार आदि परमागम रचे और आचार्य अमृतचंद्र ने आत्मख्याति टीका से उनका मर्म समझाया।"},{number:"९",tag:"चौपाई",lines:["षट्खण्डागम धवला ग्रंथ, खोल दिया शिव-सुख का पंथ।","तत्त्वार्थ सूत्र उमास्वामी गायो, मोक्षमार्ग जग को समझायो॥"],meaning:"षट्खंडागम और धवला जैसे महान ग्रंथों ने कर्म-सिद्धांत का रहस्य खोला। आचार्य उमास्वामी ने 'तत्त्वार्थसूत्र' रचकर 'सम्यग्दर्शनज्ञानचारित्राणि मोक्षमार्गः' का अमर सूत्र दिया।"},{number:"१०",tag:"चौपाई",lines:["जो जिनवाणी को नित ध्यावे, सम्यग्दर्शन पावन पावे।","मिथ्या ज्ञान-अंधेरा भागे, केवलज्ञान-सूर्य उर जागे॥"],meaning:"जो नित्य जिनवाणी का स्वाध्याय और मनन करता है, उसे निर्मल सम्यग्दर्शन प्राप्त होता है; उसके मिथ्यात्व का अंधकार दूर होता है और हृदय में ज्ञान-सूर्य उदित होता है।"},{number:"११",tag:"चौपाई",lines:["अक्षर-अक्षर में अमृत धारा, भव-आतप से तारे सारा।","श्रुतपंचमी पर्व सुहावन, जिनवाणी पूजा अति पावन॥"],meaning:"जिनवाणी के प्रत्येक अक्षर में अमृत की धारा बहती है जो संसार के त्रिविध तापों को शांत करती है। श्रुतपंचमी के पावन पर्व पर सम्पूर्ण जैन समाज जिनवाणी की महापूजा करता है।"},{number:"१२",tag:"चौपाई",lines:["शास्त्र दान जो नर देवे, स्वर्ग-मोक्ष पदवी सो लेवे।","अंग-पूर्व का ज्ञान विशाला, तू ही माँ भव-तारनहारा॥"],meaning:"जो जिनवाणी शास्त्रों का मुद्रण, संरक्षण और ज्ञान-दान कराता है, वह स्वर्ग और मोक्ष की पदवी पाता है। ग्यारह अंग और चौदह पूर्व का ज्ञान धारण करने वाली माँ भवतारणहारी है।"},{number:"१३",tag:"चौपाई",lines:["काव्य-व्याकरण न्याय सिखावे, वीतरागता उर उपजावे।","राग-द्वेष मद-मोह नसावे, शांत सुधा रस खूब बहावे॥"],meaning:"न्याय, व्याकरण और साहित्य का यथार्थ ज्ञान देकर यह वाणी अंतःकरण में वीतरागता प्रगट करती है, राग-द्वेष व मोह का नाश कर शांत रस की अमृतधारा बहाती है।"},{number:"१४",tag:"चौपाई",lines:["विद्या-बुद्धि का दान तू देती, मंदबुद्धि को ज्ञानी करती।","वाक्-सिद्धि प्रतिभा चमकावे, जन-मन में आनंद बढ़ावे॥"],meaning:"माँ जिनवाणी मंदबुद्धि को भी प्रखर ज्ञानी बनाती है और वाक्-सिद्धि व आत्मिक प्रतिभा को चमकाती है, जिससे अंतःकरण में परमानंद की वृद्धि होती है।"},{number:"१५",tag:"चौपाई",lines:["जो चालीसा प्रेम से गावे, सकल मनोरथ पूर्ण पावे।","मेरी मति को निर्मल कीजे, सम्यग्ज्ञान हृदय में दीजे॥"],meaning:"जो भी श्रद्धापूर्वक इस चालीसा का पाठ करता है, उसके ज्ञान-सम्बन्धी सभी मनोरथ पूर्ण होते हैं। हे माँ! मेरी बुद्धि को निर्मल कीजिए और हृदय में सम्यग्ज्ञान का प्रकाश भर दीजिए।"},{number:"१६",tag:"चौपाई",lines:["सत्य-अहिंसा धर्म सिखाओ, आतम-विद्या सहज पढ़ाओ।","जिनवाणी सम और न कोई, भव-दुख मेटन हारी सोई॥"],meaning:"सत्य और अहिंसा का पाठ पढ़ाने वाली जिनवाणी के समान संसार में अन्य कोई हितैषी नहीं है, जो जीवों के जन्म-मरण के अनंत दुःखों को मिटाने में समर्थ हो।"},{number:"१७",tag:"चौपाई",lines:["अक्षर-मात्रा बिंदु विहीना, क्षमा करो माँ करुणा-लीना।","चरण कमल में शीश नवाऊँ, नित्य प्रति माँ के गुण गाऊँ॥"],meaning:"उच्चारण अथवा लेखन में अक्षर, मात्रा या पद की जो भी भूल हुई हो, हे करुणामयी माँ! उसे क्षमा कीजिए। आपके चरण-कमलों में शीश नवाकर नित्य आपके गुण गाता हूँ।"},{number:"१८",tag:"चौपाई",lines:["घर-घर में जिनवाणी विराजे, स्वाध्याय का नगाड़ा बाजे।","शास्त्र-सभा में अमृत बरसे, भविक जन प्रभु दर्शन तरसे॥"],meaning:"प्रत्येक जैन गृह में जिनवाणी की प्रतिष्ठा हो और स्वाध्याय की गूँज हो। शास्त्र-सभाओं में जिनवाणी रूपी अमृत बरसे और भव्य जीव वीतराग धर्म को आत्मसात् करें।"},{number:"१९",tag:"चौपाई",lines:["पाप-मलिनता सब हर लीजे, वीतराग-पद मुझको दीजे।","निसिदिन शरण तुम्हारी माँगी, बन जाऊँ मैं सच्चा त्यागी॥"],meaning:"हमारी समस्त पाप-मलिनता को धोकर हमें वीतराग पद प्रदान कीजिए। हम नित्य आपकी शरण माँगते हैं ताकि संसार के भोगों से विरक्त होकर सच्चे त्यागी बन सकें।"},{number:"२०",tag:"चौपाई",lines:["द्वादशांग जिनवाणी माई, तेरी महिमा जग में छाई।","चालीसा चालीस दिन गावे, निश्चय मुक्ति-महल को पावे॥"],meaning:"द्वादशांग जिनवाणी माता की महिमा तीनों लोकों में व्याप्त है। जो चालीस दिन तक इस चालीसा का पाठ करता है, वह नियम से मोक्ष महल की प्राप्ति करता है।"},{number:"२१",tag:"दोहा",lines:["जिनवाणी माता नमो, ज्ञान-सिंधु सुख-धाम।","चरण कमल में शीश धर, पूरण कीजे काम॥"],meaning:"ज्ञान के सिंधु और सुख के धाम जिनवाणी माता को मेरा नमन है। आपके चरण-कमलों में शीश धरकर प्रार्थना है कि हमारे आत्म-कल्याण के कार्यों को सिद्ध कीजिए।"},{number:"२२",tag:"दोहा",lines:["जा वाणी के ज्ञान ते, सूझे लोकालोक।","सो वाणी मस्तक धरूँ, सदा देत हूँ ढोक॥"],meaning:"जिस जिनवाणी माता के ज्ञान से सम्पूर्ण लोकालोक का यथार्थ स्वरूप दर्पण के समान प्रत्यक्ष दिखाई देता है, उस पावन जिनवाणी को मैं मस्तक पर धारण कर सदा नमस्कार करता हूँ।"},{number:"२३",tag:"जाप मंत्र",lines:["॥ मूल मंत्र एवं ध्यान ॥","ॐ ह्रीं श्रीं क्लीं जिनवाण्यै नमः।"],meaning:"द्वादशांग जिनवाणी माता (श्रुतदेवी सरस्वती) के पावन चरणों में मेरा त्रिकाल नमन हो।"}]},"vidyasagar-chalisa":{id:"vidyasagar-chalisa",category:"chalisa",title:"आचार्य श्री विद्यासागर चालीसा",subtitle:"संत शिरोमणि युगप्रवर्तक आचार्य श्री विद्यासागर जी महाराज की भक्ति-स्तुति",type:"structured",verses:[{number:"१",tag:"दोहा",lines:["ज्ञान-सिंधु समता-धनी, वीतराग अवतार।","विद्यासागर गुरु नमो, वंदन बारंबार॥"],meaning:"ज्ञान के अगाध सागर, समता भाव के अनुपम स्वामी और वीतरागता के साक्षात् अवतार प्रातःस्मरणीय आचार्य श्री विद्यासागर जी महाराज के पावन चरणों में मेरा बारंबार कोटि-कोटि वंदन है।"},{number:"२",tag:"दोहा",lines:["ज्ञानसागर गुरु के शिष्य, कुंदकुंद के रूप।","कलिकाल में मुनिराज सम, वीतरागता भूप॥"],meaning:"चारित्र चक्रवर्ती पूज्य गुरुवर आचार्य श्री ज्ञानसागर जी के अनन्य पट्टशिष्य, साक्षात् आचार्य कुंदकुंद स्वामी के प्रतिरूप तथा इस पंचम काल में वीतरागी दिगम्बर मुनि चर्या के अद्वितीय सम्राट गुरुवर को हमारा नमन है।"},{number:"३",tag:"चौपाई",lines:["जय विद्यासागर मुनिराजा, पूर्ण करो सेवक के काजा।","सद्लगगा पावन जन्म स्थान, मल्लप्पा श्रीमंत सुजान॥"],meaning:"हे तपोमूर्ति मुनिराज श्री विद्यासागर जी महाराज! आपकी जय हो, आप अपने इस सेवक के आत्म-कल्याण रूपी कार्य सिद्ध करें। कर्नाटक का सद्लगा गाँव आपका पावन जन्म स्थल है, जहाँ धर्मात्मा श्रेष्ठ श्रावक श्री मल्लप्पा जी आपके पिता थे।"},{number:"४",tag:"चौपाई",lines:["श्रीमती मात की कोख सुहाई, विद्याधर ने महिमा पाई।","बचपन से वैराग्य समाया, खेल-कूद सब छोड़ छुड़ाया॥"],meaning:"परम विदुषी व धर्मपरायणा माता श्रीमती जी की पावन कुक्षी को आपने अलंकृत किया और 'विद्याधर' नाम पाकर बचपन से ही जगत को महिमामंडित किया। बाल्यावस्था से ही सांसारिक खेल-कूद छोड़कर आपके अंतर में वैराग्य प्रस्फुटित हो उठा था।"},{number:"५",tag:"चौपाई",lines:["अजमेर में मुनि दीक्षा लीनी, ज्ञानसागर ने कृपा कीनी।","कठिन परीषह सब सह डारे, तप-बल से निज कर्म विदारे॥"],meaning:"राजस्थान की पावन अजमेर धरा पर पूज्य आचार्य ज्ञानसागर जी महाराज की महती अनुकंपा से आपने दिगम्बर मुनि दीक्षा अंगीकार की। आपने २२ परीषहों को सहज भाव से सहन कर घोर तपस्या के बल से पूर्वोपार्जित कर्मों का क्षय किया।"},{number:"६",tag:"चौपाई",lines:["निशिदिन आत्म-ध्यान लवलीन, वीतराग समता आधीन।","मौन साधना व्रत अनुकूला, भू-शयन कंटक सम फूला॥"],meaning:"आप रात-दिन अंतर्मुखी होकर आत्म-ध्यान में लीन रहते हैं और परम वीतराग समता रस का पान करते हैं। मौन साधना, कठोर व्रतों का निर्दोष पालन और कांटों-पत्थरों से युक्त कठोर भूमि पर भी फूलों के समान समता भाव से शयन करते हैं।"},{number:"७",tag:"चौपाई",lines:["एक बार ही भोजन पाते, अल्पाहार जल तृप्त कराते।","पैदल चले सकल भू-मंडल, तीर्थों का कीन्हा उद्धार॥"],meaning:"आप चौबीस घंटे में केवल एक बार खड़े होकर करपात्र में अल्पाहार व चुल्लू भर जल ग्रहण कर संतुष्ट रहते हैं। बिना किसी वाहन के पद-विहार करते हुए आपने सम्पूर्ण भारत भूमि को पावन किया और प्राचीन उपेक्षित तीर्थों का जीर्णोद्धार कराया।"},{number:"८",tag:"चौपाई",lines:["कुंडलपुर में बड़े बाबा का, मंदिर भव्य बनवायो न्यारा।","नेमावर में नर्मदा तीरे, त्रिकाल चौबीसी मंदिर धीरे॥"],meaning:"कुंडलपुर महातीर्थ में देवाधिदेव बड़े बाबा श्री आदिनाथ भगवान का विशाल व अनुपम पाषाण मंदिर आपकी पावन प्रेरणा से निर्मित हुआ। इसी प्रकार नर्मदा तट पर स्थित नेमावर सिद्धोदय सिद्धक्षेत्र में त्रिकाल चौबीसी जिनालय का भव्य निर्माण कराया।"},{number:"९",tag:"चौपाई",lines:["हथकरघा का मार्ग दिखाया, मूक माटी महाकाव्य बनाया।","गौ-शालाएं खूब खुलवाई, भारत की संस्कृति जगाई॥"],meaning:"आपने अहिंसक हथकरघा (अहिंसा वस्त्र) को जन-जन तक पहुँचाकर स्वावलंबन का मार्ग प्रशस्त किया तथा 'मूक माटी' जैसे अमर दार्शनिक महाकाव्य की रचना की। विशाल गौशालाएँ (दयोदय) स्थापित कराकर मूक पशुओं की रक्षा की और भारतीय संस्कृति का पुनरुद्धार किया।"},{number:"१०",tag:"चौपाई",lines:["प्रतिभास्थली संस्कार सिखाये, नारी शक्ति के मान बढ़ाये।","युवा वर्ग को दिशा दिखाई, संयम की महत्ता समझाई॥"],meaning:"कन्याओं को संस्कारयुक्त उच्च शिक्षा देने हेतु 'प्रतिभास्थली' विद्यालयों की स्थापना कर नारी शक्ति का गौरव बढ़ाया। भटके हुए युवा वर्ग को सदाचार, ब्रह्मचर्य और संयम की महत्ता समझाकर धर्म के सच्चे मार्ग पर अग्रसर किया।"},{number:"११",tag:"चौपाई",lines:["कुंदकुंद की वाणी गाई, जन-जन में समता फैलाई।","आचार्य पद की शोभा बढ़ाई, संघ बड़ा अनुशासन छाई॥"],meaning:"भगवान कुंदकुंद स्वामी के समयसार व अध्यात्म रस को सरल भाषा में प्रवाहित कर जन-जन में समता व शांति का संचार किया। आचार्य पद को अपने तपोबल से अलंकृत किया और आपके विशाल मुनि संघ में अद्वितीय अनुशासन व चारित्र की आभा फैली।"},{number:"१२",tag:"चौपाई",lines:["मुनि-आर्यिका संघ अपारा, सब पर गुरुवर कृपा-धारा।","डोंगरगढ़ चंद्रगिरि माहीं, सल्लेखना कीन्ह मन माहीं॥"],meaning:"सैकड़ों मुनि, ऐलक, क्षुल्लक और आर्यिकाओं से युक्त आपके विशाल संघ पर आपकी वात्सल्यमयी अमृत वर्षा सदैव रही। छत्तीसगढ़ के डोंगरगढ़ स्थित पावन चंद्रगिरि तीर्थ पर आपने अपने नश्वर शरीर को त्यागने हेतु समाधिमरण (सल्लेखना) का पावन संकल्प लिया।"},{number:"१३",tag:"चौपाई",lines:["तीन दिवस का अनशन कीन्हा, समाधिमरण सहज रस लीना।","देवलोक सिधारे स्वामी, जय विद्यासागर अंतरयामी॥"],meaning:"अंतिम समय में आपने तीन दिनों तक पूर्ण आहार-जल का त्याग कर अखंड आत्म-लीनता के साथ समाधिमरण रूपी महाव्रत सिद्ध किया। शांत भाव से देह त्याग कर आप देवलोक पधारे; हे अंतर्यामी विद्यासागर स्वामी! आपकी जय-जयकार हो।"},{number:"१४",tag:"चौपाई",lines:["जो जन गुरुवर को नित ध्यावे, जीवन में संयम सुख पावे।","काम-क्रोध मद-मोह विनाशी, विद्यासागर ज्ञान-प्रकाशी॥"],meaning:"जो भी भव्य प्राणी गुरुवर श्री विद्यासागर जी का नित्य स्मरण व ध्यान करता है, उसके जीवन में संयम, शील और शांति का प्रादुर्भाव होता है। आप काम, क्रोध, मान, माया और लोभ के संहारक तथा केवलज्ञान ज्योति के प्रकाशक हैं।"},{number:"१५",tag:"चौपाई",lines:["गुरुवर की मूरत उर धारी, संकट कटे विपत्ति भारी।","रोग-दोष सब दूर नसावें, गुरु-चरणों में जो सिर नावें॥"],meaning:"जिसने भी गुरुवर की शांत, वीतरागी मुद्रा को अपने हृदय में बसा लिया, उसके जीवन के बड़े से बड़े संकट और विपदाएँ क्षण भर में कट जाती हैं। जो गुरुवर के चरणों में शीश झुकाता है, उसके शारीरिक व मानसिक सभी रोग-दोष शांत हो जाते हैं।"},{number:"१६",tag:"चौपाई",lines:["विद्या बुद्धि विवेक बढ़ावें, आतम-विद्या सहज सिखावें।","राष्ट्र-संत जग में कहलाये, प्राणी मात्र पे दया लखाये॥"],meaning:"आप भक्तों की विद्या, बुद्धि और विवेक में वृद्धि करते हैं तथा आत्म-अनुभव की सच्ची विद्या सहज सिखाते हैं। आप समूचे राष्ट्र के गौरव 'राष्ट्र-संत' कहलाए और समस्त जीव-जंतुओं के प्रति करुणा व अहिंसा की पावन प्रेरणा दी।"},{number:"१७",tag:"चौपाई",lines:["जो चालीसा चालीस दिन गावे, गुरु कृपा से सुख सब पावे।","पुत्र-पौत्र संपति घर आवे, विघ्न-बाधा सब मिट जावे॥"],meaning:"जो भक्त चालीस दिनों तक पूर्ण निष्ठा व भक्ति से इस चालीसा का पाठ करता है, उसे पूज्य गुरुदेव की कृपा से आत्मिक शांति व सांसारिक सुख प्राप्त होते हैं और घर के सारे विघ्न, संकट दूर हो जाते हैं।"},{number:"१८",tag:"चौपाई",lines:["मैं अज्ञान शरण में आया, गुरुवर ने मोक्षमार्ग दिखाया।","अपनी दया दृष्टि बरसाओ, भव-सागर से पार लगाओ॥"],meaning:"हे गुरुदेव! मैं संसारी अज्ञानी प्राणी आपकी शरण में आया हूँ, आपने ही मुझे विशुद्ध दिगम्बर मोक्ष मार्ग का दिग्दर्शन कराया है। मुझ पर अपनी कृपादृष्टि बनाए रखें और इस जन्म-मरण रूपी भवसागर से पार उतारें।"},{number:"१९",tag:"चौपाई",lines:["सच्चे गुरु तुम जग में तारे, अंधकार में दीप उजारे।","‘समयसागर’ को पट्ट बिठाया, संघ-भार उन पर सँभलाया॥"],meaning:"हे सच्चे सद्गुरु! अज्ञान के घोर अंधकार में आप ज्ञान-ज्योति के देदीप्यमान दीपक बनकर आए। समाधि से पूर्व आपने पूज्य मुनि श्री समयसागर जी महाराज को अपना आचार्य पट्ट सौंपकर सम्पूर्ण संघ की बागडोर सौंपी।"},{number:"२०",tag:"चौपाई",lines:["गुरुवर की शिक्षा न भूलें, धर्म-मार्ग पर नित-प्रति झूलें।","अहिंसा परमो धर्म का पाठ, विद्यासागर की महिमा ठाठ॥"],meaning:"हम गुरुवर की अमृतमयी शिक्षाओं को जीवन भर न भूलें और नित्य जिनधर्म के पावन मार्ग पर दृढ़ रहें। 'अहिंसा परमो धर्म' के शाश्वत सिद्धांत को अंगीकार करने वाले गुरुवर विद्यासागर जी की महिमा तीनों लोकों में अनुपम है।"},{number:"२१",tag:"चौपाई",lines:["चरण कमल में शीश नवाऊँ, जनम-जनम गुरु-भक्ति पाऊँ।","विद्यासागर गुरु अमर हमारे, भविक जनों के प्राण पियारे॥"],meaning:"हे गुरुदेव! आपके चरण-कमलों में बारम्बार नतमस्तक हूँ, मुझे जन्म-जन्मांतर तक आपकी पावन भक्ति और चारित्र का मार्ग मिले। पूज्य विद्यासागर जी महाराज अपने आदर्शों व साधना से सदैव अमर हैं और भव्य जीवों के प्राणों से प्यारे हैं।"},{number:"२२",tag:"चौपाई",lines:["जय जय विद्यासागर स्वामी, तीन लोक में नामी स्वामी।","चालीसा जो प्रेम से गाये, वीतराग पद निश्चित पाये॥"],meaning:"तीनों लोकों में विख्यात पूज्य आचार्य विद्यासागर स्वामी की जय हो! जो भी प्राणी इस चालीसा का प्रेम व विशुद्धि से गान करता है, वह निश्चित ही वीतराग पद (मोक्ष) को प्राप्त करता है।"},{number:"२३",tag:"दोहा",lines:["विद्यासागर गुरु चरण में, कोटि-कोटि परनाम।","समाधि-मरण कर शिव गये, पूरण कीजे काम॥"],meaning:"पूज्य आचार्य श्री विद्यासागर जी महाराज के पावन चरणों में मेरा अनंत-अनंत नमन है। आप निर्दोष समाधिमरण पूर्वक सिद्धगति की ओर अग्रसर हुए हैं, हे गुरुदेव! हमारे सम्यक्त्व और कल्याण के संकल्पों को पूर्ण करें।"},{number:"२४",tag:"दोहा",lines:["गुरुवर का संदेश सदा, जीवन में अपनाएँ।","सत्य अहिंसा धर्म से, भव-भव पार लगाएँ॥"],meaning:"हम गुरुवर द्वारा दिए गए त्याग, तपस्या, अहिंसा, राष्ट्र-प्रेम और वीतरागता के संदेश को अपने आचरण में उतारें तथा सत्य-अहिंसा मयी जिनधर्म की नौका से संसार सागर को पार कर जाएँ।"},{number:"२५",tag:"जाप मंत्र",lines:["ॐ ह्रीं श्रीं क्लीं ऐं संत शिरोमणि आचार्य श्री विद्यासागर गुरुभ्यो नमः।"],meaning:"इस परम पावन बीजाक्षर युक्त मंत्र का नित्य १०८ बार स्मरण करने से गुरु-कृपा, चित्त की एकाग्रता, समता भाव तथा आत्मिक विशुद्धि की प्राप्ति होती है।"}]},"gautam-ganadhar-chalisa":{id:"gautam-ganadhar-chalisa",category:"chalisa",title:"श्री गौतम गणधर चालीसा",subtitle:"भगवान महावीर के प्रथम गणधर स्वामी श्री गौतम स्वामी की भक्ति-स्तुति",type:"structured",verses:[{number:"१",tag:"दोहा",lines:["महावीर के चरण में, गौतम कीन्हे ध्यान।","गणधर पद पावन लहे, सकल शास्त्र के ज्ञान॥"],meaning:"भगवान महावीर स्वामी के पावन चरण-कमलों में ध्यान लगाकर जिन्होंने परम पवित्र गणधर पद प्राप्त किया और सम्पूर्ण द्वादशांग जिनवाणी शास्त्रों का ज्ञान धारण किया, उन गौतम स्वामी को हमारा नमन है।"},{number:"२",tag:"दोहा",lines:["इंद्रभूति विप्र कुल, मान गलित जब भाय।","द्वादशांग की रचना करी, वंदूँ शीश नवाय॥"],meaning:"ब्राह्मण कुल में जन्मे महापंडित इंद्रभूति का मिथ्या मान जब समवशरण के मानस्तंभ को देखते ही गलित हो गया, तब उन्होंने द्वादशांग जिनवाणी की रचना की; ऐसे पूज्य गौतम स्वामी के चरणों में मैं शीश झुकाकर वंदना करता हूँ।"},{number:"३",tag:"चौपाई",lines:["जय गौतम गणधर सुखदाई, महावीर के शिष्य बड़ाई।","इंद्रभूति था नाम तुम्हारा, वेदों का था ज्ञान अपारा॥"],meaning:"हे सुखदाता गौतम गणधर स्वामी! आपकी जय हो, आप देवाधिदेव महावीर प्रभु के प्रधान व पट्टशिष्य हैं। दीक्षा पूर्व आपका नाम 'इंद्रभूति' था और आप चारों वेदों व व्याकरण आदि समस्त विद्याओं के प्रकांड विद्वान थे।"},{number:"४",tag:"चौपाई",lines:["पावापुर में मान बढ़ाया, पांच सौ शिष्यन संग सिधाया।","समवशरण जब पहुंचे स्वामी, मान-स्तंभ लख शीश नवामी॥"],meaning:"पावापुर में आयोजित यज्ञ में अपने ज्ञान का परचम फहराने आप पाँच सौ शिष्यों सहित पधारे थे। किंतु जब भगवान महावीर के समवशरण के अलौकिक मानस्तंभ के दर्शन किए, तो आपका अहंकार क्षण भर में विगलित हो गया और नतमस्तक हो गए।"},{number:"५",tag:"चौपाई",lines:["गर्व-गुमान तुरंत गिलाया, महावीर के शरण में आया।","दीक्षा ले मुनि-धर्म सम्हाला, क्षण में ज्ञान-सूर्य उजियाला॥"],meaning:"आपने अपना समस्त मिथ्या गर्व और अभिमान त्याग कर भगवान महावीर की शरण ग्रहण की। प्रभु से जिनदीक्षा अंगीकार कर दिगम्बर मुनि धर्म को धारण किया, जिससे आपके अंतरंग में ज्ञान-सूर्य का दिव्य प्रकाश जगमगा उठा।"},{number:"६",tag:"चौपाई",lines:["प्रथम गणधर पदवी पाई, द्वादशांग जिनवाणी गाई।","दिव्यध्वनी जो खिरी प्रभु की, भाषा रूप दीन्ह मुनिवर की॥"],meaning:"भगवान महावीर के समवशरण में आपको प्रथम गणधर की सर्वोच्च पदवी प्राप्त हुई। भगवान की ओंकारमयी निरक्षरी दिव्यध्वनि को आपने ही ग्रहण कर द्वादशांग श्रुतवाणी के रूप में ग्रथित व व्याख्यायित किया।"},{number:"७",tag:"चौपाई",lines:["अंग-पूर्व की रचना कीनी, भव्य जनों को शिक्षा दीनी।","अष्ट महाऋद्धिधारी स्वामी, आकाशगामी अंतरयामी॥"],meaning:"आपने आचारांग आदि बारह अंगों और चौदह पूर्वों की रचना कर भव्य जीवों को मोक्षमार्ग का उपदेश दिया। आप अणिमा, महिमा आदि आठों महाऋद्धियों और आकाशगामिनी आदि अनेक अलौकिक ऋद्धियों से संपन्न अंतर्यामी मुनिराज थे।"},{number:"८",tag:"चौपाई",lines:["अक्षीण महानस ऋद्धि सुहाई, थाली से सब सेना खाई।","चार ज्ञान के धारी मुनिवर, वीतराग समता के सागर॥"],meaning:"आपके पास 'अक्षीण महानस' जैसी अद्भुत ऋद्धि थी, जिससे एक छोटी सी थाली से पूरी सेना को तृप्त कर दिया गया। आप मति, श्रुत, अवधि और मनःपर्यय—इन चार प्रत्यक्ष व परोक्ष ज्ञानों के धारक तथा परम वीतराग समता के सागर थे।"},{number:"९",tag:"चौपाई",lines:["महावीर प्रभु जब शिव सिधारे, गौतम ने तब नैन उघारे।","प्रभु-वियोग से अंतर जागा, राग-स्नेह का बंधन भागा॥"],meaning:"कार्तिक कृष्ण अमावस्या को जब भगवान महावीर पावापुर से मोक्ष पधारे, तब प्रभु के वियोग से गौतम स्वामी के अंतर में वैराग्य की तीव्र ज्वाला प्रज्वलित हुई और प्रभु के प्रति रहा सूक्ष्म रागात्मक स्नेह भी छिन्न-भिन्न हो गया।"},{number:"१०",tag:"चौपाई",lines:["दीपावली की पावन राती, केवलज्ञान प्रगट्यो सुख-पाती।","चौदह वर्ष विहार कराया, जन-जन को जिनधर्म सिखाया॥"],meaning:"दीपावली की उसी पावन रात्रि के अंतिम प्रहर में राग नष्ट होते ही आपको लोकालोक प्रकाशक 'केवलज्ञान' की प्राप्ति हुई। तत्पश्चात आपने चौदह वर्षों तक सर्वत्र धर्म-विहार कर जन-जन को अहिंसा व जिनधर्म का मर्म समझाया।"},{number:"११",tag:"चौपाई",lines:["गुणावा पावन तीर्थ सुहावन, जहां से मोक्ष गये मुनि पावन।","अष्टकर्म का नाश कराया, सिद्धालय में वास उपाया॥"],meaning:"बिहार स्थित अतिशयकारी गुणावा जी तीर्थ वह परम पावन भूमि है, जहाँ से आपने समस्त आठों कर्मों का क्षय कर परम पावन मोक्ष पद प्राप्त किया और सिद्धालय में सदा-सदा के लिए विराजमान हो गए।"},{number:"१२",tag:"चौपाई",lines:["गौतम स्वामी ऋद्धि के दाता, सब संकट के नाशन त्राता।","जो जन गौतम नाम उचारे, दारिद्र्य दुःख पल में विडारे॥"],meaning:"गौतम स्वामी आत्मिक ऋद्धि-सिद्धि के प्रदाता और भक्तों के समस्त संकटों को हरने वाले रक्षक हैं। जो भी प्राणी श्रद्धा से गौतम स्वामी का नाम स्मरण करता है, उसका दारिद्र्य और दुःख क्षण भर में विलीन हो जाता है।"},{number:"१३",tag:"चौपाई",lines:["विद्या बुद्धि रिद्धि सिद्धा, गौतम चरण मिले निर्विधा।","लक्ष्मी का भण्डार भरावे, जो प्रातः गौतम गुण गावे॥"],meaning:"गौतम स्वामी के चरणों की शरण लेने से विद्या, सद्बुद्धि और लौकिक-पारलौकिक सिद्धियाँ निर्विघ्न प्राप्त होती हैं। जो प्रातःकाल उठकर गौतम स्वामी के गुणों का गान करता है, उसके घर में धर्म-लक्ष्मी व ऐश्वर्य की वृद्धि होती है।"},{number:"१४",tag:"चौपाई",lines:["अन्न-वस्त्र की कमी न होवे, पाप-ताप सब धुलते धोवे।","व्यापार में लाभ करावे, कोटि-कोटि संपति बरसावे॥"],meaning:"उनके भक्तों के घर में अन्न, वस्त्र और धन-धान्य की कभी कमी नहीं होती; जन्म-जन्मांतर के संचित पाप व संताप नष्ट हो जाते हैं तथा न्यायपूर्ण आजीविका व व्यापार में प्रचुर सफलता प्राप्त होती है।"},{number:"१५",tag:"चौपाई",lines:["जो चालीसा प्रेम से गावे, मनोकामना पूरण पावे।","रोग-दोष सब दूर नसावे, गौतम नाम महाफल पावे॥"],meaning:"जो भी श्रावक इस चालीसा का प्रेम व एकाग्रता से पाठ करता है, उसकी धर्ममय मनोकामनाएँ पूर्ण होती हैं। समस्त आधि-व्याधि व शारीरिक-मानसिक रोग दूर हो जाते हैं और गौतम नाम के स्मरण से महान पुण्य फल की प्राप्ति होती है।"},{number:"१६",tag:"चौपाई",lines:["दीपावली पर पूजा कीजे, गौतम नाम बही पर लीजे।","संवत का प्रारंभ सुहावे, गौतम कृपा से लाभ कमावे॥"],meaning:"दीपावली के मंगल अवसर पर गौतम स्वामी की विशेष पूजा-अर्चना की जाती है और नववर्ष के बही-खातों पर 'श्री गौतम स्वामी' का नाम अंकित किया जाता है, जिससे संपूर्ण वर्ष मंगलमय और लाभप्रद व्यतीत होता है।"},{number:"१७",tag:"चौपाई",lines:["सकल ऋद्धि के स्वामी ध्याऊँ, पावन पद में चित्त लगाऊँ।","मैं अज्ञान शरण में आया, गौतम प्रभु ने पार लगाया॥"],meaning:"समस्त अलौकिक ऋद्धियों के स्वामी गौतम गणधर का मैं नित्य ध्यान धरता हूँ और उनके चरणों में अपना मन लगाता हूँ। मैं अज्ञानी संसारी जीव आपकी शरण में आया हूँ, हे प्रभु! मुझे इस भव-सिंधु से पार लगाइए।"},{number:"१८",tag:"चौपाई",lines:["मोह-महामद नाश करो जी, सम्यग्दर्शन उर में धरो जी।","अहिंसा सत्य दया का सार, गौतम स्वामी जय जयकार॥"],meaning:"हे प्रभु! हमारे हृदय से मिथ्यात्व और मोह रूपी मदिरा के नशे को नष्ट कर सम्यग्दर्शन रूपी अमूल्य निधि स्थापित कीजिए। अहिंसा, सत्य, अचौर्य, ब्रह्मचर्य और अपरिग्रह के साक्षात् मूर्तिमान स्वरूप गौतम स्वामी की जय-जयकार हो।"},{number:"१९",tag:"चौपाई",lines:["श्रुत-ज्ञानामृत खूब पिलाया, जग को मुक्ति-मार्ग दिखाया।","मुनि संघ के नायक स्वामी, नमो नमो त्रिभुवन के नामी॥"],meaning:"आपने जिनवाणी रूपी अमृत का रसपान कराकर समूचे जगत को मोक्ष का प्रशस्त मार्ग दिखाया। आप चतुर्विध मुनि संघ के महानायक हैं; हे त्रिभुवन में पूजित गौतम स्वामी! आपको बारंबार नमन है।"},{number:"२०",tag:"चौपाई",lines:["हाथ जोड़ विनती प्रभु मोरी, काटो भव-भव की यह डोरी।","सच्चे मन से जो कोई ध्यावे, जीवन में आनंद बढ़ावे॥"],meaning:"हे प्रभु! दोनों हाथ जोड़कर मेरी यही प्रार्थना है कि चौरासी लाख योनियों के आवागमन के इस बंधन को काट दीजिए। जो भी सच्चे अंतःकरण से आपका ध्यान करता है, उसके जीवन में शाश्वत आनंद और शांति का संचार होता है।"},{number:"२१",tag:"चौपाई",lines:["घर में सुख-शांति बरसाओ, बिगड़े काम तुरंत बनाओ।","गौतम स्वामी ज्ञान के सागर, कृपा करो मुझ पर करुणाकर॥"],meaning:"हे करुणा के सागर गौतम स्वामी! हमारे गृह में सुख, शांति और सौहार्द का वास हो तथा हमारे रुके हुए कार्य संपन्न हों। आप ज्ञान के अथाह सागर हैं, मुझ दीन भक्त पर अपनी कृपा दृष्टि बनाए रखें।"},{number:"२२",tag:"चौपाई",lines:["निसिदिन गौतम नाम पुकारूँ, जनम-जनम का ताप निवारूँ।","चालीसा चालीस दिन गाये, सिद्ध-लोक में वास सो पाये॥"],meaning:"मैं रात-दिन गौतम स्वामी के पावन नाम का स्मरण कर अपने जन्म-जन्मांतर के पाप-संतापों का निवारण करता हूँ। जो भव्य जीव चालीस दिनों तक इस चालीसा का पाठ करता है, वह कालांतर में सिद्धपद को प्राप्त करता है।"},{number:"२३",tag:"दोहा",lines:["गौतम स्वामी के चरण, ध्यावे जो नर-नार।","ऋद्धि-सिद्धि संपदा लहे, पावे पद निर्वार॥"],meaning:"जो भी भव्य स्त्री या पुरुष श्री गौतम स्वामी के पावन चरणों का ध्यान करता है, वह इस लोक में ऋद्धि, सिद्धि और धर्म-संपदा प्राप्त करता है तथा अंत में परम पद निर्वाण को प्राप्त करता है।"},{number:"२४",tag:"दोहा",lines:["ॐ ह्रीं श्रीं गौतम गणधराय नमः, जपे जो आठों याम।","सकल अमंगल दूर हों, पूरण हो सब काम॥"],meaning:"जो प्राणी आठों पहर 'ॐ ह्रीं श्रीं गौतम गणधराय नमः' मंत्र का भक्तिभाव से जाप करता है, उसके जीवन से समस्त अमंगल दूर हो जाते हैं और सभी धर्मानुरागी कार्य सिद्ध होते हैं।"},{number:"२५",tag:"जाप मंत्र",lines:["ॐ ह्रीं श्रीं क्लीं गौतम-गणधराय नमः।"],meaning:"इस महामंत्र का प्रतिदिन १०८ बार जाप करने से बुद्धि, विद्या, ज्ञान, ऋद्धि और आत्म-कल्याण की प्राप्ति होती है।"}]},"sammed-shikhar-chalisa":{id:"sammed-shikhar-chalisa",category:"chalisa",title:"श्री सम्मेद शिखर जी चालीसा",subtitle:"शाश्वत सिद्धक्षेत्र बीस तीर्थंकरों की पावन निर्वाण भूमि की भक्ति-स्तुति",type:"structured",verses:[{number:"१",tag:"दोहा",lines:["बीस जिनेश्वर मोक्ष गये, जहां से सिद्ध अनंत।","सम्मेद शिखर पावन मही, वंदूँ बारंबार॥"],meaning:"जहाँ से वर्तमान चौबीसी के बीस तीर्थंकर भगवंत और अनंत-अनंत मुनिराज कर्मों का क्षय कर मोक्ष पधारे हैं, उस परम पावन सम्मेद शिखर सिद्धक्षेत्र की धरा को मेरा बारम्बार नमन है।"},{number:"२",tag:"दोहा",lines:["पारसनाथ पहाड़ सुहावन, झारखंड का धाम।","एक बार वंदन करे, मिटे नरक का काम॥"],meaning:"झारखंड प्रदेश में स्थित अनुपम पारसनाथ पर्वत (सम्मेद शिखर) ऐसा महातीर्थ है, जिसकी भक्तिपूर्वक एक बार भी भाव-वंदना करने से जीव के नरक-निगोद आदि दुर्गति के कर्म कट जाते हैं।"},{number:"३",tag:"चौपाई",lines:["जय सम्मेद शिखर गिरिराज, सिद्धक्षेत्र त्रिभुवन के ताज।","शाश्वत तीरथ परम पुनीता, कोटि-कोटि मुनि कर्म विजीता॥"],meaning:"हे सिद्धक्षेत्रों के शिरोमणि सम्मेद शिखर गिरिराज! आपकी जय हो, आप तीनों लोकों के मुकुटमणि हैं। यह महातीर्थ अनादि-अनंत शाश्वत है, जहाँ करोड़ों-करोड़ों दिगम्बर मुनिराजों ने तपस्या कर कर्म शत्रुओं पर विजय पाई।"},{number:"४",tag:"चौपाई",lines:["बीस तीर्थंकर शिवपद पाये, पद-चिन्हों की महिमा छाये।","अजित, संभव, अभिनंदन स्वामी, सुमति, पद्मप्रभ अंतरयामी॥"],meaning:"वर्तमान अवसर्पिणी काल के बीस तीर्थंकरों ने इसी पावन गिरिराज से मोक्ष प्राप्त किया है। द्वितीय तीर्थंकर अजितनाथ, तृतीय सम्भवनाथ, चतुर्थ अभिनंदननाथ, पंचम सुमतिनाथ और षष्ठ पद्मप्रभु स्वामी ने यहीं से निर्वाण पद पाया।"},{number:"५",tag:"चौपाई",lines:["सुपार्श्व, चंद्रप्रभ, पुष्पदंता, शीतल, श्रेयांस मुनि भगवंता।","विमल, अनंत, धर्म जिनराया, शांति, कुंथु, अरह पद पाया॥"],meaning:"सप्तम सुपार्श्वनाथ, अष्टम चंद्रप्रभु, नवम पुष्पदंत (सुविधिनाथ), दशम शीतलनाथ, एकादश श्रेयांसनाथ, द्वादश विमलनाथ, त्रयोदश अनंतनाथ, चतुर्दश धर्मनाथ, पंचदश शांतिनाथ, षोडश कुंथुनाथ और सप्तदश अरहनाथ प्रभु ने यहाँ से मुक्ति पाई।"},{number:"६",tag:"चौपाई",lines:["मल्लि, मुनिसुव्रत, नमि जिनराजा, पार्श्वनाथ सिद्धन के ताज़ा।","चौबीस में से बीस जिनेशा, इस गिरि से काटे सब क्लेशा॥"],meaning:"उन्नीसवें मल्लिनाथ, बीसवें मुनिसुव्रतनाथ, इक्कीसवें नमिनाथ और तेईसवें भगवान पार्श्वनाथ स्वामी ने इसी पर्वतराज से निर्वाण प्राप्त किया। इस प्रकार चौबीस में से बीस तीर्थंकरों ने यहीं से समस्त कर्म-क्लेशों का क्षय किया।"},{number:"७",tag:"चौपाई",lines:["मधुवन नगरी तलहटी सोहे, धर्मशालाएं मन को मोहे।","प्रातःकाल वंदना ध्यावें, नौ कोस की परिक्रमा जावें॥"],meaning:"पर्वत की तलहटी में स्थित पावन मधुवन नगरी अत्यंत मनोहारी है, जहाँ की सुंदर धर्मशालाएँ और जिनालय यात्रियों के मन को मोह लेते हैं। भक्तजन ब्रह्ममुहूर्त में भक्तिभाव से नौ कोस (सत्ताईस किलोमीटर) की गिरिराज परिक्रमा व वंदना प्रारंभ करते हैं।"},{number:"८",tag:"चौपाई",lines:["गंधर्व नाला शीतल पानी, अमृत सम मीठी जिनवाणी।","शीतल नाला चढ़ाई भारी, जयकारा बोलें नर-नारी॥"],meaning:"मार्ग में गंधर्व नाले का शीतल जल यात्रियों की थकान मिटाता है और जिनवाणी रूपी अमृत की स्मृति दिलाता है। आगे शीतल नाले की कठिन चढ़ाई पर सभी श्रद्धालु नर-नारी प्रभु के जयकारे लगाते हुए उत्साहपूर्वक आगे बढ़ते हैं।"},{number:"९",tag:"चौपाई",lines:["पारसनाथ की टोंक सुहाई, स्वर्ण छत्र की छटा लखाई।","जल मंदिर में पूजा कीजे, अर्घ्य चढ़ाकर समता लीजे॥"],meaning:"सबसे ऊँची चोटी पर भगवान पार्श्वनाथ की स्वर्णमयी टोंक शोभित है, जिस पर छत्र की अलौकिक छटा दर्शनीय है। पावन जल मंदिर में पहुँचकर प्रभु का अभिषेक-पूजन कर, अर्घ्य समर्पित करके भक्तजन समता भाव ग्रहण करते हैं।"},{number:"१०",tag:"चौपाई",lines:["ढोलक मंजीरा झांझ बजावें, भक्ति-भाव से चालीसा गावें।","सम्मेद शिखर की पावन माटी, मस्तक धरे कटे भव-घाटी॥"],meaning:"यात्री ढोलक, मंजीरा और झांझ की मधुर ध्वनि के साथ भक्ति-रस में डूबकर चालीसा और स्तुतियाँ गाते हैं। सम्मेद शिखर की पावन रज को मस्तक पर धारण करने मात्र से संसार के जन्म-मरण की कठिन घाटियाँ कट जाती हैं।"},{number:"११",tag:"चौपाई",lines:["जो जन एक बार चढ़ जावे, नरक-निगोद की गति नहिं पावे।","असंख्य मुनिवर यहाँ समाये, तप के बल से मोक्ष सिधाये॥"],meaning:"जो भी भव्य प्राणी जीवन में एक बार भी शुद्ध भावों से शिखरजी की वंदना करता है, वह नरक और निगोद जैसी तिर्यंच दुर्गति में नहीं पड़ता। इस पावन भूमि पर असंख्यात मुनिराजों ने ध्यान व तपस्या कर सिद्धपद प्राप्त किया है।"},{number:"१२",tag:"चौपाई",lines:["डोलियों पर वृद्ध सिधारे, जय-जय पारसनाथ पुकारे।","जंगल में मंगल दरसावे, शांत तपोभूमि मन भावे॥"],meaning:"वृद्ध, बालक और अशक्त यात्री डोलियों पर बैठकर 'जय पारसनाथ' का उद्घोष करते हुए वंदना करते हैं। घने वनों से आच्छादित यह पर्वत अपने शांत और ध्यानमय वातावरण से अंतर्मन को परम शांति प्रदान करता है।"},{number:"१३",tag:"चौपाई",lines:["चारों ओर हरियाली छाई, पक्षी करें प्रभु की प्रभुताई।","टोंक-टोंक पर शीश नवावें, अष्टद्रव्य से अर्घ चढ़ावें॥"],meaning:"चारों ओर फैली प्राकृतिक हरियाली और कलरव करते पक्षी मानो तीर्थंकरों की महिमा गा रहे हों। श्रद्धालु प्रत्येक टोंक पर नतमस्तक होकर अष्टद्रव्य से भावपूर्ण निर्वाण अर्घ्य समर्पित करते हैं।"},{number:"१४",tag:"चौपाई",lines:["कपूर-आरती ज्योति जगावें, मनवांछित सब वैभव पावें।","रोग-दोष सब दूर नसावें, शिखर वंदना जो नर पावें॥"],meaning:"कपूर की दीप-आरती प्रज्वलित कर प्रभु की आरती उतारने से आत्म-वैभव की प्राप्ति होती है। जो भी प्राणी इस सिद्धक्षेत्र की वंदना का पावन अवसर पाता है, उसके समस्त शारीरिक और मानसिक रोग-दोष शांत हो जाते हैं।"},{number:"१५",tag:"चौपाई",lines:["दुख-दारिद्र्य पल में मिट जावे, सुख-शांति घर में भर जावे।","जो चालीसा चालीस दिन गावे, शिखर जी का फल वो पावे॥"],meaning:"शिखरजी के स्मरण से दुःख और दारिद्र्य का नाश होकर घर-परिवार में सुख, शांति व समृद्धि की वृद्धि होती है। जो नियमपूर्वक चालीस दिनों तक इस चालीसा का पाठ करता है, उसे साक्षात् शिखरजी की वंदना का महान पुण्य प्राप्त होता है।"},{number:"१६",tag:"चौपाई",lines:["सम्मेद शिखर की रक्षा कीजे, प्राणन से भी प्यारा कीजे।","तीर्थ-रक्षा का संकल्प उठावें, जिनशासन की ध्वजा फहरावें॥"],meaning:"इस पावन शाश्वत महातीर्थ की पवित्रता की रक्षा हमें अपने प्राणों से भी अधिक प्रिय मानकर करनी चाहिए। हम सभी मिलकर तीर्थ-संरक्षण का संकल्प लें और विश्व भर में जिनशासन की अहिंसा ध्वजा फहराएँ।"},{number:"१७",tag:"चौपाई",lines:["मैं पापी प्रभु शरण तिहारी, वंदूँ बार-बार गिरि भारी।","जन्म-मरण का फेरा काटो, आत्म-रस की गागर बाँटो॥"],meaning:"हे बीस तीर्थंकर भगवंतों! मैं संसारी जीव आपकी पावन शरण में आया हूँ और इस महान पर्वतराज को बार-बार वंदन करता हूँ। मेरे जन्म-मरण के सांसारिक फेरे को समाप्त कर मुझे विशुद्ध आत्मानुभूति का अमृत प्रदान कीजिए।"},{number:"१८",tag:"चौपाई",lines:["सम्यग्दर्शन पावन दीजे, निज आतम में लीन करीजे।","सम्मेद शिखर तीरथ सुखकारी, महिमा गावत दुनिया सारी॥"],meaning:"हे प्रभु! मुझे निर्मल सम्यग्दर्शन का वरदान दीजिए ताकि मैं अपनी शुद्ध आत्मा में लीन हो सकूँ। सम्मेद शिखर समस्त जीवों को आत्मिक सुख देने वाला अनुपम तीर्थ है, जिसकी महिमा सम्पूर्ण जगत गाता है।"},{number:"१९",tag:"चौपाई",lines:["पारसनाथ प्रभु कृपा निधान, दीजे प्रभु जी आतम ज्ञान।","दूर-दूर से यात्री आवें, भाव सहित परिक्रमा लगावें॥"],meaning:"हे कृपा के निधान भगवान पार्श्वनाथ! हमें केवलज्ञान की ओर ले जाने वाला सम्यक् आत्मज्ञान प्रदान कीजिए। देश-विदेश के कोने-कोने से लाखों श्रद्धालु यहाँ आकर भाव-विभोर होकर गिरिराज की परिक्रमा करते हैं।"},{number:"२०",tag:"चौपाई",lines:["चरण कमल में ध्यान लगाऊँ, मुक्ति-महल का पथ मैं पाऊँ।","सम्मेद शिखर की जय जयकार, बीस जिनेश्वर बेड़ा पार॥"],meaning:"प्रभु के पावन चरण-कमलों में ध्यान लगाकर मैं मुक्ति रूपी महल का सच्चा मार्ग प्राप्त करूँ। सम्मेद शिखर गिरिराज की सदा जय हो, यहाँ से मोक्ष पधारे बीस जिनेश्वर प्रभु हमारा बेड़ा पार करें।"},{number:"२१",tag:"चौपाई",lines:["अखंड ज्योति टोंकन पर जागे, अंधकार अज्ञान का भागे।","हाथ जोड़ विनती करूँ सुनिये पारसनाथ, भव-सागर में डूबते पकड़ो मेरा हाथ॥"],meaning:"शिखरजी की प्रत्येक टोंक पर ज्ञान की अखंड ज्योति प्रज्वलित है जिससे अज्ञान का अंधकार मिटता है। हे पार्श्वनाथ प्रभु! हाथ जोड़कर मेरी यही प्रार्थना है कि इस संसार सागर में डूबते हुए मेरा हाथ थाम लीजिए।"},{number:"२२",tag:"चौपाई",lines:["निसिदिन शिखर जी को ध्याऊँ, अंत समय समाधि पाऊँ।","चालीसा जो प्रेम से गाये, सिद्ध-पदवी निश्चित पाये॥"],meaning:"मैं रात-दिन इस परम पावन शिखरजी का स्मरण करूँ और जीवन के अंतिम समय में शांत समाधिमरण प्राप्त करूँ। जो भी भव्य जीव इस चालीसा का प्रेम व विशुद्धि से पाठ करता है, वह निश्चित ही सिद्ध पदवी को प्राप्त करता है।"},{number:"२३",tag:"दोहा",lines:["सम्मेद शिखर गिरिराज को, वंदूँ मन वच काय।","बीस जिनेश्वर की कृपा, सब संकट मिट जाय॥"],meaning:"मन, वचन और काया की पूर्ण एकाग्रता से मैं सम्मेद शिखर गिरिराज की वंदना करता हूँ। यहाँ से मोक्ष पधारे बीस तीर्थंकर भगवंतों की महती अनुकंपा से जीवन के समस्त संकट व संताप मिट जाते हैं।"},{number:"२४",tag:"दोहा",lines:["तीर्थराज सम्मेद शिखर, पावन परम पुनीत।","‘जिनवाणी’ सेवा करूँ, प्रभु चरणों में प्रीत॥"],meaning:"तीर्थराज सम्मेद शिखर परम पावन और अंतःकरण को पवित्र करने वाला तीर्थ है। जीवन भर मुझे जिनवाणी माता की सेवा और वीतरागी प्रभु के चरण-कमलों में अनन्य प्रीति प्राप्त हो।"},{number:"२५",tag:"जाप मंत्र",lines:["ॐ ह्रीं श्रीं सम्मेद-शिखर-सिद्धक्षेत्रेभ्यो नमः।"],meaning:"इस पावन मंत्र का नित्य १०८ बार स्मरण करने से सम्मेद शिखर जी की संपूर्ण वंदना का अक्षय पुण्य तथा आत्म-शांति प्राप्त होती है।"}]},"girnar-chalisa":{id:"girnar-chalisa",category:"chalisa",title:"श्री गिरनार जी तीर्थ चालीसा",subtitle:"भगवान नेमिनाथ की दीक्षा, ज्ञान व मोक्ष कल्याणक भूमि उज्जयंत महातीर्थ की भक्ति-स्तुति",type:"structured",verses:[{number:"१",tag:"दोहा",lines:["उज्जयंत गिरिराज पर, नेमिनाथ जिनराय।","कोटि-कोटि मुनि मोक्ष गये, वंदूँ शीश नवाय॥"],meaning:"उज्जयंत (गिरनार) पर्वतराज पर २२वें तीर्थंकर भगवान नेमिनाथ स्वामी और करोड़ों मुनिराज कर्मों को नष्ट कर मोक्ष पधारे हैं; उस परम पावन गिरिराज को मैं शीश झुकाकर वंदन करता हूँ।"},{number:"२",tag:"दोहा",lines:["सौराष्ट्र धरा पावन भली, जूनागढ़ विख्यात।","नेमिनाथ प्रभु के चरण, ध्याऊँ दिवस और रात॥"],meaning:"गुजरात के सौराष्ट्र प्रदेश में ऐतिहासिक जूनागढ़ नगरी की पावन धरा पर स्थित गिरनार महातीर्थ में भगवान नेमिनाथ के पावन चरण-कमलों का मैं दिन-रात ध्यान करता हूँ।"},{number:"३",tag:"चौपाई",lines:["जय गिरनार महा सुखदाता, नेमिनाथ जग के पितु-माता।","बाईसवें तीर्थंकर स्वामी, तीन लोक के अंतरयामी॥"],meaning:"हे सुखदाता गिरनार तीर्थ! आपकी जय हो, जहाँ नेमिनाथ प्रभु जगत के माता-पिता रूप रक्षक हैं। वे बाईसवें तीर्थंकर, तीनों लोकों के ज्ञाता और अंतर्यामी परमात्मा हैं।"},{number:"४",tag:"चौपाई",lines:["समुद्रविजय शिवा के नंदन, शौरीपुर के राज-निकंदन।","कृष्ण-बलराम के भाई प्यारे, बाल ब्रह्मचारी अविकारी॥"],meaning:"शौरीपुर के राजा समुद्रविजय और महारानी शिवादेवी के आत्मज प्रभु नेमिनाथ, श्रीकृष्ण व बलराम के प्रिय चचेरे भ्राता तथा काम-विकारों से सर्वथा रहित अखंड बाल ब्रह्मचारी थे।"},{number:"५",tag:"चौपाई",lines:["राजुल संग ब्याह रचाया, बारात सजी मन हर्षाया।","पशुओं की जब चीख सुनाई, करुणा प्रभु के उर में छाई॥"],meaning:"राजकुमारी राजुल (राजीमती) के साथ विवाह हेतु बारात सज-धज कर जूनागढ़ पहुँची थी। किंतु मार्ग में भोजन हेतु बाड़े में बंद मूक पशुओं का करुण क्रंदन सुनकर प्रभु का हृदय करुणा से द्रवित हो उठा।"},{number:"६",tag:"चौपाई",lines:["छोड़ दिया सब राज-सिंहासन, रथ मोड़ा तोड़ा जग-बंधन।","गिरनार पर्वत पर आये, कठिन तपस्या ध्यान लगाये॥"],meaning:"प्रभु ने तत्काल रथ मोड़ लिया, राजवैभव और वैवाहिक संबंधों को त्याग कर संसार के समस्त बंधनों को तोड़ दिया। वे गिरनार पर्वत पर पधारे और कठोर दिगम्बर तपस्या व आत्म-ध्यान में लीन हो गए।"},{number:"७",tag:"चौपाई",lines:["दीक्षा ज्ञान और मोक्ष पाया, गिरनार तीर्थ को चमकाया।","उज्जयंत पर्वत की महिमा, अवर्णनीय गिरनार गरिमा॥"],meaning:"भगवान नेमिनाथ ने इसी पर्वत पर दीक्षा, केवलज्ञान और निर्वाण कल्याणक प्राप्त कर गिरनार तीर्थ को परम पावन बनाया। इस उज्जयंत गिरिराज की गरिमा और महिमा शब्दों से परे अवर्णनीय है।"},{number:"८",tag:"चौपाई",lines:["प्रथम टोंक पर मंदिर सोहे, नेमिनाथ छवि मन को मोहे।","सहस्राम्र वन पावन भारी, जहां तपस्या कीन्ह अपारी॥"],meaning:"प्रथम टोंक पर प्राचीन विशाल जिनालय शोभित है, जहाँ प्रभु नेमिनाथ की श्यामवर्णी शांत पद्मासन प्रतिमा मन को मोह लेती है। पावन सहस्राम्र वन वह तपोभूमि है जहाँ प्रभु ने घोर तपश्चर्या की थी।"},{number:"९",tag:"चौपाई",lines:["पाँचवीं टोंक शिखर अति पावन, नेमिनाथ मोक्ष कल्याणक भावन।","दस हजार सीढ़ियाँ चढ़ जावें, भक्त-जन जयकारा लगावें॥"],meaning:"पाँचवीं टोंक गिरनार का सर्वोच्च और परम पावन शिखर है, जो भगवान नेमिनाथ के मोक्ष कल्याणक का साक्षात् स्थल है। श्रद्धालु लगभग दस हजार सीढ़ियाँ चढ़कर प्रभु के जयघोष के साथ वहाँ पहुँचते हैं।"},{number:"१०",tag:"चौपाई",lines:["राजुल ने भी दीक्षा लीनी, गिरनार पर साधना कीनी।","कोटि-कोटि मुनि यहाँ समाये, कर्म काट शिव-धाम सिधाये॥"],meaning:"राजकुमारी राजुल ने भी प्रभु के वैराग्य का अनुसरण कर आर्यिका दीक्षा ग्रहण की और गिरनार की गुफाओं में साधना की। यहाँ करोड़ों मुनिराजों ने तपस्या कर कर्मों का नाश किया और मुक्ति पाई।"},{number:"११",tag:"चौपाई",lines:["गिरनार की माटी चंदन, सुर-नर करते इसका वंदन।","जो जन गिरनार पर जावे, भव-भव के बंधन कट जावे॥"],meaning:"गिरनार की पावन रज चंदन के समान पवित्र है, जिसकी वंदना देव और मनुष्य सभी करते हैं। जो भी भव्य प्राणी शुद्ध भावों से गिरनार की यात्रा करता है, उसके जन्म-मरण के बंधन कट जाते हैं।"},{number:"१२",tag:"चौपाई",lines:["रोग-कष्ट सब दूर नसावें, नेमिनाथ जब नाम सुनावें।","पशु-रक्षा का पाठ पढ़ाया, जीव-दया का दीप जलाया॥"],meaning:"भगवान नेमिनाथ का नाम स्मरण करने से समस्त आधि-व्याधि व संकट दूर हो जाते हैं। प्रभु ने मूक पशुओं की रक्षा कर समूचे विश्व में अहिंसा और जीवदया का अमर प्रकाश फैलाया।"},{number:"१३",tag:"चौपाई",lines:["शौर्य और वैराग्य के संगम, नेमिनाथ प्रभु पावन अनुपम।","ढोल नगाड़े मंदिर बाजे, आरती में जयकारा गाजे॥"],meaning:"भगवान नेमिनाथ शौर्य, पराक्रम और परम वैराग्य के अनुपम संगम हैं। जिनालयों में ढोल-नगाड़ों की मंगल ध्वनि गूंजती है और आरती में गगनभेदी जयकारों से वातावरण गुंजायमान होता है।"},{number:"१४",tag:"चौपाई",lines:["पंचामृत अभिषेक करावें, अष्टद्रव्य से अर्घ चढ़ावें।","गिरनार तीर्थ की रक्षा कीजे, तन-मन-धन अर्पण कर दीजे॥"],meaning:"प्रभु का परम पावन जिन-अभिषेक कर अष्टद्रव्य से भावपूर्ण अर्घ्य समर्पित करते हैं। इस अनादि तीर्थ की रक्षा और पवित्रता बनाए रखने हेतु हमें तन, मन और धन समर्पित करने को तत्पर रहना चाहिए।"},{number:"१५",tag:"चौपाई",lines:["तीर्थ पर जो संकट आवे, जैन समाज ध्वजा फहरावे।","नेमिनाथ प्रभु कृपा निधान, दीजे प्रभु जी आतम ज्ञान॥"],meaning:"जब-जब तीर्थ पर संकट के बादल छाते हैं, तब-तब समस्त जैन समाज एकजुट होकर तीर्थ की रक्षा हेतु ध्वजा फहराता है। हे कृपा के निधान नेमिनाथ प्रभु! हमें आत्म-ज्ञान का वरदान दीजिए।"},{number:"१६",tag:"चौपाई",lines:["जो चालीसा चालीस दिन गावे, मनवांछित सब वैभव पावे।","पुत्र-पौत्र संपति घर आवे, दुःख-दरिद्र सब मिट जावे॥"],meaning:"जो भी भक्तजन चालीस दिनों तक भक्तिपूर्वक इस चालीसा का पाठ करते हैं, उन्हें धर्म, अर्थ, काम और मोक्ष रूपी वैभव प्राप्त होता है और घर के सारे दुःख व दारिद्र्य नष्ट हो जाते हैं।"},{number:"१७",tag:"चौपाई",lines:["मैं अज्ञान शरण में आया, नेमिनाथ प्रभु ने अपनाया।","काम-क्रोध मद-लोभ विनाशी, वीतराग आनंद-प्रकाशी॥"],meaning:"मैं अज्ञानी संसारी प्राणी आपकी शरण में आया हूँ, हे प्रभु! मुझे अपनाकर संसार-ताप से मुक्ति दिलाइए। आप काम, क्रोध, मान और लोभ के संहारक तथा वीतराग आनंद के प्रकाशक हैं।"},{number:"१८",tag:"चौपाई",lines:["अहिंसा परम धर्म सिखलाया, जग को मुक्ति-राह दिखाया।","जूनागढ़ की पावन धरती, जहाँ गिरनार की शोभा सजती॥"],meaning:"आपने परम अहिंसा धर्म की दीक्षा देकर समस्त जगत को कल्याणकारी मोक्षमार्ग दिखाया। जूनागढ़ की पावन धरती धन्य है, जहाँ गगनचुंबी गिरनार पर्वतराज सुशोभित है।"},{number:"१९",tag:"चौपाई",lines:["चारों ओर पहाड़ सुहावन, दृश्य लगे अति पावन-भावन।","टोंकन-टोंकन शीश नवाऊँ, जनम-जनम प्रभु भक्ति पाऊँ॥"],meaning:"चारों ओर हरी-भरी पर्वतमालाएँ अत्यंत मनोहारी और चित्त को शांत करने वाली हैं। मैं प्रत्येक टोंक पर शीश झुकाकर प्रार्थना करता हूँ कि जन्म-जन्मांतर तक मुझे प्रभु नेमिनाथ की भक्ति प्राप्त हो।"},{number:"२०",tag:"चौपाई",lines:["हाथ जोड़ विनती प्रभु मोरी, काटो जनम-मरण की डोरी।","सच्चे मन से जो कोई ध्यावे, निश्चय मुक्ति-महल को पावे॥"],meaning:"हे प्रभु! दोनों हाथ जोड़कर मेरी विनती है कि मेरे आवागमन के चक्र को समाप्त कीजिए। जो सच्चे मन से आपका ध्यान करता है, वह निश्चित ही मुक्ति महल (मोक्ष) को प्राप्त करता है।"},{number:"२१",tag:"चौपाई",lines:["नेमिनाथ प्रभु अंतरयामी, तुम हो मेरे पूरण स्वामी।","गिरनार तीर्थ की जय जयकार, नेमिनाथ प्रभु बेड़ा पार॥"],meaning:"हे अंतर के ज्ञाता नेमिनाथ स्वामी! आप ही मेरे सच्चे नाथ और शरणदाता हैं। गिरनार महातीर्थ की सदा जय-जयकार हो और प्रभु नेमिनाथ हमारा संसार-सागर से बेड़ा पार करें।"},{number:"२२",tag:"चौपाई",lines:["निसिदिन ध्यान धरूँ प्रभु तेरा, मेटो भव-सागर का फेरा।","चालीसा जो प्रेम से गाये, सिद्ध-लोक में वास सो पाये॥"],meaning:"मैं दिन-रात आपके वीतराग स्वरूप का ध्यान धरता हूँ, मेरे संसार-भ्रमण के फेरे को मिटाइए। जो भी इस चालीसा का प्रेमपूर्वक पाठ करता है, वह सिद्धलोक में अविनाशी पद प्राप्त करता है।"},{number:"२३",tag:"दोहा",lines:["गिरनार पर्वत नेमिनाथ, वंदूँ शीश नवाय।","सकल अमंगल दूर हों, सब संकट मिट जाय॥"],meaning:"गिरनार पर्वतराज पर विराजमान भगवान नेमिनाथ के चरणों में शीश झुकाकर वंदना करने से समस्त अमंगल दूर हो जाते हैं और जीवन के सारे कष्ट व संकट शांत हो जाते हैं।"},{number:"२४",tag:"दोहा",lines:["नेमिनाथ भगवान की, जो गावे चालीस।","ऋद्धि-सिद्धि संपदा लहे, पूरण होय आसीस॥"],meaning:"जो भी भक्तजन भगवान नेमिनाथ की इस चालीसा का नियम से पाठ करते हैं, उन्हें धर्म-ऋद्धि, आत्मिक शांति और जिनशासन के आशीर्वाद से समस्त सुख प्राप्त होते हैं।"},{number:"२५",tag:"जाप मंत्र",lines:["ॐ ह्रीं श्रीं उज्जयंत-गिरनार-सिद्धक्षेत्राय श्री नेमिनाथाय नमः।"],meaning:"इस बीजमंत्र का नित्य १०८ बार जाप करने से भय, संकट और आधि-व्याधि का निवारण होकर आत्मिक शांति व धर्म की वृद्धि होती है।"}]},"kundkund-chalisa":{id:"kundkund-chalisa",category:"chalisa",title:"श्री कुंदकुंद स्वामी चालीसा",subtitle:"कलिकाल सर्वज्ञ परमागम प्रणेता आचार्य श्री कुंदकुंद देव की भक्ति-स्तुति",type:"structured",verses:[{number:"१",tag:"दोहा",lines:["सीमंधर प्रभु समवशरण, पहुंचे जो आकाश।","कुंदकुंद मुनिराज को, वंदन बारंबार॥"],meaning:"ऋद्धि के बल से आकाश मार्ग से विदेह क्षेत्र जाकर देवाधिदेव भगवान सीमंधर स्वामी के साक्षात् समवशरण में पहुँचने वाले प्रातःस्मरणीय आचार्य श्री कुंदकुंद देव को मेरा बारम्बार नमन है।"},{number:"२",tag:"दोहा",lines:["कलिकाल सर्वज्ञ जग-गुरु, आगम के आधार।","समयसार पाहुड़ दिया, कीन्हा परमोपकार॥"],meaning:"इस पंचम काल में 'कलिकाल सर्वज्ञ' के रूप में पूजित, सम्पूर्ण जिन-आगम के मूल आधार तथा 'समयसार' आदि पावन परमागमों की रचना कर भव्य जीवों पर महान उपकार करने वाले जगद्गुरु को वंदन है।"},{number:"३",tag:"चौपाई",lines:["जय कुंदकुंद मुनीश्वर स्वामी, अध्यात्म के अंतरयामी।","दक्षिण भारत जन्म सुहावन, कौण्डकुन्द पुर पावन-भावन॥"],meaning:"हे अध्यात्म रस के मर्मज्ञ, मुनीश्वर श्री कुंदकुंद स्वामी! आपकी जय हो। दक्षिण भारत की पावन भूमि पर स्थित 'कौण्डकुन्दपुर' (कोंडकौंडल) नामक पावन ग्राम में आपका जन्म हुआ था।"},{number:"४",tag:"चौपाई",lines:["बाल्यकाल से वैराग्य लीना, जिन-दीक्षा धारण कर दीना।","पद्मनंदि था नाम तुम्हारा, चारण ऋद्धिधारी अवतारा॥"],meaning:"आपने बाल्यावस्था में ही संसार की असारता को जानकर दिगम्बर जिनदीक्षा धारण कर ली थी। आपका मूल नाम मुनि 'पद्मनंदि' था और आप भूमि से चार अंगुल ऊपर गमन करने वाली आकाशचारिणी चारण-ऋद्धि के धारक थे।"},{number:"५",tag:"चौपाई",lines:["अन्तरिक्ष में गमन कराया, विदेह क्षेत्र समवशरण सिधाया।","सीमंधर प्रभु दर्शन पायो, आठ दिवस तक अमृत न्हायो॥"],meaning:"ऋद्धिबल से देवों द्वारा सत्कार पाकर आप आकाश मार्ग से सीमंधर स्वामी के समवशरण में विदेह क्षेत्र पहुँचे। वहाँ आठ दिनों तक साक्षात् अरहंत प्रभु के दर्शन कर दिव्यध्वनि रूपी ज्ञान-अमृत का रसपान किया।"},{number:"६",tag:"चौपाई",lines:["साक्षात जिनवाणी सुनी भाई, भारत भूमि पे प्रगटाई।","समयसार परमागम कीन्हा, शुद्धातम का दर्शन दीन्हा॥"],meaning:"साक्षात् तीर्थंकर भगवान के मुखारविंद से सुनी हुई विशुद्ध जिनवाणी को आपने भरत क्षेत्र की धरा पर लिपिबद्ध किया और 'समयसार' जैसे महान ग्रंथ की रचना कर शुद्ध निश्चयनय से आत्मा का साक्षात् दर्शन कराया।"},{number:"७",tag:"चौपाई",lines:["प्रवचनसार में ज्ञान बताया, नियमसार शिव-मार्ग दिखाया।","पंचास्तिकाय अष्टपाहुड़ गाये, भव्य जनों के भाग जगाये॥"],meaning:"आपने 'प्रवचनसार' में ज्ञान व ज्ञेय तत्त्वों का गंभीर विवेचन किया, 'नियमसार' में परम मोक्षमार्ग का दिग्दर्शन कराया तथा 'पंचास्तिकाय' व 'अष्टपाहुड़' आदि ग्रंथों की रचना कर भव्यात्माओं के सोए भाग्य को जगाया।"},{number:"८",tag:"चौपाई",lines:["द्रव्य-गुण-पर्याय समझाई, निश्चय-व्यवहार की संधि मिलाई।","आत्मा को शुद्धात्मा भाया, देह भिन्न चैतन्य लखाया॥"],meaning:"आपने छह द्रव्यों, उनके गुणों और पर्यायों का यथार्थ स्वरूप समझाया तथा निश्चय और व्यवहार नय की सुंदर संधि स्थापित की। देह और आत्मा के अत्यंत भिन्न स्वभाव को प्रकाशित कर चैतन्यमय शुद्धात्मा की अनुभूति कराई।"},{number:"९",tag:"चौपाई",lines:["राग-द्वेष सब कर्म उपाधि, आत्मा तो आनंद समाधि।","कुंदकुंद की वाणी अमृत, जो पीवे हो जाये अमरित॥"],meaning:"आपने उद्घोष किया कि राग-द्वेष और मोह सब कर्मजनित विकार हैं, आत्मा तो साक्षात् आनंदमयी समाधि स्वरूप है। कुंदकुंद देव की यह अमृतमयी वाणी जो भी अंतःकरण से ग्रहण करता है, वह अमर पद (मोक्ष) को पाता है।"},{number:"१०",tag:"चौपाई",lines:["मंगलं भगवान वीरो, मंगलं गौतमो गणी।","मंगलं कुन्दकुन्दाद्यो, जैनधर्मोस्तु मंगलम्॥"],meaning:"जैन परंपरा का यह सर्वोपरि मंगल पाठ उद्घोष करता है—भगवान महावीर मंगल रूप हैं, गौतम गणधर मंगल रूप हैं, कुंदकुंदाचार्य आदि समस्त गुरु मंगल रूप हैं और वीतरागी जैन धर्म परम मंगलमय है।"},{number:"११",tag:"चौपाई",lines:["आचार्य परम्परा के सरताज, कुंदकुंद मुनिराज का राज।","पोन्नूर पर्वत तप की भूमि, जहां विराजे कुंदकुंद स्वामी॥"],meaning:"दिगम्बर आचार्य परंपरा में कुंदकुंद देव को सर्वोच्च मुकुटमणि का स्थान प्राप्त है। तमिलनाडु का पावन पोन्नूर पर्वत (नीलगिरि) आपकी तपोभूमि है, जहाँ आज भी स्वामी जी के चरण-चिह्न विराजमान हैं।"},{number:"१२",tag:"चौपाई",lines:["चरण पादुका पूजत भाई, मनवांछित सब संपति पाई।","जो कुंदकुंद ग्रंथ नित बांचे, सम्यग्दर्शन उर में नाचे॥"],meaning:"पोन्नूर पर्वत पर स्थित आपकी पावन चरण-पादुकाओं की वंदना से आत्मिक शांति व मनोवांछित फल प्राप्त होते हैं। जो नित्य कुंदकुंद देव के ग्रंथों का स्वाध्याय करता है, उसके हृदय में सम्यग्दर्शन प्रफुल्लित हो उठता है।"},{number:"१३",tag:"चौपाई",lines:["मिथ्यामत का अंधकार भागे, केवलज्ञान प्रकाश उर जागे।","अमृतचंद्र ने टीका कीनी, जयसेन ने व्याख्या दीनी॥"],meaning:"इन ग्रंथों के स्वाध्याय से मिथ्यात्व का गहन अंधकार नष्ट होकर सम्यग्ज्ञान का प्रकाश खिलता है। महान आचार्य अमृतचंद्र देव ने 'आत्मख्याति' तथा आचार्य जयसेन ने 'तात्पर्यवृत्ति' टीका लिखकर आपके उपदेशों को जगद्व्यापी बनाया।"},{number:"१४",tag:"चौपाई",lines:["टोडरमल और बनारसी दासा, कुंदकुंद वचनों पर विश्वासा।","गुरुवर विद्यासागर ध्यावें, कुंदकुंद की जय जय गावें॥"],meaning:"पंडित टोडरमल जी और कविवर बनारसीदास जी जैसे मनीषियों ने कुंदकुंद वाणी पर अटूट विश्वास जताया। आधुनिक युग के संत शिरोमणि आचार्य विद्यासागर जी महाराज भी कुंदकुंद देव को आदर्श मानकर उनकी स्तुति करते रहे।"},{number:"१५",tag:"चौपाई",lines:["समयसार का पाठ सुनाओ, भव-भव के संताप मिटाओ।","जो चालीसा चालीस दिन गावे, ज्ञान-सिंधु में गोता लावे॥"],meaning:"समयसार का नित्य पठन-पाठन जीव के जन्म-जन्मांतर के संतापों को शांत कर देता है। जो भी इस चालीसा का चालीस दिन तक पाठ करता है, वह अध्यात्म-ज्ञान के अगाध सागर में गोता लगाकर परम तृप्त हो जाता है।"},{number:"१६",tag:"चौपाई",lines:["विद्या बुद्धि विवेक बढ़ावे, आत्म-शांति जीवन में पावे।","रोग-दोष सब दूर नसावे, गुरु-चरणों में जो सिर नावे॥"],meaning:"कुंदकुंद स्वामी की शरण में जाने से विद्या, बुद्धि और भेद-विज्ञान रूपी विवेक की वृद्धि होती है। जो गुरुवर के चरणों में शीश नवाता है, उसके शारीरिक रोग और मानसिक दोष समूल नष्ट हो जाते हैं।"},{number:"१७",tag:"चौपाई",lines:["घर में सुख-शांति बरसाओ, धर्म-मार्ग पर हमें चलाओ।","मैं अज्ञान शरण में आया, कुंदकुंद मुनि ने अपनाया॥"],meaning:"हे पूज्य गुरुदेव! हमारे घर में सुख-शांति का संचार हो और हम सदैव सच्चे जिनधर्म के मार्ग पर चलें। मुझ अज्ञानी जीव को आपने अपनी अध्यात्म-वाणी का संबल देकर अपनी शरण में अपनाया है।"},{number:"१८",tag:"चौपाई",lines:["अपनी करुणा-दृष्टि बरसाओ, भव-सागर से पार लगाओ।","शुद्धोपयोग की राह दिखाओ, आतम-रस का पान कराओ॥"],meaning:"हे मुनिराज! हम पर अपनी करुणादृष्टि बनाए रखें और संसार-सागर से पार उतारें। हमें शुभोपयोग से आगे बढ़कर परम शुद्धोपयोग की राह दिखाइए और निज आत्मानुभव का अलौकिक रस पिलाइए।"},{number:"१९",tag:"चौपाई",lines:["कुंदकुंद स्वामी जय जयकारा, वीतरागता का उजियारा।","जैन धर्म का मूल अधारा, कुंदकुंद वचनों की धारा॥"],meaning:"परम वीतरागता के प्रकाशपुंज आचार्य कुंदकुंद स्वामी की सर्वत्र जय-जयकार हो! दिगम्बर जैन धर्म की मूल धुरी और आधारशिला कुंदकुंद देव के अमृत वचनों की पावन धारा ही है।"},{number:"२०",tag:"चौपाई",lines:["निसिदिन गुरुवर ध्यान लगाऊँ, जनम-जनम स्वाध्याय रचाऊँ।","चरण कमल में शीश नवाऊँ, सिद्ध-वधु का वर बन जाऊँ॥"],meaning:"मैं दिन-रात गुरुदेव के ध्यान में लीन रहूँ और जन्म-जन्मांतर तक जिनवाणी के स्वाध्याय में प्रीति रखूँ। आपके पावन चरणों में नमन करते हुए अंततः मुक्ति रूपी सिद्ध-वधु का वरण कर मोक्ष प्राप्त करूँ।"},{number:"२१",tag:"चौपाई",lines:["अहिंसा सत्य दया का सार, कुंदकुंद देव जय जयकार।","कलिकाल के तीर्थंकर सम, पूजत सुर-नर मुनि अनुपम॥"],meaning:"अहिंसा, सत्य और सर्वोदय दया के सारभूत आचार्य कुंदकुंद देव की जय हो! आप इस पंचम काल में तीर्थंकर के सदृश हैं, जिनकी वंदना देव, मानव और मुनिराज सभी परम आदर से करते हैं।"},{number:"२२",tag:"चौपाई",lines:["हाथ जोड़ विनती प्रभु मोरी, काटो कर्म-जाल की डोरी।","कुंदकुंद चालीसा जो गावे, मोक्ष-महल का पथ वो पावे॥"],meaning:"हाथ जोड़कर मेरी यही प्रार्थना है कि इस अनादि कर्म-जंजाल के बंधन को काट दीजिए। जो भी भव्य जीव इस कुंदकुंद चालीसा का विशुद्ध भाव से पाठ करता है, वह निश्चित ही मोक्ष-महल का प्रशस्त मार्ग प्राप्त करता है।"},{number:"२३",tag:"दोहा",lines:["कुंदकुंद गुरु के चरण में, कोटि-कोटि परनाम।","समयसार अमृत दिया, पूरण कीजे काम॥"],meaning:"आचार्य श्री कुंदकुंद स्वामी के पावन चरणों में मेरा कोटि-कोटि प्रणाम है। जिन्होंने समयसार रूपी दिव्य अमृत प्रदान किया, वे हमारे आत्म-कल्याण रूपी सभी संकल्पों को पूर्ण करें।"},{number:"२४",tag:"दोहा",lines:["शुद्धातम अनुभव करे, मिटे सकल संताप।","कुंदकुंद मुनिराज की, जय बोले निष्पाप॥"],meaning:"कुंदकुंद वाणी के अनुसार जो भी शुद्धात्मा का अनुभव करता है, उसके संसार के समस्त संताप मिट जाते हैं। निष्पाप होकर जो कुंदकुंद मुनिराज की जय बोलता है, वह परम पद को प्राप्त करता है।"},{number:"२५",tag:"जाप मंत्र",lines:["ॐ ह्रीं श्रीं कलिकाल-सर्वज्ञ-श्रीमद्-भगवत्-कुंदकुंदाचार्य-गुरुभ्यो नमः।"],meaning:"इस महामंत्र का प्रतिदिन १०८ बार जाप करने से मिथ्यात्व का नाश, सम्यग्दर्शन की प्राप्ति, भेद-विज्ञान और आत्म-कल्याण की सिद्धि होती है।"}]}};export{n as ChalisaData};
